#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spi.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define MCP3008_COMMAND 0x01

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct spi_ioc_transfer xfer;
    unsigned char tx[3], rx[3];
    int spi_fd;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        memset(tx, 0, sizeof(tx));
        memset(rx, 0, sizeof(rx));

        tx[0] = MCP3008_COMMAND;
        tx[1] = (MCP3008_CHANNEL << 4) | 0x08;

        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = 3;
        xfer.delay_usecs = 0;
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = 8;
        xfer.cs_change = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 1) {
            perror("SPI transfer failed");
            close(spi_fd);
            return EXIT_FAILURE;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s - ADC Value: %d\n", timestamp, adc_value);

        sleep(1);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

