#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <spi/spi.h>

#define FLAME_SENSOR_PIN 4
#define MCP3008_CHANNEL 0
#define MCP3008_CE_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CSV_FILE "flame_data.csv"

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_sensor;
    int spi_fd;
    FILE *csv_file;
    struct spi_ioc_transfer spi_xfer;
    unsigned char spi_buf[3];
    unsigned char adc_value;
    double temperature;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input on flame sensor line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        return 1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read flame sensor
        int flame_detected = gpiod_line_get_value(flame_sensor);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            continue;
        }

        // Read ADC
        memset(spi_buf, 0, sizeof(spi_buf));
        spi_buf[0] = 0x01;
        spi_buf[0] |= (MCP3008_CHANNEL << 4);
        spi_buf[1] = 0x00;

        spi_xfer.tx_buf = (unsigned long)spi_buf;
        spi_xfer.rx_buf = (unsigned long)spi_buf;
        spi_xfer.len = 3;
        spi_xfer.delay_usecs = 0;
        spi_xfer.speed_hz = SPI_SPEED;
        spi_xfer.bits_per_word = 8;
        spi_xfer.cs_change = 1;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            continue;
        }

        adc_value = ((spi_buf[1] & 0x03) << 8) | spi_buf[2];

        // Calculate temperature (example conversion, adjust as needed)
        temperature = (double)adc_value * 3.3 / 1024.0 * 100.0;

        // Get current time
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write to CSV
        fprintf(csv_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(csv_file);

        sleep(1);
    }

    // Clean up
    fclose(csv_file);
    close(spi_fd);
    gpiod_line_release(flame_sensor);
    gpiod_chip_close(chip);

    return 0;
}

