#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <i2c/smbus.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CONFIG 0x01
#define ADC_READ 0x00
#define TEMP_THRESHOLD 60.0
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_TIME_MS 50
#define LOG_FILE "fire_log.txt"

static volatile int running = 1;
static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor;
static struct gpiod_line *buzzer;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        running = 0;
    }
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        goto cleanup_gpio;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "Failed to get buzzer line\n");
        goto cleanup_gpio;
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor") < 0 ||
        gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        goto cleanup_gpio;
    }

    return 0;

cleanup_gpio:
    if (buzzer) gpiod_line_release(buzzer);
    if (flame_sensor) gpiod_line_release(flame_sensor);
    gpiod_chip_close(chip);
    return 1;
}

int init_i2c() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        return 1;
    }

    // Configure ADC
    if (i2c_smbus_write_word_data(i2c_fd, ADC_CONFIG, 0x8583) < 0) {
        fprintf(stderr, "Failed to configure ADC\n");
        close(i2c_fd);
        return 1;
    }

    return 0;
}

int read_temperature() {
    int adc_value = i2c_smbus_read_word_data(i2c_fd, ADC_READ);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    // Convert ADC value to temperature (assuming 3.3V reference and 10-bit ADC)
    float voltage = (adc_value * 3.3) / 4095.0;
    return (int)((voltage - 0.5) * 100.0);
}

void log_event(const char *message) {
    time_t now;
    time(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_gpio()) {
        gpioTerminate();
        return 1;
    }

    if (init_i2c()) {
        gpiod_line_release(buzzer);
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_line_release(buzzer);
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    int last_flame_state = 0;
    time_t flame_debounce_time = 0;

    while (running) {
        int flame_state = gpiod_line_get_value(flame_sensor);
        int temp = read_temperature();

        if (flame_state != last_flame_state) {
            flame_debounce_time = time(NULL);
        }

        if (time(NULL) - flame_debounce_time > DEBOUNCE_TIME_MS / 1000) {
            if (flame_state && temp > TEMP_THRESHOLD) {
                log_event("Fire detected!");
                gpiod_line_set_value(buzzer, 1);
                sleep(2);
                gpiod_line_set_value(buzzer, 0);
                log_event("Fire event logged");
            } else if (flame_state) {
                log_event("Flame detected!");
            } else if (temp > TEMP_THRESHOLD) {
                char temp_log[64];
                snprintf(temp_log, sizeof(temp_log), "Temperature: %d°C", temp);
                log_event(temp_log);
            }
        }

        last_flame_state = flame_state;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(buzzer);
    gpiod_line_release(flame_sensor);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

