        perror("Failed to open log file");
        cleanup(0);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value;
        if (read_adc(0, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
