            fprintf(stderr, "Sensor absent or invalid reading\n");
            continue;
        }

        int fan_state = (adc_value > CURRENT_THRESHOLD) ? 1 : 0;
        gpiod_line_set_value(fan_line, fan_state);

        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        fprintf(log_file, "%s, %u\n", timestamp, adc_value);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    cleanup(0);
    return EXIT_SUCCESS;
}

