#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MICS4514_ADDR 0x19
#define ADS1115_ADDR 0x48
#define LOG_FILE "co_log.txt"
#define LOG_INTERVAL 5
#define CALIBRATION_FACTOR 1.166 // Example calibration factor, adjust as needed

static int i2c_handle;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        if (i2c_handle >= 0) {
            close(i2c_handle);
        }
        if (log_file) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int read_adc_value(int mux_channel) {
    uint8_t config[3] = {0};
    uint8_t buffer[2] = {0};

    config[0] = 0x01; // Start single conversion
    config[1] = (mux_channel << 4) | 0x83; // MUX selection, gain = 1, data rate = 128SPS

    if (i2cWriteDevice(i2c_handle, ADS1115_ADDR, config, 3) < 0) {
        fprintf(stderr, "Failed to write to ADS1115\n");
        return -1;
    }

    usleep(10000); // Wait for conversion to complete

    if (i2cReadDevice(i2c_handle, ADS1115_ADDR, buffer, 2) < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

float convert_to_ppm(int raw_value) {
    // Example conversion formula, adjust based on sensor datasheet
    float resistance = (float)raw_value * 3.3 / 32768.0;
    float ppm = 1000000.0 / (resistance * CALIBRATION_FACTOR);
    return ppm;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int raw_value = read_adc_value(0); // Assuming MICS-4514 is connected to channel 0
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        float ppm = convert_to_ppm(raw_value);
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

