#define SPI_DEVICE "/dev/spidev0.0"
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define SPI_SPEED 1000000

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor;
static struct gpiod_line *mcp3008_cs;
static FILE *csv_file;

void cleanup(int signum) {
    if (csv_file) fclose(csv_file);
    if (spi_fd >= 0) close(spi_fd);
    if (mcp3008_cs) gpiod_line_release(mcp3008_cs);
    if (flame_sensor) gpiod_line_release(flame_sensor);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_mcp3008(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    gpiod_line_set_value(mcp3008_cs, 0);
    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        gpiod_line_set_value(mcp3008_cs, 1);
        return -1;
    }
    gpiod_line_set_value(mcp3008_cs, 1);

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main() {
    struct timespec ts;
    char timestamp[64];
    int flame_present, temperature;

    signal(SIGINT, cleanup);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        cleanup(0);
    }

    mcp3008_cs = gpiod_chip_get_line(chip, MCP3008_CS_PIN);
    if (!mcp3008_cs) {
        fprintf(stderr, "Failed to get MCP3008 CS line\n");
        cleanup(0);
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor") < 0 ||
        gpiod_line_request_output(mcp3008_cs, "mcp3008_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup(0);
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup(0);
    }

    // Open CSV file
    csv_file = fopen("flame_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup(0);
    }
    fprintf(csv_file, "Timestamp,Flame_Present,Temperature\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        flame_present = gpiod_line_get_value(flame_sensor);
        temperature = read_mcp3008(0);

        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature\n");
            continue;
        }

        fprintf(csv_file, "%s,%d,%d\n", timestamp, flame_present, temperature);
        fflush(csv_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

