#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "audio_log.txt"

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void i2c_start() {
    gpioSetMode(I2C_SDA_PIN, PI_OUTPUT);
    gpioSetMode(I2C_SCL_PIN, PI_OUTPUT);
    gpioWrite(I2C_SDA_PIN, PI_HIGH);
    gpioWrite(I2C_SCL_PIN, PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SDA_PIN, PI_LOW);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
}

void i2c_stop() {
    gpioWrite(I2C_SDA_PIN, PI_LOW);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SCL_PIN, PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SDA_PIN, PI_HIGH);
}

int i2c_write_byte(uint8_t byte) {
    for (int i = 7; i >= 0; i--) {
        gpioWrite(I2C_SDA_PIN, (byte & (1 << i)) ? PI_HIGH : PI_LOW);
        gpioSleep(PI_TIME_RELATIVE, 0, 50000);
        gpioWrite(I2C_SCL_PIN, PI_HIGH);
        gpioSleep(PI_TIME_RELATIVE, 0, 50000);
        gpioWrite(I2C_SCL_PIN, PI_LOW);
    }

    gpioWrite(I2C_SDA_PIN, PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SCL_PIN, PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);

    int ack = gpioRead(I2C_SDA_PIN);
    gpioWrite(I2C_SCL_PIN, PI_LOW);

    return ack == PI_LOW;
}

int i2c_read_byte(int ack) {
    int byte = 0;
    gpioSetMode(I2C_SDA_PIN, PI_INPUT);

    for (int i = 7; i >= 0; i--) {
        gpioWrite(I2C_SCL_PIN, PI_HIGH);
        gpioSleep(PI_TIME_RELATIVE, 0, 50000);
        byte |= (gpioRead(I2C_SDA_PIN) ? 1 : 0) << i;
        gpioWrite(I2C_SCL_PIN, PI_LOW);
        gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    }

    gpioSetMode(I2C_SDA_PIN, PI_OUTPUT);
    gpioWrite(I2C_SDA_PIN, ack ? PI_LOW : PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SCL_PIN, PI_HIGH);
    gpioSleep(PI_TIME_RELATIVE, 0, 50000);
    gpioWrite(I2C_SCL_PIN, PI_LOW);

    return byte;
}

float read_microphone(int address) {
    i2c_start();
    if (!i2c_write_byte(address << 1)) {
        i2c_stop();
        return -999.0;
    }

    if (!i2c_write_byte(0x00)) {  // Assuming 0x00 is the register for sound pressure level
        i2c_stop();
        return -999.0;
    }

    i2c_start();
    if (!i2c_write_byte((address << 1) | 1)) {
        i2c_stop();
        return -999.0;
    }

    uint16_t value = i2c_read_byte(1) << 8 | i2c_read_byte(0);
    i2c_stop();

    // Convert raw value to dB (this is a placeholder, actual conversion depends on microphone specs)
    return (float)value / 10.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    time_t start_time = time(NULL);

    while (keep_running) {
        float mic1_level = read_microphone(0x40);  // Assuming address 0x40 for first microphone
        float mic2_level = read_microphone(0x41);  // Assuming address 0x41 for second microphone

        float avg_level = (mic1_level + mic2_level) / 2.0;

        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, %.1f\n", timestamp, avg_level);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

