#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_MS 1
#define LED_PIN 27
#define HIGH_THRESHOLD 0.8 // Adjust as needed

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void signal_handler(int signo) {
    if (signo == SIGINT) {
        gpiod_line_set_value(led_line, 0);
        cleanup();
    }
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (write(spi_fd, tx, 3) != 3 || read(spi_fd, rx, 3) != 3) {
        fprintf(stderr, "SPI read/write error\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

double compute_rms(int *samples, int num_samples) {
    long long sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += (long long)samples[i] * samples[i];
    }
    return sqrt((double)sum / num_samples);
}

int main() {
    int samples_mic1[NUM_SAMPLES], samples_mic2[NUM_SAMPLES];
    double rms_mic1, rms_mic2;
    struct timespec start_time, current_time;
    char timestamp[64];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("audio_events.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup();
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        cleanup();
    }

    signal(SIGINT, signal_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        for (int i = 0; i < NUM_SAMPLES; i++) {
            samples_mic1[i] = read_adc(0);
            samples_mic2[i] = read_adc(1);
            if (samples_mic1[i] < 0 || samples_mic2[i] < 0) {
                fprintf(stderr, "ADC read error\n");
                cleanup();
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        rms_mic1 = compute_rms(samples_mic1, NUM_SAMPLES);
        rms_mic2 = compute_rms(samples_mic2, NUM_SAMPLES);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        struct tm *tm_info = localtime(&current_time.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rms_mic1, rms_mic2);
        fflush(log_file);

        if (rms_mic1 > HIGH_THRESHOLD || rms_mic2 > HIGH_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
        }

        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                          (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
        if (elapsed_ms < 100) {
            usleep((100 - elapsed_ms) * 1000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

