int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int ads1115_read_adc(int channel) {
    uint8_t config = 0x80 | (channel << 12) | 0x200; // Single-shot mode, 128SPS
    if (i2c_write(i2c_fd, 1, config) != 2) return -1;

    usleep(1000000 / 128); // Wait for conversion

    uint8_t data[2];
    if (i2c_read(i2c_fd, 0, data) != 2) return -1;

    return (data[0] << 4) | (data[1] >> 4);
}

