    // Assuming a gain of 1 and a known sensitivity of the sensor
    return voltage * 10.0; // Example conversion, adjust as needed
}

void update_buffer(float current) {
    buffer[buffer_index] = (int)(current * 100); // Store in centi-amps
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average_current() {
    long sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return (float)sum / BUFFER_SIZE / 100.0; // Convert back to amps
}

