        perror("Failed to request GPIO line as output");
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = ads1115_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        float voltage = adc_value * (3.3 / 32767.0);
        float current = ads1115_voltage_to_current(voltage);

        update_buffer(current);

        float avg_current = calculate_average_current();
        if (avg_current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }

        usleep(1000000 / SAMPLE_RATE);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

