#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT (0x80)
#define TCS34725_ENABLE (0x00)
#define TCS34725_ATIME (0x01)
#define TCS34725_AILTL (0x04)
#define TCS34725_AILTH (0x05)
#define TCS34725_AIHTL (0x06)
#define TCS34725_AIHTH (0x07)
#define TCS34725_PERS (0x0C)
#define TCS34725_CONFIG (0x0D)
#define TCS34725_CONTROL (0x0F)
#define TCS34725_ID (0x12)
#define TCS34725_CDATAL (0x14)
#define TCS34725_CDATAH (0x15)
#define TCS34725_RDATAL (0x16)
#define TCS34725_RDATAH (0x17)
#define TCS34725_GDATAL (0x18)
#define TCS34725_GDATAH (0x19)
#define TCS34725_BDATAL (0x1A)
#define TCS34725_BDATAH (0x1B)

#define EXPECTED_ID 0x44

static int i2c_fd;
static FILE *csv_file;
static int consecutive_failures = 0;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = 3;
    while (retries--) {
        if (write(i2c_fd, buf, 2) == 2) {
            consecutive_failures = 0;
            return 0;
        }
        fprintf(stderr, "Warning: I2C write failed, retries left: %d\n", retries);
        usleep(10000);
    }
    consecutive_failures++;
    return -1;
}

int i2c_read(uint8_t reg, uint8_t *value) {
    int retries = 3;
    while (retries--) {
        if (write(i2c_fd, &reg, 1) == 1 && read(i2c_fd, value, 1) == 1) {
            consecutive_failures = 0;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed, retries left: %d\n", retries);
        usleep(10000);
    }
    consecutive_failures++;
    return -1;
}

int init_sensor() {
    uint8_t id;
    if (i2c_read(TCS34725_ID | TCS34725_COMMAND_BIT, &id) != 0 || id != EXPECTED_ID) {
        fprintf(stderr, "Error: Sensor ID mismatch or read failed\n");
        return -1;
    }

    if (i2c_write(TCS34725_ATIME, 0xEB) != 0) return -1; // 24ms integration time
    if (i2c_write(TCS34725_CONTROL, 0x01) != 0) return -1; // Power on
    usleep(3000); // Wait 3ms after power-on
    if (i2c_write(TCS34725_ENABLE, 0x01) != 0) return -1; // Enable RGBC
    return 0;
}

int read_sensor(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (i2c_read(TCS34725_CDATAL | TCS34725_COMMAND_BIT, buf) != 0) return -1;
    *clear = (buf[1] << 8) | buf[0];
    if (i2c_read(TCS34725_RDATAL | TCS34725_COMMAND_BIT, buf) != 0) return -1;
    *red = (buf[1] << 8) | buf[0];
    if (i2c_read(TCS34725_GDATAL | TCS34725_COMMAND_BIT, buf) != 0) return -1;
    *green = (buf[1] << 8) | buf[0];
    if (i2c_read(TCS34725_BDATAL | TCS34725_COMMAND_BIT, buf) != 0) return -1;
    *blue = (buf[1] << 8) | buf[0];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char filename[] = "color_log.csv";
    csv_file = fopen(filename, "a+");
    if (!csv_file) {
        perror("Error opening CSV file");
        return EXIT_FAILURE;
    }

    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        fprintf(csv_file, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
    }

    char device[20];
    snprintf(device, sizeof(device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec ts, last_read;
    clock_gettime(CLOCK_MONOTONIC, &last_read);

    while (1) {
        if (consecutive_failures >= 3) {
            fprintf(stderr, "Error: Too many consecutive I2C failures\n");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        if ((ts.tv_sec - last_read.tv_sec) >= 1) {
            uint16_t clear, red, green, blue;
            if (read_sensor(&clear, &red, &green, &blue) == 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
                fflush(csv_file);
                last_read = ts;
            }
        }

        // Busy-wait for 1ms to allow signal handling
        ts.tv_nsec += 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

