#define CHANNEL_1 1
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

uint16_t read_adc(int channel) {
    uint8_t tx[3] = {1, (channel << 4) | 0x1, 0};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer spi;

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = 0;
    spi.bits_per_word = 8;
    spi.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return 0xFFFF;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("moisture_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    fflush(log_file);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        uint16_t moisture1 = read_adc(CHANNEL_0);
        uint16_t moisture2 = read_adc(CHANNEL_1);

        if (moisture1 == 0xFFFF || moisture2 == 0xFFFF) {
            fprintf(stderr, "Error reading sensors\n");
        } else {
            fprintf(log_file, "%s,%u,%u\n", timestamp, moisture1, moisture2);
            fflush(log_file);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

