#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_shutdown = NULL;

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (motor_shutdown) {
        gpiod_line_release(motor_shutdown);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_spi(void) {
    struct spi_ioc_transfer xfer = {
        .tx_buf = NULL,
        .rx_buf = (unsigned long)malloc(3),
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 0;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x0;
    tx[2] = 0x00;

    while (retries < MAX_RETRIES) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
            perror("SPI transfer failed");
            retries++;
            usleep(100000);
            continue;
        }

        rx[0] = tx[1];
        rx[1] = tx[2];
        rx[2] = 0;

        return ((rx[0] & 0x03) << 8) | rx[1];
    }

    return -1;
}

double adc_to_current(int adc_value) {
    // Assuming a 3.3V reference and a 10-bit ADC
    double voltage = (adc_value * 3.3) / 1023.0;
    // Assuming a sensitivity of 0.1V/A
    return voltage / 0.1;
}

int main(void) {
    struct timespec ts;
    char buffer[100];
    int adc_value;
    double current;
    int retries;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    motor_shutdown = gpiod_chip_get_line(chip, 17);
    if (!motor_shutdown) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_shutdown, "motor_shutdown", 1) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0) {
        if (ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,Current (A)\n");
        }
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        retries = 0;
        while (retries < MAX_RETRIES) {
            adc_value = read_adc(ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            usleep(100000);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ADC after %d attempts\n", MAX_RETRIES);
            cleanup();
            return EXIT_FAILURE;
        }

        current = adc_to_current(adc_value);

        fprintf(log_file, "%s,%.2f\n", buffer, current);
        fflush(log_file);

        if (current > CURRENT_THRESHOLD) {
            fprintf(log_file, "%s,Over-current event detected\n", buffer);
            fflush(log_file);

            if (gpiod_line_set_value(motor_shutdown, 0) < 0) {
                perror("Failed to disable motor");
            }

            sleep(1);

            if (gpiod_line_set_value(motor_shutdown, 1) < 0) {
                perror("Failed to enable motor");
            }
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

