#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x5A
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        gpioI2CClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure(kPa)\n");
        fflush(log_file);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        int retries = 0;
        float pressure = 0.0f;

        while (retries < MAX_RETRIES) {
            char data[4];
            int bytes_read = gpioI2CReadI2CBlock(i2c_handle, 0x00, data, 4);

            if (bytes_read == 4) {
                pressure = ((data[0] << 12) | (data[1] << 4) | (data[2] >> 4)) * 0.02;
                break;
            } else {
                fprintf(stderr, "I2C read error: %s\n", gpioStrError(bytes_read));
                retries++;
                sleep(1);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read pressure sensor after %d attempts\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

