#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define MLX90834_ADDR 0x0E
#define PRESSURE_CHANNEL 0
#define TEMP_CHANNEL 1
#define WARNING_LED_PIN 17
#define MAX_RETRIES 3
#define PRESSURE_THRESHOLD 105.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (i2c_write(fd, reg, 0) != 2) {
        return -1;
    }
    return read(fd, buf, len);
}

int ads1115_read(int channel) {
