        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup(0);
    }

    int retries;
    int pressure_raw, temp_raw;
    float pressure, temperature;

    while (1) {
        retries = 0;
        do {
            pressure_raw = ads1115_read(PRESSURE_CHANNEL);
            temp_raw = ads1115_read(TEMP_CHANNEL);
            retries++;
        } while ((pressure_raw < 0 || temp_raw < 0) && retries < MAX_RETRIES);

