            cleanup(0);
        }

        pressure = mlx90834_to_pressure(pressure_raw);
        temperature = ntc_to_celsius(ads1115_to_voltage(temp_raw));

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
