#include <spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_MAX_VALUE 1023
#define CURRENT_THRESHOLD 10000 // 10A in mA
#define LOG_FILE "current_log.txt"
#define GPIO_MOTOR_SHUTDOWN 27
#define GPIO_SPI_CE 8
#define GPIO_SPI_SCLK 11
#define GPIO_SPI_MOSI 10
#define GPIO_SPI_MISO 9

static int spi_handle = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        close(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (motor_shutdown_line) {
        gpiod_line_release(motor_shutdown_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    int adc_value;
    float current;
    char log_entry[100];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    motor_shutdown_line = gpiod_chip_get_line(chip, GPIO_MOTOR_SHUTDOWN);
    if (!motor_shutdown_line) {
        fprintf(stderr, "Failed to get motor shutdown line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 0) < 0) {
        fprintf(stderr, "Failed to request motor shutdown line\n");
        gpiod_line_release(motor_shutdown_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_release(motor_shutdown_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_handle);
        gpiod_line_release(motor_shutdown_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        adc_value = spiXfer(spi_handle, 0x0180, 8);
        if (adc_value < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            cleanup(0);
        }

        adc_value = (adc_value & 0x3FF); // Mask to get 10-bit value
        current = (float)adc_value * 3.3 / ADC_MAX_VALUE * 1000; // Convert to mA

        time(&ts.tv_sec);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S.%03ld, %f\n", tm_info, ts.tv_nsec / 1000000);

        if (fprintf(log_file, "%s", log_entry) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            cleanup(0);
        }
        fflush(log_file);

        if (current > CURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT event detected: %.2f mA\n", current);
            gpiod_line_set_value(motor_shutdown_line, 1);
            cleanup(0);
        }

        nanosleep(&(struct timespec){0, 100000000}, NULL); // Sleep for 100ms
    }

    return EXIT_SUCCESS;
}

