#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define ALARM_PIN 4
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CHANNEL 0
#define LOG_FILE "co_log.txt"
#define VOLTAGE_THRESHOLD 2.5

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *ce_line;
static struct gpiod_line *alarm_line;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (ce_line) {
        gpiod_line_release(ce_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

float adc_read(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x08;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return (float)adc_value * 3.3 / 1023.0;
}

int main() {
    struct timespec ts;
    char timestamp[20];
    float voltage;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ce_line = gpiod_chip_get_line(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        cleanup(0);
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm line");
        cleanup(0);
    }

    if (gpiod_line_request_output(ce_line, "SPI CE0", 0) < 0) {
        perror("Failed to request CE line");
        cleanup(0);
    }

    if (gpiod_line_request_output(alarm_line, "Alarm", 0) < 0) {
        perror("Failed to request alarm line");
        cleanup(0);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup(0);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup(0);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        gpiod_line_set_value(ce_line, 1);
        voltage = adc_read(CHANNEL);
        gpiod_line_set_value(ce_line, 0);

        if (voltage < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            gpiod_line_set_value(alarm_line, 0);
            sleep(1);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
        fflush(log_file);

        if (voltage > VOLTAGE_THRESHOLD) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

