        }
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    int retries = 3;
    while (retries--) {
        int result = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "SPI transfer failed, retrying... (%d)\n", retries);
        usleep(100000);  // 100ms delay before retry
    }
    return -1;
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

