    if (gpiod_line_request_output(cs_line, "MCP3008_CS", 1) < 0) {
        perror("Failed to request CS line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    time_t raw_time;
    struct tm time_info;
    char timestamp[64];
    unsigned char adc_value;

    while (1) {
        gpiod_line_set_value(cs_line, 0);  // Assert CS
        adc_value = read_adc(SPI_CHANNEL);
        gpiod_line_set_value(cs_line, 1);  // Deassert CS

        if (adc_value == (unsigned char)-1) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        time(&raw_time);
        if (localtime_r(&raw_time, &time_info) == NULL) {
            perror("Failed to get local time");
            continue;
        }

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &time_info) == 0) {
            fprintf(stderr, "Failed to format timestamp\n");
            continue;
        }

        fprintf(log_file, "%s, %d\n", timestamp, adc_value);
        fflush(log_file);

        if (adc_value > ALARM_THRESHOLD) {
            fprintf(stderr, "ALARM: Methane concentration exceeds %d ppm\n", ALARM_THRESHOLD);
        }

        sleep(1);
    }

    // This point should never be reached
    fclose(log_file);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

