#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>
#include <i2c/smbus.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define MLX90830_ADDRESS 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define SAMPLE_RATE 1

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

int init_ads1115() {
    uint16_t config = 0x8583; // AIN0, 1.024V, 128SPS
    if (i2c_smbus_write_word_data(i2c_fd, ADS1115_CONFIG_REG, config) < 0) {
        perror("Failed to configure ADS1115");
        return -1;
    }
    return 0;
}

float read_pressure() {
    uint16_t adc_value;
    if (i2c_smbus_read_word_data(i2c_fd, ADS1115_CONVERSION_REG) < 0) {
        perror("Failed to read from ADS1115");
        return -1;
    }
    adc_value = i2c_smbus_read_word_data(i2c_fd, ADS1115_CONVERSION_REG);
    float voltage = adc_value * (3.3 / 32768.0);
    return voltage * 100.0; // Assuming a linear relationship for simplicity
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_ads1115() < 0) {
        cleanup(0);
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        float pressure = read_pressure();
        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            time_t now = time(NULL);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
            fprintf(log_file, "%s, %.2f\n", timestamp, pressure);
            fflush(log_file);
        }
        sleep(SAMPLE_RATE);
    }

    return EXIT_SUCCESS;
}

