#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define CE0_PIN 8
#define HUMIDITY_THRESHOLD 80.0

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 6) | 0x18;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

double adc_to_humidity(int adc_value) {
    return (double)adc_value / 4095.0 * 100.0;
}

double adc_to_temperature(int adc_value) {
    double resistance = 10000.0 * ((4095.0 / (double)adc_value) - 1.0);
    double temp = 1.0 / (log(resistance / 10000.0) / 3950.0 + 1.0 / 298.15) - 273.15;
    return temp;
}

void send_email_alert(double humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo 'Humidity exceeded threshold: %.2f%%' | ssmtp user@example.com", humidity);
    system(command);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, CE0_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "HIH-4602-A_CS", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("humidity_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_humidity = read_adc(0);
        int adc_temperature = read_adc(1);

        if (adc_humidity < 0 || adc_temperature < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            continue;
        }

        double humidity = adc_to_humidity(adc_humidity);
        double temperature = adc_to_temperature(adc_temperature);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(60);  // Wait for 1 minute before next reading
    }

    return EXIT_SUCCESS;
