int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 6) | 0x18;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

double adc_to_humidity(int adc_value) {
    return (double)adc_value / 4095.0 * 100.0;
}

double adc_to_temperature(int adc_value) {
    double resistance = 10000.0 * ((4095.0 / (double)adc_value) - 1.0);
    double temp = 1.0 / (log(resistance / 10000.0) / 3950.0 + 1.0 / 298.15) - 273.15;
    return temp;
}

