        gpiod_line_set_value(ce_line, 0);

        // Extract ADC value
        adc_value = ((rx[0] & 0x0F) << 8) | rx[1];

        // Convert to temperature
        temperature = adc_to_temperature(adc_value);

        // Validate temperature
