            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
            continue;
        }

        // Get current timestamp
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log temperature
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

