int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x0;
    tx[2] = 0x0;

    gpiod_line_set_value(cs_line, 0);
    if (spi_transfer(tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }
    gpiod_line_set_value(cs_line, 1);

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main() {
    struct timespec ts;
    int x, y, z;
    char log_entry[100];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
