        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI mode/speed\n");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        x = read_adc(0);
        y = read_adc(1);
        z = read_adc(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        snprintf(log_entry, sizeof(log_entry), "%ld.%09ld,%d,%d,%d",
                 ts.tv_sec, ts.tv_nsec, x, y, z);
        fprintf(log_file, "%s\n", log_entry);
        fflush(log_file);

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file);
        }

        usleep(10000); // 100 Hz sampling
    }

    return EXIT_SUCCESS;
}

