    fflush(log_file);

    signal(SIGINT, signal_handler);

    while (1) {
        time_t now = time(NULL);
        uint16_t ir, red;
        int error = 0;

        if (read_si1172_data(&ir, &red) < 0) {
            error = 1;
        }

        fprintf(log_file, "%ld,%d,%d,%d\n", (long)now, ir, red, error);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

