#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_MAX_VALUE 1023
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

double adc_to_flow_rate(int adc_value) {
    if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
        fprintf(stderr, "Sensor absent or malfunctioning\n");
        return -1;
    }
    return (double)adc_value / ADC_MAX_VALUE * FLOW_MAX;
}

int main() {
    struct spi_ioc_transfer spi;
    uint8_t tx[3] = {1, (SPI_CHANNEL << 4) | 0x01, 0};
    uint8_t rx[3] = {0};
    int adc_value;
    double flow_rate;
    struct timespec ts;
    char timestamp[30];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI device open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "SPI configuration failed\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        memset(&spi, 0, sizeof(spi));
        spi.tx_buf = (unsigned long)tx;
        spi.rx_buf = (unsigned long)rx;
        spi.len = 3;
        spi.delay_usecs = 0;
        spi.speed_hz = SPI_SPEED;
        spi.bits_per_word = 8;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < 0 || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Invalid flow rate: %.2f L/min\n", flow_rate);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                 tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, ts.tv_nsec / 1000);

        fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
        fflush(log_file);

        usleep(1000000);  // Sleep for 1 second
    }

    return EXIT_SUCCESS;
}

