#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x28
#define MEASURE_CMD 0x40
#define SAMPLE_INTERVAL 5
#define LOG_FILE "environmental_data.csv"

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int ret = read(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    time_t last_sample_time = 0;

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            buf[0] = MEASURE_CMD;
            if (i2c_write(i2c_fd, buf, 1) < 0) {
                sleep(5);
                continue;
            }

            sleep(1);  // Wait for conversion

            if (i2c_read(i2c_fd, buf, 6) < 0) {
                sleep(5);
                continue;
            }

            // CRC check (simplified, actual implementation would be more complex)
            if (buf[5] != (buf[0] ^ buf[1] ^ buf[2] ^ buf[3] ^ buf[4])) {
                fprintf(stderr, "CRC check failed\n");
                sleep(5);
                continue;
            }

            int32_t pressure = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
            int32_t temperature = ((int32_t)buf[3] << 16) | ((int32_t)buf[4] << 8) | buf[5];

            // Convert raw ADC values to Celsius and Pascals
            // These formulas are placeholders and should be replaced with actual ICP-10125 formulas
            float temp_c = temperature / 100.0f;
            float pressure_pa = pressure * 100.0f;

            time_t timestamp = time(NULL);
            struct tm *tm_info = localtime(&timestamp);
            char timestamp_str[20];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp_str, temp_c, pressure_pa);
            fflush(log_file);

            printf("Timestamp: %s, Temperature: %.2f°C, Pressure: %.2f Pa\n", 
                   timestamp_str, temp_c, pressure_pa);

            last_sample_time = current_time;
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

