#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SAMPLES 1000
#define NUM_MICROPHONES 2

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int init_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        return -1;
    }
    return spi_handle;
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {0x01, (channel << 4) | 0x01, 0x00};
    unsigned char rx[3] = {0};
    int count = spiXfer(spi_handle, tx, rx, 3);
    if (count < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void apply_noise_cancellation(int *samples, int num_samples) {
    // Simple moving average filter
