#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNEL 0
#define SPI_SPEED 500000
#define ADC_MAX_VALUE 1023
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3] = {
        0x01,
        (channel << 4) | 0x00,
        0x00,
    };
    unsigned char rx[3] = {0};
    int ret;

    ret = spi_transfer(tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(CHANNEL);
        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        fprintf(log_file, "%s,%d\n", timestamp, adc_value);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

