#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define DEFAULT_TEMP 25.0

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

double read_ambient_temperature() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (!file) return DEFAULT_TEMP;

    double temp;
    if (fscanf(file, "%lf", &temp) != 1) {
        fclose(file);
        return DEFAULT_TEMP;
    }

    fclose(file);
    return temp;
}

void log_flame_data(FILE *log_file, int raw_adc, double voltage, double compensated_voltage, double temp, int flame_detected) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%.2f,%.2f,%.1f,%s\n", 
            timestamp, raw_adc, voltage, compensated_voltage, temp, 
            flame_detected ? "DETECTED" : "CLEAR");
    fflush(log_file);
}

int main() {
    int spi_fd, buzzer_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *buzzer_line;
    unsigned char tx[3], rx[3];
    FILE *log_file;
    double ambient_temp;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Failed to set SPI mode/speed");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("Failed to request buzzer GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(buzzer_line);
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Read ambient temperature
    ambient_temp = read_ambient_temperature();

    while (keep_running) {
        int retries = 0;
        int raw_adc = -1;

        while (retries < MAX_RETRIES && raw_adc < 0 || raw_adc > 1023) {
            tx[0] = 0x01;  // Start bit
            tx[1] = (0x80 | (ADC_CHANNEL << 4));  // Single-ended configuration
            tx[2] = 0x00;  // Dummy byte

            if (spi_transfer(spi_fd, tx, rx, 3) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                fprintf(log_file, "%s,SPI_ERROR,,,%f,\n", 
                        asctime(localtime(&now)), ambient_temp);
                fflush(log_file);
                gpiod_line_set_value(buzzer_line, 0);  // Turn off buzzer
                usleep(SAMPLE_INTERVAL_MS * 1000);
                retries++;
                continue;
            }

            raw_adc = ((rx[1] & 0x03) << 8) | rx[2];
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", raw_adc);
            continue;
        }

        double voltage = (raw_adc * 3.3) / 1023.0;
        double compensated_voltage = voltage * (25.0 / ambient_temp);
        int flame_detected = (raw_adc > 500);  // Adjust threshold as needed

        gpiod_line_set_value(buzzer_line, flame_detected);
        log_flame_data(log_file, raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return 0;
}

