    tx[1] = (MCP3008_CHANNEL << 4) | 0x00;
    tx[2] = 0x00;

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

