#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIB 0
#define DEFAULT_MAX_CALIB 1023
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_spi(int spi_channel, int speed) {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int read_adc(int spi_fd, int adc_channel) {
    unsigned char tx[3] = {1, (adc_channel << 4) | 0x1, 0};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_moisture(const char *filename, int moisture_percent) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(file, "%s, %d%%\n", timestamp, moisture_percent);
    fclose(file);
}

void send_email(const char *recipient, const char *subject, const char *body, const char *msmtp_config) {
    FILE *fp = popen("msmtp -C", "w");
    if (!fp) {
        perror("Failed to open msmtp pipe");
        return;
    }

    fprintf(fp, "%s\n", msmtp_config);
    fprintf(fp, "To: %s\n", recipient);
    fprintf(fp, "Subject: %s\n\n", subject);
    fprintf(fp, "%s\n", body);

    if (pclose(fp) != 0) {
        perror("Failed to send email");
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calib = DEFAULT_MIN_CALIB;
    int max_calib = DEFAULT_MAX_CALIB;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;
    const char *recipient = NULL;
    const char *msmtp_config = NULL;
    const char *log_file = "plant_data.txt";

    for (int i = 1; i < argc; i += 2) {
        if (i + 1 >= argc) {
            fprintf(stderr, "Invalid argument\n");
            return 1;
        }

        if (strcmp(argv[i], "--spi-channel") == 0) {
            spi_channel = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--adc-channel") == 0) {
            adc_channel = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--min-calib") == 0) {
            min_calib = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--max-calib") == 0) {
            max_calib = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--moisture-threshold") == 0) {
            moisture_threshold = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--logging-interval") == 0) {
            logging_interval = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--recipient") == 0) {
            recipient = argv[i + 1];
        } else if (strcmp(argv[i], "--msmtp-config") == 0) {
            msmtp_config = argv[i + 1];
        } else {
            fprintf(stderr, "Unknown argument: %s\n", argv[i]);
            return 1;
        }
    }

    if (!recipient || !msmtp_config) {
        fprintf(stderr, "Recipient email and msmtp config are required\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int spi_fd = setup_spi(spi_channel, 500000);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int adc_value = read_adc(spi_fd, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        int moisture_percent = (int)((float)(adc_value - min_calib) / (max_calib - min_calib) * 100.0);
        if (moisture_percent < 0) moisture_percent = 0;
        if (moisture_percent > 100) moisture_percent = 100;

        log_moisture(log_file, moisture_percent);

        if (moisture_percent < moisture_threshold) {
            char subject[64];
            char body[256];
            snprintf(subject, sizeof(subject), "Low Soil Moisture Alert");
            snprintf(body, sizeof(body), "The soil moisture has fallen below %d%%. Current moisture: %d%%", moisture_threshold, moisture_percent);
            send_email(recipient, subject, body, msmtp_config);
        }

        sleep(logging_interval);
    }

    close(spi_fd);
    gpioTerminate();
    return 0;
}

