#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <bcm2835.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11

#define ADC_MAX_VALUE 1023
#define PRESSURE_MIN_VOLTAGE 0.1
#define PRESSURE_MAX_VOLTAGE 3.2

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_pressure(float pressure) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

float read_pressure() {
    uint16_t adc_value = bcm2835_spi_transfer16(0);

    if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
        return -1.0; // Sensor absent or stuck at 0V or 3.3V
    }

    float voltage = (float)adc_value * 3.3 / ADC_MAX_VALUE;
    return voltage * 100.0; // Assuming a 100 kPa range
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!bcm2835_init()) {
        fprintf(stderr, "Failed to initialize bcm2835 library\n");
        return 1;
    }

    bcm2835_spi_begin();
    bcm2835_spi_setBitOrder(BCM2835_SPI_BIT_ORDER_MSBFIRST);
    bcm2835_spi_setDataMode(BCM2835_SPI_MODE0);
    bcm2835_spi_setClockDivider(BCM2835_SPI_CLOCK_DIVIDER_64);
    bcm2835_spi_chipSelect(CE_PIN);
    bcm2835_spi_setChipSelectPolarity(CE_PIN, LOW);

    while (keep_running) {
        float pressure = read_pressure();

        if (pressure < 0) {
            if (pressure == -1.0) {
                fprintf(stderr, "Sensor absent or stuck at 0V or 3.3V\n");
            }
        } else {
            log_pressure(pressure);
        }

        sleep(1);
    }

    bcm2835_spi_end();
    bcm2835_close();

    return 0;
}

