#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define RELAY_PIN 17

typedef struct {
    time_t timestamp;
    int moisture_level;
    const char *pump_state;
} SensorData;

SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int pump_state = 0; // 0 = off, 1 = on

void log_data(int moisture_level) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].moisture_level = moisture_level;
    circular_buffer[buffer_index].pump_state = pump_state ? "ON" : "OFF";
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_buffer() {
    printf("Timestamp\tMoisture Level\tPump State\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld\t%d\t%s\n", circular_buffer[idx].timestamp,
               circular_buffer[idx].moisture_level,
               circular_buffer[idx].pump_state);
    }
}

void handle_signal(int signum) {
    gpioWrite(RELAY_PIN, 0); // Ensure pump is off
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        unsigned char tx[3] = {0x01, 0x80, 0x00};
        unsigned char rx[3] = {0};

        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        log_data(adc_value);
        print_buffer();

        if (adc_value < MOISTURE_LOW_THRESHOLD && !pump_state) {
            gpioWrite(RELAY_PIN, 1);
            pump_state = 1;
        } else if (adc_value > MOISTURE_HIGH_THRESHOLD && pump_state) {
            gpioWrite(RELAY_PIN, 0);
            pump_state = 0;
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

