void print_buffer() {
    printf("Timestamp\tMoisture Level\tPump State\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld\t%d\t%s\n", circular_buffer[idx].timestamp,
               circular_buffer[idx].moisture_level,
               circular_buffer[idx].pump_state);
    }
}

void handle_signal(int signum) {
    gpioWrite(RELAY_PIN, 0); // Ensure pump is off
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        unsigned char tx[3] = {0x01, 0x80, 0x00};
        unsigned char rx[3] = {0};

        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        log_data(adc_value);
        print_buffer();

        if (adc_value < MOISTURE_LOW_THRESHOLD && !pump_state) {
            gpioWrite(RELAY_PIN, 1);
            pump_state = 1;
        } else if (adc_value > MOISTURE_HIGH_THRESHOLD && pump_state) {
            gpioWrite(RELAY_PIN, 0);
            pump_state = 0;
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}
