        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int read_i2c_register(int reg) {
    char buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        error_exit("Failed to write to I2C device");
    }
    if (read(i2c_fd, buf, 1) != 1) {
        error_exit("Failed to read from I2C device");
    }
    return buf[0];
}

void write_i2c_register(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        error_exit("Failed to write to I2C device");
    }
}

