    if (ret < 0) {
        gpiod_chip_close(chip);
        error_exit("Failed to request GPIO line");
    }

    gpiod_line_set_value(line, 1);
    usleep(100000);
    gpiod_line_set_value(line, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        error_exit("Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAX30102_I2C_ADDR) < 0) {
        close(i2c_fd);
        error_exit("Failed to set I2C slave address");
    }

