    if (part_id != EXPECTED_PART_ID) {
        char error_msg[100];
        snprintf(error_msg, sizeof(error_msg), "MAX30102 not detected. PART_ID: 0x%02X\n", part_id);
        error_exit(error_msg);
    }

    while (1) {
        int spo2 = read_i2c_register(SPO2_REG);
        int heart_rate = read_i2c_register(HEART_RATE_REG);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            if (spo2 < 95) {
                fprintf(log_file, "%s SpO2: %d%%\n", timestamp, spo2);
            }
            if (heart_rate > 100) {
                fprintf(log_file, "%s Heart Rate: %d BPM\n", timestamp, heart_rate);
            }
            fclose(log_file);
        }

        sleep(1);
    }

    return 0;
}

