#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNELS 3
#define SPI_SPEED 1000000
#define RETRY_COUNT 3
#define LOG_FILE "analog_log.csv"
#define LOG_INTERVAL_MS 500

static volatile sig_atomic_t keep_running = 1;
static int spi_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

float read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 0;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    while (retries < RETRY_COUNT) {
        if (spi_transfer(tx, rx, 3) == 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        retries++;
        usleep(1000);
    }

    return -1; // Indicate failure
}

void log_voltage(int channel, float voltage) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
    fflush(log_file);
}

int main() {
    struct spi_ioc_transfer tr;
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &(int){SPI_MODE_0});
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
        fflush(log_file);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        for (int channel = 0; channel < CHANNELS; channel++) {
            float voltage = read_adc(channel);
            if (voltage >= 0) {
                voltage = voltage * (3.3 / 1023.0); // Convert to voltage
                log_voltage(channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

