        int adc_value = read_adc(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Calibration sample %d read failed, continuing\n", i);
            continue;
        }
        baseline_sum += adc_value;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }
    int baseline = baseline_sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Baseline: %d\n", baseline);

    while (keep_running) {
        int adc_value = read_adc(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, continuing\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
