            gpioWrite(RELAY_PIN, 1);
            usleep(RELAY_DURATION_MS * 1000);
            gpioWrite(RELAY_PIN, 0);

            if (gpioRead(DOOR_SENSOR_PIN) == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    close(i2c_fd);
    gpioTerminate();
    return 0;
