#include <errno.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BUS 0
#define SPI_DEVICE 0

#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

#define NUM_SENSORS 3
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL 5

static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(int cs_pin, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 1,
    };

    if (gpioWrite(cs_pin, 0) != 0) {
        fprintf(stderr, "Failed to select chip %d\n", cs_pin);
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpioWrite(cs_pin, 1);
        return -1;
    }

    gpioWrite(cs_pin, 1);
    return 0;
}

int read_adc(int cs_pin, int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};

    if (spi_transfer(cs_pin, tx, rx, 3) != 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) + rx[2];
}

void log_sensor_data(int sensor1, int sensor2, int sensor3) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);
    gpioWrite(CS2_PIN, 1);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int sensor_values[NUM_SENSORS] = {-1, -1, -1};

        for (int i = 0; i < NUM_SENSORS; i++) {
            int cs_pin = (i == 0) ? CS0_PIN : (i == 1) ? CS1_PIN : CS2_PIN;
            sensor_values[i] = read_adc(cs_pin, 0);
        }

        log_sensor_data(sensor_values[0], sensor_values[1], sensor_values[2]);
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    close(spi_fd);
    gpioTerminate();
    return 0;
}

