#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define DEFAULT_THRESHOLD 300  // 30% of 1023 (10-bit ADC range)
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000  // 1 MHz
#define SPI_MODE SPI_MODE_0
#define MOISTURE_SENSOR_CHANNEL 0
#define RELAY_PIN 18

static volatile sig_atomic_t terminate = 0;
static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;

void log_message(const char *message) {
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0';  // Remove newline
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 3;
    int adc_value = -1;

    while (retries > 0 && adc_value == -1) {
        tx[0] = 0x01;
        tx[1] = (channel << 4) | 0x00;
        tx[2] = 0x00;

        if (spi_transfer(tx, rx, 3) == 0) {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        } else {
            retries--;
            usleep(100000);  // 100ms delay before retry
        }
    }

    if (adc_value == -1) {
        log_message("Error: Failed to read ADC after 3 retries");
    }

    return adc_value;
}

void activate_pump(int duration) {
    gpiod_line_set_value(relay_line, 1);
    char message[100];
    snprintf(message, sizeof(message), "Pump activated for %d seconds", duration);
    log_message(message);
    sleep(duration);
}

void signal_handler(int signum) {
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    char spi_device_path[50];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting SPI parameters");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    while (!terminate) {
        int moisture_level = read_adc(MOISTURE_SENSOR_CHANNEL);
        if (moisture_level != -1) {
            char message[100];
            snprintf(message, sizeof(message), "Moisture level: %d (%.2f%%)", moisture_level, (float)moisture_level / 10.23 * 100);
            log_message(message);

            if (moisture_level < threshold) {
                activate_pump(pump_duration);
            }
        }

        sleep(sleep_interval);
