        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    unsigned char tx[3] = {ADC_COMMAND, 0x00, 0x00};
    unsigned char rx[3] = {0};

    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_event(int value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s, %d\n", timestamp, value);
    fflush(log_file);
}

