#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[2];
    __u8 write_buf[1] = {0};
    __u8 read_buf[2];

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, PCF8591_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        // Dummy read
        messages[0].addr = PCF8591_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = write_buf;

        // Read current sample
        messages[1].addr = PCF8591_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 2;
        messages[1].buf = read_buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        printf("%d\n", read_buf[1]);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

