#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <pigpio.h>
#include <i2c/smbus.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS 1
#define ADC_ADDR 0x48
#define SENSOR_PIN 27
#define BUFFER_SIZE 100
#define SAMPLE_RATE 1
#define THRESHOLD_GAUSS 500.0
#define ADC_VREF 3.3
#define ADC_MAX 32767

typedef struct {
    double values[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static CircularBuffer buffer = {.index = 0, .count = 0};

void cleanup(int signum) {
    syslog(LOG_INFO, "Received signal %d, cleaning up...", signum);
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    closelog();
    exit(EXIT_SUCCESS);
}

double get_average(CircularBuffer *buf) {
    double sum = 0.0;
    for (int i = 0; i < buf->count; i++) {
        sum += buf->values[i];
    }
    return sum / buf->count;
}

double adc_to_gauss(int16_t adc_value) {
    double voltage = (double)adc_value * ADC_VREF / ADC_MAX;
    if (voltage < 0 || voltage > ADC_VREF) {
        syslog(LOG_ERR, "ADC out of range: %f V", voltage);
        return 0.0;
    }
    // Assuming a linear relationship for simplicity
    return voltage * 1000.0; // Convert V to Gauss
}

void monitor_sensor() {
    int16_t adc_value;
    double gauss;

    while (1) {
        adc_value = i2c_smbus_read_word_data(i2c_fd, 0x00);
        if (adc_value < 0) {
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            sleep(1);
            continue;
        }

        gauss = adc_to_gauss(adc_value);
        buffer.values[buffer.index] = gauss;
        buffer.index = (buffer.index + 1) % BUFFER_SIZE;
        if (buffer.count < BUFFER_SIZE) {
            buffer.count++;
        }

        double avg_gauss = get_average(&buffer);
        syslog(LOG_INFO, "Current average: %.2f Gauss", avg_gauss);

        if (avg_gauss > THRESHOLD_GAUSS) {
            gpiod_line_set_value(line, 1);
            syslog(LOG_WARNING, "Threshold exceeded! Motor shutdown activated.");
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(SAMPLE_RATE);
    }
}

int main() {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "hall_sensor_monitor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    monitor_sensor();

    return EXIT_SUCCESS;
}

