static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_event(int moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

    fprintf(file, "%s - Moisture Level: %d\n", timestamp, moisture_level);
    fclose(file);
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    if (!bcm2835_spi_begin()) {
        fprintf(stderr, "SPI begin failed\n");
        return -1;
    }

    bcm2835_spi_setBitOrder(BCM2835_SPI_BIT_ORDER_MSBFIRST);
    bcm2835_spi_setDataMode(BCM2835_SPI_MODE0);
    bcm2835_spi_setClockDivider(BCM2835_SPI_CLOCK_DIVIDER_64);  // ~1.5625MHz
    bcm2835_spi_chipSelect(BCM2835_SPI_CS0);
    bcm2835_spi_setSpeedHz(ADC_SPEED);

    uint8_t adc_command[3] = {0x01, (channel << 4) | 0x00, 0x00};
    uint8_t adc_result[3] = {0};

    if (!bcm2835_spi_transfernb(adc_command, adc_result, 3)) {
        fprintf(stderr, "SPI transfer failed\n");
        bcm2835_spi_end();
        return -1;
    }

    bcm2835_spi_end();

    int adc_value = ((adc_result[1] & 0x03) << 8) | adc_result[2];
    return adc_value;
}

int main() {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        bcm2835_close();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int moisture_level = read_adc(ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading ADC\n");
            break;
        }

        if (moisture_level < MOISTURE_THRESHOLD) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            log_event(moisture_level);
            sleep(WATERING_DURATION);
        }

        sleep(CHECK_INTERVAL);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    bcm2835_close();
    return 0;
}

