#include <signal.h>
#include <errno.h>

#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_FULL_SCALE 1023.0
#define SAMPLE_INTERVAL_MS 1000

static int spi_handle;
static volatile bool running = true;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        running = false;
    }
}

bool init_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return false;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return false;
    }

    return true;
}

int read_adc() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float map_adc_to_intensity(int adc_value) {
    // This mapping is an example and should be adjusted based on the sensor's characteristics
    return (float)adc_value / ADC_FULL_SCALE * 100.0; // Assuming 100mm/h as max intensity
}

void log_sample(int adc_value, float intensity) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("%s, ADC: %d, Intensity: %.2f mm/h\n", timestamp, adc_value, intensity);
}

void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    if (!init_spi()) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            float intensity = map_adc_to_intensity(adc_value);
            log_sample(adc_value, intensity);
        }
        time_sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

