#include <errno.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define SENSOR_PIN AIN0
#define PGA_GAIN 4.096
#define SAMPLE_INTERVAL_MS 100
#define LED_PIN 17
#define BLINK_DURATION_MS 1000
#define BLINK_INTERVAL_MS 50

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

float read_sensor(int i2c_fd) {
    uint16_t config = (1 << 15) | (SENSOR_PIN << 12) | (1 << 9) | (3 << 12); // Single-shot mode,PGA=4.096V
    if (i2c_smbus_write_word_data(i2c_fd, 1, config) < 0) {
        perror("Failed to write to ADS1115");
        return -1;
    }
    usleep(8000); // Wait for conversion to complete
    int16_t adc_value = i2c_smbus_read_word_data(i2c_fd, 0);
    if (adc_value < 0) {
        perror("Failed to read from ADS1115");
        return -1;
    }
    return (adc_value * PGA_GAIN) / 32767.0;
}

void blink_led(int times) {
    for (int i = 0; i < times; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(BLINK_INTERVAL_MS * 1000);
        gpiod_line_set_value(led_line, 0);
        usleep(BLINK_INTERVAL_MS * 1000);
    }
}

int main(int argc, char *argv[]) {
    float threshold = 100.0;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        float field_strength = read_sensor(i2c_fd);
        if (field_strength < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            break;
        }
        printf("Magnetic field strength: %.2f G\n", field_strength);
        if (field_strength > threshold) {
            blink_led(20); // 1 second / 50ms = 20 blinks
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}
