static mosquitto *mosq;
static int pump_state = 0;

void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    closelog();
}

void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, exiting...", signum);
    gpiod_line_set_value(line, 0);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_moisture(void) {
    unsigned char tx[3] = {1, (8 + SPI_CHANNEL) << 4, 0};
    unsigned char rx[3] = {0};
    int adc_value = 0;

    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) + rx[2];
    return adc_value;
}

void control_pump(int new_state) {
    if (new_state != pump_state) {
        pump_state = new_state;
        gpiod_line_set_value(line, pump_state);
