        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create Mosquitto instance");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_SUBSCRIBE, 0);
    mosquitto_message_callback_set(mosq, mqtt_on_message);

    while (1) {
        int moisture = read_moisture();
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            syslog(LOG_INFO, "Moisture: %d%%", moisture);
            if (moisture < MOISTURE_THRESHOLD_LOW) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
                control_pump(0);
            }

            char payload[20];
            snprintf(payload, sizeof(payload), "%d", moisture);
            mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUBLISH, strlen(payload), payload, 0, false);
        }

        sleep(60);
        mosquitto_loop(mosq, -1, 1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

