#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define CHANNEL 0
#define VREF 3.3
#define READ_INTERVAL_MS 500

static int spi_fd;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    int ret;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Error setting SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Error setting SPI speed");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

uint16_t read_adc() {
    uint8_t tx[3] = {0x01, (CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
        return 0xFFFF;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    signal(SIGINT, cleanup);

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc();
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "Error reading ADC\n");
            cleanup(SIGINT);
        }

        float voltage = (float)adc_value * VREF / 1023.0;
        printf("Raw Value: %d, Voltage: %.3f V\n", adc_value, voltage);

        usleep(READ_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

