        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s (%s)\n", msg, strerror(errno));
    cleanup(0);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    tx[0] = 1;
    tx[1] = (MCP3008_COMMAND | (channel << 4)) & 0xEF;
    tx[2] = 0;

    if (spi_ioc_transfer(spi_fd, (struct spi_ioc_transfer[]) {
        {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .cs_change = 0,
        }
    }, 1) < 0) {
        handle_error("SPI transfer failed");
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

