#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define CSV_FILE "tamper_log.csv"
#define LOG_INTERVAL 5
#define ADC_COMMAND 0x01
#define ADC_CHANNEL 0x00

static volatile int keep_running = 1;
static int spi_fd;
static int i2c_fd;
static FILE *csv_file;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc() {
    unsigned char tx[3] = {1, (ADC_CHANNEL << 4) | 0x01, 0};
    unsigned char rx[3] = {0};
    int ret;

    ret = spi_transfer(tx, rx, 3);
    if (ret < 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int read_bh1750() {
    unsigned char data[2];
    int ret;

    usleep(180000);  // 180ms delay

    ret = write(i2c_fd, &data[0], 1);
    if (ret != 1) {
        return -1;
    }

    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(spi_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    time_t last_log_time = time(NULL);
    int error_code = 0;

    while (keep_running) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            int sound_level = read_adc();
            int light_level = read_bh1750();

            if (sound_level < 0) {
                error_code = 1;
            } else if (light_level < 0) {
                error_code = 2;
            } else {
                error_code = 0;
            }

            time_t now;
            struct tm *tm_info;
            char timestamp[20];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
            fflush(csv_file);

            last_log_time = current_time;
        }

        usleep(100000);  // Sleep for 100ms to reduce CPU usage
    }

    fclose(csv_file);
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

