#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spi.h>

#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define READING_INTERVAL 60
#define GPIO_PUMP 17
#define MAX_RETRIES 3

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_moisture(void) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_ioc_transfer(spi_fd, tx, rx, sizeof(tx)) < 0) {
            fprintf(stderr, "SPI transfer failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(100000); // 100ms delay before retry
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        return (adc_value * 100) / 1023; // Convert to percentage
    }

    fprintf(stderr, "Failed to read moisture sensor after %d attempts\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    struct spi_ioc_transfer xfer;
    int moisture;
    time_t last_reading_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PUMP);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "pump-control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PUMP);
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        moisture = read_moisture();
        if (moisture < 0) {
            fprintf(stderr, "Failed to read moisture sensor\n");
        } else {
            time_t now = time(NULL);
            printf("%s, Moisture: %d%%\n", ctime(&now), moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                if (gpiod_line_set_value(line, 1) < 0) {
                    fprintf(stderr, "Failed to activate pump\n");
                } else {
