        int fan_state = (co2_value > CO2_THRESHOLD) ? 1 : 0;
        set_fan(fan_state);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%d", timestamp, co2_value, fan_state);
        log_message(log_entry);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

