    gpioWrite(RELAY_PIN, PI_LOW);

    return 0;
}

void cleanup_gpio() {
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
}

int init_spi() {
    int spi_handle = spiOpen(CE_PIN, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }
    return spi_handle;
}

void cleanup_spi(int spi_handle) {
    spiClose(spi_handle);
}

