    return ((rx[1] & 0x03) << 8) | rx[2];
}

int read_distance(int spi_handle) {
    int adc_value = read_adc(spi_handle);
    if (adc_value < 0) return -1;

    // Convert ADC value to distance (this is a simplified conversion)
    return (int)(100.0 * (1.0 - (float)adc_value / 1023.0));
}

void log_event(int distance) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

    fprintf(log_file, "[%s] Distance: %d cm\n", timestamp, distance);
    fflush(log_file);
}

