            }
        } else if (distance >= SENSOR_THRESHOLD) {
            gpioWrite(RELAY_PIN, PI_LOW);
        }

        last_distance = distance;
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (log_file) fclose(log_file);
    cleanup_spi(spi_handle);
    cleanup_gpio();
    return 0;
}

