#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_SAMPLES 3
#define LOG_FILE "irrigation.log"
#define SOLENOID_PIN 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Gracefully shutting down...\n");
        gpioPWM(SOLENOID_PIN, 0);
        gpioTerminate();
        close(spi_fd);
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    }
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value = -1;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (write(spi_fd, tx, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("SPI read failed");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main() {
    int adc_values[ADC_SAMPLES];
    int valid_samples = 0;
    int sum = 0;
    int average = 0;
    int valve_position = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SOLENOID_PIN, PWM_FREQUENCY);
    gpioPWM(SOLENOID_PIN, 0);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("SPI device open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI ioctl failed");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Log file open failed");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("GPIO chip open failed");
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!line) {
        perror("GPIO line get failed");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "solenoid_valve", 0) < 0) {
        perror("GPIO line request output failed");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        valid_samples = 0;
        sum = 0;

        for (int i = 0; i < ADC_SAMPLES; i++) {
            adc_values[i] = read_adc(0);
            if (adc_values[i] >= 0) {
                sum += adc_values[i];
                valid_samples++;
            }
