void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Gracefully shutting down...\n");
        gpioPWM(SOLENOID_PIN, 0);
        gpioTerminate();
        close(spi_fd);
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    }
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value = -1;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (write(spi_fd, tx, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("SPI read failed");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

