#define CHANNEL 0
#define RETRY_LIMIT 5
#define MOISTURE_MIN 0
#define MOISTURE_MAX 1023

static int spi_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 0;
    int adc_value = -1;

    while (retries < RETRY_LIMIT) {
        tx[0] = 0x01;
        tx[1] = (channel << 4) | 0x00;
        tx[2] = 0x00;

        if (spi_ioc_transfer(spi_fd, (struct spi_ioc_transfer[]) {
            {
                .tx_buf = (unsigned long)tx,
                .rx_buf = (unsigned long)rx,
                .len = 3,
                .delay_usecs = 0,
                .speed_hz = SPI_SPEED,
                .bits_per_word = 8,
                .cs_change = 0,
            }
        }, 1) < 0) {
            retries++;
            usleep(100000 * (1 << retries)); // Exponential backoff
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value >= MOISTURE_MIN && adc_value <= MOISTURE_MAX) {
            break;
        }

        retries++;
        usleep(100000 * (1 << retries)); // Exponential backoff
    }

    return adc_value;
}

float adc_to_moisture(int adc_value) {
    return (float)(MOISTURE_MAX - adc_value) / (MOISTURE_MAX - MOISTURE_MIN) * 100.0;
}

int main() {
    struct spi_ioc_transfer spi;
    struct sigaction sa;

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("soil_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(CHANNEL);
        time_t now = time(NULL);
        char timestamp[26];
        ctime_r(&now, timestamp);
        timestamp[24] = '\0';

        if (adc_value >= 0) {
            float moisture = adc_to_moisture(adc_value);
            fprintf(log_file, "%s, CH%d: %d (%.2f%%)\n", timestamp, CHANNEL, adc_value, moisture);
        } else {
            fprintf(log_file, "%s, CH%d: Error - Failed to read ADC\n", timestamp, CHANNEL);
        }
        fflush(log_file);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

