#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <math.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define LDR_CHANNEL 0
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_FREQ 440
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_VOLUME 0
#define MAX_VOLUME 1023
#define CONFIG_FILE "theremin_config.txt"

static volatile int keep_running = 1;
static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static int pwm_fd;
static unsigned int last_distance = 50;
static unsigned int last_volume = 512;

void cleanup(int signum) {
    keep_running = 0;
    if (spi_fd >= 0) close(spi_fd);
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
    exit(0);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

unsigned int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x0;
    tx[2] = 0x0;

    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return last_volume;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

unsigned int measure_distance() {
    struct timespec start, end;
    unsigned long long duration;

    gpiod_line_set_value(trig_line, 1);
    nanosleep(&(struct timespec){0, 10}, NULL);
    gpiod_line_set_value(trig_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            fprintf(stderr, "Error getting time\n");
            return last_distance;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            fprintf(stderr, "Error getting time\n");
            return last_distance;
        }
    }

    duration = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    unsigned int distance = duration / 58232;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return last_distance;
    }

    last_distance = distance;
    return distance;
}

void set_pwm_duty_cycle(unsigned int duty_cycle) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open PWM duty cycle file\n");
        return;
    }
    fprintf(fp, "%u", duty_cycle);
    fclose(fp);
}

void set_pwm_frequency(unsigned int frequency) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/period");
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open PWM period file\n");
        return;
    }
    fprintf(fp, "%u", 1000000000 / frequency);
    fclose(fp);
}

void save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open config file for writing\n");
        return;
    }
    fprintf(fp, "%u %u\n", last_distance, last_volume);
    fclose(fp);
}

void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open config file for reading\n");
        return;
    }
    if (fscanf(fp, "%u %u", &last_distance, &last_volume) != 2) {
        fprintf(stderr, "Failed to read config file\n");
    }
    fclose(fp);
}

int main() {
    signal(SIGINT, cleanup);

    load_config();

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trig_line);
        close(spi_fd);
        return 1;
    }

    gpiod_line_request_output(trig_line, "theremin_trig", 0);
    gpiod_line_request_input(echo_line, "theremin_echo");

    pwm_fd = open("/sys/class/pwm/pwm0/export", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to export PWM\n");
        cleanup(0);
        return 1;
    }
    write(pwm_fd, "0", 1);
    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwm0/enable", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to enable PWM\n");
        cleanup(0);
        return 1;
    }
    write(pwm_fd, "1", 1);
    close(pwm_fd);

    set_pwm_frequency(PWM_FREQ);

    while (keep_running) {
        unsigned int distance = measure_distance();
        unsigned int volume = read_adc(LDR_CHANNEL);

        unsigned int frequency = MIN_DISTANCE + (distance - MIN_DISTANCE) * (MAX_DISTANCE - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        set_pwm_frequency(frequency);

        unsigned int duty_cycle = MIN_VOLUME + (volume - MIN_VOLUME) * (MAX_VOLUME - MIN_VOLUME) / (MAX_VOLUME - MIN_VOLUME);
        set_pwm_duty_cycle(duty_cycle);

        usleep(10000);
    }

    save_config();
    cleanup(0);
    return 0;
}

