    fprintf(fp, "%u", duty_cycle);
    fclose(fp);
}

void set_pwm_frequency(unsigned int frequency) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwm0/period");
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open PWM period file\n");
        return;
    }
    fprintf(fp, "%u", 1000000000 / frequency);
    fclose(fp);
}

void save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open config file for writing\n");
        return;
    }
    fprintf(fp, "%u %u\n", last_distance, last_volume);
    fclose(fp);
}

void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open config file for reading\n");
        return;
    }
    if (fscanf(fp, "%u %u", &last_distance, &last_volume) != 2) {
        fprintf(stderr, "Failed to read config file\n");
    }
    fclose(fp);
}

int main() {
    signal(SIGINT, cleanup);

    load_config();

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(trig_line);
        close(spi_fd);
        return 1;
    }

    gpiod_line_request_output(trig_line, "theremin_trig", 0);
    gpiod_line_request_input(echo_line, "theremin_echo");

    pwm_fd = open("/sys/class/pwm/pwm0/export", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to export PWM\n");
        cleanup(0);
        return 1;
    }
    write(pwm_fd, "0", 1);
    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwm0/enable", O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to enable PWM\n");
        cleanup(0);
        return 1;
    }
    write(pwm_fd, "1", 1);
    close(pwm_fd);

    set_pwm_frequency(PWM_FREQ);

    while (keep_running) {
        unsigned int distance = measure_distance();
        unsigned int volume = read_adc(LDR_CHANNEL);

        unsigned int frequency = MIN_DISTANCE + (distance - MIN_DISTANCE) * (MAX_DISTANCE - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        set_pwm_frequency(frequency);

        unsigned int duty_cycle = MIN_VOLUME + (volume - MIN_VOLUME) * (MAX_VOLUME - MIN_VOLUME) / (MAX_VOLUME - MIN_VOLUME);
        set_pwm_duty_cycle(duty_cycle);

        usleep(10000);
    }

    save_config();
    cleanup(0);
    return 0;
}
