void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_adc(int channel) {
    unsigned char tx[3] = {1, (channel << 4) | 0x1, 0};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int i = 0; i < RETRY_COUNT; i++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return ((rx[1] & 0x03) << 8) | rx[2];
    }
    fprintf(stderr, "Failed to read ADC after %d attempts\n", RETRY_COUNT);
    return -1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
