        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_zeros = 0;
    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            consecutive_zeros++;
            if (consecutive_zeros >= 5) {
                fprintf(stderr, "Sensor absent condition detected\n");
                consecutive_zeros = 0;
            }
        } else {
            consecutive_zeros = 0;
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        const char *status;
        if (adc_value > 50) {
            status = "Alcohol detected! Limit exceeded.";
        } else if (adc_value < 20) {
            status = "Sobriety confirmed.";
        } else {
            status = "Alcohol level within acceptable range.";
        }

        fprintf(log_file, "%s, %d ppm, %s\n", timestamp, adc_value, status);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

