#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

#define NUM_READINGS 100
#define ACCELERATION_STEPS 100
#define DECELERATION_STEPS 100
#define CONSTANT_SPEED_DURATION 2
#define REVERSE_DELAY 1

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    return 0;
}

void cleanup_gpio() {
    gpioTerminate();
}

int setup_spi() {
    if (gpioSetMode(10, PI_ALT0) < 0 ||
        gpioSetMode(9, PI_ALT0) < 0 ||
        gpioSetMode(11, PI_ALT0) < 0 ||
        gpioSetMode(8, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set SPI GPIO modes\n");
        return -1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return -1;
    }

    return 0;
}

void cleanup_spi() {
    spiClose(SPI_CHANNEL);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void set_motor_speed(int enable, int dir, int speed) {
    gpioPWM(enable, speed);
    gpioWrite(dir, speed > 0 ? 1 : 0);
}

void accelerate_motor(int enable, int dir, int target_speed) {
    for (int i = 0; i <= ACCELERATION_STEPS; i++) {
        int speed = (int)((float)target_speed * i / ACCELERATION_STEPS);
        set_motor_speed(enable, dir, speed);
        usleep(10000); // 10ms per step
    }
}

void decelerate_motor(int enable, int dir, int current_speed) {
    for (int i = ACCELERATION_STEPS; i >= 0; i--) {
        int speed = (int)((float)current_speed * i / ACCELERATION_STEPS);
        set_motor_speed(enable, dir, speed);
        usleep(10000); // 10ms per step
    }
}

int main() {
    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int adc1 = read_adc(0);
        int adc2 = read_adc(1);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            break;
        }

        int speed1 = (int)((float)adc1 / 1023.0 * 100.0);
        int speed2 = (int)((float)adc2 / 1023.0 * 100.0);

        // Accelerate Motor 1
        accelerate_motor(MOTOR1_ENABLE, MOTOR1_DIR, speed1);

        // Accelerate Motor 2
        accelerate_motor(MOTOR2_ENABLE, MOTOR2_DIR, speed2);

        // Hold constant speed
        sleep(CONSTANT_SPEED_DURATION);

        // Decelerate Motor 1
        decelerate_motor(MOTOR1_ENABLE, MOTOR1_DIR, speed1);

        // Decelerate Motor 2
        decelerate_motor(MOTOR2_ENABLE, MOTOR2_DIR, speed2);

        // Pause
        sleep(5);

        // Reverse direction
        gpioWrite(MOTOR1_DIR, 1);
        gpioWrite(MOTOR2_DIR, 0);
        sleep(REVERSE_DELAY);

        // Repeat cycle
    }

    cleanup_spi();
    cleanup_gpio();

    return EXIT_SUCCESS;
}

