#define SPI_DEVICE 0
#define MCP3008_CHANNEL 0
#define CALIBRATION_TIME 5
#define DEBOUNCE_TIME_MS 10
#define THRESHOLD 500

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpiod_line_set_value(led_line, 0);
    close(spi_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int read_adc(int channel) {
    unsigned char tx[3] = {0x01, (channel << 4) | 0x00, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    int baseline = 0;
    int last_led_state = 0;
    struct timespec last_change;

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

