    // Main loop
    printf("Monitoring sound levels...\n");
    clock_gettime(CLOCK_MONOTONIC, &last_change);
    while (1) {
        int sample = read_adc(MCP3008_CHANNEL);
        if (sample < 0) {
            cleanup(0);
        }

        if (sample > baseline + THRESHOLD) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if ((now.tv_sec - last_change.tv_sec) * 1000 +
                (now.tv_nsec - last_change.tv_nsec) / 1000000 >= DEBOUNCE_TIME_MS) {
                gpiod_line_set_value(led_line, 1);
                last_led_state = 1;
                clock_gettime(CLOCK_MONOTONIC, &last_change);
            }
        } else {
            if (last_led_state == 1) {
                gpiod_line_set_value(led_line, 0);
                last_led_state = 0;
            }
        }

        usleep(10000);  // 10ms
    }

    return 0;
}

