#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spi.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "audio_log.txt"
#define CHIP_SELECT_PIN 8
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SAMPLE_RATE 1000
#define SAMPLE_INTERVAL_NS (1000000000 / SAMPLE_RATE)

static int spi_fd;
static int log_fd;
static struct gpiod_line *cs_line;
static struct gpiod_chip *chip;

void cleanup(int signum) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(EXIT_SUCCESS);
}

int setup_spi() {
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_MAX_SPEED_HZ;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CHIP_SELECT_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(cs_line, "SPI_CS", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_log_file() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

int read_adc(uint16_t *value) {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    gpiod_line_set_value(cs_line, 0);
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    gpiod_line_set_value(cs_line, 1);

    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main() {
    struct timespec next_sample_time, current_time;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_NS};
    char log_buffer[64];
    ssize_t bytes_written;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_log_file() < 0) {
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample_time);

    while (1) {
        uint16_t adc_value;
        if (read_adc(&adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);
        int64_t timestamp_ns = (current_time.tv_sec - next_sample_time.tv_sec) * 1000000000LL +
                               (current_time.tv_nsec - next_sample_time.tv_nsec);

        snprintf(log_buffer, sizeof(log_buffer), "%lld|%u\n", timestamp_ns, adc_value);
        bytes_written = write(log_fd, log_buffer, strlen(log_buffer));
        if (bytes_written < 0) {
            perror("Failed to write to log file");
        } else {
            fsync(log_fd);
        }

        nanosleep(&sleep_time, NULL);
        clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample_time);
        next_sample_time.tv_sec += SAMPLE_INTERVAL_NS / 1000000000;
        next_sample_time.tv_nsec += SAMPLE_INTERVAL_NS % 1000000000;
        if (next_sample_time.tv_nsec >= 1000000000) {
            next_sample_time.tv_sec += 1;
            next_sample_time.tv_nsec -= 1000000000;
        }
    }

    return EXIT_SUCCESS;
}

