#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RETRY_DELAY_MS 100
#define LOG_FILE "gas_log.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

float read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retry_count = 0;

    while (retry_count < 3) {
        tx[0] = 0x01;
        tx[1] = (channel << 4) | 0x00;
        tx[2] = 0x00;

        if (spiXfer(spi_handle, tx, rx, 3) == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        retry_count++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1.0f;
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    float voltage, ppm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(0, SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        voltage = read_adc(0) * (3.3f / 1023.0f);
        if (voltage < 0) {
            fprintf(stderr, "ADC read failed\n");
            continue;
        }

        ppm = voltage * 100.0f; // Placeholder calculation

        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s - Voltage: %.2fV, PPM: %.2f\n", timestamp, voltage, ppm);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, voltage, ppm);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

