#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spi.h>
#include <math.h>

#define SPI_BUS 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define MCP3008_CHANNELS 3
#define MCP3008_CS_PIN 8
#define ADXL335_SENSITIVITY 0.0039 // 3.3V / 8192 (10-bit ADC range)
#define KALMAN_Q 0.1
#define KALMAN_R 0.1
#define SAMPLE_RATE 10
#define SAMPLE_INTERVAL (1.0 / SAMPLE_RATE)

typedef struct {
    double x, y, z;
} Vector3D;

typedef struct {
    double q;
    double r;
    double x;
    double p;
    double k;
} KalmanFilter;

static int running = 1;
static struct spi_ioc_transfer spi_xfer[MCP3008_CHANNELS];
static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void kalman_init(KalmanFilter *kf, double q, double r) {
    kf->q = q;
    kf->r = r;
    kf->x = 0;
    kf->p = 1;
    kf->k = 0;
}

double kalman_update(KalmanFilter *kf, double measurement) {
    kf->p = kf->p + kf->q;
    kf->k = kf->p / (kf->p + kf->r);
    kf->x = kf->x + kf->k * (measurement - kf->x);
    kf->p = (1 - kf->k) * kf->p;
    return kf->x;
}

void signal_handler(int signum) {
    running = 0;
}

int init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    for (int i = 0; i < MCP3008_CHANNELS; i++) {
        spi_xfer[i].tx_buf = (unsigned long)malloc(3);
        spi_xfer[i].rx_buf = (unsigned long)malloc(3);
        spi_xfer[i].len = 3;
        spi_xfer[i].delay_usecs = 0;
        spi_xfer[i].bits_per_word = 8;
        spi_xfer[i].cs_change = 0;

        if (!spi_xfer[i].tx_buf || !spi_xfer[i].rx_buf) {
            perror("Failed to allocate SPI transfer buffers");
            close(spi_fd);
            return -1;
        }
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel >= MCP3008_CHANNELS) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char tx[3] = {0x01, (8 + channel) << 4, 0x00};
    unsigned char rx[3] = {0};

    spi_xfer[channel].tx_buf = (unsigned long)tx;
    spi_xfer[channel].rx_buf = (unsigned long)rx;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer[channel]) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, MCP3008_CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "MCP3008_CS", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup() {
    for (int i = 0; i < MCP3008_CHANNELS; i++) {
        free((void *)spi_xfer[i].tx_buf);
        free((void *)spi_xfer[i].rx_buf);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (cs_line) {
        gpiod_line_release(cs_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup();
        return 1;
    }

    KalmanFilter kf_x, kf_y, kf_z;
    kalman_init(&kf_x, KALMAN_Q, KALMAN_R);
    kalman_init(&kf_y, KALMAN_Q, KALMAN_R);
    kalman_init(&kf_z, KALMAN_Q, KALMAN_R);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc_x = read_adc(0);
        int adc_y = read_adc(1);
        int adc_z = read_adc(2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            break;
        }

        double acc_x = kalman_update(&kf_x, adc_x * ADXL335_SENSITIVITY - 1.65); // Center at 0g
        double acc_y = kalman_update(&kf_y, adc_y * ADXL335_SENSITIVITY - 1.65);
        double acc_z = kalman_update(&kf_z, adc_z * ADXL335_SENSITIVITY - 1.65);

        printf("Acceleration: X=%.3f g, Y=%.3f g, Z=%.3f g\n", acc_x, acc_y, acc_z);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

