#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define READ_INTERVAL_MS 100
#define MIN_MAGNETIC_FIELD -100
#define MAX_MAGNETIC_FIELD 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct timespec sleep_time = {0, READ_INTERVAL_MS * 1000000};
    int sensor1_value, sensor2_value, sensor3_value;
    double sensor1_mT, sensor2_mT, sensor3_mT;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1_line, "DRV5055VA_Sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "DRV5055VA_Sensor2") < 0 ||
        gpiod_line_request_input(sensor3_line, "DRV5055VA_Sensor3") < 0) {
        fprintf(stderr, "Error requesting GPIO lines as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        sensor1_value = gpiod_line_get_value(sensor1_line);
        sensor2_value = gpiod_line_get_value(sensor2_line);
        sensor3_value = gpiod_line_get_value(sensor3_line);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            continue;
        }

        sensor1_mT = sensor1_value * 3.3;
        sensor2_mT = sensor2_value * 3.3;
        sensor3_mT = sensor3_value * 3.3;

        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field out of range\n");
            continue;
        }

        fprintf(log_file, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
        fflush(log_file);

        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

