#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spi.h>

#define MOISTURE_THRESHOLD 30
#define CHECK_INTERVAL 60
#define LOG_FILE "watering.log"
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    ctime_r(&now, timestamp);
    timestamp[24] = '\0';

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) & 0x70;
    tx[2] = 0x00;

    if (write(spi_fd, tx, 3) != 3) {
        log_message("SPI write error");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        log_message("SPI read error");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) + rx[2];
    return adc_value;
}

void set_pump(int on) {
    int err;
    if (on) {
        err = gpiod_line_set_value(line, 1);
    } else {
        err = gpiod_line_set_value(line, 0);
    }

    if (err < 0) {
        log_message("Failed to set GPIO value");
    }
}

void signal_handler(int signum) {
    log_message("Shutting down...");
    set_pump(0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int adc_value;
    int pump_state = 0;

    log_message("Program started");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "watering_pump", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer spi_xfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
