#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int reconnect_delay = 1;

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (mosq) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        mosq = NULL;
    }
}

void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result != 0) {
        log_error("Connection failed");
        return;
    }
    log_error("Connected to MQTT broker");
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to subscribe");
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    cJSON *json = cJSON_Parse((const char *)msg->payload);
    if (!json) {
        log_error("Failed to parse JSON");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state)) {
        log_error("Invalid JSON format: led_state must be a boolean");
        cJSON_Delete(json);
        return;
    }

    bool state = cJSON_IsTrue(led_state);
    int rc = gpiod_line_set_value(line, state ? 1 : 0);
    if (rc < 0) {
        log_error("Failed to set GPIO value");
    }

    cJSON_Delete(json);
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_error("Disconnected from MQTT broker");
    while (1) {
        log_error("Attempting to reconnect in %d seconds...", reconnect_delay);
        sleep(reconnect_delay);
        int ret = mosquitto_reconnect(mosq);
        if (ret == MOSQ_ERR_SUCCESS) {
            log_error("Reconnected successfully");
            reconnect_delay = 1;
            return;
        }
        if (reconnect_delay < MAX_RECONNECT_DELAY) {
            reconnect_delay *= 2;
        }
    }
}

void signal_handler(int signum) {
    log_error("Received signal, cleaning up...");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    int rc = gpiod_line_request_output(line, "LED Control", 0);
    if (rc < 0) {
        log_error("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client instance");
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        cleanup();
        return EXIT_FAILURE;
    }

    int loop_rc;
    do {
        loop_rc = mosquitto_loop(mosq, -1, 1);
    } while (loop_rc == MOSQ_ERR_SUCCESS);

    log_error("MQTT loop terminated");
    cleanup();
    return EXIT_FAILURE;
}

