#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_PATH "/dev/gpiochip0"
#define LINE_OFFSET 17
#define CONSUMER_LABEL "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    struct sigaction sa;
    int ret;

    // Set up signal handlers
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open(CHIP_PATH);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    ret = gpiod_line_request_falling_edge_events(line, CONSUMER_LABEL);
    if (ret < 0) {
        perror("Failed to request GPIO line events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t now;
            char timestamp[64];
            struct tm *tm_info;

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "[%s] Vibration detected, initiating shutdown\n", timestamp);
            printf("[%s] Vibration detected, initiating shutdown\n", timestamp);
            fflush(log_file);

            system("sudo shutdown -h now");
        }
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

