#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CONTROL 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESSDATA 0xF7
#define BMP280_REG_TEMPDATA 0xFA

#define I2C_BUS 1
#define LOG_FILE "altitude_log.txt"
#define SAMPLE_INTERVAL 5

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

uint8_t bmp280_read_chip_id() {
    uint8_t id;
    if (i2c_read(i2c_fd, BMP280_REG_CHIPID, &id, 1) != 1) {
        fprintf(stderr, "Error reading BMP280 chip ID\n");
        return 0;
    }
    return id;
}

void bmp280_init() {
    // Set up for normal mode, 1x oversampling
    i2c_write(i2c_fd, BMP280_REG_CONFIG, 0x04);
    i2c_write(i2c_fd, BMP280_REG_CONTROL, 0x3F);
}

int bmp280_read_raw(int32_t *temp, int32_t *press) {
    uint8_t buf[8];
    if (i2c_read(i2c_fd, BMP280_REG_PRESSDATA, buf, 8) != 8) {
        fprintf(stderr, "Error reading BMP280 raw data\n");
        return -1;
    }
    *press = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    *temp = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

float compensate_temperature(int32_t raw_temp) {
    // Placeholder for temperature compensation
    return raw_temp / 100.0f;
}

float compensate_pressure(int32_t raw_press) {
    // Placeholder for pressure compensation
    return raw_press / 256.0f;
}

float calculate_altitude(float pressure) {
    // Placeholder for altitude calculation
    return 44330.0f * (1.0f - pow(pressure / 1013.25f, 0.1903f));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_read_chip_id() != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not detected\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bmp280_init();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int32_t raw_temp, raw_press;
        if (bmp280_read_raw(&raw_temp, &raw_press) == 0) {
            float temp = compensate_temperature(raw_temp);
            float press = compensate_pressure(raw_press);
            float altitude = calculate_altitude(press);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f\n", timestamp, altitude);
            fflush(log_file);
        }
        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

