#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define CHIP_SELECT_PIN 8

typedef struct {
    float temperatures[BUFFER_SIZE];
    int index;
} CircularBuffer;

static int spi_fd;
static CircularBuffer buffer = { .index = 0 };
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

float read_temperature() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value * (3.3 / 1023.0) * 100.0; // Convert to temperature in Celsius
}

void write_to_file() {
    FILE *file = fopen("temp_log.dat", "wb+");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer.index + i) % BUFFER_SIZE;
        if (fwrite(&buffer.temperatures[idx], sizeof(float), 1, file) != 1) {
            perror("Failed to write to file");
            fclose(file);
            return;
        }
    }

    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CHIP_SELECT_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "SPI_CS", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature = read_temperature();
        if (temperature >= 0) {
            buffer.temperatures[buffer.index] = temperature;
            buffer.index = (buffer.index + 1) % BUFFER_SIZE;

            printf("Temperature: %.2f °C\n", temperature);
            write_to_file();
        }

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

