#define LOG_FILE "environmental_log.txt"

int i2c_fd;
int spi_fd;
volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer error");
        return -1;
    }
    return 0;
}

int read_bh1750() {
    uint8_t cmd = 0x20; // Power on, continuous mode
    if (i2c_write(i2c_fd, &cmd, 1) < 0) return -1;
    usleep(180000); // Wait for measurement

    uint8_t data[2];
    if (i2c_read(i2c_fd, data, 2) < 0) return -1;
    return (data[0] << 8) | data[1];
}

int read_max4466() {
    uint8_t cmd = 0x40; // Start single conversion
    if (i2c_write(i2c_fd, &cmd, 1) < 0) return -1;
    usleep(70000); // Wait for conversion

    uint8_t data[2];
    if (i2c_read(i2c_fd, data, 2) < 0) return -1;
    return (data[0] << 4) | (data[1] >> 4);
}

int read_mcp3008(int channel) {
    uint8_t tx[3] = {0x01, (8 + channel) << 4, 0x00};
    uint8_t rx[3] = {0};
    if (spi_transfer(spi_fd, tx, rx, 3) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

