    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("I2C BH1750 address set error");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(MCP3008_SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI bus open error");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Log file open error");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    time_t last_log_time = 0;

    while (keep_running) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;

            int light = read_bh1750();
            int sound = read_max4466();
            int adc_value = read_mcp3008(MCP3008_CHANNEL);

            if (light >= 0 && sound >= 0 && adc_value >= 0) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                fprintf(log_file, "%s, Light: %d, Sound: %d, ADC: %d\n", timestamp, light, sound, adc_value);
                fflush(log_file);
            }
        }
        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    fclose(log_file);
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

