#define PIN 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s: %s\n", msg, strerror(errno));
    cleanup(0);
    exit(EXIT_FAILURE);
}

int main() {
    struct timespec ts = {1, 0};
    int value;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    line = gpiod_chip_get_line(chip, PIN);
    if (!line) {
        handle_error("Failed to get GPIO line");
    }

    int ret = gpiod_line_request_input(line, "flame-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        handle_error("Failed to request line as input");
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    while (1) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            handle_error("Failed to read GPIO line");
        }

        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d\n", timestamp, PIN, value);
        fflush(log_file);

        if (value == 1) {
            printf("ALARM: Flame detected!\n");
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}

