#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_BUS "/dev/i2c-1"
#define MCP4725_ADDR 0x60
#define TMP36_VREF 3.3
#define TMP36_COEFF 100.0
#define TMP36_OFFSET 0.5
#define MCP3008_COMMAND 0x01
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL 500000 // 0.5 seconds in microseconds

static int spi_fd;
static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    printf("Cleanup complete. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    tx[0] = 1;
    tx[1] = (MCP3008_COMMAND << 4) | (channel & 0x07);
    tx[2] = 0;

    if (spi_transfer(tx, rx, 3) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int write_dac(int value) {
    unsigned char data[3];
    data[0] = 0x40; // Write command
    data[1] = (value >> 8) & 0xFF;
    data[2] = value & 0xFF;

    if (write(i2c_fd, data, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI device open failed");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open failed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("I2C slave address set failed");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Log file open failed");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC. Retrying...\n");
            usleep(SAMPLE_INTERVAL);
            continue;
        }

        float voltage = (adc_value * TMP36_VREF) / 1023.0;
        float temperature = (voltage - TMP36_OFFSET) * TMP36_COEFF;

        int dac_value = (int)((temperature / 100.0) * 4095.0);
        if (write_dac(dac_value) < 0) {
            fprintf(stderr, "Failed to write DAC. Retrying...\n");
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %d, %.2f°C, %.3fV\n", timestamp, adc_value, temperature, voltage);
        printf("%s, %d, %.2f°C, %.3fV\n", timestamp, adc_value, temperature, voltage);

        fflush(log_file);
        usleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

