#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS[NUM_RELAYS] = {17, 22, 23, 24}
#define ACTIVE_HIGH 1
#define INACTIVE_LOW 0
#define DELAY_SECONDS 1

// GPIO chip and line descriptors
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];

// Signal handler function
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);

    // Set all relays to inactive
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], INACTIVE_LOW);
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    exit(EXIT_SUCCESS);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines for relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for pin %d\n", RELAY_PINS[i]);
            signal_handler(SIGINT);
        }

        int ret = gpiod_line_request_output(lines[i], "relay", INACTIVE_LOW);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for pin %d\n", RELAY_PINS[i]);
            signal_handler(SIGINT);
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            // Activate relay
            int ret = gpiod_line_set_value(lines[i], ACTIVE_HIGH);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for pin %d\n", RELAY_PINS[i]);
                signal_handler(SIGINT);
            }
            sleep(DELAY_SECONDS);

            // Deactivate relay
            ret = gpiod_line_set_value(lines[i], INACTIVE_LOW);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for pin %d\n", RELAY_PINS[i]);
                signal_handler(SIGINT);
            }
            sleep(DELAY_SECONDS);
        }
    }

    return EXIT_SUCCESS;
}

