#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <bcm2835.h>

#define ADC_CHANNEL 0
#define THRESHOLD 500
#define DEBOUNCE_DELAY 500
#define LED_PIN 16
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (led_line) {
        gpiod_line_release(led_line);
    }

    gpioTerminate();
    exit(0);
}

void log_event() {
    FILE *log_file = fopen("sound_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

    fprintf(log_file, "%s - Sound event detected\n", timestamp);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (!bcm2835_init()) {
        fprintf(stderr, "Failed to initialize BCM2835 library\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    bcm2835_spi_begin();
    bcm2835_spi_setBitOrder(BCM2835_SPI_BIT_ORDER_MSBFIRST);
    bcm2835_spi_setDataMode(BCM2835_SPI_MODE0);
    bcm2835_spi_setClockDivider(BCM2835_SPI_CLOCK_DIVIDER_64);  // 1MHz
    bcm2835_spi_chipSelect(BCM2835_SPI_CS0);
    bcm2835_spi_setChipSelectPolarity(BCM2835_SPI_CS0, LOW);

    signal(SIGINT, cleanup);

    while (1) {
        uint8_t adc_value[3];
        adc_value[0] = 0x01;
        adc_value[1] = (ADC_CHANNEL << 4) | 0x08;
        adc_value[2] = 0x00;

        if (!bcm2835_spi_transfernb(adc_value, adc_value, 3)) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int value = ((adc_value[1] & 0x03) << 8) | adc_value[2];

        if (value > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            log_event();
            usleep(500000);  // 500ms
            gpiod_line_set_value(led_line, 0);
            usleep(DEBOUNCE_DELAY * 1000);  // Debounce delay
        }

        usleep(10000);  // 10ms sampling interval
    }

    return 0;
}

