#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD_TIME 3
#define MOTOR_REVERSE_TIME 3
#define PWM_DUTY 150

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    int spi_handle;
    FILE *log_file;
    char buffer[256];
    unsigned char spi_data[3];
    int rain_level;
    struct timespec sleep_time = {1, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, 17);
    lines[1] = gpiod_chip_get_line(chip, 18);
    lines[2] = gpiod_chip_get_line(chip, 27);

    if (!lines[0] || !lines[1] || !lines[2]) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(lines[0], "rain_motor_in1", 0) < 0 ||
        gpiod_line_request_output(lines[1], "rain_motor_in2", 0) < 0 ||
        gpiod_line_request_software_pwm(lines[2], "rain_motor_pwm", 0, 255) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        spi_data[0] = 0x01;
        spi_data[1] = 0x80;
        spi_data[2] = 0x00;

        if (spiXfer(spi_handle, spi_data, sizeof(spi_data), NULL, sizeof(spi_data), 0) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            break;
        }

        rain_level = ((spi_data[1] & 0x03) << 8) | spi_data[2];

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %d\n", buffer, rain_level);
        fflush(log_file);

        if (rain_level > RAIN_THRESHOLD) {
            gpiod_line_set_value(lines[0], 1);
            gpiod_line_set_value(lines[1], 0);
            gpiod_line_set_value(lines[2], PWM_DUTY);
            sleep(MOTOR_FORWARD_TIME);
        } else {
            gpiod_line_set_value(lines[0], 0);
            gpiod_line_set_value(lines[1], 1);
            gpiod_line_set_value(lines[2], PWM_DUTY);
            sleep(MOTOR_REVERSE_TIME);
        }

        nanosleep(&sleep_time, NULL);
    }

    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_chip_close(chip);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

