#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define RETRY_DELAY 1

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_distance(int distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        chip = gpiod_chip_open("/dev/gpiochip0");
        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip\n");
            sleep(RETRY_DELAY);
            continue;
        }

        line = gpiod_chip_get_line(chip, GPIO_PIN);
        if (!line) {
            fprintf(stderr, "Error getting GPIO line\n");
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        int ret = gpiod_line_request_input(line, "GP2Y0A21YK0F");
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line as input\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        while (keep_running) {
            value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO line\n");
                break;
            }

            int distance = value ? 0 : 1000;  // Assuming 1000mm for binary 1
            log_distance(distance);

            if (distance < 200) {
                printf("Feeder Activated\n");
            } else {
                printf("Feeder Idle\n");
            }

            sleep(1);  // Read every second
        }

        gpiod_line_release(line);
        gpiod_chip_close(chip);
        sleep(RETRY_DELAY);
    }

    return 0;
}

