#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 500000
#define ADC_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define PUMP_GPIO 17
#define LOG_FILE "soil_moisture.log"

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *pump_line;
static FILE *log_file;

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (pump_line) {
        gpiod_line_release(pump_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        gpiod_line_set_value(pump_line, 0);
        cleanup();
        exit(0);
    }
}

static int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

static int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value) {
    // Assuming a linear relationship between ADC value and moisture percentage
    // Adjust the coefficients based on your sensor's characteristics
    return (float)adc_value / 1023.0 * 100.0;
}

static void log_sample(float moisture, int pump_status) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    int adc_value;
    float moisture;
    int pump_status = 0;

    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to configure SPI");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) {
        perror("Failed to get GPIO line for pump");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture_pump", 0) < 0) {
        perror("Failed to request GPIO line for pump");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (1) {
        adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(5);
            continue;
        }

        moisture = adc_to_moisture(adc_value);
        if (moisture < 0 || moisture > 100) {
            fprintf(stderr, "Invalid moisture value: %.2f%%\n", moisture);
            sleep(5);
            continue;
        }

        pump_status = (moisture < MOISTURE_THRESHOLD);
        gpiod_line_set_value(pump_line, pump_status);

        log_sample(moisture, pump_status);

        sleep(60);
    }

    return 0;
}

