#include <bcm2835.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define LED_PIN 21
#define LOG_FILE "magnetic_log.txt"
#define FIELD_THRESHOLD 10.0
#define SAMPLE_INTERVAL_MS 100

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

float read_adc() {
    unsigned char tx[3] = {1, (ADC_CHANNEL << 4) | 0x1, 0};
    unsigned char rx[3] = {0};
    if (write(spi_fd, tx, 3) != 3 || read(spi_fd, rx, 3) != 3) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float adc_to_field(float adc_value) {
    // Assuming a linear relationship for simplicity
    return adc_value * 3.3 / 1023.0 * 1000.0; // Convert to mT
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835 initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bcm2835_spi_begin();
    bcm2835_spi_setBitOrder(BCM2835_SPI_BIT_ORDER_MSBFIRST);
    bcm2835_spi_setDataMode(BCM2835_SPI_MODE0);
    bcm2835_spi_setClockDivider(BCM2835_SPI_CLOCK_DIVIDER_64);
    bcm2835_spi_chipSelect(BCM2835_SPI_CS0);
    bcm2835_spi_setChipSelectPolarity(BCM2835_SPI_CS0, LOW);

    spi_fd = bcm2835_spi_getFd();
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to get SPI file descriptor\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        float adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        float field_strength = adc_to_field(adc_value);
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %.2f mT\n", timestamp, field_strength);
        fflush(log_file);

        if (field_strength > FIELD_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

