int main() {
    signal(SIGINT, cleanup);

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(CHANNEL);
        if (adc_value < 0) {
            log_moisture(-1);
        } else {
            log_moisture(adc_value);
        }
        sleep(READ_INTERVAL);
    }

    return EXIT_SUCCESS;
}
