#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "current_log.txt"
#define CURRENT_SENSOR_MIN_VOLTAGE 0.0
#define CURRENT_SENSOR_MAX_VOLTAGE 5.0
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t terminate = 0;

void sigint_handler(int signum) {
    terminate = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_handle;
    FILE *log_file;
    char buffer[64];
    time_t raw_time;
    struct tm *time_info;
    unsigned char adc_data[3];
    float voltage, current;

    // Initialize GPIO and SPI
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "MLX91211_CS", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(0, SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!terminate) {
        // Read ADC value
        memset(adc_data, 0, sizeof(adc_data));
        if (spiXfer(spi_handle, (char *)adc_data, (char *)adc_data, 3) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Convert ADC value to voltage
        voltage = ((adc_data[1] & 0x03) << 8 | adc_data[2]) * (CURRENT_SENSOR_MAX_VOLTAGE / 1023.0);

        if (voltage < CURRENT_SENSOR_MIN_VOLTAGE || voltage > CURRENT_SENSOR_MAX_VOLTAGE) {
            fprintf(stderr, "Voltage out of range: %.2f V\n", voltage);
            continue;
        }

        // Convert voltage to current (assuming a linear relationship)
        current = voltage * 10.0; // Adjust this factor based on your sensor's characteristics

        // Get current time
        time(&raw_time);
        time_info = localtime(&raw_time);

        // Format and write to log file
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(log_file, "%s %.2f A\n", buffer, current);
        fflush(log_file);

        gpiod_line_set_value(line, 0);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
        gpiod_line_set_value(line, 1);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return EXIT_SUCCESS;
}

