#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define CHIP "gpiochip0"
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_READS 5
#define DEBOUNCE_DELAY_US 2000
#define LOG_INTERVAL_SEC 1

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;

void cleanup(int signum) {
    printf("Cleaning up GPIO resources...\n");
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int read_sensor(struct gpiod_line *line) {
    int count_1 = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            return -1;
        }
        if (value == 0) count_1++;
        usleep(DEBOUNCE_DELAY_US);
    }
    return (count_1 > DEBOUNCE_READS / 2) ? 0 : 1;
}

int main() {
    int ret;

    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting line for sensor 1: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting line for sensor 2: %s\n", strerror(errno));
        goto cleanup_sensor1;
    }

    ret = gpiod_line_request_input(sensor1_line, "sensor1");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for sensor 1: %s\n", strerror(errno));
        goto cleanup_sensor2;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for sensor 2: %s\n", strerror(errno));
        goto cleanup_sensor1;
    }

    signal(SIGINT, cleanup);

    while (1) {
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensors\n");
            goto cleanup_sensor2;
        }

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        } else {
            printf("%d\n", sensor1_state | sensor2_state);
        }

        sleep(LOG_INTERVAL_SEC);
    }

cleanup_sensor2:
    gpiod_line_release(sensor2_line);
cleanup_sensor1:
    gpiod_line_release(sensor1_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

