#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define PIR_PIN 17
#define DEBOUNCE_TIME_MS 200
#define POLL_INTERVAL_MS 50
#define SNAPSHOT_DIR "/home/pi/security_cam/"
#define SNAPSHOT_COMMAND "libcamera-still"
#define SNAPSHOT_FORMAT "-o"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int pir_state = 0;
    int last_state = 0;
    struct timespec debounce_time, poll_time;
    clock_gettime(CLOCK_MONOTONIC, &debounce_time);

    openlog("pir_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting PIR sensor monitoring");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "PIR_Sensor") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as input: %s", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state != last_state) {
            clock_gettime(CLOCK_MONOTONIC, &debounce_time);
            last_state = current_state;
        }

        clock_gettime(CLOCK_MONOTONIC, &poll_time);
        if ((poll_time.tv_sec - debounce_time.tv_sec) * 1000 +
            (poll_time.tv_nsec - debounce_time.tv_nsec) / 1000000 >= DEBOUNCE_TIME_MS) {
            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected");
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char filename[256];
                snprintf(filename, sizeof(filename), "%smotion_%04d%02d%02dT%02d%02d%02d.jpg",
                         SNAPSHOT_DIR, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                         tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

                mkdir(SNAPSHOT_DIR, 0755);

                pid_t pid = fork();
                if (pid == 0) {
                    execlp(SNAPSHOT_COMMAND, SNAPSHOT_COMMAND, SNAPSHOT_FORMAT, filename, NULL);
                    syslog(LOG_ERR, "Failed to execute %s: %s", SNAPSHOT_COMMAND, strerror(errno));
                    exit(EXIT_FAILURE);
                } else if (pid > 0) {
                    int status;
                    waitpid(pid, &status, 0);
                    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                        syslog(LOG_INFO, "Snapshot captured successfully: %s", filename);
                    } else {
                        syslog(LOG_ERR, "Snapshot capture failed");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to fork: %s", strerror(errno));
                }
            }
        }

        nanosleep(&(struct timespec){0, POLL_INTERVAL_MS * 1000000}, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    syslog(LOG_INFO, "Shutting down PIR sensor monitoring");

    return EXIT_SUCCESS;
}

