#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define BUFFER_COUNT 1
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)

static int fd = -1;
static char *buffer = NULL;
static int buffer_fd = -1;
static int stop_streaming = 0;

void cleanup(int signum) {
    stop_streaming = 1;
}

void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    int frame_count = 1;
    struct sigaction sa;

    // Open device
    fd = open(device, O_RDWR);
    if (fd == -1) handle_error("Failed to open device");

    // Set up signal handlers
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set format to grayscale
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) handle_error("Failed to set format");

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) handle_error("Failed to request buffers");

    // Map buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) handle_error("Failed to query buffer");

        buffer_fd = open(device, O_RDWR);
        if (buffer_fd == -1) handle_error("Failed to open device for buffer");

        buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, buffer_fd, buf.m.offset);
        if (buffer == MAP_FAILED) handle_error("Failed to map buffer");

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) handle_error("Failed to queue buffer");
    }

    // Start streaming
    int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) handle_error("Failed to start streaming");

    while (!stop_streaming) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) continue;
            handle_error("Select failed");
        }

        if (r == 0) {
            fprintf(stderr, "Timeout occurred\n");
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            handle_error("Failed to dequeue buffer");
        }

        char filename[20];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count++);
        FILE *file = fopen(filename, "wb");
        if (!file) handle_error("Failed to open output file");

        fprintf(file, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        if (fwrite(buffer, IMAGE_SIZE, 1, file) != 1) handle_error("Failed to write image data");

        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) handle_error("Failed to requeue buffer");
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) handle_error("Failed to stop streaming");

    // Clean up
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (munmap(buffer, IMAGE_SIZE) == -1) handle_error("Failed to unmap buffer");
        close(buffer_fd);
    }

    close(fd);

    return 0;
}

