#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define FRAME_LOG_FILE "frame_log.txt"
#define DEVICE_NAME "/dev/video0"
#define IOCTL_CHECK(expr) \
    do { \
        if ((expr) == -1) { \
            perror("ioctl"); \
            goto cleanup; \
        } \
    } while (0)

static int fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    IOCTL_CHECK(ioctl(fd, VIDIOC_QUERYCAP, &cap));

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    IOCTL_CHECK(ioctl(fd, VIDIOC_S_FMT, &fmt));

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    IOCTL_CHECK(ioctl(fd, VIDIOC_REQBUFS, &req));

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        IOCTL_CHECK(ioctl(fd, VIDIOC_QUERYBUF, &buf));

        void *mapped = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mapped == MAP_FAILED) {
            perror("mmap");
            return -1;
        }

        IOCTL_CHECK(ioctl(fd, VIDIOC_QBUF, &buf));
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    IOCTL_CHECK(ioctl(fd, VIDIOC_STREAMON, &type));

    return 0;
}

void cleanup() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        struct v4l2_requestbuffers req;
        memset(&req, 0, sizeof(req));
        req.count = 4;
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;
        ioctl(fd, VIDIOC_REQBUFS, &req);

        for (unsigned int i = 0; i < req.count; ++i) {
            struct v4l2_buffer buf;
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;
            ioctl(fd, VIDIOC_QUERYBUF, &buf);
            munmap((void *)buf.m.offset, buf.length);
        }

        close(fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_device() != 0) {
        fprintf(stderr, "Failed to initialize device\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(FRAME_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int ret;

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 1;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        } else if (ret == 0) {
            continue;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        IOCTL_CHECK(ioctl(fd, VIDIOC_DQBUF, &buf));

        struct timeval timestamp;
        gettimeofday(&timestamp, NULL);
        fprintf(log_file, "%ld.%06ld\n", timestamp.tv_sec, timestamp.tv_usec);
        fflush(log_file);

        IOCTL_CHECK(ioctl(fd, VIDIOC_QBUF, &buf));
    }

    cleanup();
    return EXIT_SUCCESS;
}

