#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define BUFFER_COUNT 4
#define MAX_FRAGMENT_SIZE 65000
#define HEADER_SIZE 16

static int fd = -1;
static void *buffers[BUFFER_COUNT];
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static int sockfd = -1;
static struct sockaddr_in dest_addr;
static volatile sig_atomic_t keep_running = 1;

static void cleanup(int signum) {
    keep_running = 0;
}

static void check(int res, const char *msg) {
    if (res < 0) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

static void init_camera() {
    struct v4l2_format fmt;
    fd = open("/dev/video0", O_RDWR);
    check(fd, "Opening video device");

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    check(ioctl(fd, VIDIOC_REQBUFS, &req), "Requesting buffers");

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        check(ioctl(fd, VIDIOC_QUERYBUF, &buf), "Querying buffer");

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        check((long)buffers[i], "Mapping buffer");
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    check(ioctl(fd, VIDIOC_S_FMT, &fmt), "Setting pixel format");

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        check(ioctl(fd, VIDIOC_QBUF, &buf), "Queueing buffer");
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    check(ioctl(fd, VIDIOC_STREAMON, &type), "Starting capture");
}

static void send_fragment(int frame_index, int fragment_index, int total_fragments, int payload_size, const void *data) {
    char header[HEADER_SIZE];
    memcpy(header, &frame_index, sizeof(int));
    memcpy(header + 4, &fragment_index, sizeof(int));
    memcpy(header + 8, &total_fragments, sizeof(int));
    memcpy(header + 12, &payload_size, sizeof(int));

    struct iovec iov[2] = {
        {.iov_base = header, .iov_len = HEADER_SIZE},
        {.iov_base = (void *)data, .iov_len = payload_size}
    };

    struct msghdr msg = {
        .msg_iov = iov,
        .msg_iovlen = 2
    };

    check(sendmsg(sockfd, &msg, 0), "Sending fragment");
}

static void capture_and_send() {
    int frame_index = 0;
    while (keep_running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv = {0, 1000000}; // 1 second timeout
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            perror("Select");
            continue;
        }

        if (r == 0) {
            fprintf(stderr, "Select timeout\n");
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        check(ioctl(fd, VIDIOC_DQBUF, &buf), "Dequeuing buffer");

        int total_fragments = (buf.bytesused + MAX_FRAGMENT_SIZE - 1) / MAX_FRAGMENT_SIZE;
        for (int i = 0; i < total_fragments; i++) {
            int offset = i * MAX_FRAGMENT_SIZE;
            int payload_size = (buf.bytesused - offset > MAX_FRAGMENT_SIZE) ? MAX_FRAGMENT_SIZE : buf.bytesused - offset;
            send_fragment(frame_index, i, total_fragments, payload_size, (char *)buffers[buf.index] + offset);
        }

        check(ioctl(fd, VIDIOC_QBUF, &buf), "Requeuing buffer");
        frame_index++;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <API call 1> <API call 2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "CSI_CAMERA_POWER", 1);
    if (ret < 0) {
        perror("Requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    init_camera();

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    check(sockfd, "Creating socket");

    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(12345);
    dest_addr.sin_addr.s_addr = inet_addr("192.168.1.100");

    capture_and_send();

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(fd, VIDIOC_STREAMOFF, &type);

    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buffers[i], buf.length);
    }

    close(fd);
    close(sockfd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

