    exit(EXIT_FAILURE);
}

static void sigint_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    if (mmap_ptr != MAP_FAILED) {
        munmap(mmap_ptr, buf.length);
    }
    if (file) {
        fclose(file);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(EXIT_SUCCESS);
}

