    if (!file) {
        errno_exit("Opening Output File");
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        errno_exit("Dequeuing Buffer");
    }

    if (buf.bytesused > 0) {
        if (fwrite(mmap_ptr, 1, buf.bytesused, file) != buf.bytesused) {
            errno_exit("Writing to File");
        }
    } else {
        fprintf(stderr, "Dequeued buffer has zero bytes used\n");
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        errno_exit("Re-queueing Buffer");
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        errno_exit("Stopping Streaming");
    }

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(mmap_ptr, buf.length) == -1) {
            errno_exit("Unmapping Buffer");
        }
    }

    if (fclose(file) != 0) {
        errno_exit("Closing Output File");
    }

    if (close(fd) == -1) {
        errno_exit("Closing Device");
    }

    printf("Image captured successfully\n");
    return 0;
