#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define MIN_DUTY 50
#define MAX_DUTY 100
#define MID_DUTY 75
#define DUTY_RANGE (MAX_DUTY - MIN_DUTY)
#define POSITION_RANGE (125 - 25)
#define POSITION_STEP 5

static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo, *tilt_servo, *tilt_up, *tilt_down, *pan_left, *pan_right;
static int pan_position = MID_DUTY;
static int tilt_position = MID_DUTY;

void cleanup(int signum) {
    gpiod_line_release(pan_servo);
    gpiod_line_release(tilt_servo);
    gpiod_line_release(tilt_up);
    gpiod_line_release(tilt_down);
    gpiod_line_release(pan_left);
    gpiod_line_release(pan_right);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    int duty_us = (duty_cycle * PWM_PERIOD_US) / 1000;
    struct timespec on_time = {0, duty_us * 1000};
    struct timespec off_time = {0, (PWM_PERIOD_US - duty_us) * 1000};

    if (gpiod_line_set_value(line, 1) < 0) return -1;
    nanosleep(&on_time, NULL);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    nanosleep(&off_time, NULL);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    pan_servo = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_servo = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    tilt_up = gpiod_chip_get_line(chip, TILT_UP_PIN);
    tilt_down = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    pan_left = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    pan_right = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_servo || !tilt_servo || !tilt_up || !tilt_down || !pan_left || !pan_right) {
        perror("gpiod_chip_get_line");
        cleanup(0);
    }

    if (gpiod_line_request_output(pan_servo, "pan_servo", 0) < 0 ||
        gpiod_line_request_output(tilt_servo, "tilt_servo", 0) < 0 ||
        gpiod_line_request_input(tilt_up, "tilt_up") < 0 ||
        gpiod_line_request_input(tilt_down, "tilt_down") < 0 ||
        gpiod_line_request_input(pan_left, "pan_left") < 0 ||
        gpiod_line_request_input(pan_right, "pan_right") < 0) {
        perror("gpiod_line_request");
        cleanup(0);
    }

    while (1) {
        if (set_pwm_duty_cycle(pan_servo, pan_position) < 0 ||
            set_pwm_duty_cycle(tilt_servo, tilt_position) < 0) {
            perror("set_pwm_duty_cycle");
            cleanup(0);
        }

        if (gpiod_line_get_value(tilt_up) == 0) {
            tilt_position = (tilt_position + POSITION_STEP <= MAX_DUTY) ? tilt_position + POSITION_STEP : MAX_DUTY;
            usleep(100000);  // Debounce
        }
        if (gpiod_line_get_value(tilt_down) == 0) {
            tilt_position = (tilt_position - POSITION_STEP >= MIN_DUTY) ? tilt_position - POSITION_STEP : MIN_DUTY;
            usleep(100000);  // Debounce
        }
        if (gpiod_line_get_value(pan_left) == 0) {
            pan_position = (pan_position + POSITION_STEP <= MAX_DUTY) ? pan_position + POSITION_STEP : MAX_DUTY;
            usleep(100000);  // Debounce
        }
        if (gpiod_line_get_value(pan_right) == 0) {
            pan_position = (pan_position - POSITION_STEP >= MIN_DUTY) ? pan_position - POSITION_STEP : MIN_DUTY;
            usleep(100000);  // Debounce
        }

        usleep(50000);  // 50ms polling interval
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

