#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static void *buffer = NULL;
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static int n_buffers;
static unsigned char *yuyv_data;
static unsigned char *rgb_data;
static int width, height;

void errno_exit(const char *s) {
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    if (fd != -1) {
        ioctl(fd, VIDIOC_STREAMOFF, &(int){0});
    }
    if (buffer != NULL) {
        munmap(buffer, req.count * req.size);
    }
    if (fd != -1) {
        close(fd);
    }
    if (yuyv_data != NULL) {
        free(yuyv_data);
    }
    if (rgb_data != NULL) {
        free(rgb_data);
    }
    exit(EXIT_SUCCESS);
}

void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char y, u, v;
    int r, g, b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            y = yuyv[0];
            u = yuyv[1];
            v = yuyv[3];

            r = y + (1.370705 * (v - 128));
            g = y - (0.698001 * (v - 128)) - (0.337633 * (u - 128));
            b = y + (1.732446 * (u - 128));

            rgb[0] = (r > 255) ? 255 : (r < 0) ? 0 : r;
            rgb[1] = (g > 255) ? 255 : (g < 0) ? 0 : g;
            rgb[2] = (b > 255) ? 255 : (b < 0) ? 0 : b;

            y = yuyv[2];
            u = yuyv[1];
            v = yuyv[3];

            r = y + (1.370705 * (v - 128));
            g = y - (0.698001 * (v - 128)) - (0.337633 * (u - 128));
            b = y + (1.732446 * (u - 128));

            rgb[3] = (r > 255) ? 255 : (r < 0) ? 0 : r;
            rgb[4] = (g > 255) ? 255 : (g < 0) ? 0 : g;
            rgb[5] = (b > 255) ? 255 : (b < 0) ? 0 : b;

            yuyv += 4;
            rgb += 6;
        }
    }
}

void apply_blur_filter(unsigned char *rgb, int width, int height) {
    int i, j, k, l;
    unsigned char r, g, b;
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) errno_exit("malloc");

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            r = g = b = 0;
            for (k = -1; k <= 1; k++) {
                for (l = -1; l <= 1; l++) {
                    int x = j + l;
                    int y = i + k;
                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        r += rgb[(y * width + x) * 3];
                        g += rgb[(y * width + x) * 3 + 1];
                        b += rgb[(y * width + x) * 3 + 2];
                    }
                }
            }
            temp[(i * width + j) * 3] = r / 9;
            temp[(i * width + j) * 3 + 1] = g / 9;
            temp[(i * width + j) * 3 + 2] = b / 9;
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

void write_jpeg_file(const char *filename, unsigned char *rgb, int width, int height) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
