    exit(EXIT_FAILURE);
}

static int xioctl(int fd, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main(int argc, char **argv)
{
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsizeenum;
    struct v4l2_frmivalenum frmivalenum;
    struct v4l2_queryctrl queryctrl;
    int fd;

    fd = open("/dev/video0", O_RDWR);
    if (fd == -1)
        errno_exit("Opening /dev/video0");

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1)
        errno_exit("VIDIOC_QUERYCAP");

    printf("Driver: %s\nCard: %s\nBus info: %s\nDriver version: %d.%d.%d\n",
           cap.driver, cap.card, cap.bus_info,
           (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);

    CLEAR(frmsizeenum);
    frmsizeenum.index = 0;
    frmsizeenum.pixel_format = V4L2_PIX_FMT_MJPEG;

    printf("Supported frame sizes:\n");
    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum) != -1) {
        printf("  %dx%d\n", frmsizeenum.discrete.width, frmsizeenum.discrete.height);
        frmsizeenum.index++;
    }

    CLEAR(frmivalenum);
    frmivalenum.index = 0;
    frmivalenum.pixel_format = V4L2_PIX_FMT_MJPEG;

    printf("Frame intervals for each size:\n");
    while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmivalenum) != -1) {
        printf("  %dx%d: %d/%d fps\n", frmivalenum.frame.size.width, frmivalenum.frame.size.height,
               frmivalenum.interval.numerator, frmivalenum.interval.denominator);
        frmivalenum.index++;
    }

    CLEAR(queryctrl);
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == -1) {
        if (errno == EINVAL) {
            printf("Autofocus control is not supported.\n");
        } else {
            errno_exit("VIDIOC_QUERYCTRL");
        }
    } else {
        printf("Autofocus control is %s.\n", queryctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "disabled" : "enabled");
    }

    if (close(fd) == -1)
        errno_exit("Closing /dev/video0");

    return 0;
}

