#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define PWM_FREQ 50
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500
#define PWM_RANGE 20000 // 20ms in microseconds
#define PWM_DIVIDER 16

volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioSetPWMfrequency(PAN_SERVO_PIN, 0);
        gpioSetPWMfrequency(TILT_SERVO_PIN, 0);
        gpioTerminate();
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQ);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQ);

    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    int pan_pulse_width = CENTER_PULSE_WIDTH;
    int tilt_pulse_width = CENTER_PULSE_WIDTH;

    printf("Startup message:\n");
    printf("Pan servo on GPIO4 (BCM), Tilt servo on GPIO5 (BCM)\n");
    printf("UP button on GPIO6, DOWN on GPIO7, LEFT on GPIO8, RIGHT on GPIO9\n");
    printf("Center position: Pan = %dµs, Tilt = %dµs\n", pan_pulse_width, tilt_pulse_width);

    while (keep_running) {
        if (gpioRead(UP_BUTTON_PIN) == PI_LOW) {
            tilt_pulse_width = (tilt_pulse_width + 10 > MAX_PULSE_WIDTH) ? MAX_PULSE_WIDTH : tilt_pulse_width + 10;
        }
        if (gpioRead(DOWN_BUTTON_PIN) == PI_LOW) {
            tilt_pulse_width = (tilt_pulse_width - 10 < MIN_PULSE_WIDTH) ? MIN_PULSE_WIDTH : tilt_pulse_width - 10;
        }
        if (gpioRead(LEFT_BUTTON_PIN) == PI_LOW) {
            pan_pulse_width = (pan_pulse_width - 10 < MIN_PULSE_WIDTH) ? MIN_PULSE_WIDTH : pan_pulse_width - 10;
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == PI_LOW) {
            pan_pulse_width = (pan_pulse_width + 10 > MAX_PULSE_WIDTH) ? MAX_PULSE_WIDTH : pan_pulse_width + 10;
        }

        gpioPWM(PAN_SERVO_PIN, (pan_pulse_width * PWM_RANGE) / 20000);
        gpioPWM(TILT_SERVO_PIN, (tilt_pulse_width * PWM_RANGE) / 20000);

        time_sleep(0.05);
