#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <curl/curl.h>
#include <sys/stat.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2
#define POLL_INTERVAL 100
#define JPEG_QUALITY 85
#define MOTION_CAPTURES_DIR "motion_captures"
#define JPEG_FILENAME_FORMAT "%s/motion_%lld.jpg"

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static CURL *curl_handle = NULL;

void signal_handler(int signum) {
    keep_running = 0;
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(line, "PIR_Sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int create_motion_captures_dir() {
    struct stat st = {0};
    if (stat(MOTION_CAPTURES_DIR, &st) == -1) {
        if (mkdir(MOTION_CAPTURES_DIR, 0700) != 0) {
            fprintf(stderr, "Error creating directory %s: %s\n", MOTION_CAPTURES_DIR, strerror(errno));
            return -1;
        }
    }
    return 0;
}

void capture_jpeg(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -q %d -o %s -t 1", JPEG_QUALITY, filename);
    if (system(command) != 0) {
        fprintf(stderr, "Error capturing JPEG\n");
    }
}

size_t write_data(void *ptr, size_t size, size_t nmemb, void *stream) {
    size_t written = fwrite(ptr, size, nmemb, (FILE *)stream);
    return written;
}

void post_motion_data(const char *filename, const char *timestamp, const char *ip, const char *port) {
    char url[256];
    snprintf(url, sizeof(url), "http://%s:%s/upload", ip, port);

    CURLcode res;
    curl_formadd(&curl_handle, &curl_httppost,
                 CURLFORM_COPYNAME, "file",
                 CURLFORM_FILE, filename,
                 CURLFORM_END);

    curl_formadd(&curl_httppost, &curl_httppost,
                 CURLFORM_COPYNAME, "timestamp",
                 CURLFORM_COPYCONTENTS, timestamp,
                 CURLFORM_END);

    curl_formadd(&curl_httppost, &curl_httppost,
                 CURLFORM_COPYNAME, "motion_status",
                 CURLFORM_COPYCONTENTS, "true",
                 CURLFORM_END);

    curl_formadd(&curl_httppost, &curl_httppost,
                 CURLFORM_COPYNAME, "gpio_pin",
                 CURLFORM_COPYCONTENTS, "17",
                 CURLFORM_END);

    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_HTTPPOST, curl_httppost);

    res = curl_easy_perform(curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    curl_formfree(curl_httppost);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    const char *port = argv[2];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    if (create_motion_captures_dir() != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_handle = curl_easy_init();
    if (!curl_handle) {
        fprintf(stderr, "Error initializing cURL\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    time_t last_motion_time = 0;
    int motion_detected = 0;

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value == 1) {
            time_t current_time = time(NULL);
            if (current_time - last_motion_time >= DEBOUNCE_TIME) {
                if (!motion_detected) {
                    char filename[256];
                    time_t now;
                    struct tm *timeinfo;
                    char timestamp[64];

                    time(&now);
                    timeinfo = localtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", timeinfo);

                    snprintf(filename, sizeof(filename), JPEG_FILENAME_FORMAT, MOTION_CAPTURES_DIR, (long long)now);
                    capture_jpeg(filename);
                    post_motion_data(filename, timestamp, ip, port);

                    motion_detected = 1;
                }
                last_motion_time = current_time;
            }
        } else {
            motion_detected = 0;
        }

        usleep(POLL_INTERVAL * 1000);
    }

    curl_easy_cleanup(curl_handle);
    curl_global_cleanup();
    cleanup_gpio();

    return EXIT_SUCCESS;
}

