#include <signal.h>
#include <gpiod.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define PIR_PIN 17
#define DEBOUNCE_TIME_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int log_fd;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[26];
    char log_entry[256];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    snprintf(log_entry, sizeof(log_entry), "[%s] %s\n", timestamp, message);
    write(log_fd, log_entry, strlen(log_entry));
}

void capture_image() {
    time_t now;
    struct tm *tm_info;
    char filename[64];
    char command[256];
    int status;

    time(&now);
    tm_info = localtime(&now);
    strftime(filename, sizeof(filename), "/home/pi/images/%Y%m%d_%H%M%S_%3d.jpg", tm_info, (int)(tm_info->tm_usec / 1000));

    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    status = system(command);

    if (status != 0) {
        log_message("Image capture failed");
    } else {
        log_message("Image captured successfully");
    }
}

void handle_edge_event() {
    struct timespec ts = { .tv_sec = 0, .tv_nsec = DEBOUNCE_TIME_MS * 1000000 };
    int event_count;

    event_count = gpiod_line_event_wait(line, &ts);
    if (event_count > 0) {
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) == 0 && event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            capture_image();
        }
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received termination signal");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(log_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    int ret;

    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip");
        close(log_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        log_message("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "PIR-Sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        log_message("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message("Failed to set up signal handler");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    log_message("PIR sensor monitoring started");

    while (1) {
        handle_edge_event();
    }

    return EXIT_SUCCESS;
}

