#include <pigpio.h>

#define PAN_PIN 17
#define TILT_PIN 18
#define NEUTRAL_PULSE_WIDTH 1500
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PWM_FREQUENCY 50
#define STEP 5
#define DELAY_MS 100

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180 degrees)\n");
        return -1;
    }

    int pulse_width = NEUTRAL_PULSE_WIDTH + (angle - 90) * 20;
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

    if (gpioSetServoPulsewidth(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width\n");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(PAN_PIN, PI_OUTPUT) < 0 || gpioSetMode(TILT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY) < 0 || gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(PAN_PIN, 90) < 0 || set_servo_angle(TILT_PIN, 90) < 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    int pan_angle = 90;
    int tilt_angle = 90;

    while (keep_running) {
        int c = getchar();
        if (c == 'q') {
            break;
        }

        switch (c) {
            case 'a': // Left
                pan_angle -= STEP;
                if (pan_angle < 0) pan_angle = 0;
                break;
            case 'd': // Right
                pan_angle += STEP;
                if (pan_angle > 180) pan_angle = 180;
                break;
            case 'w': // Up
                tilt_angle -= STEP;
                if (tilt_angle < 0) tilt_angle = 0;
                break;
            case 's': // Down
                tilt_angle += STEP;
                if (tilt_angle > 180) tilt_angle = 180;
                break;
            default:
                continue;
        }

        if (set_servo_angle(PAN_PIN, pan_angle) < 0 || set_servo_angle(TILT_PIN, tilt_angle) < 0) {
            break;
        }

        usleep(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_PIN, 90);
    set_servo_angle(TILT_PIN, 90);

    gpioTerminate();
    return 0;
}

