#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x3C
#define SSD1306_COMMAND 0x00
#define SSD1306_DATA 0x40

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int i2c_write(const uint8_t *buf, size_t len) {
    if (write(i2c_fd, buf, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int ssd1306_init() {
    static const uint8_t init_cmds[] = {
        0xAE, 0x20, 0x10, 0xB0, 0xC8, 0x00, 0x10, 0x40, 0x81, 0xFF,
        0xA1, 0xA6, 0xA8, 0x3F, 0xAD, 0x8E, 0xD3, 0x00, 0xD5, 0x80,
        0xD9, 0xF1, 0xDA, 0x12, 0xD8, 0x30, 0x8D, 0x14, 0xAF
    };
    return i2c_write(init_cmds, sizeof(init_cmds));
}

int ssd1306_set_pos(uint8_t col, uint8_t page) {
    uint8_t buf[] = {0xB0 | page, 0x00 | (col & 0x0F), 0x10 | ((col >> 4) & 0x0F)};
    return i2c_write(buf, sizeof(buf));
}

int ssd1306_write_data(const uint8_t *buf, size_t len) {
    uint8_t data[len + 1];
    data[0] = SSD1306_DATA;
    memcpy(&data[1], buf, len);
    return i2c_write(data, len + 1);
}

int ssd1306_clear() {
    uint8_t buf[128 * 8] = {0};
    for (int i = 0; i < 8; i++) {
        if (ssd1306_set_pos(0, i) < 0) return -1;
        if (ssd1306_write_data(buf, sizeof(buf)) < 0) return -1;
    }
    return 0;
}

int ssd1306_print(const char *str) {
    while (*str) {
        if (ssd1306_set_pos(0, 0) < 0) return -1;
        if (ssd1306_write_data((uint8_t*)str, 1) < 0) return -1;
        str++;
    }
    return 0;
}

int read_cpu_temp(char *buf, size_t size) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) return -1;
    if (fgets(buf, size, fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int read_cpu_usage(int *usage) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) return -1;
    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (sscanf(line, "cpu %d %*d %*d %*d %*d %*d %*d %*d", usage) != 1) {
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "SSD1306 Reset", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(100000);  // 100ms delay for OLED to power up
    gpiod_line_set_value(line, 1);  // Set OLED reset high

    if (ssd1306_init() < 0) {
        fprintf(stderr, "Failed to initialize SSD1306\n");
        cleanup(0);
    }

    ssd1306_clear();

    char temp_buf[8];
    int cpu_usage;

    while (1) {
        if (read_cpu_temp(temp_buf, sizeof(temp_buf)) < 0) {
            ssd1306_print("Temp Read Err");
        } else {
            char display_buf[32];
            snprintf(display_buf, sizeof(display_buf), "Temp: %.2fC\nCPU: %d%%",
                     atof(temp_buf) / 1000.0, cpu_usage);
            ssd1306_clear();
