#include <lcd.h>

#define PIN 17
#define PULSE_PER_LITER 7.5
#define I2C_BUS 1
#define LCD_ADDR 0x27

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int lcd;
static unsigned long long pulse_count = 0;
static double total_volume = 0.0;
static time_t last_log_time = 0;
static time_t last_lcd_update = 0;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_and_update_display() {
    time_t now = time(NULL);
    if (now - last_log_time >= 1) {
        double flow_rate = pulse_count / (PULSE_PER_LITER * (now - last_log_time));
        total_volume += flow_rate;
        printf("Current Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
        last_log_time = now;
    }

    if (now - last_lcd_update >= 10) {
        char buffer[16];
        snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", pulse_count / (PULSE_PER_LITER * 10));
        lcdPosition(lcd, 0, 0);
        lcdPuts(lcd, buffer);
        snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
        lcdPosition(lcd, 0, 1);
        lcdPuts(lcd, buffer);
        last_lcd_update = now;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    line = gpiod_chip_get_line(chip, PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_input(line, "YF-S201") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    lcd = lcdInit(2, 16, I2C_BUS, LCD_ADDR);
    if (lcd < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    time_t start_time = time(NULL);
    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }
        if (value == 1) {
            pulse_count++;
        }
        log_and_update_display();
        usleep(100000);  // 100ms delay
    }

    lcdClose(lcd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return 0;
}

