#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <bcm2835.h>
#include <mcp3008.h>
#include <lcd.h>
#include <i2c.h>
#include <spi.h>

#define ANEMOMETER_PIN 17
#define WIND_VANE_SPI_CHANNEL 0
#define LCD_I2C_BUS 1
#define SAMPLE_WINDOW_MS 500
#define PULSE_COUNT_PER_REV 2
#define WIND_SPEED_FACTOR 1.492 // Adjust based on your anemometer calibration

volatile int pulse_count = 0;
volatile time_t last_sample_time;
struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd, i2c_fd, lcd_handle;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

void setup_anemometer() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        exit(1);
    }

    line = gpiod_chip_get_line(chip, ANEMOMETER_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        exit(1);
    }

    int ret = gpiod_line_request_rising_edge_events(line, "anemometer", pulse_callback);
    if (ret < 0) {
        fprintf(stderr, "Failed to request rising edge events\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        exit(1);
    }
}

void setup_adc() {
    if (!bcm2835_init()) {
        fprintf(stderr, "Failed to initialize BCM2835 library\n");
        exit(1);
    }

    bcm2835_spi_begin();
    bcm2835_spi_setBitOrder(BCM2835_SPI_BIT_ORDER_MSBFIRST);
    bcm2835_spi_setDataMode(BCM2835_SPI_MODE0);
    bcm2835_spi_setClockDivider(BCM2835_SPI_CLOCK_DIVIDER_64); // 1MHz
    bcm2835_spi_chipSelect(BCM2835_SPI_CS0);
    bcm2835_spi_setChipSelectPolarity(BCM2835_SPI_CS0, LOW);
}

void setup_lcd() {
    i2c_fd = i2cOpen(LCD_I2C_BUS, 0x27);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    lcd_handle = lcdInit(2, 16, 4, 0x27, 0, 0, 0, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        i2cClose(i2c_fd);
        exit(1);
    }
}

float read_wind_speed() {
    time_t current_time = time(NULL);
    int elapsed_ms = (int)(current_time - last_sample_time) * 1000;

    if (elapsed_ms < SAMPLE_WINDOW_MS) {
        return 0.0;
    }

    float wind_speed = (pulse_count * 60.0 / PULSE_COUNT_PER_REV) / (elapsed_ms / 1000.0) * WIND_SPEED_FACTOR;
    pulse_count = 0;
    last_sample_time = current_time;
    return wind_speed;
}

int read_wind_direction() {
    uint16_t adc_value = mcp3008Read(WIND_VANE_SPI_CHANNEL);
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading may be stuck at %d\n", adc_value);
    }

    // Convert ADC value to wind direction (0-360 degrees)
    // This is a simplified conversion and should be adjusted based on your wind vane calibration
    return (int)((adc_value / 1023.0) * 360.0);
}

void update_lcd(float wind_speed, int wind_direction) {
    char wind_speed_str[16];
    char wind_direction_str[16];

    snprintf(wind_speed_str, sizeof(wind_speed_str), "Speed: %.1f m/s", wind_speed);
    snprintf(wind_direction_str, sizeof(wind_direction_str), "Dir: %d deg", wind_direction);

    lcdPosition(lcd_handle, 0, 0);
    lcdPuts(lcd_handle, wind_speed_str);
    lcdPosition(lcd_handle, 0, 1);
    lcdPuts(lcd_handle, wind_direction_str);
}

void cleanup(int signum) {
    printf("Cleaning up...\n");

    if (line) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }

    gpioTerminate();

    if (bcm2835_spi_end() != 0) {
        fprintf(stderr, "Failed to end SPI\n");
    }
    bcm2835_close();

    if (lcd_handle >= 0) {
        lcdClose(lcd_handle);
    }

    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }

    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    setup_anemometer();
    setup_adc();
    setup_lcd();

    last_sample_time = time(NULL);

    while (1) {
        float wind_speed = read_wind_speed();
        int wind_direction = read_wind_direction();
        update_lcd(wind_speed, wind_direction);
        usleep(SAMPLE_WINDOW_MS * 1000);
    }

    return 0;
}

