#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define ROW_PINS[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20}
#define DELAY_US 800

volatile sig_atomic_t keep_running = 1;

int mem_fd;
void *gpio_map;
unsigned int *gpio;

void setup_gpio() {
    mem_fd = open("/dev/gpiomem", O_RDWR | O_SYNC);
    if (mem_fd < 0) {
        fprintf(stderr, "Error: Unable to open /dev/gpiomem\n");
        exit(EXIT_FAILURE);
    }

    gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, mem_fd, 0x20200000);
    if (gpio_map == MAP_FAILED) {
        fprintf(stderr, "Error: Unable to map GPIO\n");
        close(mem_fd);
        exit(EXIT_FAILURE);
    }

    gpio = (volatile unsigned int *)gpio_map;

    for (int i = 0; i < NUM_ROWS; i++) {
        gpio[ROW_PINS[i] / 10] &= ~(7 << ((ROW_PINS[i] % 10) * 3));
        gpio[ROW_PINS[i] / 10] |= (1 << ((ROW_PINS[i] % 10) * 3));
    }

    for (int i = 0; i < NUM_COLS; i++) {
        gpio[COL_PINS[i] / 10] &= ~(7 << ((COL_PINS[i] % 10) * 3));
        gpio[COL_PINS[i] / 10] |= (1 << ((COL_PINS[i] % 10) * 3));
    }
}

void cleanup_gpio() {
    if (gpio_map) {
        munmap(gpio_map, 4096);
    }
    if (mem_fd >= 0) {
        close(mem_fd);
    }
}

void set_row(int row, int state) {
    if (row < 0 || row >= NUM_ROWS) {
        fprintf(stderr, "Error: Invalid row number\n");
        return;
    }
    gpio[ROW_PINS[row] / 10] &= ~(7 << ((ROW_PINS[row] % 10) * 3));
    gpio[ROW_PINS[row] / 10] |= (state << ((ROW_PINS[row] % 10) * 3));
}

void set_col(int col, int state) {
    if (col < 0 || col >= NUM_COLS) {
        fprintf(stderr, "Error: Invalid column number\n");
        return;
    }
    gpio[COL_PINS[col] / 10] &= ~(7 << ((COL_PINS[col] % 10) * 3));
    gpio[COL_PINS[col] / 10] |= (state << ((COL_PINS[col] % 10) * 3));
}

void animate_left_to_right() {
    for (int frame = 0; frame < NUM_COLS && keep_running; frame++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            set_row(row, 1);
            set_col((frame + row) % NUM_COLS, 0);
            usleep(DELAY_US);
            set_col((frame + row) % NUM_COLS, 1);
            set_row(row, 0);
        }
    }
}

void animate_right_to_left() {
    for (int frame = 0; frame < NUM_COLS && keep_running; frame++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            set_row(row, 1);
            set_col((NUM_COLS - 1 - frame + row) % NUM_COLS, 0);
            usleep(DELAY_US);
            set_col((NUM_COLS - 1 - frame + row) % NUM_COLS, 1);
            set_row(row, 0);
        }
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();

    while (keep_running) {
        animate_left_to_right();
        animate_right_to_left();
    }

    cleanup_gpio();
    return 0;
}

