#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

const int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

void cleanup(int signum) {
    printf("Cleaning up...\n");
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %d\n", row_pins[i]);
            cleanup(0);
        }
        int ret = gpiod_line_request_output(row_lines[i], "LED Row", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request row line %d\n", row_pins[i]);
            cleanup(0);
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %d\n", col_pins[i]);
            cleanup(0);
        }
        int ret = gpiod_line_request_output(col_lines[i], "LED Column", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request column line %d\n", col_pins[i]);
            cleanup(0);
        }
    }

    while (1) {
        for (int col = 0; col < NUM_COLS; col++) {
            // Set all column cathodes HIGH
            for (int i = 0; i < NUM_COLS; i++) {
                int ret = gpiod_line_set_value(col_lines[i], 1);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set column %d HIGH\n", col_pins[i]);
                    cleanup(0);
                }
            }

            // Set current column cathode LOW
            int ret = gpiod_line_set_value(col_lines[col], 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set column %d LOW\n", col_pins[col]);
                cleanup(0);
            }

            // Light LEDs sequentially
            for (int row = 0; row < NUM_ROWS; row++) {
                ret = gpiod_line_set_value(row_lines[row], 1);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set row %d HIGH\n", row_pins[row]);
                    cleanup(0);
                }
                usleep(10000); // 10ms delay between LEDs
            }

            // Clear all row anodes
            for (int row = 0; row < NUM_ROWS; row++) {
                ret = gpiod_line_set_value(row_lines[row], 0);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set row %d LOW\n", row_pins[row]);
                    cleanup(0);
                }
            }

            usleep(DELAY_MS * 1000); // 150ms delay between columns
        }
    }

    return 0;
}

