static int i2c_fd;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Graceful shutdown initiated.\n");
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_sensor(int *distance) {
    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C interface\n");
        return EXIT_FAILURE;
    }

    if (open_log_file() < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_sample_time = time(NULL);
    int distance;

    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) >= SAMPLE_INTERVAL_MS / 1000.0) {
            if (read_sensor(&distance) < 0) {
                distance = -1;
            }

            time_t now;
            struct tm *tm_info;
            char timestamp[20];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);

            last_sample_time = current_time;
        }

        usleep(10000); // Sleep for 10ms to reduce CPU usage
    }

    return EXIT_SUCCESS;
}

