#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Si1145 Register Addresses
#define SI1145_COMMAND 0x00
#define SI1145_PS1DATA0 0x0A
#define SI1145_ALSDATA0 0x0D

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int si1145_init() {
    if (i2c_write(i2c_fd, SI1145_COMMAND, 0x01) != 1 || // RESET
        i2c_write(i2c_fd, SI1145_COMMAND, 0x11) != 1 || // QUERY
        i2c_write(i2c_fd, SI1145_COMMAND, 0x40) != 1) { // MAIN
        return -1;
    }
    usleep(10000); // Wait for initialization
    return 0;
}

int si1145_read(uint16_t *proximity, uint16_t *ambient) {
    uint8_t buf[4];
    if (i2c_read(i2c_fd, SI1145_PS1DATA0, buf) != 1 ||
        i2c_read(i2c_fd, SI1145_PS1DATA0 + 1, buf + 1) != 1 ||
        i2c_read(i2c_fd, SI1145_ALSDATA0, buf + 2) != 1 ||
        i2c_read(i2c_fd, SI1145_ALSDATA0 + 1, buf + 3) != 1) {
        return -1;
    }
    *proximity = (buf[1] << 8) | buf[0];
    *ambient = (buf[3] << 8) | buf[2];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    uint16_t proximity, ambient;

    while (1) {
        if (si1145_read(&proximity, &ambient) == 0) {
            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
            fprintf(log_file, "%s Proximity: %d, Ambient: %d\n", timestamp, proximity, ambient);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read from Si1145 sensor\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

