#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    int last_state = 1;
    struct timespec last_detection = {0, 0};

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup(0);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup(0);
