#define SI1145_ADDR 0x60
#define PART_ID 0x45
#define I2C_BUS 1
#define LOG_FILE "biometric_data.log"

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    char timestamp[64];
    uint8_t part_id, prox_data, light_data;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = i2cReadByteData(i2c_handle, 0x00, &part_id);
    if (ret < 0 || part_id != PART_ID) {
        fprintf(stderr, "Sensor not found or PART_ID mismatch\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        ret = i2cReadByteData(i2c_handle, 0x1A, &prox_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            break;
        }

        ret = i2cReadByteData(i2c_handle, 0x21, &light_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read light data\n");
            break;
        }

        fprintf(log_file, "%s,%d,%d\n", timestamp, prox_data, light_data);
        fflush(log_file);

        sleep(1);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

