#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_DURATION_US 10
#define ECHO_TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define LOG_FILE "distance_log.txt"
#define WATER_THRESHOLD_CM 15
#define LOG_INTERVAL_SEC 60

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        return -1;
    }

    return 0;
}

int measure_distance(void) {
    struct timespec start, end;
    int64_t echo_start_us, echo_end_us;

    // Send 10µs pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(TRIGGER_DURATION_US);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo to rise
    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, ECHO_TIMEOUT_US * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo rise\n");
        return -1;
    }

    if (gpiod_line_event_get_time(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &start) < 0) {
        fprintf(stderr, "Failed to get echo rise time\n");
        return -1;
    }

    // Wait for echo to fall
    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, ECHO_TIMEOUT_US * 1000) < 0) {
        fprintf(stderr, "Timeout waiting for echo fall\n");
        return -1;
    }

    if (gpiod_line_event_get_time(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &end) < 0) {
        fprintf(stderr, "Failed to get echo fall time\n");
        return -1;
    }

    echo_start_us = (int64_t)start.tv_sec * 1000000 + start.tv_nsec / 1000;
    echo_end_us = (int64_t)end.tv_sec * 1000000 + end.tv_nsec / 1000;

    int distance = (int)((echo_end_us - echo_start_us) / 58.0);

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %d cm\n", distance);
        return -1;
    }

    return distance;
}

int main(void) {
    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);

    while (keep_running) {
        int distance = measure_distance();
        time_t current_time = time(NULL);

        if (distance >= 0) {
            char timestamp[64];
            struct tm *tm_info;

            time(&current_time);
            tm_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

            fprintf(log_file, "[%s] Distance: %d cm\n", timestamp, distance);
            if (distance < WATER_THRESHOLD_CM) {
                fprintf(log_file, "[%s] Time to water the plant!\n", timestamp);
            }
            fflush(log_file);
        } else {
            char timestamp[64];
            struct tm *tm_info;

            time(&current_time);
            tm_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

            fprintf(log_file, "[%s] Error or timeout\n", timestamp);
            fflush(log_file);
        }

        while (difftime(time(NULL), last_log_time) < LOG_INTERVAL_SEC) {
            sleep(1);
            if (!keep_running) {
                break;
            }
        }
        last_log_time = time(NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

