#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define I2C_RETRIES 3

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int init_apds9960() {
    uint8_t id;
    if (i2c_read(i2c_fd, 0x92, &id) != 1 || id != 0xA0) {
        return -1;
    }

    i2c_write(i2c_fd, 0x80, 0x01);  // Enable ALS and proximity
    i2c_write(i2c_fd, 0x81, 0x60);  // ALS gain = 1x, proximity gain = 1x
    i2c_write(i2c_fd, 0x83, 0x00);  // ALS integration time = 100ms
    i2c_write(i2c_fd, 0x84, 0x00);  // Proximity integration time = 100ms
    i2c_write(i2c_fd, 0x85, 0x00);  // Wait time = 0ms
    i2c_write(i2c_fd, 0x86, 0x20);  // Proximity LED = 100mA, Drive current = 100mA
    i2c_write(i2c_fd, 0x87, 0x01);  // Enable proximity sensor

    return 0;
}

int read_apds9960(uint16_t *proximity, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t buf[8];
    if (i2c_read(i2c_fd, 0x94, buf) != 1 || buf[0] != 0x00) {
        return -1;
    }

    *proximity = (buf[1] << 4) | (buf[0] >> 4);
    *r = (buf[3] << 4) | (buf[2] >> 4);
    *g = (buf[5] << 4) | (buf[4] >> 4);
    *b = (buf[7] << 4) | (buf[6] >> 4);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
