    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("distance_log.txt", "a");
