        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        usleep(TRIGGER_DELAY_MS * 1000);

        unsigned int echo_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - echo_time > 1000000) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
        }

        echo_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - echo_time > 1000000) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
        }

        unsigned int pulse_duration = gpioTick() - echo_time;
        float distance = pulse_duration / 58.0f;

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s, %.1f\n", timestamp, distance);
        fprintf(log_file, "%s, %.1f\n", timestamp, distance);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(i2c_handle);
    gpioTerminate();

    return 0;
}
