#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define SENSOR_READ_INTERVAL_MS 100
#define LED_PIN 17
#define DISTANCE_THRESHOLD 20

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int read_distance() {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[2];

    if (write(i2c_fd, tx, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(10000);  // Wait for sensor to process

    if (read(i2c_fd, rx, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (rx[0] << 8) | rx[1];
}

int main() {
    struct timespec ts;
    int distance;
    char timestamp[64];
    struct sigaction sa;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        distance = read_distance();
        if (distance >= 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));
            fprintf(log_file, "%s Distance: %d cm\n", timestamp, distance);
            fflush(log_file);

            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
            gpiod_line_set_value(led_line, 0);
        }

        nanosleep(&(struct timespec){0, SENSOR_READ_INTERVAL_MS * 1000000}, NULL);
    }

    return EXIT_SUCCESS;
}

