#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int si1182_init() {
    uint8_t retry_count;
    uint8_t value;

    for (retry_count = 0; retry_count < MAX_RETRIES; retry_count++) {
        if (i2c_write(i2c_fd, 0x00, 0x00) == 1 &&
            i2c_read(i2c_fd, 0x00, &value) == 1 && value == 0x00) {
            return 0;
        }
        usleep(10000);
    }
    return -1;
}

int si1182_read_sensor(uint16_t *proximity, uint16_t *ambient) {
    uint8_t retry_count;
    uint8_t buf[4];

    for (retry_count = 0; retry_count < MAX_RETRIES; retry_count++) {
        if (i2c_write(i2c_fd, 0x00, 0x11) == 1 &&
            i2c_read(i2c_fd, 0x22, buf) == 4) {
            *proximity = (buf[1] << 8) | buf[0];
            *ambient = (buf[3] << 8) | buf[2];
            return 0;
        }
        usleep(10000);
    }
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("set i2c slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1182_init() < 0) {
        fprintf(stderr, "Failed to initialize SI1182\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_sample_time = time(NULL);
    uint16_t proximity, ambient;

    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) >= SAMPLE_INTERVAL_MS / 1000.0) {
            if (si1182_read_sensor(&proximity, &ambient) == 0) {
                time_t now;
                struct tm *tm_info;
                char timestamp[26];

                time(&now);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s, Proximity: %d, Ambient: %d\n", timestamp, proximity, ambient);
                fflush(log_file);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
            last_sample_time = current_time;
        }
        usleep(10000);
    }

    return EXIT_SUCCESS;
}

