#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x29 // Example address, adjust as needed
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY_MS 100
#define MEASUREMENT_COMMAND_SIZE 4
#define MEASUREMENT_RESPONSE_SIZE 15
#define HEADER_BYTE 0x00 // Example header, adjust as needed
#define INTRUSION_THRESHOLD 1000 // in mm

int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signo) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, const uint8_t *buf, size_t len) {
    ssize_t bytes_written = write(fd, buf, len);
    if (bytes_written != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t command[MEASUREMENT_COMMAND_SIZE] = {0x00, 0x01, 0x02, 0x03}; // Example command
    uint8_t response[MEASUREMENT_RESPONSE_SIZE];

    while (1) {
        if (i2c_write(i2c_fd, command, MEASUREMENT_COMMAND_SIZE) != 0) {
            continue;
        }

        usleep(10000); // 10 ms delay

        if (i2c_read(i2c_fd, response, MEASUREMENT_RESPONSE_SIZE) != 0) {
            continue;
        }

        if (response[0] != HEADER_BYTE) {
            fprintf(stderr, "Invalid header byte\n");
            continue;
        }

        uint16_t distance = (response[11] << 8) | response[12];
        uint32_t total_distance = 0;

        for (int i = 0; i < SAMPLE_COUNT; ++i) {
            total_distance += distance;
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        uint32_t average_distance = total_distance / SAMPLE_COUNT;

        if (average_distance < INTRUSION_THRESHOLD) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
            fprintf(log_file, "[%s] Average Distance: %u mm\n", timestamp, average_distance);
            fflush(log_file);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

