#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_I2C_ADDR 0x29
#define VL53L0X_MODEL_ID_REG 0x0C
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_RESULT_RANGE_STATUS 0x14

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    uint8_t model_id;
    uint8_t status;
    uint16_t distance;
    struct timespec sleep_time;
    struct tm *tm_info;
    char time_str[20];

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, VL53L0X_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Read model ID
    if (read(i2c_fd, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify model ID
    if (model_id != 0xEE) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        close(i2c_fd);
        return 1;
    }

    printf("VL53L0X sensor initialized successfully\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Read RESULT_INTERRUPT_STATUS
        if (read(i2c_fd, &status, 1) != 1) {
            fprintf(stderr, "Warning: Error reading RESULT_INTERRUPT_STATUS: %s\n", strerror(errno));
            continue;
        }

        // Check if new data is ready
        if (status & 0x01) {
            // Read RESULT_RANGE_STATUS
            if (read(i2c_fd, (uint8_t*)&distance, 2) != 2) {
                fprintf(stderr, "Warning: Error reading RESULT_RANGE_STATUS: %s\n", strerror(errno));
                continue;
            }

            // Get current time
            time_t now = time(NULL);
            tm_info = localtime(&now);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            // Print distance
            printf("%s Distance: %d mm\n", time_str, distance);
        }

        // Sleep for 100ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

