void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Ctrl+C pressed. Cleaning up...\n");
        if (i2c_handle >= 0) {
            close(i2c_handle);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access/talk to slave\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t proximity_data;
    while (1) {
        int bytes_written = write(i2c_handle, NULL, 0);
        if (bytes_written < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error\n");
            } else {
                fprintf(stderr, "Failed to write to I2C device\n");
            }
            sleep(1);
            continue;
        }

        int bytes_read = read(i2c_handle, &proximity_data, sizeof(proximity_data));
        if (bytes_read < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error\n");
            } else {
                fprintf(stderr, "Failed to read from I2C device\n");
            }
            sleep(1);
            continue;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "Sensor not present (NACK received)\n");
            sleep(1);
            continue;
        }

        printf("Proximity data: %d\n", proximity_data);
        usleep(SENSOR_READ_INTERVAL_MS * 1000);
    }

    close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

