#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3101_ADDR 0x53
#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT_LIGHT 0x02
#define OPT3101_REG_ERROR_FLAGS 0x04
#define PERIOD_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int i2c_write(int file, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(file, buf, sizeof(buf));
}

int i2c_read(int file, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(file, &reg, 1) != 1) {
        return -1;
    }
    return read(file, buf, len);
}

int main() {
    int i2c_file;
    uint8_t buffer[3];
    int16_t distance;
    uint16_t ambient_light;
    uint8_t error_flags;

    signal(SIGINT, signal_handler);

    i2c_file = open(I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file, I2C_SLAVE, OPT3101_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_read(i2c_file, OPT3101_REG_DISTANCE, buffer, 2) != 2) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            distance = (buffer[0] << 8) | buffer[1];
            printf("Distance: %d mm\n", distance);
        }

        if (i2c_read(i2c_file, OPT3101_REG_AMBIENT_LIGHT, buffer, 2) != 2) {
            fprintf(stderr, "Error reading ambient light\n");
        } else {
            ambient_light = (buffer[0] << 8) | buffer[1];
            printf("Ambient Light: %d lux\n", ambient_light);
        }

        if (i2c_read(i2c_file, OPT3101_REG_ERROR_FLAGS, &error_flags, 1) != 1) {
            fprintf(stderr, "Error reading error flags\n");
        } else {
            printf("Error Flags: 0x%02X\n", error_flags);
        }

        usleep(PERIOD_MS * 1000);
    }

    close(i2c_file);
    return EXIT_SUCCESS;
}

