#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define MEASUREMENT_INTERVAL_US 1000000
#define MAX_DISTANCE_US 38000
#define MIN_DISTANCE_US 20

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;

void cleanup(int signum) {
    if (echo_line) gpiod_line_release(echo_line);
    if (trigger_line) gpiod_line_release(trigger_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec start, end;
    uint64_t duration;
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(0);
    }

    ret = gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        cleanup(0);
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        cleanup(0);
    }

    printf("HC-SR04 sensor reading program started\n");
    printf("Note: Ensure a 1kΩ resistor is used between GPIO %d and the sensor's echo pin\n", ECHO_PIN);

    while (1) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo start
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo start timeout\n");
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
        }

        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
            continue;
        }

        // Wait for echo end
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo end timeout\n");
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
        }

        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
            continue;
        }

        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration < MIN_DISTANCE_US || duration > MAX_DISTANCE_US) {
            fprintf(stderr, "Invalid pulse duration: %llu µs\n", duration);
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        printf("%s - Distance: %llu µm\n", timestamp, duration / 58);

        usleep(MEASUREMENT_INTERVAL_US - duration);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

