#include <gpiod.h>

#define UART_DEV "/dev/serial0"
#define BUFFER_SIZE 136
#define MAGIC_WORD_SIZE 8
#define DISTANCE_BINS 64
#define DISTANCE_THRESHOLD 1000 // 1.0 meter in mm
#define ALERT_LED_PIN 17

static int uart_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alert_led = NULL;

void cleanup(int signum) {
    if (alert_led) {
        gpiod_line_release(alert_led);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_uart() {
    struct termios options;

    uart_fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening UART device");
        return -1;
    }

    if (tcgetattr(uart_fd, &options) < 0) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return -1;
    }

    options.c_cflag = B115200 | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(uart_fd, TCIFLUSH);

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

int init_alert_led() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
