    alert_led = gpiod_chip_get_line(chip, ALERT_LED_PIN);
    if (!alert_led) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(alert_led, "alert_led", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(alert_led);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

