static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t keep_running = 1;

void log_state_change(int state) {
    FILE *log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: Obstacle %s\n", timestamp, state ? "detected" : "removed");
    fclose(log_file);
}

void handle_signal(int signum) {
    keep_running = 0;
}

int main() {
    int last_state = 1;  // Assume no obstacle initially

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        perror("Failed to request sensor line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor line");
            break;
        }

        if (current_state != last_state) {
            log_state_change(current_state);
            if (gpiod_line_set_value(buzzer_line, current_state) < 0) {
                perror("Failed to set buzzer line");
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (sensor_line) gpiod_line_release(sensor_line);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

