#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define MEASURE_INTERVAL_MS 100
#define DISTANCE_THRESHOLD 10.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    return write(fd, buf, len);
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    return read(fd, buf, len);
}

int read_distance() {
    uint8_t tx_buf[2] = {0x00, 0x00};
    uint8_t rx_buf[2];

    if (i2c_write(i2c_fd, tx_buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    usleep(50000);  // Wait for measurement

    if (i2c_read(i2c_fd, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    return (rx_buf[0] << 8) | rx_buf[1];
}

int main() {
    char filename[20];
    struct timespec ts;
    char timestamp[64];
    int distance;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "distance_alert", 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

            fprintf(log_file, "%s, %d\n", timestamp, distance);
            fflush(log_file);

            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        }

        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

