#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>
#include < VL53L1X.h>

#define LOG_FILE "distance_log.csv"
#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define POLL_INTERVAL_MS 100

VL53L1_Dev_t dev;
int i2c_handle;
FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Shutting down...\n");
        VL53L1_StopMeasurement(&dev);
        VL53L1_DeleteDevice(&dev);
        close(i2c_handle);
        if (log_file) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    VL53L1_Error status = VL53L1_Init(&dev, i2c_handle);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1 initialization failed: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    status = VL53L1_StartMeasurement(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1 start measurement failed: %d\n", status);
        VL53L1_DeleteDevice(&dev);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        VL53L1_StopMeasurement(&dev);
        VL53L1_DeleteDevice(&dev);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    struct timeval tv;
    uint16_t distance;
    char guidance[20];

    while (1) {
        gettimeofday(&tv, NULL);
        char timestamp[20];
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)tv.tv_sec, (long)tv.tv_usec);

        status = VL53L1_GetDistance(&dev, &distance);
        if (status != VL53L1_ERROR_NONE) {
            fprintf(stderr, "VL53L1 get distance failed: %d\n", status);
            continue;
        }

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        if (distance < 300) {
            strcpy(guidance, "STOP");
        } else if (distance < 600) {
            strcpy(guidance, "APPROACH");
        } else if (distance < 1200) {
            strcpy(guidance, "SLOW");
        } else {
            strcpy(guidance, "CLEAR");
        }

        printf("Parking Guidance: %s\n", guidance);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

