#define I2C_BUS 1
#define I2C_ADDR 0x50
#define SENSOR_READ_INTERVAL_MS 100
#define LED_GPIO 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = write(fd, buf, len);
        if (ret >= 0) return ret;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = read(fd, buf, len);
        if (ret >= 0) return ret;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

uint16_t read_distance() {
    uint8_t buf[2];
    if (i2c_read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read distance\n");
        return 0xFFFF; // Indicate error
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        uint16_t distance = read_distance();
        if (distance == 0xFFFF) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            clock_gettime(CLOCK_MONOTONIC, &current);
            double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;

            int blink_freq = 1000 - (distance / 10); // Adjust blink frequency based on distance
            if (blink_freq < 100) blink_freq = 100;
            if (blink_freq > 1000) blink_freq = 1000;

            int half_cycle_time = blink_freq / 2;
            gpiod_line_set_value(led_line, 1);
            usleep(half_cycle_time * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(half_cycle_time * 1000);

            printf("%.3f, %d\n", elapsed, distance);
        }

        usleep(SENSOR_READ_INTERVAL_MS * 500); // Sleep for half the interval to maintain timing
    }

    return EXIT_SUCCESS;
}

