#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_INTERVAL_US 10000
#define DEBOUNCE_INTERVAL_US 50000
#define LOG_FILE "proximity_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static FILE *log_file;

void log_event(int sensor_id, const char *event) {
    struct timespec ts;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = gmtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s.%09ldZ, Sensor %d, %s\n",
            timestamp, ts.tv_nsec, sensor_id, event);
    fflush(log_file);
}

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int retries = 3;
    int sensor1_state = -1, sensor2_state = -1;
    struct timespec last_change[2] = {0};

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);

    if (!sensor1_line || !sensor2_line) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    gpiod_line_request_input(sensor1_line, "sensor1");
    gpiod_line_request_input(sensor2_line, "sensor2");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        int current_sensor1_state = gpiod_line_get_value(sensor1_line);
        int current_sensor2_state = gpiod_line_get_value(sensor2_line);

        if (current_sensor1_state != sensor1_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if ((now.tv_sec - last_change[0].tv_sec) * 1000000 +
                (now.tv_nsec - last_change[0].tv_nsec) >= DEBOUNCE_INTERVAL_US) {
                if (current_sensor1_state == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
                sensor1_state = current_sensor1_state;
                last_change[0] = now;
            }
        }

        if (current_sensor2_state != sensor2_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if ((now.tv_sec - last_change[1].tv_sec) * 1000000 +
                (now.tv_nsec - last_change[1].tv_nsec) >= DEBOUNCE_INTERVAL_US) {
                if (current_sensor2_state == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
                sensor2_state = current_sensor2_state;
                last_change[1] = now;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    return EXIT_SUCCESS;
}

