#define CSV_FILENAME "distance_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write_read(int fd, uint8_t *write_buf, int write_len, uint8_t *read_buf, int read_len) {
    if (write(fd, write_buf, write_len) != write_len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, read_buf, read_len) != read_len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILENAME, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t write_buf[1] = {MEAS_STATUS_REG};
    uint8_t read_buf[2];
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (i2c_write_read(i2c_fd, write_buf, sizeof(write_buf), read_buf, sizeof(read_buf)) == 0) {
            if (read_buf[0] & 0x01) {  // Check if measurement is ready
                uint16_t distance = (read_buf[1] << 8) | read_buf[0];
                char timestamp[20];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                fprintf(csv_file, "%s,%d\n", timestamp, distance);
                fflush(csv_file);
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &current);
        long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms < SAMPLE_INTERVAL_MS) {
            usleep((SAMPLE_INTERVAL_MS - elapsed_ms) * 1000);
        }
        clock_gettime(CLOCK_MONOTONIC, &start);
    }

    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

