#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x29
#define I2C_SLAVE_FORCE 0x0706
#define ZONE_COUNT 64
#define READ_DELAY_MS 500

int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int init_sensor() {
    // Power on the sensor
    if (i2c_write(i2c_fd, 0x0000, 0x01) != 1) return -1;
    usleep(10000); // 10ms delay

    // Wait for the sensor to be ready
    uint8_t status;
    do {
        if (i2c_read(i2c_fd, 0x0001, &status) != 1) return -1;
    } while (!(status & 0x01));

    // Configure the sensor for 8x8 zone grid
    if (i2c_write(i2c_fd, 0x001E, 0x01) != 1) return -1; // Set resolution
    if (i2c_write(i2c_fd, 0x0020, 0x01) != 1) return -1; // Enable streaming mode
    if (i2c_write(i2c_fd, 0x0021, 0x01) != 1) return -1; // Enable continuous mode

    return 0;
}

int read_zone_data(uint16_t *distances) {
    if (i2c_write(i2c_fd, 0x0010, 0x01) != 1) return -1; // Start measurement

    uint8_t status;
    do {
        if (i2c_read(i2c_fd, 0x0011, &status) != 1) return -1;
    } while (!(status & 0x01));

    for (int i = 0; i < ZONE_COUNT; i++) {
        uint8_t msb, lsb;
        if (i2c_read(i2c_fd, 0x0080 + i * 2, &msb) != 1 ||
            i2c_read(i2c_fd, 0x0080 + i * 2 + 1, &lsb) != 1) {
            return -1;
        }
        distances[i] = (msb << 8) | lsb;
    }

    return 0;
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        cleanup(0);
    }

    uint16_t distances[ZONE_COUNT];
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (read_zone_data(distances) < 0) {
            fprintf(stderr, "Failed to read zone data\n");
            continue;
        }

        printf("Zone distances:\n");
        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %2d: %5d mm\n", i, distances[i]);
        }
        printf("\n");

        clock_gettime(CLOCK_MONOTONIC, &current);
        long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 +
                          (current.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms < READ_DELAY_MS) {
            usleep((READ_DELAY_MS - elapsed_ms) * 1000);
        }
        clock_gettime(CLOCK_MONOTONIC, &start);
    }

    return EXIT_SUCCESS;
}

