#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x00 // Replace with actual sensor address
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result;
    do {
        result = i2cReadI2CBlockData(fd, reg, buf, len);
        if (result < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < MAX_RETRIES);
    return result;
}

int i2c_write(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result;
    do {
        result = i2cWriteI2CBlockData(fd, reg, buf, len);
        if (result < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < MAX_RETRIES);
    return result;
}

int read_distance(int fd) {
    uint8_t buf[2];
    if (i2c_read(fd, 0x00, buf, 2) < 0) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    struct timespec start, current;
    int i2c_handle;
    struct sigaction sa;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            long long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 +
                                   (current.tv_nsec - start.tv_nsec) / 1000000;
            printf("Timestamp: %lld ms, Distance: %d mm\n", elapsed_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

