#define VL53L4CX_RESULT_RANGE_STATUS_REG 0x14
#define POLL_INTERVAL_MS 500

static int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        gpioI2CClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, VL53L4CX_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    struct timespec ts;
    char timestamp[64];
    uint8_t int_status, range_status;

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        struct tm *tm_info = localtime(&ts.tv_sec);
        snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                 tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, ts.tv_nsec / 1000);

        if (gpioI2CWriteByteData(i2c_handle, VL53L4CX_INT_STATUS_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to write to interrupt status register\n");
            continue;
        }

        usleep(10000); // Small delay to allow the sensor to respond

        if (gpioI2CReadByteData(i2c_handle, VL53L4CX_INT_STATUS_REG, &int_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status register\n");
            continue;
        }

        if (!(int_status & 0x01)) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (gpioI2CReadByteData(i2c_handle, VL53L4CX_RESULT_RANGE_STATUS_REG, &range_status) < 0) {
            fprintf(stderr, "Failed to read range status register\n");
            continue;
        }

        printf("Timestamp: %s, Distance: %d mm\n", timestamp, range_status);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

