#include <pigpio.h>
#include < VL53L1X.h>

#define BUZZER_PIN 22
#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define MEASURE_INTERVAL_MS 500
#define DISTANCE_THRESHOLD_MM 100

VL53L1_Dev_t dev;
struct gpiod_chip *chip;
struct gpiod_line *buzzer_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    VL53L1_StopMeasurement(&dev);
    VL53L1_ShutdownDevice(&dev);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line for buzzer\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for buzzer\n");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (VL53L1_Init(&dev, I2C_BUS, I2C_ADDRESS) != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    VL53L1_StartMeasurement(&dev);

    signal(SIGINT, cleanup);

    while (1) {
        VL53L1_Result_t result;
        if (VL53L1_GetResult(&dev, &result) == VL53L1_ERROR_NONE) {
            printf("Distance: %d mm\n", result.MeasuredDistance);
            if (result.MeasuredDistance < DISTANCE_THRESHOLD_MM) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpiod_line_set_value(buzzer_line, 0);
        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

