#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define TIMEOUT_MS 50
#define READ_INTERVAL_MS 200
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double measure_distance() {
    gpiod_line_event event;
    struct timespec start, end;
    long long elapsed_ns;

    gpiod_line_set_value(TRIG_PIN, 1);
    gpioDelay(10);
    gpiod_line_set_value(TRIG_PIN, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < TIMEOUT_MS * 1000; i++) {
        if (gpiod_line_event_wait(ECHO_PIN, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE, 1000) > 0) {
            if (gpiod_line_event_read(ECHO_PIN, &event) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
                return (double)elapsed_ns / 5800.0; // Speed of sound ~343 m/s = 5800 cm/s
            }
        }
    }

    return -1.0; // Timeout
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line, *servo_line;
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);

    if (!trigger_line || !echo_line || !servo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0);
    gpiod_line_request_input(echo_line, "HC-SR04 Echo");
    gpiod_line_request_output(servo_line, "SG90 Servo", 0);

    log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0) {
            int angle = map_distance_to_angle(distance);
            gpioServoWrite(SERVO_PIN, angle);

            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s: Distance: %.2f cm, Angle: %d\n", timestamp, distance, angle);
            fflush(log_file);
        }
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_MS / 1000, (READ_INTERVAL_MS % 1000) * 1000);
    }

    gpioServoWrite(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

