#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <gpiod.h>
#include <pigpio.h>
#include < VL53L1_platform.h>
#include < VL53L1_api.h>

#define MQ_NAME "/distance_queue"
#define BUZZER_PIN 23
#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TIMING_BUDGET 50000
#define DISTANCE_THRESHOLD 100

static VL53L1_Dev_t dev;
static int i2c_handle;
static struct mq_attr mq_attr;
static mqd_t mq;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    printf("Cleaning up...\n");

    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq_unlink(MQ_NAME);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (i2c_handle >= 0) {
        gpioTerminate();
    }

    VL53L1_ShutdownDevice(&dev);
    exit(EXIT_SUCCESS);
}

int main() {
    VL53L1_Error status;
    uint16_t distance;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(SIGINT);
    }

    // Initialize VL53L1X sensor
    status = VL53L1_Init(&dev, I2C_ADDR);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1X initialization failed: %d\n", status);
        cleanup(SIGINT);
    }

    // Set timing budget
    status = VL53L1_SetMeasurementTimingBudgetMicroSeconds(&dev, TIMING_BUDGET);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to set timing budget: %d\n", status);
        cleanup(SIGINT);
    }

    // Start continuous measurements
    status = VL53L1_StartMeasurement(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to start continuous measurement: %d\n", status);
        cleanup(SIGINT);
    }

    // Set up message queue
    mq_attr.mq_flags = 0;
    mq_attr.mq_maxmsg = 10;
    mq_attr.mq_msgsize = sizeof(uint16_t);
    mq_attr.mq_curmsgs = 0;

    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0644, &mq_attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        cleanup(SIGINT);
    }

    // Set up GPIO for buzzer
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(SIGINT);
    }

    line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup(SIGINT);
    }

    if (gpiod_line_request_output(line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        cleanup(SIGINT);
    }

    // Main loop
    while (1) {
        status = VL53L1_GetDistance(&dev, &distance);
        if (status == VL53L1_ERROR_NONE) {
            // Log distance to message queue
            if (mq_send(mq, (const char *)&distance, sizeof(uint16_t), 0) == -1) {
                perror("mq_send");
            }

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }

            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to get distance: %d\n", status);
        }

        usleep(50000); // 50ms delay
    }

    return EXIT_SUCCESS;
}

