#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define LOG_FILE "gate_log.txt"
#define DISTANCE_THRESHOLD 20

static int i2c_fd;
static FILE *log_file;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void setup_i2c() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(1);
    }
}

void vl53l1x_soft_reset() {
    unsigned char reset_cmd = 0x00;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Failed to send soft reset command");
    }
    usleep(100000); // Wait 100ms for reset
}

void vl53l1x_start_ranging() {
    unsigned char start_cmd = 0x01;
    if (write(i2c_fd, &start_cmd, 1) != 1) {
        perror("Failed to start ranging");
    }
}

uint16_t vl53l1x_read_distance() {
    unsigned char distance_cmd = 0x10;
    if (write(i2c_fd, &distance_cmd, 1) != 1) {
        perror("Failed to request distance");
        return 0xFFFF; // Error value
    }

    unsigned char distance[2];
    if (read(i2c_fd, distance, 2) != 2) {
        perror("Failed to read distance");
        return 0xFFFF; // Error value
    }

    return (distance[0] << 8) | distance[1];
}

void setup_servo() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz for SG90
}

void open_gate() {
    gpioPWM(SERVO_PIN, 125); // 90 degrees
    log_event("Gate opened");
}

void close_gate() {
    gpioPWM(SERVO_PIN, 25); // 0 degrees
    log_event("Gate closed");
}

void handle_signal(int signo) {
    log_event("Received signal, cleaning up...");
    gpioTerminate();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

void force_open() {
    open_gate();
}

void force_close() {
    close_gate();
}

const char* status_request() {
    static char status[20];
    uint16_t distance = vl53l1x_read_distance();
    if (distance == 0xFFFF) {
        snprintf(status, sizeof(status), "Error reading distance");
    } else {
        snprintf(status, sizeof(status), "Distance: %d cm", distance);
    }
    return status;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    setup_i2c();
    vl53l1x_soft_reset();
    log_event("VL53L1X soft reset complete");

    // Wait for boot (adjust timing as needed)
    usleep(500000);

    vl53l1x_start_ranging();
    log_event("VL53L1X ranging started");

    setup_servo();
    log_event("Servo initialized");

    uint16_t last_distance = 0xFFFF;
    while (1) {
        uint16_t distance = vl53l1x_read_distance();
        if (distance == 0xFFFF) {
            log_event("Error reading distance, retrying...");
            usleep(1000000); // Wait 1 second before retry
            continue;
        }

        if (distance < DISTANCE_THRESHOLD && last_distance >= DISTANCE_THRESHOLD) {
            open_gate();
        } else if (distance >= DISTANCE_THRESHOLD && last_distance < DISTANCE_THRESHOLD) {
            close_gate();
        }

        last_distance = distance;
        usleep(100000); // Check every 100ms
    }

    return 0;
}

