#include <string.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_INTERVAL_US 200000
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define TIMEOUT_US 60000

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static int running = 1;

static void signal_handler(int signum) {
    running = 0;
}

static void log_distance(uint64_t distance_us, const struct timespec *ts) {
    char timestamp[64];
    struct tm tm_info;
    char distance_str[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime_r(&ts->tv_sec, &tm_info));
    snprintf(distance_str, sizeof(distance_str), "%llu", (unsigned long long)distance_us);

    fprintf(log_file, "%s.%09ldZ %s\n", timestamp, ts->tv_nsec, distance_str);
    fflush(log_file);
    printf("%s.%09ldZ %s\n", timestamp, ts->tv_nsec, distance_str);
}

static void echo_callback(struct gpiod_line *line, int event, uint64_t timestamp, void *user_data) {
    static uint64_t rising_tick = 0;
    static int waiting_for_rising = 1;
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    if (waiting_for_rising) {
        if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
            rising_tick = timestamp;
            waiting_for_rising = 0;
        }
    } else {
        if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
            uint64_t pulse_width = timestamp - rising_tick;

            if (pulse_width >= MIN_PULSE_WIDTH_US && pulse_width <= MAX_PULSE_WIDTH_US) {
                uint64_t distance_us = pulse_width / 58; // Speed of sound ~343 m/s -> 58 µs/cm
                log_distance(distance_us, &ts);
            } else {
                fprintf(stderr, "Warning: Rejected pulse width %llu µs at %s.%09ldZ\n",
                        (unsigned long long)pulse_width, timestamp, ts.tv_nsec);
            }

            waiting_for_rising = 1;
        }
    }
}

int main() {
    struct sigaction sa;
    int ret;

    // Initialize signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request TRIG line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(-ret));
        goto cleanup;
    }

    // Request ECHO line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_rising_edge_events(echo_line, "hc-sr04-echo", echo_callback, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line events: %s\n", strerror(-ret));
        goto cleanup;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Main loop
    while (running) {
        // Send trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        usleep(TRIGGER_INTERVAL_US - 10); // Account for trigger time
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }

    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    if (trig_line) {
        gpiod_line_release(trig_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}
