void log_state(const char *state, uint16_t distance) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] State: %s, Distance: %d mm\n", time_str, state, distance);
    fflush(log_file);
}

void open_gate() {
    gpioServoWrite(SERVO_PIN, OPEN_ANGLE);
    log_state("OPEN", 0);
}

void close_gate() {
    gpioServoWrite(SERVO_PIN, CLOSED_ANGLE);
    log_state("CLOSED", 0);
}

void check_sensor() {
    uint16_t distance;
    VL53L1_GetDistance(&dev, &distance);
    if (distance <= OPEN_DISTANCE) {
        open_gate();
    } else if (distance > CLOSED_DISTANCE) {
        close_gate();
    }
    log_state(distance <= OPEN_DISTANCE ? "OPEN" : "CLOSED", distance);
}

