        .consumer = "parking_gate",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };

    struct gpiod_line *shutdown_line = gpiod_chip_get_line(chip, SHUTDOWN_PIN);
    if (!shutdown_line) {
        fprintf(stderr, "Failed to get shutdown line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request(shutdown_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request shutdown line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    gpiod_line_set_value(shutdown_line, 0); // Activate VL53L1X
    usleep(100000); // Wait for sensor to power up

