        fprintf(stderr, "Failed to set VL53L1X device mode\n");
        VL53L1_ShutdownDevice(&dev);
        gpiod_line_release(shutdown_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

