#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include < VL53L1X.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define POLL_INTERVAL_MS 500
#define DISTANCE_THRESHOLD_MM 200
#define LOG_FILE "gate_events.log"
#define GPIO_OPEN 18
#define GPIO_CLOSE 19

VL53L1_Dev_t dev;
int i2c_handle;
FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *line_open, *line_close;

void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file);
}

void cleanup(int signum) {
    printf("Cleaning up...\n");

    if (line_open) gpiod_line_release(line_open);
    if (line_close) gpiod_line_release(line_close);
    if (chip) gpiod_chip_close(chip);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    if (VL53L1_StopMeasurement(&dev) == VL53L1_ERROR_NONE)
        printf("Sensor stopped successfully.\n");

    exit(EXIT_SUCCESS);
}

int main() {
    VL53L1_Error status;
    uint16_t distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line_open = gpiod_chip_get_line(chip, GPIO_OPEN);
    line_close = gpiod_chip_get_line(chip, GPIO_CLOSE);
    if (!line_open || !line_close) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line_open, "VL53L1X Open", 0);
    gpiod_line_request_output(line_close, "VL53L1X Close", 1);

    status = VL53L1_DataInit(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_DataInit failed: %d\n", status);
        cleanup(0);
    }

    status = VL53L1_SetDeviceAddress(&dev, SENSOR_ADDR);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_SetDeviceAddress failed: %d\n", status);
        cleanup(0);
    }

    status = VL53L1_SensorInit(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_SensorInit failed: %d\n", status);
        cleanup(0);
    }

    status = VL53L1_SetDeviceMode(&dev, VL53L1_DEVICEMODE_SINGLE_RANGING);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_SetDeviceMode failed: %d\n", status);
        cleanup(0);
    }

    status = VL53L1_SetMeasurementTimingBudgetMicroSeconds(&dev, 50000);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_SetMeasurementTimingBudgetMicroSeconds failed: %d\n", status);
        cleanup(0);
    }

    status = VL53L1_StartMeasurement(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_StartMeasurement failed: %d\n", status);
        cleanup(0);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        status = VL53L1_GetDistance(&dev, &distance);
        if (status == VL53L1_ERROR_NONE) {
            if (distance <= DISTANCE_THRESHOLD_MM) {
                gpiod_line_set_value(line_open, 1);
                gpiod_line_set_value(line_close, 0);
                log_event("Gate opened");
            } else {
                gpiod_line_set_value(line_open, 0);
                gpiod_line_set_value(line_close, 1);
                log_event("Gate closed");
            }
        } else {
            fprintf(stderr, "VL53L1_GetDistance failed: %d\n", status);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

