                gpiod_line_set_value(line_close, 0);
                log_event("Gate opened");
            } else {
                gpiod_line_set_value(line_open, 0);
                gpiod_line_set_value(line_close, 1);
                log_event("Gate closed");
            }
        } else {
            fprintf(stderr, "VL53L1_GetDistance failed: %d\n", status);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
