    if (read(i2c_fd, buf, 1) != 1) return -1;
    *value = buf[0];
    return 0;
}

int setup_mpr121() {
    uint8_t value;

    // Soft reset
    i2c_write(MPR121_ECR, 0x00);
    usleep(10000);

    // Check if sensor is present
    if (i2c_read(MPR121_MHDR, &value) != 0) return -1;

    // Configure sensor
    i2c_write(MPR121_MHDR, 0x02);
    i2c_write(MPR121_NHDR, 0x01);
    i2c_write(MPR121_NCLR, 0x00);
    i2c_write(MPR121_FDLR, 0x00);
    i2c_write(MPR121_MHDF, 0x01);
