    i2c_write(MPR121_FDLT, 0x00);
    i2c_write(MPR121_TOUCH_THRESHOLD, 0x10);
    i2c_write(MPR121_RELEASE_THRESHOLD, 0x05);
    i2c_write(MPR121_DEBOUNCE, 0x00);
    i2c_write(MPR121_CONFIG1, 0x10);
    i2c_write(MPR121_CONFIG2, 0x20);
    i2c_write(MPR121_CHARGING_TIME1, 0x14);
    i2c_write(MPR121_CHARGING_TIME2, 0x01);
    i2c_write(MPR121_ECR, 0x8F);

    return 0;
}

void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(led_lines[i], (pattern & (1 << i)) ? 1 : 0);
    }
}

