    uint8_t touch_status[2];
    uint8_t pattern;
    struct timespec ts;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Setup MPR121
    if (setup_mpr121() != 0) {
        fprintf(stderr, "Failed to setup MPR121\n");
        cleanup(0);
        return 1;
    }

    // Setup GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(0);
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, LED_PINS[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for LED %d\n", i);
            cleanup(0);
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "LED", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line for LED %d\n", i);
            cleanup(0);
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Proximity-based interactive art installation started\n");

    while (1) {
        if (i2c_read(MPR121_TOUCH_STATUS, &touch_status[0]) != 0 ||
            i2c_read(MPR121_TOUCH_STATUS + 1, &touch_status[1]) != 0) {
            fprintf(stderr, "Failed to read touch status\n");
            cleanup(0);
            return 1;
        }

        pattern = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                pattern |= 1 << (i % 4);
            }
        }

        set_led_pattern(pattern);

        if (pattern != 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "[%s.%09ld] Proximity detected: 0x%02X\n", 
                    timestamp, ts.tv_nsec, pattern);
            fflush(log_file);
        }

        usleep(50000);  // 50ms delay
    }

    return 0;
}

