#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 343.0 // m/s
#define TEMP_CORRECTION 0.0 // Correction for 20°C
#define MIN_DISTANCE 2.0 // cm
#define MAX_DISTANCE 400.0 // cm
#define TRIGGER_PULSE_DURATION 10 // µs
#define ECHO_TIMEOUT 30000 // µs
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t terminate = 0;

void sigint_handler(int signum) {
    terminate = 1;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec start, end;
    int ret;

    // Send 10µs pulse to trigger
    gpiod_line_set_value(trigger, 0);
    nanosleep(&(struct timespec){0, 5000}, NULL); // 5µs low
    gpiod_line_set_value(trigger, 1);
    nanosleep(&(struct timespec){0, TRIGGER_PULSE_DURATION * 1000}, NULL); // 10µs high
    gpiod_line_set_value(trigger, 0);

    // Wait for echo high
    ret = gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING_EDGE, ECHO_TIMEOUT * 1000);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for rising edge: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Echo pulse not detected within timeout\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo low
    ret = gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING_EDGE, ECHO_TIMEOUT * 1000);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for falling edge: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Echo pulse ended without falling edge within timeout\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    double duration = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    double distance = (duration / 2.0) / 1e6 * SPEED_OF_SOUND + TEMP_CORRECTION;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return distance;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    FILE *log_file;
    char timestamp[64];
    struct timespec ts;
    double distance;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Error getting trigger line\n");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error getting echo line\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "HC-SR04 Trigger", 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output\n");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Error requesting echo line as input\n");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        goto cleanup;
    }

    while (!terminate) {
        distance = measure_distance(chip, trigger, echo);
        if (distance >= 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));
            fprintf(log_file, "%s %.2f\n", timestamp, distance);
            fflush(log_file);
        }
        sleep(1);
    }

    fclose(log_file);

cleanup:
    if (log_file) fclose(log_file);
    if (echo) gpiod_line_release(echo);
    if (trigger) gpiod_line_release(trigger);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

