    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void echo_isr_event_handler(struct gpiod_line *line, int event_type, void *user_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int current_tick = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        echo_start_tick = current_tick;
    } else if (event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_end_tick = current_tick;
        if (echo_start_tick != -1) {
            int pulse_width_us = echo_end_tick - echo_start_tick;
            if (pulse_width_us < 0) {
                pulse_width_us += 1000000;
                tick_wrap_around = 1;
            }
            if (pulse_width_us > MIN_PULSE_WIDTH_US && pulse_width_us < MAX_PULSE_WIDTH_US) {
                float distance_m = pulse_width_us / 5800.0;
                fprintf(log_file, "%ld.%06ld, %.2f\n", ts.tv_sec, ts.tv_nsec / 1000, distance_m);
                fflush(log_file);
            }
            echo_start_tick = -1;
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        cleanup(0);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        cleanup(0);
    }

    if (gpiod_line_request_output(trig_line, "ultrasonic_trigger", 0) < 0) {
        fprintf(stderr, "Failed to request TRIG line as output\n");
        cleanup(0);
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "ultrasonic_echo", echo_isr_event_handler, NULL) < 0) {
        fprintf(stderr, "Failed to request ECHO line for rising edge events\n");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    while (1) {
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIGGER_DURATION_US);
        gpiod_line_set_value(trig_line, 0);
        sleep(1);
    }

    return EXIT_SUCCESS;
}
