#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_PIN 24
#define MEASURE_INTERVAL_MS 100
#define LOG_FILE "gate_log.txt"

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void handle_signal(int signum) {
    log_message("Shutting down...");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line) {
        gpiod_line_release(line);
    }
    gpioTerminate();
    exit(0);
}

int init_i2c() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        log_message("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int read_distance() {
    uint8_t buffer[2];
    if (write(i2c_fd, "\x14", 1) != 1) {
        log_message("Failed to write to VL53L1X");
        return -1;
    }
    usleep(10000); // Wait for measurement
    if (read(i2c_fd, buffer, 2) != 2) {
        log_message("Failed to read from VL53L1X");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, PI_LOW); // Initialize gate to closed state

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (init_i2c() < 0) {
        log_message("Failed to initialize I2C");
        handle_signal(SIGINT);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_message("Program started");

    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            int cm = distance / 10;
            char log_buf[100];
            snprintf(log_buf, sizeof(log_buf), "Distance: %d cm", cm);
            log_message(log_buf);

            int gate_state = (cm < 20) ? PI_HIGH : PI_LOW;
            if (gpioRead(GATE_PIN) != gate_state) {
                gpioWrite(GATE_PIN, gate_state);
                snprintf(log_buf, sizeof(log_buf), "Gate %s", (gate_state == PI_HIGH) ? "opened" : "closed");
                log_message(log_buf);
            }
        }
        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    return 0;
}

