#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define NUM_SAMPLES 5
#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define PULSE_WIDTH_MIN 10000 // 10 µs
#define PULSE_WIDTH_MAX 20000 // 20 µs
#define TIMEOUT_MS 30
#define MOVING_AVERAGE_WINDOW 5

volatile sig_atomic_t stop_program = 0;
volatile uint32_t pulse_width = 0;
volatile int new_pulse = 0;
uint32_t distance_samples[NUM_SAMPLES] = {0};
int sample_index = 0;
uint32_t moving_average_sum = 0;

void signal_handler(int signum) {
    stop_program = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int echo_started = 0;

    if (level == 1) {
        start_tick = tick;
        echo_started = 1;
    } else if (level == 0 && echo_started) {
        uint32_t end_tick = tick;
        uint32_t duration = (end_tick >= start_tick) ? (end_tick - start_tick) : (UINT32_MAX - start_tick + end_tick);

        if (duration >= PULSE_WIDTH_MIN && duration <= PULSE_WIDTH_MAX) {
            pulse_width = duration;
            new_pulse = 1;
        }
        echo_started = 0;
    }
}

uint32_t get_moving_average(uint32_t new_sample) {
    moving_average_sum -= distance_samples[sample_index];
    distance_samples[sample_index] = new_sample;
    moving_average_sum += new_sample;
    sample_index = (sample_index + 1) % NUM_SAMPLES;
    return moving_average_sum / NUM_SAMPLES;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    FILE *log_file;
    int servo_initialized = 0;
    int gpio_initialized = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpio_initialized = 1;

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0 || gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        goto cleanup;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        goto cleanup;
    }

    if (gpioHardwarePWM(SERVO_PIN, 50, 0) < 0) {
        fprintf(stderr, "Failed to initialize hardware PWM for servo\n");
        goto cleanup;
    }
    servo_initialized = 1;

    log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }
    fprintf(log_file, "Timestamp,Distance(cm),ServoAngle(degrees)\n");
    fflush(log_file);

    signal(SIGINT, signal_handler);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t start_time = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    while (!stop_program) {
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        uint64_t current_time;
        do {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            current_time = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
        } while ((current_time - start_time) / 1000000 < 100);

        uint32_t distance_cm = -1;
        if (new_pulse) {
            distance_cm = pulse_width / 58;
            if (distance_cm < DISTANCE_MIN || distance_cm > DISTANCE_MAX) {
                distance_cm = -1;
            }
            new_pulse = 0;
        }

        uint32_t filtered_distance = get_moving_average(distance_cm);

        int servo_angle = 90;
        if (filtered_distance != -1) {
            servo_angle = (int)((filtered_distance - DISTANCE_MIN) * 180 / (DISTANCE_MAX - DISTANCE_MIN));
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > 180) servo_angle = 180;
        }

        if (gpioServo(SERVO_PIN, servo_angle) != 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
        fprintf(log_file, "%llu,%d,%d\n", timestamp, filtered_distance, servo_angle);
        fflush(log_file);

        usleep(10000); // 100ms delay
    }

    fclose(log_file);

cleanup:
    if (servo_initialized) {
        gpioServo(SERVO_PIN, 0);
    }
    if (gpio_initialized) {
        gpioTerminate();
    }
    return 0;
}

