#include <gpiod.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUFFER_SIZE 10
#define WARNING_LED_PIN 17
#define MEASUREMENT_INTERVAL_MS 50
#define DISTANCE_THRESHOLD_MM 200

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *led_line;
int circular_buffer[BUFFER_SIZE] = {0};
int buffer_index = 0;

void sigint_handler(int signum) {
    printf("Shutting down...\n");
    gpiod_line_set_value(led_line, 0);
    close(i2c_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write error");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int init_sensor() {
    // Set default configuration
    if (i2c_write(i2c_fd, 0x001E, 0x00) || i2c_write(i2c_fd, 0x002D, 0x01)) {
        fprintf(stderr, "Failed to set default configuration\n");
        return -1;
    }

    // Enable signal rate checking
    if (i2c_write(i2c_fd, 0x0011, 0x07) || i2c_write(i2c_fd, 0x0010, 0x03)) {
        fprintf(stderr, "Failed to enable signal rate checking\n");
        return -1;
    }

    // Configure cross-talk compensation
    if (i2c_write(i2c_fd, 0x0024, 0x01) || i2c_write(i2c_fd, 0x0023, 0xFF)) {
        fprintf(stderr, "Failed to configure cross-talk compensation\n");
        return -1;
    }

    // Start ranging
    if (i2c_write(i2c_fd, 0x0000, 0x02)) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }

    return 0;
}

int read_distance(uint16_t *distance) {
    uint8_t buffer[2];
    if (i2c_read(i2c_fd, 0x0014, &buffer[0]) || i2c_read(i2c_fd, 0x0015, &buffer[1])) {
        fprintf(stderr, "Failed to read distance\n");
        return -1;
    }
    *distance = (buffer[1] << 8) | buffer[0];
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, WARNING_LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "VL53L1X Warning LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            circular_buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            gpiod_line_set_value(led_line, distance < DISTANCE_THRESHOLD_MM);

            printf("Distance: %d mm\n", distance);
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    return 0;
}

