#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <syslog.h>

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_I2C_ADDRESS 0x60
#define LOG_FILE "proximity.log"
#define I2C_BUS 1
#define GPIO_PIN 27

static volatile int keep_running = 1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

void log_proximity(int value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    const char *status = (value <= threshold) ? "SAFE" : "ALERT";

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s %d %s\n", timestamp, value, status);
    fflush(log_file);
}

void read_proximity() {
    unsigned char buffer[2];
    int value;

    if (i2c_read_i2c_block_data(i2c_handle, 0xAA, 2, buffer) < 0) {
        fprintf(stderr, "Error reading proximity value\n");
        return;
    }

    value = (buffer[0] << 8) | buffer[1];
    log_proximity(value);
}

void interrupt_callback(int gpio, int level, uint32_t tick) {
    static int interrupt_flag = 0;
    interrupt_flag = 1;
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    if (gpioSetAlertFunc(GPIO_PIN, interrupt_callback) < 0) {
        fprintf(stderr, "Error setting GPIO interrupt\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            read_proximity();
        }
        usleep(1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

