#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define DUTY_CYCLE 50
#define TIMEOUT_MS 200

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line;
static int pwm_handle;

void sigint_handler(int signum) {
    keep_running = 0;
}

double map_distance_to_freq(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return MIN_FREQ * pow(MAX_FREQ / MIN_FREQ, (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
}

double measure_distance() {
    struct timespec start, end;
    long long elapsed_ns;

    gpiod_line_set_value(trigger_line, 1);
    gpioDelay(10);
    gpiod_line_set_value(trigger_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);
    int echo_state = gpiod_line_get_value(echo_line);
    while (echo_state == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Echo timeout\n");
            return -1;
        }
        echo_state = gpiod_line_get_value(echo_line);
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (echo_state == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Echo timeout\n");
            return -1;
        }
        echo_state = gpiod_line_get_value(echo_line);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return (double)elapsed_ns / 5800.0;  // Speed of sound ~343 m/s = 5800 cm/s
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        gpioTerminate();
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line (trigger)");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    pwm_handle = gpioHardwarePWM(PWM_PIN, 0, DUTY_CYCLE * 10000);
    if (pwm_handle < 0) {
        perror("gpioHardwarePWM");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    double prev_freq = MIN_FREQ;

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0) {
            double freq = map_distance_to_freq(distance);
            if (freq != prev_freq) {
                gpioPWM(pwm_handle, freq);
                prev_freq = freq;
            }
        }
        gpioDelay(10000);  // 10ms delay between measurements
    }

    gpioSetPWMfrequency(pwm_handle, 0);
    gpioTerminate();
    gpiod_chip_close(chip);
    return 0;
}

