#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 5
#define MAX_DISTANCE 50
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define ECHO_TIMEOUT 100000 // 100 ms in microseconds
#define READING_INTERVAL 10000 // 10 ms in microseconds

static volatile int keep_running = 1;

void sigint_handler(int signo) {
    keep_running = 0;
}

double map(double x, double in_min, double in_max, double out_min, double out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int gpio_result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM on BUZZER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    double last_valid_distance = 0;

    while (keep_running) {
        gpioWrite(TRIG_PIN, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        long start_time = gpioTick();
        long end_time = start_time;

        while (gpioRead(ECHO_PIN) == 0) {
            start_time = gpioTick();
            if (start_time - end_time > ECHO_TIMEOUT) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
        }

        end_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 1) {
            end_time = gpioTick();
            if (end_time - start_time > ECHO_TIMEOUT) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
        }

        long duration = end_time - start_time;
        double distance = duration * 0.034 / 2; // Speed of sound ~343 m/s

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        double frequency = map(distance, MIN_DISTANCE, MAX_DISTANCE, MIN_FREQ, MAX_FREQ);
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioHardwarePWM(BUZZER_PIN, frequency * 2, frequency * 50); // 50% duty cycle
        gpioDelay(READING_INTERVAL);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

