#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define MEASURE_INTERVAL_MS 500
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define TOO_CLOSE_CM 10

static volatile int exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

double measure_distance(struct gpiod_chip *chip, int trig_fd, int echo_fd) {
    struct timespec start, end;
    long elapsed_ns;

    gpiod_line_set_value(trig_fd, 1);
    usleep(10);
    gpiod_line_set_value(trig_fd, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);
    int echo_value = gpiod_line_get_value(echo_fd);
    while (echo_value == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            return -1;
        }
        echo_value = gpiod_line_get_value(echo_fd);
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (echo_value == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            return -1;
        }
        echo_value = gpiod_line_get_value(echo_fd);
    }

    double distance_cm = (elapsed_ns / 1000000000.0) * 34300 / 2;
    return distance_cm;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int trig_fd, echo_fd;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "hc-sr04-trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    trig_fd = gpiod_line_get_fd(trig_line);
    echo_fd = gpiod_line_get_fd(echo_line);

    while (!exit_flag) {
        double distance = measure_distance(chip, trig_fd, echo_fd);

        if (distance < 0) {
            printf("Invalid reading\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < TOO_CLOSE_CM) {
                printf("Too close!\n");
            }
        }

        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

