#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define READ_DELAY_MS 100

static int spi_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void cleanup(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (cs_line) {
        gpiod_line_release(cs_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int handle = spiOpen(CS_PIN, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

int read_distance() {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    int count = spiXfer(spi_handle, tx, rx, 4);

    if (count != 4) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }

    int distance = ((rx[1] & 0x3F) << 8) | rx[2];
    if (distance < 200 || distance > 5000) {
        fprintf(stderr, "Invalid distance reading: %d mm\n", distance);
        return -1;
    }

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line for CS\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "ICU-20201_CS", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = init_spi();
    if (spi_handle < 0) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int distance = read_distance();
        if (distance >= 0) {
            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);
        }

        gpiod_line_set_value(cs_line, 1);
        usleep(1000);
        gpiod_line_set_value(cs_line, 0);

        usleep(READ_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

