    if (gpiod_line_request_output(cs_line, "ICU-20201_CS", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = init_spi();
    if (spi_handle < 0) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int distance = read_distance();
        if (distance >= 0) {
            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);
        }

        gpiod_line_set_value(cs_line, 1);
        usleep(1000);
        gpiod_line_set_value(cs_line, 0);

        usleep(READ_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}
