#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SI1120_ADDR 0x60
#define ALS_DATA_0 0x05
#define ALS_DATA_1 0x06
#define PSM_DATA_0 0x0A
#define PSM_DATA_1 0x0B
#define COMMAND 0x00
#define RESET_CMD 0x01
#define PART_ID 0x02
#define EXPECTED_PART_ID 0x51
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int i2c_retry_write(int fd, uint8_t reg, uint8_t value) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cWriteByteData(fd, reg, value) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_retry_read(int fd, uint8_t reg, uint8_t *value) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cReadByteData(fd, reg, value) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int reset_si1120() {
    if (i2c_retry_write(i2c_handle, COMMAND, RESET_CMD) != 0) {
        fprintf(stderr, "Failed to reset SI1120\n");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    uint8_t part_id;
    if (i2c_retry_read(i2c_handle, PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read SI1120 part ID\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Invalid SI1120 part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

int read_sensor_data(uint16_t *als, uint16_t *proximity) {
    uint8_t als_low, als_high, prox_low, prox_high;

    if (i2c_retry_read(i2c_handle, ALS_DATA_0, &als_low) != 0 ||
        i2c_retry_read(i2c_handle, ALS_DATA_1, &als_high) != 0 ||
        i2c_retry_read(i2c_handle, PSM_DATA_0, &prox_low) != 0 ||
        i2c_retry_read(i2c_handle, PSM_DATA_1, &prox_high) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *als = (uint16_t)als_low | ((uint16_t)als_high << 8);
    *proximity = (uint16_t)prox_low | ((uint16_t)prox_high << 8);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (reset_si1120() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    uint16_t als, proximity;

    while (!terminate) {
        if (read_sensor_data(&als, &proximity) == 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s ALS: %u Proximity: %u\n", timestamp, als, proximity);
            fflush(log_file);
        }
        time_sleep(1.0 / 1000.0 * SAMPLE_INTERVAL_MS);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

