#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x0A
#define SI1182_COMMAND_REG 0x0B
#define SI1182_ALS_DATA_0_REG 0x21
#define SI1182_PS_DATA_0_REG 0x22

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C read register error");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read data error");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI1182_ADDR) < 0) {
        perror("I2C set address error");
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_read(i2c_fd, SI1182_PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read Si1182 part ID\n");
        close(i2c_fd);
        return 1;
    }
    printf("Si1182 Part ID: 0x%02X\n", part_id);

    if (i2c_write(i2c_fd, SI1182_MEAS_RATE_REG, 0x00) < 0 ||
        i2c_write(i2c_fd, SI1182_COMMAND_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure Si1182\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Log file open error");
        close(i2c_fd);
        return 1;
    }

    struct timespec ts;
    struct tm *tm_info;
    char timestamp[30];
    uint16_t lux, proximity;

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s.%03ld,", timestamp, ts.tv_nsec / 1000000);
        fprintf(log_file, "%s.%03ld,", timestamp, ts.tv_nsec / 1000000);

        if (i2c_read(i2c_fd, SI1182_ALS_DATA_0_REG, (uint8_t*)&lux) < 0 ||
            i2c_read(i2c_fd, SI1182_PS_DATA_0_REG, (uint8_t*)&proximity) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        printf("%u,%u\n", lux, proximity);
        fprintf(log_file, "%u,%u\n", lux, proximity);
        fflush(log_file);

        usleep(100000);
    }

    return 0;
}

