#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIGGER_PULSE_US 10
#define MIN_DISTANCE_CM 20
#define CLOCK_MONOTONIC 1

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *buzzer_line;
static struct timespec last_echo_time;
static volatile int echo_received = 0;

static void cleanup(int signum) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

static void echo_callback(struct gpiod_line *line, int event, void *user_data) {
    struct timespec current_time;
    if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        last_echo_time = current_time;
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_received = 1;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line (trigger)");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        goto error;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        goto error;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto error;
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "ultrasonic_echo") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        goto error;
    }

    if (gpiod_line_request_falling_edge_events(echo_line, "ultrasonic_echo") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto error;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        goto error;
    }

    while (1) {
        echo_received = 0;

        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            goto error;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            goto error;
        }

        while (!echo_received) {
            usleep(100);
        }

        struct timespec echo_duration;
        if (clock_gettime(CLOCK_MONOTONIC, &echo_duration) == -1) {
            perror("clock_gettime");
            goto error;
        }

        double distance_cm = (echo_duration.tv_sec - last_echo_time.tv_sec) * 1e9 +
                             (echo_duration.tv_nsec - last_echo_time.tv_nsec) * 1e-3 / 58.0;

        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < MIN_DISTANCE_CM) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value (buzzer high)");
                goto error;
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value (buzzer low)");
                goto error;
            }
        }

        sleep(1);
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

