#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MEASURE_INTERVAL_MS 100

static volatile int keep_running = 1;

void sigint_handler(int signo) {
    keep_running = 0;
}

double measure_distance() {
    gpiod_line_event event;
    struct timespec start, end;
    long long elapsed_ns;

    gpiod_line_set_value(TRIG_PIN, 1);
    gpioDelay(10);
    gpiod_line_set_value(TRIG_PIN, 0);

    if (gpiod_line_event_wait(ECHO_PIN, GPIOD_LINE_EVENT_RISING_EDGE, NULL) < 0) {
        return -1.0;
    }
    if (gpiod_line_event_read(ECHO_PIN, &event) < 0) {
        return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (gpiod_line_event_wait(ECHO_PIN, GPIOD_LINE_EVENT_FALLING_EDGE, NULL) < 0) {
        return -1.0;
    }
    if (gpiod_line_event_read(ECHO_PIN, &event) < 0) {
        return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return (double)elapsed_ns / 5800.0;  // Speed of sound ~343 m/s = 5800 cm/s
}

void set_servo_angle(double distance) {
    int pulse_width;
    if (distance <= 200) {
        pulse_width = 500;
    } else if (distance <= 110) {
        pulse_width = 1500;
    } else {
        pulse_width = 2500;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    ret = gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    ret = gpiod_line_request_input(echo_line, "HC-SR04 Echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance, retrying...\n");
            gpioDelay(1000000);  // Wait 1 second before retrying
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        set_servo_angle(distance);

        gpioDelay(MEASURE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return 0;
}

