#define MODEL_ID_REG 0xC0
#define EXPECTED_MODEL_ID 0xEE
#define TIMING_BUDGET_REG 0x000B
#define TIMING_BUDGET 33000 // 33 ms
#define DISTANCE_REG 0x000F
#define SERVO_PIN 18
#define OPEN_DISTANCE 250
#define CLOSE_DISTANCE 200
#define LOG_FILE "gate_log.txt"

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioHardwarePWM(SERVO_PIN, 0, 0);
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int write_i2c_reg(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(i2c_handle, buf, 2);
}

int read_i2c_reg(int reg, uint8_t *value) {
    if (write(i2c_handle, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_handle, value, 1);
}

void log_gate_event(const char *action) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", time_str, action);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        cleanup(SIGINT);
    }

    if (ioctl(i2c_handle, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup(SIGINT);
    }

    uint8_t model_id;
    if (read_i2c_reg(MODEL_ID_REG, &model_id) != 1 || model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Invalid model ID\n");
        cleanup(SIGINT);
    }

    if (write_i2c_reg(TIMING_BUDGET_REG, TIMING_BUDGET & 0xFF) != 1 ||
        write_i2c_reg(TIMING_BUDGET_REG + 1, (TIMING_BUDGET >> 8) & 0xFF) != 1) {
        fprintf(stderr, "Failed to set timing budget\n");
        cleanup(SIGINT);
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioHardwarePWM(SERVO_PIN, 50, 0); // 50 Hz frequency

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(SIGINT);
    }

    int last_distance = -1;
    int target_pulse_width = 0;

    while (1) {
        uint8_t distance_low, distance_high;
        if (read_i2c_reg(DISTANCE_REG, &distance_low) != 1 ||
            read_i2c_reg(DISTANCE_REG + 1, &distance_high) != 1) {
            fprintf(stderr, "Failed to read distance\n");
            sleep(1);
            continue;
        }

        int distance = (distance_high << 8) | distance_low;

        if (distance < CLOSE_DISTANCE) {
            target_pulse_width = 2000;
            if (last_distance >= CLOSE_DISTANCE) {
                log_gate_event("Gate opened");
            }
        } else if (distance > OPEN_DISTANCE) {
            target_pulse_width = 1000;
            if (last_distance <= OPEN_DISTANCE) {
                log_gate_event("Gate closed");
            }
        }

        if (target_pulse_width != 0) {
            int current_pulse_width = gpioGetPWMdutycycle(SERVO_PIN);
            if (current_pulse_width < target_pulse_width) {
                current_pulse_width = (current_pulse_width + target_pulse_width) / 2;
            } else if (current_pulse_width > target_pulse_width) {
                current_pulse_width = (current_pulse_width + target_pulse_width) / 2;
            }
            gpioPWM(SERVO_PIN, current_pulse_width);
        }

        last_distance = distance;
        usleep(100000); // 100ms delay
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}

