#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define TRIGGER_PULSE_WIDTH 10
#define ECHO_TIMEOUT 50000
#define MEASUREMENT_DELAY 100
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

static volatile int keep_running = 1;

void sigint_handler(int signo) {
    keep_running = 0;
}

double measure_distance(struct gpiod_chip *chip, int trig_fd, int echo_fd) {
    gpiod_line_set_value(trig_fd, 1);
    usleep(TRIGGER_PULSE_WIDTH);
    gpiod_line_set_value(trig_fd, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int echo_state = 0;
    while (echo_state == 0) {
        echo_state = gpiod_line_get_value(echo_fd);
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > ECHO_TIMEOUT) {
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    echo_state = 1;
    while (echo_state == 1) {
        echo_state = gpiod_line_get_value(echo_fd);
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > ECHO_TIMEOUT) {
            return -1.0;
        }
    }

    double travel_time = (end.tv_sec - start.tv_sec) * 1000000.0 + (end.tv_nsec - start.tv_nsec) / 1000.0;
    double distance = (travel_time / 58.0);
    return distance;
}

double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;
    return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int trig_fd, echo_fd;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "HC-SR04 Trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    trig_fd = gpiod_line_get_fd(trig_line);
    echo_fd = gpiod_line_get_fd(echo_line);

    signal(SIGINT, sigint_handler);

    while (keep_running) {
        double distance = measure_distance(chip, trig_fd, echo_fd);
        double angle = map_distance_to_angle(distance);

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        if (distance >= 0) {
            int pulse_width = SERVO_MIN_PULSE + (int)((SERVO_MAX_PULSE - SERVO_MIN_PULSE) * angle / MAX_ANGLE);
            gpioServo(SERVO_PIN, pulse_width);
        }

        usleep(MEASUREMENT_DELAY * 1000);
    }

    gpioServo(SERVO_PIN, 0);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

