#define I2C_RETRIES 3
#define RETRY_DELAY_MS 100

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI7005_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si7005 initialized\n");

    while (1) {
        int retries = 0;
        while (retries < I2C_RETRIES) {
            if (i2c_write(i2c_fd, CONFIG_REG, 0x27) != 2) {
                perror("Failed to write CONFIG register");
                close(i2c_fd);
                i2c_fd = open(I2C_BUS, O_RDWR);
                if (i2c_fd < 0) {
                    perror("Failed to reopen I2C bus");
                    return EXIT_FAILURE;
                }
                if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI7005_ADDR) < 0) {
                    perror("Failed to set I2C address on retry");
                    close(i2c_fd);
                    return EXIT_FAILURE;
                }
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            usleep(10000);

            uint8_t temp_reg = TEMP_REG;
            if (i2c_write(i2c_fd, temp_reg, 0) != 1) {
                perror("Failed to write TEMP register");
                close(i2c_fd);
                i2c_fd = open(I2C_BUS, O_RDWR);
                if (i2c_fd < 0) {
                    perror("Failed to reopen I2C bus");
                    return EXIT_FAILURE;
                }
                if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI7005_ADDR) < 0) {
                    perror("Failed to set I2C address on retry");
                    close(i2c_fd);
                    return EXIT_FAILURE;
                }
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            usleep(10000);

            uint8_t temp_data[3];
            if (read(i2c_fd, temp_data, 3) != 3) {
                perror("Failed to read temperature data");
                close(i2c_fd);
                i2c_fd = open(I2C_BUS, O_RDWR);
                if (i2c_fd < 0) {
                    perror("Failed to reopen I2C bus");
                    return EXIT_FAILURE;
                }
                if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI7005_ADDR) < 0) {
                    perror("Failed to set I2C address on retry");
                    close(i2c_fd);
                    return EXIT_FAILURE;
                }
                retries++;
                continue;
            }

            uint16_t raw_temp = (temp_data[0] << 8) | temp_data[1];
            float temperature = -45.0 + (175.72 * raw_temp / 65536.0);

            printf("Temperature: %.2f°C\n", temperature);
            break;
        }

        if (retries == I2C_RETRIES) {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", I2C_RETRIES);
            return EXIT_FAILURE;
        }

        sleep(2);
    }

    return EXIT_SUCCESS;
}
