#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SHT40_I2C_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_CMD 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    struct i2c_msg messages[1];
    uint8_t buffer[6];
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            sleep(5);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        buffer[0] = MEASURE_CMD;
        messages[0].addr = SHT40_I2C_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "I2C write error\n");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        usleep(10000);  // 10ms delay

        messages[0].flags = I2C_M_RD;
        messages[0].len = 6;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "I2C read error\n");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        uint8_t temp_crc = calculate_crc8(buffer, 2);
        uint8_t hum_crc = calculate_crc8(buffer + 3, 2);

        if (temp_crc != buffer[2] || hum_crc != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            close(i2c_fd);
            sleep(5);
            continue;
        }

        float temperature = -45 + 175 * ((buffer[0] * 256 + buffer[1]) / 65535.0);
        float humidity = 100 * ((buffer[3] * 256 + buffer[4]) / 65535.0);

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        close(i2c_fd);
        sleep(5);
    }

    return 0;
}

