#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x5A
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_write(fd, reg, 0) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

float read_temp(int fd, uint8_t reg) {
    uint8_t data[2];
    if (i2c_read(fd, reg, data) != 1) {
        return -1;
    }
    return (float)(data[0] << 8 | data[1]) * 0.02 - 273.15;
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_write = 0;

    while (1) {
        time_t now = time(NULL);
        if (now - last_write >= READ_INTERVAL) {
            float ambient_temp = read_temp(i2c_fd, 0x06);
            float object_temp = read_temp(i2c_fd, 0x07);

            if (ambient_temp < -273.15 || object_temp < -273.15) {
                fprintf(stderr, "Error reading temperature\n");
            } else {
                fprintf(log_file, "%ld,%f,%f\n", (long)now, ambient_temp, object_temp);
                fflush(log_file);
                last_write = now;
            }
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

