#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5

static int i2c_fd;
static FILE *log_fp, *error_fp;

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(error_fp, "[%s] %s\n", time_str, message);
    fflush(error_fp);
}

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    if (error_fp) {
        fclose(error_fp);
    }
    exit(signum);
}

int write_i2c(int file, uint8_t *buf, int len) {
    if (write(file, buf, len) != len) {
        log_error("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int file, uint8_t *buf, int len) {
    if (read(file, buf, len) != len) {
        log_error("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int read_temperature(float *temperature) {
    uint8_t buf[6];
    buf[0] = 0x00; // Command to read temperature
    if (write_i2c(i2c_fd, buf, 1) < 0) {
        return -1;
    }
    usleep(10000); // Wait for conversion

    if (read_i2c(i2c_fd, buf, 6) < 0) {
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
