#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_I2C_ADDR 0x22
#define MEASURE_CMD 0x03
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct i2c_msg messages[2];
    uint8_t write_buf[3] = {MEASURE_CMD, 0x00, 0x00};
    uint8_t read_buf[9];
    struct timespec ts;
    char timestamp[64];
    double pressure, temperature;
    int16_t raw_pressure, raw_temp;
    uint16_t pressure_scale, temp_scale;

