        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    messages[0].addr = SDP810_I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 3;
    messages[0].buf = write_buf;

    messages[1].addr = SDP810_I2C_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 9;
    messages[1].buf = read_buf;

    while (keep_running) {
        if (write(i2c_fd, write_buf, 3) != 3) {
            perror("Failed to write to I2C device");
            break;
        }

        usleep(1000);  // Wait at least 1ms

        if (read(i2c_fd, read_buf, 9) != 9) {
            perror("Failed to read from I2C device");
            break;
        }

        if (calculate_crc8(read_buf, 2) != read_buf[2] ||
            calculate_crc8(read_buf + 3, 2) != read_buf[5] ||
            calculate_crc8(read_buf + 6, 2) != read_buf[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        raw_pressure = (read_buf[0] << 8) | read_buf[1];
        raw_temp = (read_buf[3] << 8) | read_buf[4];
        pressure_scale = (read_buf[6] << 8) | read_buf[7];
        temp_scale = (read_buf[8] << 8) | read_buf[9];

        pressure = raw_pressure * pressure_scale / 1000000.0;
        temperature = raw_temp * temp_scale / 100.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

