#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP31_I2C_ADDR 0x21
#define SDP31_MEASURE_CONTINUOUS 0x3603
#define SDP31_READ_MEASUREMENT 0xE000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, const uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(fd, buf, len) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * (1 << attempt) * 1000);
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(fd, buf, len) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * (1 << attempt) * 1000);
    }
    return -1;
}

int calculate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SDP31_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("airflow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t start_cmd[] = {0x36, 0x03};
    if (i2c_write(i2c_handle, start_cmd, sizeof(start_cmd)) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    usleep(1000);  // Wait 1ms after trigger

    while (keep_running) {
        uint8_t read_cmd[] = {0xE0, 0x00};
        uint8_t response[6];

        if (i2c_write(i2c_handle, read_cmd, sizeof(read_cmd)) != 0 ||
            i2c_read(i2c_handle, response, sizeof(response)) != 0) {
