        fprintf(stderr, "Error writing to sensor\n");
        return -1;
    }

    usleep(20000);  // Wait for measurement to complete

    if (i2cReadRetry(i2cHandle, buf, 2) != 0) {
        fprintf(stderr, "Error reading from sensor\n");
        return -1;
    }

    *value = ((buf[0] << 8) | buf[1]) * 125.0 / 65536.0 - 6;
    return 0;
}

