    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    i2cHandle = gpioI2COpen(I2C_BUS, SI7015_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
