        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float temperature, humidity;

        if (readSensorData(TEMP_MEASURE_NOHOLD, &temperature) == 0) {
            printf("%s - Temperature: %.2f°C\n", timestamp, temperature);
            fprintf(logFile, "%s - Temperature: %.2f°C\n", timestamp, temperature);
