        if (readSensorData(HUMIDITY_MEASURE_NOHOLD, &humidity) == 0) {
            printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
            fprintf(logFile, "%s - Humidity: %.2f%%\n", timestamp, humidity);
        }

        fflush(logFile);
        sleep(5);
    }

    return EXIT_SUCCESS;
}

