#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x21
#define SDP800_CONT_MEASURE_TRIGGER 0x3615
#define SDP800_READ_MEASURE 0xEC05
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_FINAL_XOR 0x00

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ CRC8_FINAL_XOR;
}

int validate_crc8(const uint8_t *data, size_t len) {
    return calculate_crc8(data, len - 1) == data[len - 1];
}

int main() {
    int i2c_fd;
    FILE *output_file;
    struct i2c_msg messages[2];
    uint8_t write_buf[2], read_buf[9];
    struct timespec start_time, current_time;
    long elapsed_ms;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SDP800_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    write_buf[0] = SDP800_CONT_MEASURE_TRIGGER >> 8;
    write_buf[1] = SDP800_CONT_MEASURE_TRIGGER & 0xFF;
    messages[0].addr = SDP800_I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = write_buf;

    messages[1].addr = SDP800_I2C_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 9;
    messages[1].buf = read_buf;

    output_file = fopen("airflow_data.txt", "w");
    if (!output_file) {
        perror("Failed to open output file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(output_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    fflush(output_file);

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (keep_running) {
        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            break;
        }

        if (!validate_crc8(read_buf, 3) || !validate_crc8(read_buf + 3, 3) || !validate_crc8(read_buf + 6, 3)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        int32_t pressure_raw = (read_buf[0] << 16) | (read_buf[1] << 8) | read_buf[2];
        int32_t temperature_raw = (read_buf[3] << 16) | (read_buf[4] << 8) | read_buf[5];

        double pressure = pressure_raw / 100.0;
        double temperature = temperature_raw / 200.0;

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                     (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        if (elapsed_ms % 100 == 0) {
            time_t now = time(NULL);
            char timestamp[26];
            ctime_r(&now, timestamp);
            timestamp[24] = '\0';

            fprintf(output_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
            fflush(output_file);
        }

        usleep(45000);
    }

    fclose(output_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

