#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static int i2c_handle;
static FILE *log_file, *error_file;

void log_message(const char *filename, const char *message) {
    FILE *file = fopen(filename, "a");
    if (file) {
        time_t now = time(NULL);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(file, "[%s] %s\n", timestamp, message);
        fclose(file);
    }
}

void error_handler(const char *message) {
    log_message("error_log.txt", message);
}

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (error_file) {
        fclose(error_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

