    while (1) {
        uint8_t write_buf[3] = { MEASURE_CMD >> 8, MEASURE_CMD & 0xFF, 0 };
        if (i2cWriteDevice(i2c_handle, write_buf, 3) < 0) {
            error_handler("Failed to write measurement command");
            continue;
