#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t write_buf[2], read_buf[6];
    struct i2c_msg messages[2];
    struct i2c_rdwr_ioctl_data packets;
    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    write_buf[0] = MEASURE_CMD;
    write_buf[1] = 0x39;  // High repeatability

    while (keep_running) {
        messages[0].addr = SHT40_I2C_ADDR;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = write_buf;

        messages[1].addr = SHT40_I2C_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 6;
        messages[1].buf = read_buf;

        packets.msgs = messages;
        packets.nmsgs = 2;

        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            fprintf(stderr, "Error during I2C communication: %s\n", strerror(errno));
            continue;
        }

        uint8_t temp_crc = calculate_crc(read_buf, 2);
        uint8_t hum_crc = calculate_crc(read_buf + 3, 2);

        if (temp_crc != read_buf[2] || hum_crc != read_buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        temperature = -45 + 175 * ((float)read_buf[0] * 256 + read_buf[1]) / 65535.0;
        humidity = 100 * ((float)read_buf[3] * 256 + read_buf[4]) / 65535.0;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s, Temperature: %.2f°C, Humidity: %.2f%%\n",
                 timestamp, temperature, humidity);

        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
            perror("Failed to write to log file");
        }

        usleep(8500);  // Wait 8.5ms
    }

    close(log_fd);
    close(i2c_fd);
    return 0;
}

