#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x21
#define SDP800_CONT_MEASURE 0x21
#define SDP800_READ_MEASURE 0x03E3
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    FILE *file;
    struct i2c_msg messages[2];
    uint8_t write_buf[2] = {SDP800_CONT_MEASURE, 0x00};
    uint8_t read_buf[9];
    struct timespec ts;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    file = fopen("airflow_data.txt", "a");
    if (file == NULL) {
        perror("Failed to open output file");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        messages[0].addr = SDP800_ADDR;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = write_buf;

        messages[1].addr = SDP800_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 9;
        messages[1].buf = read_buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            break;
        }

        if (calculate_crc8(read_buf, 6) != read_buf[6] || calculate_crc8(read_buf + 3, 3) != read_buf[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int32_t pressure_raw = (int32_t)read_buf[0] << 16 | (int32_t)read_buf[1] << 8 | read_buf[2];
        int32_t temperature_raw = (int32_t)read_buf[3] << 16 | (int32_t)read_buf[4] << 8 | read_buf[5];

        float pressure = pressure_raw / 200.0f;
        float temperature = -45.0f + 175.0f * (float)temperature_raw / 65536.0f;

        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(file);

        usleep(1000);
    }

    fclose(file);
    close(i2c_fd);
    return 0;
}

