#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_LIMIT 3
#define FAN_DELAY_MS 10

typedef struct {
    time_t timestamp;
    float temperature;
} SensorReading;

SensorReading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *fan_line;

void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    printf("Received SIGINT. Shutting down...\n");
    gpiod_line_set_value(fan_line, 0);
    cleanup();
    exit(0);
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (write(fd, buf, len) == len) {
            return 0;
        }
        retries++;
        usleep(10000);  // 10ms delay between retries
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        retries++;
        usleep(10000);  // 10ms delay between retries
    }
    return -1;
}

float read_temperature(void) {
    uint8_t cmd = 0xF3;  // Measure Relative Humidity, No Hold Master Mode
    uint8_t buf[3];

    if (i2c_write(i2c_fd, &cmd, 1) < 0) {
        fprintf(stderr, "Failed to write to Si7021\n");
        return -1;
    }

    usleep(80000);  // Wait for measurement (max 50ms for Si7021)

    if (i2c_read(i2c_fd, buf, 2) < 0) {
        fprintf(stderr, "Failed to read from Si7021\n");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temp_c = ((175.72 * raw_temp) / 65536.0) - 46.85;

    return temp_c;
}

void update_fan_state(float temp) {
    static int fan_state = 0;
    if (temp > TEMP_THRESHOLD_HIGH && !fan_state) {
        gpiod_line_set_value(fan_line, 1);
        fan_state = 1;
        usleep(FAN_DELAY_MS * 1000);
    } else if (temp < TEMP_THRESHOLD_LOW && fan_state) {
        gpiod_line_set_value(fan_line, 0);
        fan_state = 0;
        usleep(FAN_DELAY_MS * 1000);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "Si7021 Fan Control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        float temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Sensor read error or absent. Skipping this cycle.\n");
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
