#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define SCD40_I2C_BUS 1
#define SCD40_I2C_ADDR 0x62
#define SCD40_MEASURE_START 0x21B1
#define SCD40_READ_MEASUREMENT 0xEC05
#define SCD40_STOP_MEASUREMENT 0x3F86
#define SCD40_DATA_READY 0xE4B8
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2cHandle;
static FILE *logFile;

void handleSignal(int signo) {
    if (signo == SIGINT) {
        if (i2cHandle >= 0) {
            char stopCmd[3] = {0x3F, 0x86};
            i2cWriteDevice(i2cHandle, stopCmd, 2);
        }
        if (logFile) {
            fclose(logFile);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

uint8_t calculateCrc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handleSignal);

    i2cHandle = i2cOpen(SCD40_I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char startCmd[3] = {0x21, 0xB1};
    if (i2cWriteDevice(i2cHandle, startCmd, 2) != 2) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sleep(1);

    logFile = fopen("air_quality.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        char dataReadyCmd[3] = {0xE4, 0xB8};
        if (i2cWriteDevice(i2cHandle, dataReadyCmd, 2) != 2) {
            fprintf(stderr, "Failed to check data ready flag\n");
            continue;
        }

        uint8_t buffer[3];
        if (i2cReadDevice(i2cHandle, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read data ready flag\n");
            continue;
        }

        if (buffer[0] == 0x00 && buffer[1] == 0x01) {
            char readCmd[3] = {0xEC, 0x05};
            if (i2cWriteDevice(i2cHandle, readCmd, 2) != 2) {
                fprintf(stderr, "Failed to request measurement data\n");
                continue;
            }

            uint8_t data[9];
            if (i2cReadDevice(i2cHandle, data, 9) != 9) {
                fprintf(stderr, "Failed to read measurement data\n");
                continue;
            }

            uint16_t co2 = (data[0] << 8) | data[1];
            uint16_t temp = (data[3] << 8) | data[4];
            uint16_t humidity = (data[6] << 8) | data[7];

            if (calculateCrc8(data, 2) != data[2] ||
                calculateCrc8(data + 3, 2) != data[5] ||
                calculateCrc8(data + 6, 2) != data[8]) {
                fprintf(stderr, "CRC check failed\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(logFile, "%s,%u,%.2f,%.2f\n", timestamp, co2, temp / 100.0, humidity / 100.0);
            fflush(logFile);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

