#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 20
#define CO2_WARNING_PIN 17
#define CO2_WARNING_THRESHOLD 1000
#define CRC8_POLYNOMIAL 0x31

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SensorReading;

SensorReading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd;
int gpio_fd;

uint8_t calculate_crc8(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int validate_crc8(uint8_t *data, int len) {
    return calculate_crc8(data, len - 1) == data[len - 1];
}

int i2c_write(uint8_t *data, int len) {
    if (write(i2c_fd, data, len) != len) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *data, int len) {
    if (read(i2c_fd, data, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int scd40_init() {
    uint8_t init_command[] = {0x21, 0xB1};
    if (i2c_write(init_command, sizeof(init_command)) != 0)
        return -1;

    uint8_t response[3];
    if (i2c_read(response, sizeof(response)) != 0)
        return -1;

    if (!validate_crc8(response, sizeof(response))) {
        fprintf(stderr, "CRC8 validation failed for init response\n");
        return -1;
    }

    return 0;
}

int scd40_start_periodic_measurement() {
    uint8_t command[] = {0x21, 0xAC};
    if (i2c_write(command, sizeof(command)) != 0)
        return -1;

    uint8_t response[3];
    if (i2c_read(response, sizeof(response)) != 0)
        return -1;

    if (!validate_crc8(response, sizeof(response))) {
        fprintf(stderr, "CRC8 validation failed for start measurement response\n");
        return -1;
    }

    return 0;
}

int scd40_read_measurement() {
    uint8_t command[] = {0xEC, 0x05};
    if (i2c_write(command, sizeof(command)) != 0)
        return -1;

    uint8_t response[9];
    if (i2c_read(response, sizeof(response)) != 0)
        return -1;

    if (!validate_crc8(response, 3) || !validate_crc8(response + 3, 3) || !validate_crc8(response + 6, 3)) {
        fprintf(stderr, "CRC8 validation failed for measurement data\n");
        return -1;
    }

    uint16_t co2 = (response[0] << 8) | response[1];
    float temperature = -45 + 175 * ((float)(response[3] << 8 | response[4]) / 65536);
    float humidity = 100 * ((float)(response[6] << 8 | response[7]) / 65536);

    circular_buffer[buffer_index] = (SensorReading){co2, temperature, humidity};
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    printf("CO2: %d ppm, Temperature: %.2f°C, Humidity: %.2f%%\n", co2, temperature, humidity);

    gpioWrite(CO2_WARNING_PIN, co2 > CO2_WARNING_THRESHOLD ? PI_HIGH : PI_LOW);

    return 0;
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);

    uint8_t stop_command[] = {0x3F, 0x86};
    i2c_write(stop_command, sizeof(stop_command));

    gpioSetMode(CO2_WARNING_PIN, PI_INPUT);
    gpioTerminate();

    close(i2c_fd);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(CO2_WARNING_PIN, PI_OUTPUT);
    gpioWrite(CO2_WARNING_PIN, PI_LOW);

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (scd40_init() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (scd40_start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(5);
        if (scd40_read_measurement() != 0) {
            fprintf(stderr, "Failed to read measurement\n");
        }
    }

    return 0;
}

