    gpioWrite(CO2_WARNING_PIN, PI_LOW);

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (scd40_init() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (scd40_start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(5);
        if (scd40_read_measurement() != 0) {
            fprintf(stderr, "Failed to read measurement\n");
        }
    }

    return 0;
}
