#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5
#define EDGE_TIMEOUT 50
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0
#define CONSECUTIVE_FAILURES_THRESHOLD 3

static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double compute_temperature(uint64_t high_time, uint64_t total_time) {
    if (total_time == 0) return 0;
    double duty_cycle = (double)high_time / total_time;
    return 25 + (duty_cycle - 0.5) * 100;
}

void log_temperature(double temperature, const char *timestamp) {
    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(log_file, "%s ERROR: Temperature out of range: %.2f°C\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s %.2f°C\n", timestamp, temperature);
    }
    fflush(log_file);
}

int main() {
    struct timespec start, end;
    uint64_t high_time, total_time;
    int consecutive_failures = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "TMP05") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        high_time = 0;
        total_time = 0;

        clock_gettime(CLOCK_MONOTONIC, &start);

        while (total_time < 1000000 && keep_running) {
            int value = gpiod_line_get_value(line);
            clock_gettime(CLOCK_MONOTONIC, &end);

            uint64_t elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

            if (value) {
                high_time = elapsed;
            }

            total_time = elapsed;

            if (total_time - high_time > EDGE_TIMEOUT * 1000) {
                break;
            }

            usleep(1000);
        }

        double temperature = compute_temperature(high_time, total_time);

        if (temperature == 0) {
            consecutive_failures++;
            if (consecutive_failures >= CONSECUTIVE_FAILURES_THRESHOLD) {
                time_t now;
                time(&now);
                char *timestamp = ctime(&now);
                timestamp[strlen(timestamp) - 1] = '\0';
                fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                consecutive_failures = 0;
            }
        } else {
            consecutive_failures = 0;
            time_t now;
            time(&now);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0';
            log_temperature(temperature, timestamp);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

