#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define MAX_RETRIES 3
#define RETRY_DELAY 1
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL 5
#define SIMULATION_DURATION 3600

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

// Convert raw sensor data to Celsius and RH
void convert_sensor_data(uint16_t raw_temp, uint16_t raw_rh, float *temp_c, float *rh) {
    *temp_c = -45 + 175 * (float)raw_temp / 65535;
    *rh = 100 * (float)raw_rh / 65535;
}

// Write data to I2C device
int i2c_write(int fd, const uint8_t *data, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(fd, data, len) == len)
            return 0;
        sleep(RETRY_DELAY);
    }
    return -1;
}

// Read data from I2C device
int i2c_read(int fd, uint8_t *data, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(fd, data, len) == len)
            return 0;
        sleep(RETRY_DELAY);
    }
    return -1;
}

// Log data to file
void log_data(FILE *file, float temp, float rh) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temp, rh);
    fflush(file);
}

// Signal handler
volatile sig_atomic_t keep_running = 1;
void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    uint8_t buffer[6];
    float temp, rh;
    time_t start_time;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    start_time = time(NULL);

    while (keep_running && (time(NULL) - start_time) < SIMULATION_DURATION) {
        // Send measurement command
        uint8_t cmd[] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
        if (i2c_write(i2c_handle, cmd, sizeof(cmd)) != 0) {
            log_data(log_file, NAN, NAN);
            continue;
        }

        // Wait for data (6 bytes)
        usleep(15000);  // 15 ms

        // Read data
        if (i2c_read(i2c_handle, buffer, sizeof(buffer)) != 0) {
            log_data(log_file, NAN, NAN);
            continue;
        }

        // Validate CRC
        uint8_t crc_temp = buffer[2];
        uint8_t crc_rh = buffer[5];

        if (calculate_crc(buffer, 2) != crc_temp || calculate_crc(buffer, 5) != crc_rh) {
            log_data(log_file, NAN, NAN);
            continue;
        }

        // Convert raw data
        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_rh = (buffer[3] << 8) | buffer[4];
        convert_sensor_data(raw_temp, raw_rh, &temp, &rh);

        // Apply sinusoidal offset
        float time_offset = (float)(time(NULL) - start_time) / SIMULATION_DURATION * 2 * M_PI;
        temp += 2 * sin(time_offset);
        rh += 5 * sin(time_offset);

        // Log data
        log_data(log_file, temp, rh);

        // Wait for next interval
        sleep(LOG_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

