    uint8_t write_buf[3] = {0x03, 0x00, 0xF4};  // Continuous measurement command
    uint8_t read_buf[9];
    char csv_filename[] = "airflow.csv";
    time_t last_write_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    messages[0].addr = SDP810_I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 3;
    messages[0].buf = write_buf;

    messages[1].addr = SDP810_I2C_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 9;
    messages[1].buf = read_buf;

    file_fd = open(csv_filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_fd < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            break;
        }

        if (calculate_crc8(read_buf, 8) != read_buf[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int32_t pressure_raw = (int32_t)read_buf[0] << 12 | (int32_t)read_buf[1] << 4 | (read_buf[2] >> 4);
        int32_t temperature_raw = (int32_t)read_buf[3] << 12 | (int32_t)read_buf[4] << 4 | (read_buf[5] >> 4);
        uint16_t scale_factor = read_buf[6] << 8 | read_buf[7];

        float pressure = (float)pressure_raw * scale_factor / 1000000.0f;
        float temperature = (float)temperature_raw / 200.0f - 273.15f;

        time_t current_time = time(NULL);
        if (current_time - last_write_time >= 1) {
            char timestamp[20];
            struct tm *tm_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            char log_entry[100];
            snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

            if (write(file_fd, log_entry, strlen(log_entry)) < 0) {
                perror("Failed to write to CSV file");
            }

            last_write_time = current_time;
        }

        usleep(CONVERSION_TIME_MS * 1000);
    }

    close(file_fd);
    close(i2c_fd);
    return 0;
}
