#define I2C_TIMEOUT_MS 100
#define CRC8_POLYNOMIAL 0x131
#define CRC8_INIT 0xFF
#define LOG_FILE "environment.log"
#define SENSOR_RESET_CMD 0xFE

static int i2c_fd;
static FILE *log_file;

void sigint_handler(int signum) {
    (void)signum;
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = read(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

uint8_t calculate_crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(uint8_t cmd, uint16_t *value) {
    uint8_t buf[3];
    buf[0] = cmd;

    if (i2c_write(i2c_fd, buf, 1) < 0) {
        return -1;
    }

    usleep(I2C_TIMEOUT_MS * 1000);

    if (i2c_read(i2c_fd, buf, 3) < 0) {
        return -1;
    }

    if (calculate_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC error for command 0x%02X\n", cmd);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

