            if (read_sensor(0xE5, &hum_raw) < 0) {
                fprintf(stderr, "ERROR: Failed to read humidity\n");
                fprintf(log_file, "%s,%.2f,ERROR\n", timestamp, temp_c);
            } else {
                float hum_pct = 125.0f * (float)hum_raw / 65536.0f - 6.0f;
                fprintf(log_file, "%.2f,%.2f\n", temp_c, hum_pct);
            }
        }

        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

