                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static float convert_pressure(uint32_t raw) {
    return (float)raw / 100.0f;
}

static float convert_temperature(uint32_t raw) {
    return (float)raw / 200.0f - 50.0f;
}

static void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct i2c_msg messages[2];
    uint8_t write_buf[3] = {SDP810_READ_MEASURE >> 8, SDP810_READ_MEASURE & 0xFF, 0};
    uint8_t read_buf[9];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SDP810_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    write_buf[0] = SDP810_START_CONT_MEASURE >> 8;
    write_buf[1] = SDP810_START_CONT_MEASURE & 0xFF;
    messages[0].addr = SDP810_I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = write_buf;

    messages[1].addr = SDP810_I2C_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 9;
    messages[1].buf = read_buf;

    file = fopen("airflow.dat", "wb");
    if (!file) {
        perror("Failed to open output file");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            break;
        }

        if (crc8(read_buf, 2) != read_buf[2] || crc8(read_buf + 3, 2) != read_buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint32_t pressure_raw = (uint32_t)read_buf[0] << 16 | (uint32_t)read_buf[1] << 8 | read_buf[2];
        uint32_t temperature_raw = (uint32_t)read_buf[3] << 16 | (uint32_t)read_buf[4] << 8 | read_buf[5];

        float pressure = convert_pressure(pressure_raw);
        float temperature = convert_temperature(temperature_raw);

        if (fwrite(&pressure, sizeof(float), 1, file) != 1 ||
            fwrite(&temperature, sizeof(float), 1, file) != 1) {
            perror("Failed to write to file");
            break;
        }

        fflush(file);
        usleep(SDP810_CONVERSION_TIME_MS * 1000);
    }

    fclose(file);
    close(i2c_fd);
    return 0;
}
