}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(uint32_t *pressure, uint32_t *temperature) {
    uint8_t tx_data[2] = {0x03, 0xE0};
    uint8_t rx_data[9];

    if (write(i2c_fd, tx_data, 2) != 2) {
        perror("I2C write error");
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    if (read(i2c_fd, rx_data, 9) != 9) {
        perror("I2C read error");
        return -1;
    }

    if (calculate_crc8(rx_data, 8) != rx_data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *pressure = (uint32_t)rx_data[0] << 12 | (uint32_t)rx_data[1] << 4 | (rx_data[2] >> 4);
    *temperature = (uint32_t)rx_data[3] << 12 | (uint32_t)rx_data[4] << 4 | (rx_data[5] >> 4);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        return EXIT_FAILURE;
    }

