#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define FAN_PIN 18
#define SAMPLE_INTERVAL_MS 100
#define PWM_FREQ 25000

static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int read_sensor(int i2c_handle) {
    char buffer[2];
    if (i2c_read_i2c_block_data(i2c_handle, 0x00, 2, buffer) < 0) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0 ||
        gpioHardwarePWM(FAN_PIN, PWM_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_sample_time = time(NULL);
    int last_pressure = 0;

    while (!terminate) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) >= SAMPLE_INTERVAL_MS / 1000.0) {
            int pressure = read_sensor(i2c_handle);
            if (pressure >= 0) {
                int flow_rate = (pressure - last_pressure) * 10; // Example calculation
                fprintf(log_file, "%ld,%d\n", (long)current_time, pressure);
                fflush(log_file);

                // Adjust PWM duty cycle based on flow rate
                int duty_cycle = (flow_rate > 100) ? 255 : (flow_rate * 255 / 100);
                gpioPWM(FAN_PIN, duty_cycle);

                last_pressure = pressure;
            }
            last_sample_time = current_time;
        }
        usleep(1000); // Sleep for 1ms to reduce CPU usage
    }

    gpioPWM(FAN_PIN, 0); // Turn off fan
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

