#define I2C_BUS "/dev/i2c-1"
#define LPS33HW_ADDR 0x5C
#define LPS33HW_PRESS_OUT_XL 0x28
#define LPS33HW_TEMP_OUT_L 0x2B

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C read register error");
        return -1;
    }
    if (read(fd, value, len) != len) {
        perror("I2C read data error");
        return -1;
    }
    return 0;
}

int read_pressure(int fd, float *pressure) {
    uint8_t buf[3];
    if (i2c_read(fd, LPS33HW_PRESS_OUT_XL, buf, 3) != 0) {
        return -1;
    }
    *pressure = (buf[0] | (buf[1] << 8) | (buf[2] << 16)) / 4096.0f;
    return 0;
}

int read_temperature(int fd, float *temperature) {
    uint8_t buf[2];
    if (i2c_read(fd, LPS33HW_TEMP_OUT_L, buf, 2) != 0) {
        return -1;
    }
    *temperature = (int16_t)((buf[0] | (buf[1] << 8))) / 100.0f;
    return 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    struct tm tm_info;
    char timestamp[64];
    float pressure, temperature;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LPS33HW_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (!terminate) {
        clock_gettime(CLOCK_REALTIME, &ts);
        if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
            perror("Failed to get local time");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        if (read_pressure(i2c_fd, &pressure) == 0 && read_temperature(i2c_fd, &temperature) == 0) {
            fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
            fflush(log_file);
        } else {
            fprintf(stderr, "%s, Error reading sensor data\n", timestamp);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

