#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <syslog.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_MEASURE_INTERVAL 5
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

static int keep_running = 1;
static int i2c_handle;
static FILE *log_file;

void signal_handler(int signum) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup_i2c() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int read_sensor_data(float *co2, float *temperature, float *humidity) {
    unsigned char cmd[] = {0x00, 0x00};
    unsigned char buffer[18];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to SCD30");
        return -1;
    }

    usleep(20000);  // Wait for data ready

    if (i2cReadDevice(i2c_handle, buffer, 18) != 18) {
        syslog(LOG_ERR, "Failed to read from SCD30");
        return -1;
    }

    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

void write_log(float co2, float temperature, float humidity) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

void ventilation_control(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        syslog(LOG_INFO, "Ventilation: OFF");
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        syslog(LOG_INFO, "Ventilation: LOW");
    } else {
        syslog(LOG_INFO, "Ventilation: HIGH");
    }
}

int main() {
    float co2, temperature, humidity;

    openlog("scd30_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (access("/dev/i2c-1", R_OK | W_OK) != 0) {
        syslog(LOG_INFO, "No hardware detected, running in mock mode");
        closelog();
        return 0;
    }

    if (init_i2c() < 0) {
        closelog();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        cleanup_i2c();
        closelog();
        return 1;
    }

    setup_signal_handlers();

    while (keep_running) {
        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            write_log(co2, temperature, humidity);
            ventilation_control(co2);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        sleep(SCD30_MEASURE_INTERVAL);
    }

    fclose(log_file);
    cleanup_i2c();
    closelog();

    return 0;
}

