#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SDP32_I2C_ADDR 0x21
#define SDP32_READ_INTERVAL_MS 1000
#define SDP32_COMMAND_MEASURE_CONTINUOUS 0x3603
#define SDP32_COMMAND_READ_MEASUREMENT 0xE102

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static volatile int keep_running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(int i2c_handle, uint8_t *buffer, int len) {
    int ret = i2cReadI2CBlockData(i2c_handle, SDP32_COMMAND_READ_MEASUREMENT, buffer, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int verify_crc(const uint8_t *data, int len, uint8_t expected_crc) {
    uint8_t calculated_crc = crc8(data, len - 1);
    return calculated_crc == expected_crc;
}

static void signal_handler(int signum) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int i2c_handle;
    int interval_ms = SDP32_READ_INTERVAL_MS;
    struct timespec sleep_time;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval. Using default %d ms.\n", SDP32_READ_INTERVAL_MS);
            interval_ms = SDP32_READ_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    line = gpiod_chip_get_line(chip, 1);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    ret = gpiod_line_request_output(line, "SDP32_SDA", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(1, SDP32_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ret = i2cWriteWordData(i2c_handle, SDP32_COMMAND_MEASURE_CONTINUOUS, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        i2cClose(i2c_handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t buffer[9];
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        if (read_sensor(i2c_handle, buffer, sizeof(buffer)) < 0) {
            i2cClose(i2c_handle);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            gpioTerminate();
            return 1;
        }

        if (!verify_crc(buffer, 3, buffer[2]) ||
            !verify_crc(buffer + 3, 3, buffer[5]) ||
            !verify_crc(buffer + 6, 3, buffer[8])) {
            fprintf(stderr, "CRC verification failed\n");
            i2cClose(i2c_handle);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            gpioTerminate();
            return 1;
        }

        int16_t pressure = (buffer[0] << 8) | buffer[1];
        int16_t temperature = (buffer[3] << 8) | buffer[4];
        int16_t scale_factor = (buffer[6] << 8) | buffer[7];

        time_t now = time(NULL);
        printf("%s Pressure: %d Pa, Temperature: %d°C, Scale Factor: %d\n",
               ctime(&now), pressure, temperature, scale_factor);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L +
                          (current_time.tv_nsec - start_time.tv_nsec);
        long sleep_ns = interval_ms * 1000000L - elapsed_ns;

        if (sleep_ns > 0) {
            nanosleep((const struct timespec[]){{0, sleep_ns}}, NULL);
        }
    }

    i2cClose(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return 0;
}

