        int16_t temperature = (buffer[3] << 8) | buffer[4];
        int16_t scale_factor = (buffer[6] << 8) | buffer[7];

        time_t now = time(NULL);
        printf("%s Pressure: %d Pa, Temperature: %d°C, Scale Factor: %d\n",
               ctime(&now), pressure, temperature, scale_factor);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L +
                          (current_time.tv_nsec - start_time.tv_nsec);
        long sleep_ns = interval_ms * 1000000L - elapsed_ns;

        if (sleep_ns > 0) {
            nanosleep((const struct timespec[]){{0, sleep_ns}}, NULL);
        }
    }

    i2cClose(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return 0;
}
