#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int verify_crc(const uint8_t *data, int len) {
    return crc8(data, len - 1) == data[len - 1];
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t start_measurement_cmd[] = {0x03, 0x00, 0xF4, 0x2F};
    if (write(i2c_handle, start_measurement_cmd, sizeof(start_measurement_cmd)) != sizeof(start_measurement_cmd)) {
        fprintf(stderr, "Failed to start measurement\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        usleep(45000);  // Wait 45ms for conversion

        uint8_t read_cmd[] = {0x00, 0xE0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        if (write(i2c_handle, read_cmd, 3) != 3) {
            fprintf(stderr, "Failed to send read command\n");
            continue;
        }

        uint8_t raw_data[9];
        if (read(i2c_handle, raw_data, sizeof(raw_data)) != sizeof(raw_data)) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        if (!verify_crc(raw_data, 3) || !verify_crc(raw_data + 3, 3) || !verify_crc(raw_data + 6, 3)) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int32_t pressure_raw = (raw_data[0] << 12) | (raw_data[1] << 4) | (raw_data[2] >> 4);
        int32_t temperature_raw = (raw_data[3] << 12) | (raw_data[4] << 4) | (raw_data[5] >> 4);
        float pressure = pressure_raw / 100.0f;
        float temperature = temperature_raw / 200.0f;

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        sleep(1);
    }

    close(i2c_handle);
    gpioTerminate();
    return 0;
}

