#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUM_REG 0x01
#define CONF_REG 0x02
#define TEMP_HUM_DELAY_MS 20

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    unsigned char buf[3];
    float temperature, humidity;
    struct timespec delay = {0, TEMP_HUM_DELAY_MS * 1000000};

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure sensor
    buf[0] = CONF_REG;
    buf[1] = 0x10; // Temperature and humidity, 14-bit resolution
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write configuration");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Trigger temperature and humidity conversion
        buf[0] = TEMP_REG;
        if (write(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "Failed to trigger conversion\n");
            continue;
        }

        // Wait for conversion to complete
        nanosleep(&delay, NULL);

        // Read temperature
        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        temperature = ((buf[0] << 8) | buf[1]) / 65536.0 * 165.0 - 40.0;

        // Read humidity
        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }
        humidity = ((buf[0] << 8) | buf[1]) / 65536.0 * 100.0;

        // Print results
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 5 seconds before next reading
        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

