int read_si7051(int i2c_handle) {
    char buf[3];
    int ret;

    // Send measurement command
    buf[0] = 0xE3; // Measure Temperature Hold Master Mode
    ret = i2cWriteDevice(i2c_handle, buf, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to send temperature command\n");
        return -1;
    }

    // Wait for measurement to complete
    gpioSleep(PI_TIME_MILLISECONDS, 100, 0); // 100ms delay

    // Read 2 bytes of data
    ret = i2cReadI2CBlock(i2c_handle, 0, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    // Convert to temperature (simplified, not accounting for all factors)
    int raw_temp = (buf[0] << 8) | buf[1];
    float temp_c = ((175.72 * raw_temp) / 65536.0) - 46.85;

    return (int)temp_c;
}

int main() {
    int i2c_handle;
    int temp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        temp = read_si7051(i2c_handle);
        if (temp >= 0) {
            printf("Temperature: %d°C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

