#define I2C_BUS 1
#define SENSOR_ADDR 0x0C
#define READ_INTERVAL_MS 500

static int i2c_handle;

void signal_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    int16_t pressure;
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        result = i2cReadWordData(i2c_handle, 0x04);
        if (result < 0) {
            fprintf(stderr, "Failed to read pressure: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        pressure = le16toh(result);
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: Pressure: %d Pa\n", ts.tv_sec, ts.tv_nsec, pressure);

        usleep(READ_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

