#define READ_INTERVAL_SEC 5

static int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpiod_chip_close(gpiod_chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        int result = i2cWriteByte(i2c_handle, 0x33); // Trigger measurement
        if (result < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            usleep(MEASUREMENT_DELAY_MS * 1000);

            unsigned char data[6];
            result = i2cReadI2CBlock(i2c_handle, 0x00, data, 6);
            if (result < 0) {
                fprintf(stderr, "Failed to read sensor data\n");
            } else {
                int16_t temp_raw = (data[0] << 8) | data[1];
                uint32_t pressure_raw = ((uint32_t)data[2] << 16) | (data[3] << 8) | data[4];

                float temperature = temp_raw * 25.0f / 65536.0f;
                float pressure = pressure_raw * 62.5f / 1000.0f;

                printf("%s - Temperature: %.2f°C, Pressure: %.2fPa\n", timestamp, temperature, pressure);
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    return EXIT_SUCCESS;
}
