#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SDP800_I2C_ADDR 0x21
#define SDP800_DIFF_PRESSURE_CMD 0x00
#define SDP800_TEMP_CMD 0x03
#define SDP800_SERIAL_NUMBER_CMD 0x36
#define SDP800_MEASURE_INTERVAL_MS 45
#define SDP800_DATA_SIZE 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length) {
    return calculate_crc8(data, length - 1) == data[length - 1];
}

int main() {
    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (i2cWriteByte(i2c_handle, SDP800_DIFF_PRESSURE_CMD) < 0) {
            fprintf(stderr, "Failed to send differential pressure command: %s\n", strerror(errno));
            break;
        }
        time_sleep(45.0 / 1000.0);

        uint8_t data[SDP800_DATA_SIZE];
        if (i2cReadDevice(i2c_handle, data, SDP800_DATA_SIZE) != SDP800_DATA_SIZE) {
            fprintf(stderr, "Failed to read differential pressure data: %s\n", strerror(errno));
            break;
        }

        if (!validate_crc8(data, 6) || !validate_crc8(data + 3, 6)) {
            fprintf(stderr, "CRC validation failed for differential pressure or temperature data\n");
            continue;
        }

        int32_t diff_pressure_raw = (int32_t)data[0] << 16 | (int32_t)data[1] << 8 | data[2];
        int32_t temperature_raw = (int32_t)data[3] << 16 | (int32_t)data[4] << 8 | data[5];

        float diff_pressure = diff_pressure_raw / 200.0;
        float temperature = temperature_raw / 200.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, diff_pressure, temperature);
        fflush(log_file);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

