#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x21
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct i2c_msg messages[2];
    uint8_t write_buf[3] = {0x03, 0xE0, 0x00}; // Measure differential pressure command
    uint8_t read_buf[3];
    struct timespec ts;
    char timestamp[64];
    int file_exists;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    file_exists = access("airflow_log.csv", F_OK) == 0;
    log_file = fopen("airflow_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (!file_exists) {
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    }

    while (!terminate) {
        messages[0].addr = SDP800_I2C_ADDR;
        messages[0].flags = 0;
        messages[0].len = 3;
        messages[0].buf = write_buf;

        messages[1].addr = SDP800_I2C_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 3;
        messages[1].buf = read_buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C transfer failed");
            break;
        }

        uint8_t calculated_crc = calculate_crc8(read_buf, 2);
        if (calculated_crc != read_buf[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int32_t pressure_raw = (read_buf[0] << 8) | read_buf[1];
        float pressure = pressure_raw * 0.1f; // Convert to Pa

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
        fflush(log_file);

        usleep(8000); // Wait 8ms
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

