#define MEASUREMENT_INTERVAL 5
#define TRIGGER_DELAY_MS 40

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int ret = write(fd, buf, len);
    if (ret < 0) {
        perror("I2C write error");
    }
    return ret;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int ret = read(fd, buf, len);
    if (ret < 0) {
        perror("I2C read error");
    }
    return ret;
}

int check_log_size() {
    struct stat st;
    if (stat(LOG_FILE, &st) == 0) {
        if (st.st_size >= MAX_LOG_SIZE) {
            FILE *file = fopen(LOG_FILE, "w");
            if (file) {
                fclose(file);
            } else {
                perror("Error truncating log file");
                return -1;
            }
        }
    }
    return 0;
}

