        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[2] << 8) | buf[3];

        if ((buf[0] & 0x30) != 0) {
            fprintf(stderr, "Sensor error: status bits set\n");
            sleep(MEASUREMENT_INTERVAL);
            continue;
        }

        float temperature = (raw_temp / 16384.0) * 165.0 - 40.0;
        float humidity = (raw_humidity / 16384.0) * 100.0;

        if (check_log_size() < 0) {
            fprintf(stderr, "Error checking log size\n");
        }

        FILE *log_file = fopen(LOG_FILE, "a");
