#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 1000000 // 1 second timeout for sensor absence

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_gpio(struct gpiod_chip *chip, int line) {
    int value;
    int ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

unsigned long long get_time_us() {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }
    return (unsigned long long)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
}

int wait_for_edge(struct gpiod_chip *chip, int line, int expected_value, unsigned long long timeout_us) {
    unsigned long long start_time = get_time_us();
    while (get_time_us() - start_time < timeout_us) {
        if (read_gpio(chip, line) == expected_value) {
            return 1;
        }
        usleep(TICK_TIME_US * 1000);
    }
    return 0;
}

int read_nibble(struct gpiod_chip *chip, int line) {
    unsigned long long start_time = get_time_us();
    int ticks = 0;
    while (read_gpio(chip, line) == 0) {
        ticks++;
        if (ticks > MAX_NIBBLE_TICKS) {
            return -1; // Timeout
        }
        usleep(TICK_TIME_US * 1000);
    }
    while (read_gpio(chip, line) == 1) {
        ticks++;
        if (ticks > MAX_NIBBLE_TICKS) {
            return -1; // Timeout
        }
        usleep(TICK_TIME_US * 1000);
    }
    if (ticks < MIN_NIBBLE_TICKS) {
        return -1; // Invalid nibble
    }
    return ticks;
}

int read_sent_frame(struct gpiod_chip *chip, int line, unsigned char *frame, int frame_size) {
    if (!wait_for_edge(chip, line, 1, SYNC_PULSE_TICKS * TICK_TIME_US)) {
        return -1; // Sync pulse timeout
    }

    for (int i = 0; i < frame_size; i++) {
        int nibble = read_nibble(chip, line);
        if (nibble < 0) {
            return -1; // Nibble read error
        }
        frame[i] = nibble;
    }

    return 0;
}

int calculate_checksum(const unsigned char *data, int length) {
    int checksum = 0;
    for (int i = 0; i < length; i++) {
        checksum += data[i];
    }
    return checksum & 0xF;
}

void log_pressure(double pressure) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, pressure);

    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "MLX90824_SENT");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char frame[10]; // 1 sync + 3 data + 1 checksum
    while (keep_running) {
        if (read_sent_frame(chip, GPIO_PIN, frame, sizeof(frame)) == 0) {
            int status = frame[0];
            int data1 = frame[1];
            int data2 = frame[2];
            int data3 = frame[3];
            int checksum = frame[4];

            if (calculate_checksum(frame, 4) != checksum) {
                fprintf(stderr, "Checksum mismatch\n");
                continue;
            }

            // Convert SENT data to pressure (example conversion, adjust as needed)
            double pressure = (data1 << 8 | data2) * 0.1; // Assuming 0.1 Pa resolution
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Sensor read error or timeout\n");
        }

        usleep(TIMEOUT_US); // Wait before next reading
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

