#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_MEASURE_CMD 0xFD
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INIT 0xFF

static int i2cHandle;
static FILE *logFile;

void sigintHandler(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculateCRC8(const uint8_t *data, int len) {
    uint8_t crc = SHT40_CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validateCRC8(const uint8_t *data, int len) {
    return data[len - 1] == calculateCRC8(data, len - 1);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(1, SHT40_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen("environmental_data.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigintHandler);

    uint8_t buffer[6];
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        if (i2cWriteByte(i2cHandle, SHT40_MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        usleep(8500);  // 8.5ms delay for conversion

        if (i2cReadDevice(i2cHandle, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        if (!validateCRC8(buffer, 3) || !validateCRC8(buffer + 3, 3)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        float temp = -45.0 + 175.0 * ((buffer[0] * 256.0 + buffer[1]) / 65535.0);
        float humidity = 100.0 * ((buffer[3] * 256.0 + buffer[4]) / 65535.0);

        fprintf(logFile, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temp, humidity);
        fflush(logFile);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

