    int bytes_written = i2cWriteWordData(i2cHandle, cmd, 0);
    if (bytes_written < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    usleep(12400); // 12.4 ms delay

    int bytes_read = i2cReadDevice(i2cHandle, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    if (calculate_crc8(buffer, 3) != buffer[3] || calculate_crc8(buffer + 3, 3) != buffer[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *data = (buffer[0] << 8) | buffer[1];
    return 0;
}

