    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(1, SHTC3_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "I2C open error: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen("shtc3_environment.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        uint16_t temp_raw, hum_raw;
        if (read_sensor(SHTC3_TEMP_CMD, &temp_raw) == 0) {
            float temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
            if (temperature < -40.0 || temperature > 125.0) {
                fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
                continue;
            }

            if (read_sensor(SHTC3_HUM_CMD, &hum_raw) == 0) {
                float humidity = 100.0 * (float)hum_raw / 65535.0;
                if (humidity < 0.0 || humidity > 100.0) {
                    fprintf(stderr, "Humidity out of range: %.2f%%\n", humidity);
                    continue;
                }

                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
                fprintf(logFile, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
                fflush(logFile);
            }
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}
