int initI2C() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    i2cHandle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int readSensorData(int16_t *speed, int16_t *temperature) {
    unsigned char buffer[4];
    int bytesRead = i2cReadI2CBlockData(i2cHandle, 0x00, buffer, 4);

    if (bytesRead != 4) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *speed = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[2] << 8) | buffer[3];
    return 0;
}

