#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define I2C_RETRIES 3

static int i2c_fd = -1;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            retries++;
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            close(i2c_fd);
            retries++;
            sleep(1);
            continue;
        }

        return 0;
    }
    return -1;
}

int read_temperature(float *temperature) {
    uint16_t raw_temp;
    if (read(i2c_fd, &raw_temp, sizeof(raw_temp)) != sizeof(raw_temp)) {
        perror("Failed to read temperature");
        return -1;
    }

    *temperature = (float)(raw_temp >> 4) * 0.0625;
    return 0;
}

int main() {
    signal(SIGINT, cleanup);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C after %d attempts\n", I2C_RETRIES);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *timeinfo;
    char time_str[20];
    float temperature;

    while (1) {
        if (read_temperature(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature, retrying...\n");
            sleep(1);
            continue;
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, Temperature: %.2f C\n", time_str, temperature);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

