#define SAMPLE_INTERVAL 1
#define IGNORE_READS 2

static int i2c_handle;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    int handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return handle;
}

int read_sensor_data(uint32_t *data) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, SENSOR_ADDR, 0, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void log_measurement(uint32_t flow_raw, uint32_t temp_raw) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    float flow_slpm = (float)(flow_raw & 0x3FFF) * 0.703;
    float temp_c = (float)((temp_raw >> 4) & 0xFFF) * 0.0625 - 50.0;

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, flow_slpm, temp_c);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int ignore_count = 0;
    while (1) {
        uint32_t data;
        if (read_sensor_data(&data) == 0) {
            if (ignore_count < IGNORE_READS) {
                ignore_count++;
            } else {
                log_measurement(data, data >> 16);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to reinitialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = init_i2c();
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reinitialize I2C device\n");
                sleep(5);
                continue;
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

