#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define DHT11_TIMEOUT_US 250000
#define DHT11_START_LOW_US 18000
#define DHT11_RESPONSE_LOW_US 80000
#define DHT11_BIT_LOW_US 50000
#define DHT11_BIT_HIGH_US_0 26000
#define DHT11_BIT_HIGH_US_1 70000
#define DHT11_READ_INTERVAL 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *logfile;

void cleanup(int signum) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(logfile, "[%s] Signal %d received. Cleaning up...\n", timestamp, signum);

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (logfile) {
        fclose(logfile);
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(logfile, "[%s] ERROR: %s\n", timestamp, message);
}

int microsecond_delay(useconds_t us) {
    return usleep(us);
}

int set_gpio_direction(int direction) {
    int ret;
    if (direction) {
        ret = gpiod_line_request_output(line, "DHT11", 0);
    } else {
        ret = gpiod_line_request_input(line, "DHT11");
    }
    if (ret < 0) {
        log_error("Failed to set GPIO direction");
    }
    return ret;
}

int read_gpio_level() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_error("Failed to read GPIO level");
    }
    return value;
}

int write_gpio_level(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        log_error("Failed to write GPIO level");
    }
    return ret;
}

int start_signal() {
    if (write_gpio_level(0) < 0) return -1;
    if (microsecond_delay(DHT11_START_LOW_US) < 0) return -1;
    if (write_gpio_level(1) < 0) return -1;
    return 0;
}

int wait_for_response() {
    int start = microsecond_delay(0);
    while (read_gpio_level() == 0) {
        if (microsecond_delay(100) < 0) return -1;
        if (microsecond_delay(0) - start > DHT11_TIMEOUT_US) {
            log_error("Timeout waiting for response");
            return -1;
        }
    }
    start = microsecond_delay(0);
    while (read_gpio_level() == 1) {
        if (microsecond_delay(100) < 0) return -1;
        if (microsecond_delay(0) - start > DHT11_TIMEOUT_US) {
            log_error("Timeout waiting for response end");
            return -1;
        }
    }
    return 0;
}

int read_bit() {
    int start = microsecond_delay(0);
    while (read_gpio_level() == 0) {
        if (microsecond_delay(100) < 0) return -1;
        if (microsecond_delay(0) - start > DHT11_TIMEOUT_US) {
            log_error("Timeout reading bit start");
            return -1;
        }
    }
    start = microsecond_delay(0);
    while (read_gpio_level() == 1) {
        if (microsecond_delay(100) < 0) return -1;
        if (microsecond_delay(0) - start > DHT11_TIMEOUT_US) {
            log_error("Timeout reading bit end");
            return -1;
        }
    }
    return (start > DHT11_BIT_HIGH_US_0) ? 1 : 0;
}

int read_sensor_data(unsigned char *data) {
    for (int i = 0; i < 40; i++) {
        if (read_bit() < 0) return -1;
        data[i / 8] <<= 1;
