#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define I2C_RETRIES 3
#define MEASURE_CMD 0x2C
#define MEASURE_CMD_ARG 0x06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *sda_line, *scl_line;

void cleanup(int signum) {
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    if (sda_line) gpiod_line_release(sda_line);
    if (scl_line) gpiod_line_release(scl_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int i2c_write(uint8_t *data, int len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(i2c_fd, data, len) == len) return 0;
        usleep(10000); // 10ms delay between retries
    }
    return -1;
}

int i2c_read(uint8_t *data, int len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (read(i2c_fd, data, len) == len) return 0;
        usleep(10000); // 10ms delay between retries
    }
    return -1;
}

int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[] = {MEASURE_CMD, MEASURE_CMD_ARG};
    uint8_t data[6];

    if (i2c_write(cmd, sizeof(cmd)) < 0) return -1;
    usleep(15000); // 15ms delay

    if (i2c_read(data, sizeof(data)) < 0) return -1;

    if (calculate_crc8(data, 2) != data[2] || calculate_crc8(data + 3, 2) != data[5]) {
        return -1;
    }

    *temperature = (float)((data[0] << 8) | data[1]) / 65535.0 * 175.0 - 45.0;
    *humidity = (float)((data[3] << 8) | data[4]) / 65535.0 * 100.0;

    return 0;
}

int main() {
    struct timespec ts;
    char timestamp[30];
    float temperature, humidity;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    scl_line = gpiod_chip_get_line(chip, 3);
    if (!sda_line || !scl_line) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    gpiod_line_request_output(sda_line, "sht31-sda", 1);
    gpiod_line_request_output(scl_line, "sht31-scl", 1);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup(0);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup(0);
    }

    // Open log file
    log_file = fopen("sht31d_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(stderr, "Error reading SHT31-D at %s\n", timestamp);
        }
        sleep(5);
    }

    return 0;
}

