#define SENSOR1_ADDR 0x39
#define SENSOR2_ADDR 0x3A
#define LOG_FILE "cct_log.csv"
#define I2C_RETRIES 3

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int ret;

    while (retries < I2C_RETRIES) {
        ret = i2cReadI2CBlockData(fd, reg, buf, len);
        if (ret >= 0) return ret;
        retries++;
        usleep(10000);  // 10ms delay
    }

    fprintf(stderr, "I2C read error: %s\n", strerror(errno));
    return -1;
}

int i2c_write(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int ret;

    while (retries < I2C_RETRIES) {
        ret = i2cWriteI2CBlockData(fd, reg, buf, len);
        if (ret >= 0) return ret;
        retries++;
        usleep(10000);  // 10ms delay
    }

    fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    return -1;
}

int read_sensor_data(int fd, uint16_t *data) {
    uint8_t buf[4];
    if (i2c_read(fd, 0x00, buf, 4) < 0) return -1;

    data[0] = (buf[0] << 8) | buf[1];
    data[1] = (buf[2] << 8) | buf[3];
    return 0;
}

float compute_cct(uint16_t ch0, uint16_t ch1) {
    // Simplified CCT computation (replace with actual algorithm)
    return (float)(ch0 + ch1) / 2.0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    time_t last_log_time = 0;
    float total_cct = 0.0;
    int log_count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    while (keep_running) {
        uint16_t sensor1_data[2], sensor2_data[2];
        time_t current_time = time(NULL);

        if (read_sensor_data(i2c_fd, sensor1_data) == 0 &&
            read_sensor_data(i2cOpen(I2C_BUS, SENSOR2_ADDR, 0), sensor2_data) == 0) {

            float cct = compute_cct(sensor1_data[0], sensor2_data[0]);
            total_cct += cct;
            log_count++;

            if (current_time - last_log_time >= 1) {
                fprintf(log_file, "%ld,%.2f\n", (long)current_time, total_cct / log_count);
                fflush(log_file);
                total_cct = 0.0;
                log_count = 0;
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading sensor data at %ld\n", (long)current_time);
        }

        usleep(100000);  // 100ms delay
    }

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

