#define I2C_RETRY_DELAY_MS 100

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < I2C_READ_RETRIES) {
        ssize_t bytes_written = write(fd, buf, len);
        if (bytes_written == len) return 0;
        if (errno != EAGAIN && errno != EWOULDBLOCK) return -1;
        usleep(I2C_RETRY_DELAY_MS * 1000);
        retries++;
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < I2C_READ_RETRIES) {
        ssize_t bytes_read = read(fd, buf, len);
        if (bytes_read == len) return 0;
        if (errno != EAGAIN && errno != EWOULDBLOCK) return -1;
        usleep(I2C_RETRY_DELAY_MS * 1000);
        retries++;
    }
    return -1;
}

int read_sensor(float *pressure, float *temperature) {
    uint8_t tx_buf[3] = {0x00, 0x00, 0x00};
    uint8_t rx_buf[6];

    if (i2c_write(i2c_fd, tx_buf, 1) < 0) {
        log_error("Failed to write to sensor");
        return -1;
    }

    if (i2c_read(i2c_fd, rx_buf, 6) < 0) {
        log_error("Failed to read from sensor");
        return -1;
    }

    *pressure = ((rx_buf[0] << 8) | rx_buf[1]) * 0.1f;
    *temperature = ((rx_buf[3] << 8) | rx_buf[4]) * 0.02f - 273.15f;

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup(0);
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        log_error("Failed to get GPIO line");
        cleanup(0);
    }

    int ret = gpiod_line_request_output(line, "MLX90824", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line");
        cleanup(0);
    }

    while (1) {
        float pressure, temperature;
        if (read_sensor(&pressure, &temperature) == 0) {
            time_t now;
            struct tm *tm_info;
            char timestamp[64];
            char log_entry[128];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

            snprintf(log_entry, sizeof(log_entry), "[%s] Pressure: %.2f hPa, Temperature: %.2f °C\n",
                     timestamp, pressure, temperature);

            if (fputs(log_entry, log_file) == EOF) {
                log_error("Failed to write to log file");
            } else {
                fflush(log_file);
            }
        }

        sleep(2);
    }

    return 0;
}

