#define I2C_BUS "/dev/i2c-1"
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define FAN_PIN 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

typedef struct {
    float temperatures[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static CircularBuffer buffer = {.index = 0, .count = 0};

void cleanup(int signum) {
    fprintf(stderr, "Received signal %d, cleaning up...\n", signum);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

float read_temperature() {
    char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature\n");
        return -1;
    }
    return (buf[0] << 3 | buf[1] >> 5) * 0.125;
}

void update_buffer(float temp) {
    buffer.temperatures[buffer.index] = temp;
    buffer.index = (buffer.index + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

float compute_average() {
    float sum = 0;
    for (int i = 0; i < buffer.count; i++) {
        sum += buffer.temperatures[i];
    }
    return sum / buffer.count;
}

void control_fan(float avg_temp) {
    int fan_state = gpiod_line_get_value(line);
    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_state) {
        gpiod_line_set_value(line, 1);
        fprintf(stderr, "Fan ON\n");
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_state) {
        gpiod_line_set_value(line, 0);
        fprintf(stderr, "Fan OFF\n");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "Fan Control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        float temp = read_temperature();
        if (temp >= 0) {
            update_buffer(temp);
            float avg_temp = compute_average();
            control_fan(avg_temp);
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

