#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SDP810_I2C_ADDR 0x21
#define SDP810_MEASURE_CMD 0x03
#define SDP810_WAIT_TIME_MS 45
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "airflow.log"

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(float *pressure, float *temperature) {
    uint8_t buffer[9];
    int bytesRead = i2cReadI2CBlock(i2cHandle, SDP810_I2C_ADDR, buffer, 9);
    if (bytesRead != 9) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    if (calculate_crc8(buffer, 8) != buffer[8]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    *pressure = (float)((buffer[0] << 8) | buffer[1]) / 200.0f;
    *temperature = (float)((buffer[3] << 8) | buffer[4]) / 200.0f - 50.0f;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(1, SDP810_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (i2cWriteByte(i2cHandle, SDP810_MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        usleep(SDP810_WAIT_TIME_MS * 1000);

        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) == 0) {
            fprintf(logFile, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
            fflush(logFile);

            if (pressure > 5.0) {
                fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
            }
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

