#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define TEMP_HYST 27
#define TEMP_MAX 28
#define LED_PIN 17
#define I2C_RETRIES 3

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int read_i2c_reg(int reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C register: %s\n", strerror(errno));
        return -1;
    }
    int retries = 0;
    while (retries < I2C_RETRIES) {
        ssize_t bytes_read = read(i2c_fd, buf, len);
        if (bytes_read == len) {
            return 0;
        }
        fprintf(stderr, "I2C read failed, retrying (%d/%d): %s\n", retries + 1, I2C_RETRIES, strerror(errno));
        retries++;
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int last_temp = -1;
    while (1) {
        uint8_t buf[2];
        if (read_i2c_reg(TEMP_REG, buf, 2) < 0) {
            fprintf(stderr, "Failed to read temperature sensor data\n");
            cleanup(0);
        }

        int16_t raw_temp = (buf[0] << 8) | buf[1];
        float temp_c = raw_temp / 256.0;

        printf("Temperature: %.2f°C\n", temp_c);

        int new_state = (temp_c > TEMP_MAX) ? 1 : (temp_c < TEMP_HYST && last_temp >= TEMP_HYST) ? 0 : -1;
        if (new_state != -1) {
            if (gpiod_line_set_value(led_line, new_state) < 0) {
                fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
                cleanup(0);
            }
            last_temp = temp_c;
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

