#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define LOG_FILE "environment.log"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL 60
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUM_CMD 0xE5
#define READ_TEMP_CMD 0xE0

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int i2cWriteRetry(int fd, const char *buf, int len) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (i2cWrite(fd, buf, len) == len) {
            return 0;
        }
        usleep(10000); // 10ms delay
    }
    return -1;
}

int i2cReadRetry(int fd, char *buf, int len) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (i2cRead(fd, buf, len) == len) {
            return 0;
        }
        usleep(10000); // 10ms delay
    }
    return -1;
}

int readSensorData(uint16_t *temp, uint16_t *hum) {
    char buf[3];

    buf[0] = MEASURE_TEMP_CMD;
    if (i2cWriteRetry(i2cHandle, buf, 1) != 0) return -1;
    usleep(20000); // 20ms delay

    if (i2cReadRetry(i2cHandle, buf, 3) != 0) return -1;
    *temp = (buf[0] << 8) | buf[1];

    buf[0] = MEASURE_HUM_CMD;
    if (i2cWriteRetry(i2cHandle, buf, 1) != 0) return -1;
    usleep(20000); // 20ms delay

    if (i2cReadRetry(i2cHandle, buf, 3) != 0) return -1;
    *hum = (buf[0] << 8) | buf[1];

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Validate sensor presence
    char buf[2];
    if (i2cReadRetry(i2cHandle, buf, 2) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        cleanup(0);
    }

    time_t lastSampleTime = 0;
    while (1) {
        time_t now = time(NULL);
        if (now - lastSampleTime >= SAMPLE_INTERVAL) {
            uint16_t temp, hum;
            if (readSensorData(&temp, &hum) == 0) {
                float tempC = -46.85f + 175.72f * ((float)temp / 65536.0f);
                float humPct = 125.0f * ((float)hum / 65536.0f) - 6.0f;

                time_t currentTime;
                struct tm *timeInfo;
                char timestamp[20];

                time(&currentTime);
                timeInfo = localtime(&currentTime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeInfo);

                char logEntry[100];
                snprintf(logEntry, sizeof(logEntry), "%s,%.2f,%.2f\n", timestamp, tempC, humPct);

                printf("%s", logEntry);
                fflush(stdout);

                fprintf(logFile, "%s", logEntry);
                fflush(logFile);

                lastSampleTime = now;
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
                cleanup(0);
            }
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

