        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char config[2] = {CONF_REG, 0x10}; // Temperature and humidity, 14-bit resolution
    if (write(i2c_handle, config, 2) != 2) {
        perror("Failed to write configuration to HDC1080");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("enviro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_log_time = time(NULL);

    while (1) {
        unsigned char trigger[1] = {TEMP_REG};
        if (write(i2c_handle, trigger, 1) != 1) {
            perror("Failed to trigger temperature reading");
            continue;
        }

        usleep(CONVERSION_DELAY_MS * 1000);

        unsigned char temp_data[3];
        if (read(i2c_handle, temp_data, 3) != 3) {
            perror("Failed to read temperature data");
            continue;
