        trigger[0] = HUM_REG;
        if (write(i2c_handle, trigger, 1) != 1) {
            perror("Failed to trigger humidity reading");
            continue;
        }

        usleep(CONVERSION_DELAY_MS * 1000);

        unsigned char hum_data[3];
        if (read(i2c_handle, hum_data, 3) != 3) {
            perror("Failed to read humidity data");
            continue;
        }

        float humidity = ((hum_data[0] << 8) | hum_data[1]) / 65536.0 * 100.0;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_SEC) {
            fprintf(log_file, "%ld,%.2f,%.2f\n", (long)current_time, temperature, humidity);
            fflush(log_file);
            last_log_time = current_time;
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

