#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_I2C_ADDR 0x44
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_FINAL_XOR 0x00

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ CRC8_FINAL_XOR;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STS40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t write_cmd[] = {0x24, 0x00}; // Command to trigger temperature measurement
    uint8_t read_data[3];

    while (1) {
        if (write(i2c_fd, write_cmd, sizeof(write_cmd)) != sizeof(write_cmd)) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(10000); // 10ms delay for conversion

        if (read(i2c_fd, read_data, sizeof(read_data)) != sizeof(read_data)) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint8_t calculated_crc = calculate_crc8(read_data, 2);
        if (calculated_crc != read_data[2]) {
            fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", calculated_crc, read_data[2]);
            continue;
        }

        int16_t raw_temp = (read_data[0] << 8) | read_data[1];
        float temperature = -45.0 + 175.0 * (float)raw_temp / 65535.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s %.2f\n", timestamp, temperature);
        fflush(log_file);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

