#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x22
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static FILE *log_file;
static int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        gpioI2CClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, SDP810_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    uint8_t command = 0x36; // Continuous measurement mode
    if (gpioI2CWriteByte(i2c_handle, command) < 0) {
        fprintf(stderr, "Failed to send command to SDP810\n");
        cleanup(0);
    }

    usleep(50000); // Wait 50ms

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        uint8_t read_buffer[9];
        if (gpioI2CReadI2CBlock(i2c_handle, 0x00, read_buffer, 9) < 0) {
            fprintf(log_file, "%s,ERROR,I2C Read Error\n", timestamp);
            continue;
        }

        uint16_t pressure_raw = (read_buffer[0] << 8) | read_buffer[1];
        uint16_t temperature_raw = (read_buffer[3] << 8) | read_buffer[4];

        uint8_t pressure_crc = read_buffer[2];
        uint8_t temperature_crc = read_buffer[5];

        if (calculate_crc8(read_buffer, 2) != pressure_crc ||
            calculate_crc8(read_buffer + 3, 2) != temperature_crc) {
            fprintf(log_file, "%s,ERROR,CRC Error\n", timestamp);
            continue;
        }

        float pressure_Pa = pressure_raw * 10.0f;
        float temperature_C = temperature_raw / 200.0f - 273.15f;

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

