// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t txbuf[1] = {reg};
    if (i2cWriteDevice(fd, txbuf, 1) < 0) {
        return -1;
    }
    return i2cReadDevice(fd, data, len);
}

// I2C write function
int i2c_write(int fd, uint8_t reg, const uint8_t *data, int len) {
    uint8_t txbuf[len + 1];
    txbuf[0] = reg;
    memcpy(txbuf + 1, data, len);
    return i2cWriteDevice(fd, txbuf, len + 1);
}

