    FILE *error_log = fopen(ERROR_LOG, "a");
    if (error_log) {
        fprintf(error_log, "[%s] %s\n", time_str, message);
        fclose(error_log);
    }
}

// Circular buffer operations
void buffer_init(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->not_full, NULL);
    pthread_cond_init(&buffer->not_empty, NULL);
}

void buffer_push(CircularBuffer *buffer, SensorData *data) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->count == BUFFER_CAPACITY) {
        pthread_cond_wait(&buffer->not_full, &buffer->mutex);
    }
    buffer->data[buffer->head] = *data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    buffer->count++;
    pthread_cond_signal(&buffer->not_empty);
    pthread_mutex_unlock(&buffer->mutex);
}

int buffer_pop(CircularBuffer *buffer, SensorData *data) {
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->count == 0) {
        pthread_cond_wait(&buffer->not_empty, &buffer->mutex);
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    buffer->count--;
