#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x22
#define SDP810_MEASURE_CMD 0x03
#define SDP810_WAIT_TIME_MS 45
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_handle;
static FILE *log_file;

void sigint_handler(int signo) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(uint16_t *pressure, uint16_t *temperature, uint16_t *scale_factor) {
    uint8_t buffer[9];
    if (write(i2c_handle, &SDP810_MEASURE_CMD, 1) != 1) {
        fprintf(stderr, "Error writing to sensor\n");
        return -1;
    }
    usleep(SDP810_WAIT_TIME_MS * 1000);
    if (read(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
        fprintf(stderr, "Error reading from sensor\n");
        return -1;
    }

    if (calculate_crc8(buffer, 2) != buffer[2] ||
        calculate_crc8(buffer + 3, 2) != buffer[5] ||
        calculate_crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *scale_factor = (buffer[6] << 8) | buffer[7];

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("sdp810_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint16_t pressure, temperature, scale_factor;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (read_sensor_data(&pressure, &temperature, &scale_factor) == 0) {
            fprintf(log_file, "%s,%d,%d\n", timestamp, pressure, temperature);
            fflush(log_file);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

