#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define SENSOR_READ_INTERVAL 1000000 // 1 second
#define TRIGGER_DELAY 20000 // 20 ms
#define NORMAL_LED_INTERVAL 500000 // 500 ms
#define WARNING_LED_INTERVAL 100000 // 100 ms
#define WARNING_PRESSURE_THRESHOLD 95000

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

bool verify_crc(uint8_t *data, int length) {
    uint8_t crc = 0;
    for (int i = 0; i < length - 2; i++) {
        crc += data[i];
    }
    return (crc == data[length - 2]) && (data[length - 1] == 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    uint8_t buffer[6];
    struct timespec last_read_time = {0, 0};
    bool warning_state = false;
    struct timespec warning_toggle_time = {0, 0};

    while (keep_running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if ((current_time.tv_sec - last_read_time.tv_sec) * 1000000000 +
            (current_time.tv_nsec - last_read_time.tv_nsec) >= SENSOR_READ_INTERVAL) {

            ssize_t bytes_read = read(i2c_fd, buffer, sizeof(buffer));
            if (bytes_read != sizeof(buffer)) {
                if (bytes_read == -1) {
                    perror("I2C read error");
                } else {
                    fprintf(stderr, "Unexpected number of bytes read: %zd\n", bytes_read);
                }
                usleep(TRIGGER_DELAY);
                continue;
            }

            if (!verify_crc(buffer, sizeof(buffer))) {
                fprintf(stderr, "CRC check failed\n");
                usleep(TRIGGER_DELAY);
                continue;
            }

            uint16_t pressure = (buffer[0] << 8) | buffer[1];
            uint16_t temperature = (buffer[2] << 8) | buffer[3];

            printf("Pressure: %d Pa, Temperature: %d°C\n", pressure, temperature);

            if (pressure < WARNING_PRESSURE_THRESHOLD) {
                warning_state = true;
            } else {
                warning_state = false;
            }

            last_read_time = current_time;
            usleep(TRIGGER_DELAY);
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (warning_state) {
            if ((current_time.tv_sec - warning_toggle_time.tv_sec) * 1000000000 +
                (current_time.tv_nsec - warning_toggle_time.tv_nsec) >= WARNING_LED_INTERVAL) {
                gpioToggle(17);
                warning_toggle_time = current_time;
            }
        } else {
            if ((current_time.tv_sec - warning_toggle_time.tv_sec) * 1000000000 +
                (current_time.tv_nsec - warning_toggle_time.tv_nsec) >= NORMAL_LED_INTERVAL) {
                gpioToggle(17);
                warning_toggle_time = current_time;
            }
        }

        usleep(1000); // Small delay to prevent busy-waiting
    }

    close(i2c_fd);
    gpioTerminate();
    return 0;
}

