#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define TEMP_OBJ_REG 0x06
#define TEMP_AMB_REG 0x07
#define FAN_PIN 18
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *fan_line;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_read_word(int reg) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(i2c_fd, buf, 3) != 3) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return ((buf[0] << 8) | buf[1]) & 0xFFFF;
    }

    fprintf(stderr, "Failed to read from I2C device after %d attempts\n", RETRY_COUNT);
    return -1;
}

void log_temperature(double obj_temp, double amb_temp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Object: %.2f°C, Ambient: %.2f°C\n", timestamp, obj_temp, amb_temp);
    fclose(log_file);
}

void control_fan(double obj_temp, double prev_temp) {
    if (obj_temp > TEMP_THRESHOLD_HIGH && prev_temp <= TEMP_THRESHOLD_HIGH) {
        gpiod_line_set_value(fan_line, 1);
    } else if (obj_temp < TEMP_THRESHOLD_LOW && prev_temp >= TEMP_THRESHOLD_LOW) {
        gpiod_line_set_value(fan_line, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line for fan\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "Fan Control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for fan\n");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    double prev_obj_temp = 0.0;

    while (1) {
        int obj_temp_raw = i2c_read_word(TEMP_OBJ_REG);
        if (obj_temp_raw < 0) {
            fprintf(stderr, "Failed to read object temperature\n");
            continue;
        }

        int amb_temp_raw = i2c_read_word(TEMP_AMB_REG);
        if (amb_temp_raw < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            continue;
        }

        double obj_temp = obj_temp_raw * 0.02 - 273.15;
        double amb_temp = amb_temp_raw * 0.02 - 273.15;

        log_temperature(obj_temp, amb_temp);
        control_fan(obj_temp, prev_obj_temp);
        prev_obj_temp = obj_temp;

        sleep(2);
    }

    return EXIT_SUCCESS;
}

