#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP102_ADDRESS 0x48
#define TMP102_TEMP_REG 0x00
#define MEASUREMENT_INTERVAL 5

static int i2c_fd;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    }
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP102_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

float read_temperature() {
    uint16_t raw_temp;
    if (read(i2c_fd, &raw_temp, sizeof(raw_temp)) != sizeof(raw_temp)) {
        perror("Failed to read temperature");
        return -1;
    }

    // Convert raw temperature to Celsius
    return ((int16_t)raw_temp >> 4) * 0.0625;
}

int main() {
    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        float temperature = read_temperature();
        if (temperature >= 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping entry\n");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

