#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x0F
#define TEMP_HUM_REG 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define POLL_TIMEOUT_MS 500
#define OUTPUT_INTERVAL_MS 5000

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        shutdown_flag = 1;
    }
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result;

    do {
        result = i2cWriteI2CBlockData(fd, reg, buf, 0);
        if (result < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < MAX_RETRIES);

    if (result < 0) {
        return -1;
    }

    retries = 0;
    do {
        result = i2cReadI2CBlockData(fd, reg, buf, len);
        if (result < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < MAX_RETRIES);

    return result;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_handle;
    uint8_t buf[4];
    time_t last_output_time;
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    gpiod_line_request_output(line, "HDC2010_SDA", 1);

    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    last_output_time = time(NULL);

    while (!shutdown_flag) {
        // Start measurement
        buf[0] = 0x00;
        buf[1] = 0x01;
        if (i2c_write_device(i2c_handle, buf, 2) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            break;
        }

        // Wait for measurement to complete
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_TIMEOUT_MS * 1000000;
        while (1) {
            if (nanosleep(&ts, &ts) < 0) {
                fprintf(stderr, "nanosleep error\n");
                break;
            }

            result = i2c_read(i2c_handle, MEASUREMENT_CONFIG_REG, buf, 1);
            if (result < 0) {
                fprintf(stderr, "Failed to read MEASUREMENT_CONFIG\n");
                break;
            }

            if (!(buf[0] & 0x01)) {
                break;
            }
        }

        // Read temperature and humidity
        result = i2c_read(i2c_handle, TEMP_HUM_REG, buf, 4);
        if (result < 0) {
            fprintf(stderr, "Failed to read temperature and humidity\n");
            break;
        }

        float temp = (buf[0] << 8 | buf[1]) / 65536.0 * 165.0 - 40.0;
        float hum = (buf[2] << 8 | buf[3]) / 65536.0 * 100.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, hum);

        time_t current_time = time(NULL);
        if (current_time - last_output_time >= OUTPUT_INTERVAL_MS / 1000) {
            last_output_time = current_time;
        } else {
            sleep(OUTPUT_INTERVAL_MS / 1000 - (current_time - last_output_time));
        }
    }

    i2cClose(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

