#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_I2C_ADDR 0x21
#define MEASUREMENT_INTERVAL_MS 45
#define LOGGING_INTERVAL_MS 500
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    uint8_t command = 0x36; // Measure command
    if (write(i2c_handle, &command, 1) != 1) {
        perror("Failed to send measurement command");
        cleanup(SIGINT);
    }

    uint8_t buffer[6];
    int16_t pressure, temperature;
    uint8_t crc;

    while (1) {
        usleep(MEASUREMENT_INTERVAL_MS * 1000);

        if (read(i2c_handle, buffer, 6) != 6) {
            perror("Failed to read measurement data");
            cleanup(SIGINT);
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[3] << 8) | buffer[4];
        crc = buffer[2];

        if (calculate_crc8(buffer, 2) != crc) {
            fprintf(stderr, "Pressure CRC error\n");
            cleanup(SIGINT);
        }

        crc = buffer[5];
        if (calculate_crc8(buffer + 3, 2) != crc) {
            fprintf(stderr, "Temperature CRC error\n");
            cleanup(SIGINT);
        }

        printf("Pressure: %d Pa, Temperature: %d°C\n", pressure, temperature);

        usleep(LOGGING_INTERVAL_MS * 1000);
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}

