            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    uint8_t command = 0x36; // Measure command
    if (write(i2c_handle, &command, 1) != 1) {
        perror("Failed to send measurement command");
        cleanup(SIGINT);
    }

    uint8_t buffer[6];
    int16_t pressure, temperature;
    uint8_t crc;

    while (1) {
        usleep(MEASUREMENT_INTERVAL_MS * 1000);

        if (read(i2c_handle, buffer, 6) != 6) {
            perror("Failed to read measurement data");
            cleanup(SIGINT);
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[3] << 8) | buffer[4];
        crc = buffer[2];

        if (calculate_crc8(buffer, 2) != crc) {
            fprintf(stderr, "Pressure CRC error\n");
            cleanup(SIGINT);
        }

        crc = buffer[5];
        if (calculate_crc8(buffer + 3, 2) != crc) {
            fprintf(stderr, "Temperature CRC error\n");
            cleanup(SIGINT);
        }

        printf("Pressure: %d Pa, Temperature: %d°C\n", pressure, temperature);

        usleep(LOGGING_INTERVAL_MS * 1000);
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}
