int init_spi() {
    struct spi_ioc_transfer xfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
