        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

double read_temperature(int spi_fd) {
    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3] = {0x00, 0x00, 0x00};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    unsigned int raw = ((rx[1] & 0x0F) << 8) | rx[2];
    if (raw & 0x100) {
        fprintf(stderr, "Thermocouple error\n");
        return -1;
    }

    return raw * 0.25;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, SSR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
