    FILE *file = fopen(PROFILE_FILE, "r");
    if (!file) {
        perror("Failed to open profile file");
        return -1;
    }

    int count = 0;
    while (count < max_points && fscanf(file, "%lf,%lf", &profile[count].timestamp, &profile[count].setpoint) == 2) {
        count++;
    }

    fclose(file);
    return count;
}

double get_setpoint(ProfilePoint *profile, int profile_size, time_t current_time) {
    for (int i = 0; i < profile_size - 1; i++) {
        if (current_time >= profile[i].timestamp && current_time < profile[i + 1].timestamp) {
            double t = (double)(current_time - profile[i].timestamp) / (profile[i + 1].timestamp - profile[i].timestamp);
            return profile[i].setpoint + t * (profile[i + 1].setpoint - profile[i].setpoint);
        }
    }
    return profile[profile_size - 1].setpoint;
}

double pid_update(PIDState *state, double setpoint, double measured_value, double dt) {
    state->error = setpoint - measured_value;
    state->integral += state->error * dt;
    state->derivative = (state->error - state->error) / dt;

    double output = Kp * state->error + Ki * state->integral + Kd * state->derivative;
    return output;
}

