    int profile_size = load_profile(profile, 100);
    if (profile_size <= 0) {
        fprintf(stderr, "Failed to load profile\n");
        fclose(log_file);
        close(spi_fd);
        gpiod_chip_close(gpio_fd);
        return EXIT_FAILURE;
    }

