void signal_handler(int signum) {
    running = 0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ds18b20_line = gpiod_chip_get_line(chip, DS18B20_GPIO_PIN);
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO_PIN);
    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO_PIN);

    if (!ds18b20_line || !relay_line || !pwm_line) {
        perror("Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(ds18b20_line, "DS18B20") < 0 ||
        gpiod_line_request_output(relay_line, "RELAY", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "PWM", 0) < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (pwm_line) gpiod_line_release(pwm_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (ds18b20_line) gpiod_line_release(ds18b20_line);
    if (chip) gpiod_chip_close(chip);
}

void log_data(double avg_temp, double setpoint, double pid_output, int pwm_duty) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", time_str, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

double read_temperature() {
    // Implement reading from DS18B20 sensor and CRC validation
    // Return temperature in Celsius or handle errors
    return 25.0; // Placeholder
}

void set_pwm_duty(int duty) {
    // Implement setting PWM duty cycle
}

void set_relay_state(int state) {
    gpiod_line_set_value(relay_line, state);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    double integral = 0.0;
    double prev_error = 0.0;
    time_t last_log_time = time(NULL);

    while (running) {
        double temp = read_temperature();
        if (temp < -55 || temp > 125) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temp);
            continue;
        }

        double error = setpoint - temp;
        integral += error * SAMPLE_INTERVAL;
        double derivative = (error - prev_error) / SAMPLE_INTERVAL;

        double pid_output = Kp * error + Ki * integral + Kd * derivative;
        int pwm_duty = (int)(pid_output + 50.0); // Assuming 0-100% duty cycle
        pwm_duty = (pwm_duty < 0) ? 0 : (pwm_duty > 100) ? 100 : pwm_duty;

        set_pwm_duty(pwm_duty);
        set_relay_state(pwm_duty > 0);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_data(temp, setpoint, pid_output, pwm_duty);
            last_log_time = current_time;
        }

        prev_error = error;
        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    set_relay_state(0);
    set_pwm_duty(0);
    cleanup_gpio();

    return EXIT_SUCCESS;
}

