int i2c_write(const uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, data, len) == len) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, data, len) == len) {
