    uint8_t cmd[] = {0xAC, 0x33, 0x00};
    if (i2c_write(cmd, sizeof(cmd)) < 0) {
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t result[6];
    if (i2c_read(result, sizeof(result)) < 0) {
        return -1;
    }

    if ((result[0] & 0x80) != 0) {
        return -1;  // Sensor not calibrated
    }

    uint32_t raw_humidity = ((uint32_t)result[1] << 12) | ((uint32_t)result[2] << 4) | (result[3] >> 4);
    *humidity = (float)raw_humidity / 1048576.0 * 100.0;
    return 0;
}

