        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(dehumidifier_relay, "dehumidifier", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(dehumidifier_relay);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

