        float humidity;
        if (read_humidity(&humidity) == 0) {
            time_t now = time(NULL);
            char timestamp[26];
            ctime_r(&now, timestamp);
            timestamp[24] = '\0';  // Remove newline
            printf("%s: Humidity: %.2f%%\n", timestamp, humidity);

            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                gpiod_line_set_value(dehumidifier_relay, 1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                gpiod_line_set_value(dehumidifier_relay, 0);
            }
        } else {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
        }

        sleep(5);
    }

    return 0;
}

