#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define SENSOR_POLL_INTERVAL 60
#define API_URL "api.example.com"
#define API_PORT 80

int i2c_fd;
int sock_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (sock_fd >= 0) {
        close(sock_fd);
    }
    closelog();
}

void signal_handler(int signo) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signo);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_humidity(float *humidity) {
    unsigned char buf[3];
    buf[0] = 0xE5; // Humidity command

    if (write(i2c_fd, buf, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }

    usleep(50000); // Wait for conversion

    if (read(i2c_fd, buf, 3) != 3) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }

    unsigned short raw = (buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * (float)raw / 65536.0;

    return 0;
}

int http_post(const char *url, const char *data) {
    struct sockaddr_in server_addr;
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(API_PORT);
    if (inet_pton(AF_INET, url, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", url);
        close(sock_fd);
        return -1;
    }

    if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sock_fd);
        return -1;
    }

    char request[512];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "\r\n"
             "%s", url, strlen(data), data);

    if (send(sock_fd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        close(sock_fd);
        return -1;
    }

    char response[1024];
    ssize_t bytes_received = recv(sock_fd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive HTTP response: %s", strerror(errno));
        close(sock_fd);
        return -1;
    }

    response[bytes_received] = '\0';
    syslog(LOG_INFO, "HTTP Response: %s", response);

    close(sock_fd);
    return 0;
}

int main() {
    openlog("htu21d_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (i2c_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        float humidity;
        if (read_humidity(&humidity) < 0) {
            syslog(LOG_ERR, "Failed to read humidity");
        } else {
            char json[64];
            snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
            if (http_post(API_URL, json) < 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        }
        sleep(SENSOR_POLL_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

