#include <gpiod.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CONTROL 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESSUREDATA 0xF7

#define TEMP_COEFF1 25.0
#define TEMP_COEFF2 26.5
#define TEMP_COEFF3 26.0
#define TEMP_COEFF4 1.0

#define PRESSURE_THRESHOLD_LOW 980.0
#define PRESSURE_THRESHOLD_HIGH 1020.0

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "pressure_log.txt"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int verify_chip_id() {
    uint8_t id;
    if (i2c_read(i2c_fd, BMP280_REG_CHIPID, &id, 1) != 1) {
        return -1;
    }
    return (id == BMP280_CHIP_ID) ? 0 : -1;
}

int init_i2c() {
    int retries = 3;
    while (retries--) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            continue;
        }
        if (verify_chip_id() == 0) {
            return 0;
        }
        close(i2c_fd);
    }
    return -1;
}

void log_pressure(double pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(file, "[%s] Pressure: %.2f hPa\n", time_str, pressure);
        fclose(file);
    }
}

double compensate_pressure(int32_t adc_P) {
    double var1, var2;
    uint8_t regs[6];

    i2c_read(i2c_fd, 0x88, regs, 6);
    int32_t dig_T1 = (regs[1] << 8) | regs[0];
    int32_t dig_T2 = (regs[3] << 8) | regs[2];
    int32_t dig_T3 = (regs[5] << 8) | regs[4];

    i2c_read(i2c_fd, 0x8E, regs, 18);
    int32_t dig_P1 = (regs[0] << 8) | regs[1];
    int32_t dig_P2 = (regs[2] << 8) | regs[3];
    int32_t dig_P3 = (regs[4] << 8) | regs[5];
    int32_t dig_P4 = (regs[6] << 8) | regs[7];
    int32_t dig_P5 = (regs[8] << 8) | regs[9];
    int32_t dig_P6 = (regs[10] << 8) | regs[11];
    int32_t dig_P7 = (regs[12] << 8) | regs[13];
    int32_t dig_P8 = (regs[14] << 8) | regs[15];
    int32_t dig_P9 = (regs[16] << 8) | regs[17];

    int32_t var1 = (((adc_P >> 3) - (dig_P1 << 1)) * dig_P2) >> 11;
