#define RETRY_DELAY_MS 10

static int i2c_fd;
static struct gpiod_chip *pir_chip;
static struct gpiod_line *pir_line;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (pir_chip) {
        gpiod_chip_close(pir_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_write(int addr, uint8_t *buf, int len) {
    if (write(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int i2c_read(int addr, uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int read_tmp117(float *temp) {
    uint8_t buf[2];
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read(TMP117_ADDR, buf, 2) == 0) {
            *temp = (int16_t)(buf[0] << 4 | buf[1] >> 4) * 0.0625;
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_aht20(float *temp, float *humidity) {
    uint8_t buf[7];
    buf[0] = 0xAC;
    buf[1] = 0x33;
    buf[2] = 0x00;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_write(AHT20_ADDR, buf, 3) == 0) {
            usleep(80000);  // Wait for measurement
            if (i2c_read(AHT20_ADDR, buf, 7) == 0) {
                uint32_t h = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((buf[3] & 0xF0) >> 4);
                uint32_t t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
                *humidity = (float)h / 1048576.0 * 100.0;
                *temp = (float)t / 1048576.0 * 200.0 - 50.0;
                return 0;
            }
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    return (val < 0) ? -1 : val;
}

