        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set AHT20 address");
        cleanup();
        return EXIT_FAILURE;
    }

    pir_chip = gpiod_chip_open_by_number(PIR_GPIO_CHIP);
    if (!pir_chip) {
        fprintf(stderr, "Failed to open GPIO chip %d\n", PIR_GPIO_CHIP);
        cleanup();
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(pir_chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", PIR_GPIO_LINE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "PIR Sensor") < 0) {
        fprintf(stderr, "Failed to request PIR line as input\n");
        cleanup();
        return EXIT_FAILURE;
    }

    mkdir(LOG_DIR, 0755);

    time_t now;
    struct tm *tm_info;
    char filename[256];
    char timestamp[64];

    while (1) {
        time(&now);
        tm_info = localtime(&now);
        strftime(filename, sizeof(filename), "%Y-%m-%d.csv", tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (log_file == NULL || difftime(mktime(tm_info), mktime(localtime(&now))) >= 86400) {
            if (log_file) {
                fclose(log_file);
            }
            char full_path[512];
            snprintf(full_path, sizeof(full_path), "%s/%s", LOG_DIR, filename);
            log_file = fopen(full_path, "a");
            if (!log_file) {
                perror("Failed to open log file");
                cleanup();
                return EXIT_FAILURE;
            }
            if (ftell(log_file) == 0) {
                fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
            }
        }

        float temp = 0.0, humidity = 0.0;
        int motion = -1;

        if (read_tmp117(&temp) != 0) {
            fprintf(stderr, "Warning: Failed to read TMP117\n");
        }

        if (read_aht20(&temp, &humidity) != 0) {
            fprintf(stderr, "Warning: Failed to read AHT20\n");
        }

        motion = read_pir();
        if (motion < 0) {
            fprintf(stderr, "Warning: Failed to read PIR sensor\n");
        }

        log_data(timestamp, temp, humidity, motion);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

