#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL 2
#define MOTOR_DURATION 5

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor;
static struct gpiod_line *motor_ena;
static struct gpiod_line *motor_in1;
static struct gpiod_line *motor_in2;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", time_str, message);
}

void cleanup_gpio() {
    if (motor_in2) gpiod_line_release(motor_in2);
    if (motor_in1) gpiod_line_release(motor_in1);
    if (motor_ena) gpiod_line_release(motor_ena);
    if (rain_sensor) gpiod_line_release(rain_sensor);
    if (chip) gpiod_chip_close(chip);
}

void handle_signal(int signum) {
    log_message("Termination signal received. Stopping motor and cleaning up.");
    gpiod_line_set_value(motor_ena, 0);
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    rain_sensor = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_sensor) {
        perror("Failed to get rain sensor line");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    motor_ena = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    motor_in1 = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    motor_in2 = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!motor_ena || !motor_in1 || !motor_in2) {
        perror("Failed to get motor control lines");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(rain_sensor, "rain_sensor") < 0 ||
        gpiod_line_request_output(motor_ena, "motor_ena", 0) < 0 ||
        gpiod_line_request_output(motor_in1, "motor_in1", 0) < 0 ||
        gpiod_line_request_output(motor_in2, "motor_in2", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_message("Program started. Monitoring rain sensor.");

    while (1) {
        int rain_detected = !gpiod_line_get_value(rain_sensor);

        if (rain_detected) {
            log_message("Rain detected. Starting motor.");
            gpiod_line_set_value(motor_in1, 1);
            gpiod_line_set_value(motor_in2, 0);
            gpiod_line_set_value(motor_ena, 1);
            sleep(MOTOR_DURATION);
            gpiod_line_set_value(motor_ena, 0);
            log_message("Motor stopped.");
        }

        sleep(POLL_INTERVAL);
    }

    return EXIT_SUCCESS;
}

