#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_RED 17
#define GPIO_GREEN 22
#define GPIO_BLUE 27
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static unsigned int last_cpu_idle = 0, last_cpu_total = 0;

void cleanup(int signum) {
    for (int i = 0; i < 3; i++) {
        gpiod_line_set_value(lines[i], 1); // Turn off the LED
    }
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

void set_rgb_pwm(unsigned int red, unsigned int green, unsigned int blue) {
    gpiod_line_set_value(lines[0], PWM_RANGE - red);
    gpiod_line_set_value(lines[1], PWM_RANGE - green);
    gpiod_line_set_value(lines[2], PWM_RANGE - blue);
}

unsigned int get_cpu_load() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        exit(EXIT_FAILURE);
    }

    char cpu[16];
    unsigned int user, nice, system, idle, iowait, irq, softirq, steal;
    if (fscanf(fp, "%15s %u %u %u %u %u %u %u %u", cpu, &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 9) {
        fclose(fp);
        fprintf(stderr, "Failed to read CPU stats\n");
        exit(EXIT_FAILURE);
    }
    fclose(fp);

    unsigned int total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned int idle_time = idle + iowait;

    unsigned int load = 0;
    if (last_cpu_total > 0) {
        unsigned int total_diff = total - last_cpu_total;
        unsigned int idle_diff = idle_time - last_cpu_idle;
        load = (total_diff - idle_diff) * 100 / total_diff;
    }

    last_cpu_total = total;
    last_cpu_idle = idle_time;
    return load;
}

void map_load_to_color(unsigned int load, unsigned int *red, unsigned int *green, unsigned int *blue) {
    if (load <= 50) {
        *red = 255;
        *green = 2 * load;
        *blue = 0;
    } else {
        *red = 510 - 2 * load;
        *green = 255;
        *blue = 0;
    }
}

int main() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, (i == 0) ? GPIO_RED : (i == 1) ? GPIO_GREEN : GPIO_BLUE);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_output(lines[i], "RGB_LED", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line as output\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        unsigned int load = get_cpu_load();
        unsigned int red, green, blue;
        map_load_to_color(load, &red, &green, &blue);
        set_rgb_pwm(red, green, blue);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

