#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <pigpio.h>
#include <bmp280.h>

#define BMP280_I2C_ADDR 0x76
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define MEASUREMENT_INTERVAL 5

static int i2c_handle;
static int udp_socket;
static struct bmp280_dev bmp280;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        gpiod_chip_close(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    if (bmp280.dev_id != 0) {
        bmp280_close(&bmp280);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "BMP280_SDA", 1);
    if (ret < 0) {
        perror("Failed to request SDA line");
        gpiod_chip_close(chip);
        return -1;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get SCL line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "BMP280_SCL", 1);
    if (ret < 0) {
        perror("Failed to request SCL line");
        gpiod_chip_close(chip);
        return -1;
    }

    i2c_handle = gpiod_chip_fd(chip);
    gpiod_chip_close(chip);
    return 0;
}

int init_udp() {
    struct sockaddr_in server_addr;

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    server_addr.sin_addr.s_addr = inet_addr(UDP_IP);

    return 0;
}

int init_bmp280() {
    int ret;

    bmp280.dev_id = 0;
    bmp280.intf = BMP280_I2C_INTF;
    bmp280.read = bmp280_i2c_read;
    bmp280.write = bmp280_i2c_write;
    bmp280.delay_ms = bmp280_delay_ms;

    ret = bmp280_init(&bmp280);
    if (ret != BMP280_OK) {
        fprintf(stderr, "BMP280 initialization failed\n");
        return -1;
    }

    bmp280_set_power_mode(BMP280_FORCED_MODE);
    return 0;
}

int bmp280_i2c_read(uint8_t reg_addr, uint8_t *reg_data, uint32_t len) {
    int ret;
    uint8_t buffer[len + 1];

    buffer[0] = reg_addr;
    ret = i2cWriteI2CBlockData(i2c_handle, BMP280_I2C_ADDR, buffer, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    ret = i2cReadI2CBlockData(i2c_handle, BMP280_I2C_ADDR, reg_data, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    return 0;
}

int bmp280_i2c_write(uint8_t reg_addr, const uint8_t *reg_data, uint32_t len) {
    uint8_t buffer[len + 1];

    buffer[0] = reg_addr;
    memcpy(&buffer[1], reg_data, len);

    int ret = i2cWriteI2CBlockData(i2c_handle, BMP280_I2C_ADDR, buffer, len + 1);
    if (ret < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    return 0;
}

void bmp280_delay_ms(uint32_t period) {
    usleep(period * 1000);
}

int main() {
    struct sigaction sa;
    struct bmp280_data comp_data;
    char json_buffer[100];
    struct sockaddr_in server_addr;
    ssize_t bytes_sent;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_udp() < 0) {
        fprintf(stderr, "Failed to initialize UDP\n");
        gpiod_chip_close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_bmp280() < 0) {
        fprintf(stderr, "Failed to initialize BMP280\n");
        close(udp_socket);
        gpiod_chip_close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    server_addr.sin_addr.s_addr = inet_addr(UDP_IP);

    while (1) {
        bmp280_set_power_mode(BMP280_FORCED_MODE);
        bmp280_perform_measurement(&bmp280, &comp_data);

        snprintf(json_buffer, sizeof(json_buffer),
                 "{\"temperature\": %.2f, \"pressure\": %.2f}",
                 comp_data.temperature / 100.0, comp_data.pressure / 256.0);

        bytes_sent = sendto(udp_socket, json_buffer, strlen(json_buffer), 0,
                            (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (bytes_sent < 0) {
            perror("Failed to send UDP packet");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    return EXIT_SUCCESS;
}

