    uint8_t buf[3];
    if (i2c_write(i2c_fd, 0xF4, 0x2E) != 1) {
        fprintf(stderr, "Failed to write control register\n");
        return -1;
    }
    usleep(5000);  // Wait for conversion

    if (i2c_read(i2c_fd, 0xF6, buf, 3) != 3) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    *adc_temp = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    *adc_temp >>= (8 - OSS);

    return 0;
