    usleep((2 + (3 << OSS)) * 1000);  // Wait for conversion

    if (i2c_read(i2c_fd, 0xF6, buf, 3) != 3) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }

    *adc_pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    *adc_pressure >>= (8 - OSS);

    return 0;
