    x1 = ((int32_t)adc_temp - ac6) * ac5 >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    *temperature = (b5 + 8) >> 4;
    *temperature /= 10.0;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((int32_t)ac1 * 4 + x3) << OSS) + 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)(adc_pressure - b3) * (50000 >> OSS));

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
