#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID 0x60
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_CONTROL_HUM 0xF2
#define BME280_REG_CONTROL_MEAS 0xF4
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_TEMP_MSB 0xFA

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"

int i2c_fd;
FILE *log_fp;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, len);
}

int bme280_init() {
    uint8_t chip_id;
    if (i2c_read(i2c_fd, BME280_REG_CHIPID, &chip_id, 1) != 1 || chip_id != BME280_CHIP_ID) {
        return -1;
    }

    // Set humidity oversampling to x1
    if (i2c_write(i2c_fd, BME280_REG_CONTROL_HUM, 0x03) != 1) {
        return -1;
    }

    // Set temperature and pressure oversampling to x1, mode to normal
    if (i2c_write(i2c_fd, BME280_REG_CONTROL_MEAS, 0x27) != 1) {
        return -1;
    }

    return 0;
}

int bme280_read_sensor(int32_t *temp, int32_t *humidity, int32_t *pressure) {
    uint8_t buf[8];
    if (i2c_read(i2c_fd, BME280_REG_TEMP_MSB, buf, 8) != 8) {
        return -1;
    }

    *temp = (int32_t)(buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    *humidity = (int32_t)(buf[6] << 8) | buf[7];
    *pressure = (int32_t)(buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bme280_init() < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    int32_t temp, humidity, pressure;

    while (1) {
        if (bme280_read_sensor(&temp, &humidity, &pressure) < 0) {
            fprintf(stderr, "Failed to read BME280 sensor\n");
        } else {
            now = time(NULL);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_fp, "%s,%d.%02d,%d.%02d,%d.%02d\n",
                    timestamp,
                    temp / 100, abs(temp) % 100,
                    humidity / 1024, abs(humidity) % 1024,
                    pressure / 256, abs(pressure) % 256);
            fflush(log_fp);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

