#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define BMP180_ADDRESS 0x77
#define BUFFER_SIZE 1200 // 60 seconds / 0.05 seconds
#define ALERT_PIN 24
#define ALERT_THRESHOLD 5.0 // hPa

typedef struct {
    double pressure;
    struct timespec timestamp;
} SensorReading;

SensorReading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

static void cleanup(int signum) {
    gpioSetMode(ALERT_PIN, PI_INPUT);
    gpioWrite(ALERT_PIN, PI_LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

static void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

static double get_rolling_average() {
    double sum = 0.0;
    int count = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer_full || i < buffer_index) {
            sum += circular_buffer[i].pressure;
            count++;
        }
    }

    return count > 0 ? sum / count : 0.0;
}

int main() {
    struct bmp180_dev dev;
    struct timespec current_time;
    double rolling_avg;

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, PI_LOW);

    if (setenv("BMP180_I2C_BUS", "1", 1) != 0) {
        log_error("Failed to set I2C bus environment variable");
        cleanup(0);
    }

    if (bmp180_init(&dev) != BMP180_OK) {
        log_error("Failed to initialize BMP180 sensor");
        cleanup(0);
    }

    signal(SIGINT, cleanup);

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            log_error("Failed to get current time");
            continue;
        }

        if (bmp180_read_pressure(&dev) != BMP180_OK) {
            log_error("Failed to read pressure from BMP180 sensor");
            continue;
        }

        circular_buffer[buffer_index].pressure = dev.pressure;
        circular_buffer[buffer_index].timestamp = current_time;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_index == 0) {
            buffer_full = 1;
        }

        rolling_avg = get_rolling_average();
        double pressure_diff = fabs(dev.pressure - rolling_avg);

        if (pressure_diff > ALERT_THRESHOLD) {
            gpioWrite(ALERT_PIN, PI_HIGH);
            fprintf(stderr, "[ALERT] Pressure deviation: %.2f hPa (average: %.2f hPa)\n",
                    pressure_diff, rolling_avg);
        } else {
            gpioWrite(ALERT_PIN, PI_LOW);
        }

        gpioDelay(50000); // 50 ms
    }

    return EXIT_SUCCESS;
}

