#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_CHIP_ID 0x55
#define BMP180_REGISTER_CHIPID 0xD0
#define BMP180_REGISTER_CONTROL 0xF4
#define BMP180_REGISTER_TEMPDATA 0xF6
#define BMP180_REGISTER_PRESSUREDATA 0xF6
#define BMP180_REGISTER_CAL_AC1 0xAA
#define BMP180_REGISTER_CAL_AC2 0xAC
#define BMP180_REGISTER_CAL_AC3 0xAE
#define BMP180_REGISTER_CAL_AC4 0xB0
#define BMP180_REGISTER_CAL_AC5 0xB2
#define BMP180_REGISTER_CAL_AC6 0xB4
#define BMP180_REGISTER_CAL_B1 0xB6
#define BMP180_REGISTER_CAL_B2 0xB8
#define BMP180_REGISTER_CAL_MB 0xBA
#define BMP180_REGISTER_CAL_MC 0xBC
#define BMP180_REGISTER_CAL_MD 0xBE

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bmp180_log.txt"
#define SAMPLE_INTERVAL_MS 500

int i2c_fd;
int running = 1;

struct bmp180_calib_data {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
};

struct bmp180_calib_data calib;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int bmp180_read_calibration_data() {
    uint8_t buf[22];
    if (i2c_read(i2c_fd, BMP180_REGISTER_CAL_AC1, buf, 22) != 22) {
        return -1;
    }

    calib.ac1 = (buf[0] << 8) | buf[1];
    calib.ac2 = (buf[2] << 8) | buf[3];
    calib.ac3 = (buf[4] << 8) | buf[5];
    calib.ac4 = (buf[6] << 8) | buf[7];
    calib.ac5 = (buf[8] << 8) | buf[9];
    calib.ac6 = (buf[10] << 8) | buf[11];
    calib.b1 = (buf[12] << 8) | buf[13];
    calib.b2 = (buf[14] << 8) | buf[15];
    calib.mb = (buf[16] << 8) | buf[17];
    calib.mc = (buf[18] << 8) | buf[19];
    calib.md = (buf[20] << 8) | buf[21];

    return 0;
}

int bmp180_read_raw_temp() {
    uint8_t buf[2];
    if (i2c_write(i2c_fd, BMP180_REGISTER_CONTROL, 0x2E) != 1) {
        return -1;
    }
    usleep(5000);  // Wait 5ms
    if (i2c_read(i2c_fd, BMP180_REGISTER_TEMPDATA, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int bmp180_read_raw_pressure() {
    uint8_t buf[3];
    if (i2c_write(i2c_fd, BMP180_REGISTER_CONTROL, 0x34) != 1) {
        return -1;
    }
    usleep(20000);  // Wait 20ms
    if (i2c_read(i2c_fd, BMP180_REGISTER_PRESSUREDATA, buf, 3) != 3) {
        return -1;
    }
    return (buf[0] << 16) | (buf[1] << 8) | buf[2];
}

float bmp180_calc_temperature(int ut) {
    int32_t x1 = ((int32_t)ut - (int32_t)calib.ac6) * ((int32_t)calib.ac5) >> 15;
    int32_t x2 = ((int32_t)calib.mc << 11) / (x1 + (int32_t)calib.md);
    return ((x1 + x2) + 8) >> 4;
}

float bmp180_calc_pressure(int32_t up) {
    int32_t x1 = ((int32_t)calib.ac6) * ((int32_t)calib.ac5) >> 15;
    int32_t x2 = ((int32_t)calib.mc << 11) / (x1 + (int32_t)calib.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)calib.b2 * (b6 * b6) >> 12) >> 11;
    x2 = ((int32_t)calib.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)calib.ac1) * 4 + x3) << calib.ac3) + 2) >> 2;
    x1 = ((int32_t)calib.ac3 * b6) >> 13;
    x2 = ((int32_t)calib.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return p + ((x1 + x2 + 3791) >> 4);
}

void sample_sensor() {
    int raw_temp, raw_pressure;
    float temperature, pressure;

    raw_temp = bmp180_read_raw_temp();
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    raw_pressure = bmp180_read_raw_pressure();
    if (raw_pressure < 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    temperature = bmp180_calc_temperature(raw_temp) / 10.0;
    pressure = bmp180_calc_pressure(raw_pressure) / 100.0;

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f°C, Pressure: %.2fPa\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec,
            temperature, pressure);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read(i2c_fd, BMP180_REGISTER_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        close(i2c_fd);
        return 1;
    }

    if (chip_id != BMP180_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    if (bmp180_read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_fd;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);  // Assuming GPIO 17 for the timer
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    gpio_fd = gpiod_line_request_rising_edge_events(line, "bmp180_timer");
    if (gpio_fd < 0) {
        fprintf(stderr, "Error requesting GPIO events\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct timespec timeout = {0, 100000000};  // 100ms timeout
    struct gpiod_line_event event;

    while (running) {
        ssize_t ret = gpiod_line_event_wait(line, &timeout);
        if (ret > 0) {
            if (gpiod_line_event_read(line, &event) == 0) {
                sample_sensor();
            }
        } else if (ret < 0) {
            perror("Error waiting for GPIO event");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

