#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define GPIO_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define MIN_DUTY 0
#define MAX_DUTY 255
#define LOG_INTERVAL 5

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_fp;

void signal_handler(int signum) {
    running = 0;
}

int init_pwm() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(line, "pwm", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup_pwm() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int set_pwm_duty(int duty) {
    int ret = gpiod_line_set_value(line, duty > 0);
    if (ret < 0) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    return 0;
}

int read_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int map_temperature_to_duty(int temp) {
    if (temp < MIN_TEMP) return MIN_DUTY;
    if (temp > MAX_TEMP) return MAX_DUTY;

    return (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP) + MIN_DUTY;
}

int log_data(int temp, int duty) {
    if (!log_fp) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) {
            perror("Failed to open log file");
            return -1;
        }
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp / 1000, duty);
    fflush(log_fp);
    return 0;
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_pwm() < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        int duty = map_temperature_to_duty(temp);
        if (set_pwm_duty(duty) < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        if (log_data(temp, duty) < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        sleep(LOG_INTERVAL);
    }

    cleanup_pwm();
    if (log_fp) {
        fclose(log_fp);
    }

    return EXIT_SUCCESS;
}

