        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int set_pwm_duty(int duty) {
    int ret = gpiod_line_set_value(line, duty > 0);
    if (ret < 0) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    return 0;
}

int read_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int map_temperature_to_duty(int temp) {
    if (temp < MIN_TEMP) return MIN_DUTY;
    if (temp > MAX_TEMP) return MAX_DUTY;

    return (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP) + MIN_DUTY;
}

int log_data(int temp, int duty) {
    if (!log_fp) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) {
            perror("Failed to open log file");
            return -1;
        }
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp / 1000, duty);
    fflush(log_fp);
    return 0;
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_pwm() < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        int duty = map_temperature_to_duty(temp);
        if (set_pwm_duty(duty) < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        if (log_data(temp, duty) < 0) {
            cleanup_pwm();
            return EXIT_FAILURE;
        }

        sleep(LOG_INTERVAL);
    }

    cleanup_pwm();
    if (log_fp) {
        fclose(log_fp);
    }

    return EXIT_SUCCESS;
}
