#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDRESS 0x48
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define ALERT_PIN 18

static int i2c_fd;
static struct gpiod_line *alert_line;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE] = {0};
static int buffer_index = 0;
static float running_average = 0.0;

void cleanup(int signum) {
    (void)signum;
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    pthread_mutex_destroy(&buffer_mutex);
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

float read_temperature() {
    char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from LM75");
        return -1.0;
    }
    return ((buf[0] << 8 | buf[1]) >> 3) * 0.125;
}

void update_buffer(float temp) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

void update_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    running_average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

void *alert_thread(void *arg) {
    (void)arg;
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return NULL;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_output(alert_line, "alert", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return NULL;
    }

    while (1) {
        pthread_mutex_lock(&buffer_mutex);
        int alert = (running_average > TEMP_THRESHOLD);
        pthread_mutex_unlock(&buffer_mutex);

        gpiod_line_set_value(alert_line, alert);
        usleep(100000); // 100ms
    }

    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);
    return NULL;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        perror("Failed to create alert thread");
        cleanup(0);
    }

    while (1) {
        float temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature\n");
            cleanup(0);
        }

        update_buffer(temp);
        update_average();

        printf("Temperature: %.2f°C, Average: %.2f°C\n", temp, running_average);
        sleep(1);
    }

    return EXIT_SUCCESS;
}

