    j_Ki = json_object_object_get(parsed_json, "Ki");
    j_Kd = json_object_object_get(parsed_json, "Kd");

    if (j_target_temp) config.target_temp = json_object_get_double(j_target_temp);
    if (j_Kp) config.Kp = json_object_get_double(j_Kp);
    if (j_Ki) config.Ki = json_object_get_double(j_Ki);
    if (j_Kd) config.Kd = json_object_get_double(j_Kd);

