static double read_rtd_temperature() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
