    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(line, "PID_Heater", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    load_config("pid_config.json");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        double current_temp = read_rtd_temperature();
        if (current_temp < 0 || current_temp > MAX_TEMP) {
            syslog(LOG_ERR, "Temperature out of range: %.2f°C", current_temp);
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) +
                    (current_time.tv_nsec - last_time.tv_nsec) / 1e9;

        double pwm_duty;
        pid_control(config.target_temp, current_temp, &pwm_duty, dt);

        gpiod_line_set_value(line, pwm_duty > 0 ? 1 : 0);
        if (pwm_duty > 0) {
            gpioPWM(PWM_PIN, (unsigned int)pwm_duty);
        } else {
            gpioPWM(PWM_PIN, 0);
        }

        last_time = current_time;
        usleep(PID_INTERVAL_MS * 1000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    return running ? 0 : 1;
}

