#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_I2C_BUS 1
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_TIME_MS 200
#define LOG_INTERVAL_MS 2000

// BMP180 Registers
#define BMP180_CAL_AC1 0xAA
#define BMP180_CAL_AC2 0xAC
#define BMP180_CAL_AC3 0xAE
#define BMP180_CAL_AC4 0xB0
#define BMP180_CAL_AC5 0xB2
#define BMP180_CAL_AC6 0xB4
#define BMP180_CAL_B1 0xB6
#define BMP180_CAL_B2 0xB8
#define BMP180_CAL_MB 0xBA
#define BMP180_CAL_MC 0xBC
#define BMP180_CAL_MD 0xBE

// BMP180 Commands
#define BMP180_READ_TEMP 0x2E
#define BMP180_READ_PRESSURE 0x34

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

int i2c_fd;
int gpio_fd;
int gpio_pin = 27;
int log_enabled = 0;
FILE *log_file;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpioTerminate();
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signo) {
    printf("Received signal %d, cleaning up and exiting...\n", signo);
    log_enabled = 0;
    cleanup();
    exit(0);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int read_calibration_data() {
    uint8_t buf[2];
    if (i2c_read(i2c_fd, BMP180_CAL_AC1, buf, 2) != 2) return -1;
    ac1 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_AC2, buf, 2) != 2) return -1;
    ac2 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_AC3, buf, 2) != 2) return -1;
    ac3 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_AC4, buf, 2) != 2) return -1;
    ac4 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_AC5, buf, 2) != 2) return -1;
    ac5 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_AC6, buf, 2) != 2) return -1;
    ac6 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_B1, buf, 2) != 2) return -1;
    b1 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_B2, buf, 2) != 2) return -1;
    b2 = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_MB, buf, 2) != 2) return -1;
    mb = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_MC, buf, 2) != 2) return -1;
    mc = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, BMP180_CAL_MD, buf, 2) != 2) return -1;
    md = (buf[0] << 8) | buf[1];

    return 0;
}

long get_raw_temperature() {
    i2c_write(i2c_fd, 0xF4, BMP180_READ_TEMP);
    usleep(5000); // Wait for conversion

    uint8_t buf[2];
    if (i2c_read(i2c_fd, 0xF6, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

long get_raw_pressure() {
    i2c_write(i2c_fd, 0xF4, BMP180_READ_PRESSURE + (3 << 6));
    usleep(25000); // Wait for conversion

    uint8_t buf[3];
    if (i2c_read(i2c_fd, 0xF6, buf, 3) != 3) return -1;
    return ((long)buf[0] << 16) | ((long)buf[1] << 8) | buf[2];
}

double compute_pressure(long raw_temp, long raw_pressure) {
    long X1, X2, X3, B3, B6, X4, B7;
    unsigned long B4, B5;

    X1 = ((long)raw_temp - ac6) * ac5 >> 15;
    X2 = (mc << 11) / (X1 + md);
    B5 = X1 + X2;
    X1 = (ac3 * B5) >> 13;
    X2 = (b2 * (B5 >> 12)) >> 11;
    X3 = (X1 + X2) + 2;
    B3 = (((long)ac1 * 4 + X3) << 2) + 3;
    X1 = (ac2 * (B5 >> 11)) >> 11;
    X2 = (b1 * (B5 >> 12)) >> 12;
    X4 = (X1 + X2) + 2;
    B4 = (ac4 * (unsigned long)(X4 + 32768)) >> 15;
    B7 = ((unsigned long)(raw_pressure - B3) * (50000 >> 3));
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    return p + ((X1 + X2 + 3791) >> 4);
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_interrupt = 0;
    if (tick - last_interrupt > DEBOUNCE_TIME_MS * 1000) {
        log_enabled = !log_enabled;
        printf("Logging %s\n", log_enabled ? "enabled" : "disabled");
        last_interrupt = tick;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpio_set_mode(gpio_pin, PI_INPUT);
    gpio_set_pull_up_down(gpio_pin, PI_PUD_UP);
    gpio_set_glitch_filter(gpio_pin, 150000); // 150ms filter
    gpio_set_watchdog(gpio_pin, 0); // Disable watchdog
    gpio_set_alert_func(gpio_pin, gpio_callback);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup();
        return 1;
    }

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    time_t last_log_time = 0;

    while (1) {
        if (log_enabled) {
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 2) {
