#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80.0
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define CS_PIN 8
#define PWM_PIN 17
#define LOG_FILE "heater_log.csv"

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *pwm_line;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%s\n", timestamp, message);
    fflush(log_file);
}

float read_temperature() {
    unsigned char tx[4] = {0x01, 0x00, 0x00, 0x00};
    unsigned char rx[4];
    int ret;

    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_set_value(CS_PIN, 1);
    usleep(1);

    ret = spiXfer(SPI_CHANNEL, tx, rx, 4);
    if (ret < 0) {
        log_message("SPI read failure");
        return -1;
    }

    gpiod_line_set_value(CS_PIN, 0);

    if ((rx[0] & 0x07) != 0) {
        char fault[64];
        snprintf(fault, sizeof(fault), "MAX31855 fault: %02x", rx[0] & 0x07);
        log_message(fault);
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) | ((uint32_t)rx[2] << 8) | rx[3];
    return (float)raw * 0.0625;
}

void set_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    gpioPWM(PWM_PIN, (int)(duty_cycle * 255.0 / 100.0));
}

void control_loop() {
    float current_temp, error, integral = 0, last_error = 0;
    float kp = 1.0, ki = 0.1;

    while (1) {
        current_temp = read_temperature();
        if (current_temp < 0) {
            set_duty_cycle(0);
            continue;
        }

        error = TARGET_TEMP - current_temp;
        integral += error;

        float output = kp * error + ki * integral;
        if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
        if (output < 0) output = 0;

        set_duty_cycle(output);

        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "%.2f,%.2f", current_temp, output);
        log_message(log_buf);

        last_error = error;
        usleep(100000);  // 100ms
    }
}

void cleanup(int signum) {
    printf("Shutting down...\n");
    set_duty_cycle(0);
    gpioTerminate();
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "PWM", 0) < 0) {
        fprintf(stderr, "Failed to request PWM line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 0);

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    control_loop();

    return 0;
}

