volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    FILE *temp_file;
    unsigned int temp;
    int ret;

