    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(red_line, "red", 1);
    ret |= gpiod_line_request_output(green_line, "green", 1);
    ret |= gpiod_line_request_output(blue_line, "blue", 1);

    if (ret) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        goto cleanup;
    }

    temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        fprintf(stderr, "Failed to open temperature file\n");
        goto cleanup;
    }

    while (!terminate) {
        if (fscanf(temp_file, "%u", &temp) != 1) {
            if (ferror(temp_file)) {
                fprintf(stderr, "Error reading temperature\n");
                clearerr(temp_file);
            }
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("Temperature: %u m°C\n", temp);

        if (temp < 40000) {
            ret = gpiod_line_set_value(red_line, 1);
            ret |= gpiod_line_set_value(green_line, 1);
            ret |= gpiod_line_set_value(blue_line, 0);
        } else if (temp < 60000) {
            ret = gpiod_line_set_value(red_line, 1);
            ret |= gpiod_line_set_value(green_line, 0);
            ret |= gpiod_line_set_value(blue_line, 0);
        } else {
            ret = gpiod_line_set_value(red_line, 0);
            ret |= gpiod_line_set_value(green_line, 0);
            ret |= gpiod_line_set_value(blue_line, 0);
        }

        if (ret) {
            fprintf(stderr, "Failed to set GPIO values\n");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (temp_file) {
        fclose(temp_file);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return terminate ? EXIT_SUCCESS : EXIT_FAILURE;
}

