            ret = gpiod_line_set_value(red_line, 1);
            ret |= gpiod_line_set_value(green_line, 0);
            ret |= gpiod_line_set_value(blue_line, 0);
        } else {
            ret = gpiod_line_set_value(red_line, 0);
            ret |= gpiod_line_set_value(green_line, 0);
            ret |= gpiod_line_set_value(blue_line, 0);
        }

        if (ret) {
            fprintf(stderr, "Failed to set GPIO values\n");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (temp_file) {
        fclose(temp_file);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return terminate ? EXIT_SUCCESS : EXIT_FAILURE;
}
