#define GPIO_PIN 4
#define MAX_RETRIES 3
#define RETRY_DELAY 2
#define DHT22_TIMEOUT 255

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (!ptr) {
        printf("Not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

int read_dht22(int gpio_fd, float *temperature, float *humidity) {
    struct timespec start, end;
    int data[5] = {0};
    int bit_count = 0;
    int data_count = 0;

    gpiod_line_request_config config = {
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = 0,
    };

    if (gpiod_line_request(gpio_fd, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return -1;
    }

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        // Start signal
        gpiod_line_set_value(gpio_fd, 0);
        nanosleep(&(struct timespec){0, 1000000}, NULL);
        gpiod_line_set_value(gpio_fd, 1);

        // Wait for response
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(gpio_fd) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) > DHT22_TIMEOUT / 1000) {
                break;
            }
        }

        // Read data
        for (int i = 0; i < 40; i++) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(gpio_fd) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                if ((end.tv_sec - start.tv_sec) > DHT22_TIMEOUT / 1000) {
                    break;
                }
            }

            nanosleep(&(struct timespec){0, 28}, NULL);

            if (gpiod_line_get_value(gpio_fd) == 0) {
                data[data_count] = (data[data_count] << 1);
            } else {
                data[data_count] = (data[data_count] << 1) | 1;
            }

            bit_count++;
            if (bit_count == 8) {
                bit_count = 0;
                data_count++;
            }
        }

        if (data_count == 5) {
            unsigned char checksum = data[0] + data[1] + data[2] + data[3];
            if (checksum == data[4]) {
                *humidity = (float)data[0] + (float)data[1] / 100.0;
                *temperature = (float)data[2] + (float)data[3] / 100.0;
                gpiod_line_release(gpio_fd);
                return 0;
            }
        }

        nanosleep(&(struct timespec){0, RETRY_DELAY * 1000000}, NULL);
    }

    gpiod_line_release(gpio_fd);
    return -1;
}

int send_http_request(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    struct MemoryStruct chunk;
    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        struct json_object *json = json_object_new_object();
        json_object_object_add(json, "temperature", json_object_new_double(temperature));
        json_object_object_add(json, "humidity", json_object_new_double(humidity));

        const char *json_str = json_object_to_json_string(json);
        json_object_put(json);

        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_str);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    free(chunk.memory);
    return (int)res;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_fd;
    float temperature, humidity;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio_fd = gpiod_line_get_fd(line);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to get GPIO file descriptor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        if (read_dht22(gpio_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
            if (send_http_request(temperature, humidity) != CURLE_OK) {
                fprintf(stderr, "Failed to send HTTP request\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }

        sleep(60);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

