    if (gpiod_line_request_falling_edge_events(button_line, "button_interrupt", button_callback) < 0) {
        fprintf(stderr, "Failed to request button interrupt\n");
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (bmp180_init() < 0) {
        fprintf(stderr, "Failed to initialize BMP180\n");
        close(i2c_fd);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        if (logging_enabled) {
            int32_t ut, up;
            int32_t temp, pressure;

            if (bmp180_read_raw_temp(&ut) < 0 ||
                bmp180_read_raw_pressure(&up) < 0 ||
                bmp180_compensate_temp(ut, &temp) < 0 ||
                bmp180_compensate_pressure(up, &pressure) < 0) {
                fprintf(stderr, "Failed to read or compensate sensor data\n");
                continue;
            }

            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s, %d hPa\n", timestamp, pressure);
            fclose(log_file);

            usleep(CONV_DELAY_MS * 1000);
        } else {
            printf("Logging disabled. Press button to enable.\n");
            sleep(1);
        }
    }

    return 0;
}

static int bmp180_init(void) {
    if (bmp180_read_calibration() < 0) {
        return -1;
    }

    // Write control register to start temperature measurement
    uint8_t ctrl = 0x2E;
    if (write(i2c_fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Failed to write control register\n");
        return -1;
    }

    return 0;
}

static int bmp180_read_calibration(void) {
    uint8_t reg = 0xAA;
    uint8_t data[22];

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write calibration register\n");
        return -1;
    }

    if (read(i2c_fd, data, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

static int bmp180_read_raw_temp(int32_t *temp) {
    uint8_t ctrl = 0x2E;
    if (write(i2c_fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Failed to write temperature control register\n");
        return -1;
    }

    usleep(CONV_DELAY_MS * 1000);

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    *temp = (data[0] << 8) | data[1];
    return 0;
}

static int bmp180_read_raw_pressure(int32_t *pressure) {
    uint8_t ctrl = (0x34 + (OSS << 6));
    if (write(i2c_fd, &ctrl, 1) != 1) {
        fprintf(stderr, "Failed to write pressure control register\n");
        return -1;
    }

    usleep((CONV_DELAY_MS + (3 << OSS)) * 1000);

    uint8_t data[3];
    if (read(i2c_fd, data, 3) != 3) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
    *pressure >>= (8 - OSS);
    return 0;
}

static int bmp180_compensate_temp(int32_t ut, int32_t *temp) {
    int32_t x1, x2;

    x1 = ((ut - ac6) * ac5) >> 15;
    x2 = (mc << 11) / (x1 + md);
    *temp = ((x1 + x2) + 4) >> 2;

    return 0;
}

static int bmp180_compensate_pressure(int32_t up, int32_t *pressure) {
    int32_t x1, x2, x3, b3, b6, p;
    uint32_t b4, b7;

    b6 = *temp - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((ac1 * 4 + x3) << OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)(up - b3) * (50000 >> OSS));

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = p + ((x1 + x2 + 3791) >> 4);

    return 0;
}

static void button_callback(uint gpio, uint32_t level, uint32_t tick) {
    if (tick - last_interrupt_time > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = tick;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nCleaning up and exiting...\n");
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpioTerminate();
        exit(0);
    }
}
