#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5
#define RETRY_DELAY 1

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_int_from_file(const char *file_path, int *value) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        syslog(LOG_ERR, "Failed to open %s: %s", file_path, strerror(errno));
        return -1;
    }

    if (fscanf(file, "%d", value) != 1) {
        syslog(LOG_ERR, "Failed to read from %s: %s", file_path, strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int write_int_to_file(const char *file_path, int value) {
    FILE *file = fopen(file_path, "w");
    if (!file) {
        syslog(LOG_ERR, "Failed to open %s: %s", file_path, strerror(errno));
        return -1;
    }

    if (fprintf(file, "%d", value) < 0) {
        syslog(LOG_ERR, "Failed to write to %s: %s", file_path, strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

void log_fan_state_change(int new_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline

    fprintf(log_file, "[%s] Fan state changed to: %d\n", time_str, new_state);
    fclose(log_file);
}

int main() {
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    int max_state = 0;
    int current_state = 0;
    int new_state = 0;
    int cpu_temp = 0;

    if (read_int_from_file(FAN_MAX_STATE_FILE, &max_state) != 0) {
        syslog(LOG_ERR, "Failed to read max_state");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (read_int_from_file(TEMP_FILE, &cpu_temp) != 0) {
            syslog(LOG_ERR, "Failed to read CPU temperature");
            sleep(RETRY_DELAY);
            continue;
        }

        cpu_temp /= 1000;  // Convert from millidegrees to degrees

        if (cpu_temp < 45) {
            new_state = 0;
        } else if (cpu_temp < 55) {
            new_state = 1;
        } else if (cpu_temp < 65) {
            new_state = 2;
        } else {
            new_state = 3;
        }

        if (new_state != current_state) {
            if (new_state > max_state) {
                syslog(LOG_WARNING, "Requested state %d exceeds max state %d", new_state, max_state);
                new_state = max_state;
            }

            if (write_int_to_file(FAN_STATE_FILE, new_state) == 0) {
                current_state = new_state;
                log_fan_state_change(new_state);
            }
        }

        sleep(POLL_INTERVAL);
    }

    // Graceful shutdown
    if (write_int_to_file(FAN_STATE_FILE, 0) == 0) {
        log_fan_state_change(0);
        syslog(LOG_INFO, "Fan set to state 0 during shutdown");
    }

    closelog();
    return 0;
}

