#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TARGET_TEMP 50.0
#define PWM_FREQ 1000
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 500000
#define SPI_MIN_SPEED_HZ 50000
#define SPI_CS_PIN 8
#define SPI_DO_PIN 9
#define SPI_CLK_PIN 11
#define PWM_PIN 18
#define LOG_FILE "heater_log.txt"

#define MAX31855_CONFIG_REG 0x00
#define MAX31855_RTDMSB_REG 0x01
#define MAX31855_RTDLSB_REG 0x02
#define MAX31855_HFAULTMSB_REG 0x03
#define MAX31855_HFAULTLSB_REG 0x04
#define MAX31855_LFAULTMSB_REG 0x05
#define MAX31855_LFAULTLSB_REG 0x06
#define MAX31855_FAULTSTAT_REG 0x07

#define FAULT_OPEN_CIRCUIT 0x01
#define FAULT_SHORT_TO_GND 0x02
#define FAULT_SHORT_TO_VCC 0x04

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double prev_error;
} PIDController;

static volatile int keep_running = 1;
static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *pwm_line;
static FILE *log_file;
static PIDController pid = {1.0, 0.1, 0.01, 0.0, 0.0};

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

double read_temperature() {
    unsigned char tx[3] = {MAX31855_RTDMSB_REG, 0, 0};
    unsigned char rx[3];
    unsigned int rtd_msb, rtd_lsb;
    double temperature;

    if (spi_transfer(tx, rx, 3) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    rtd_msb = rx[1];
    rtd_lsb = rx[2] >> 1;

    temperature = ((rtd_msb << 8) | rtd_lsb) * 0.25;

    // Check fault bits
    tx[0] = MAX31855_FAULTSTAT_REG;
    if (spi_transfer(tx, rx, 2) < 0) {
        perror("SPI transfer for fault check failed");
        return -1;
    }

    unsigned char fault = rx[1];
    if (fault & FAULT_OPEN_CIRCUIT) {
        fprintf(log_file, "Error: Open circuit detected\n");
    } else if (fault & FAULT_SHORT_TO_GND) {
        fprintf(log_file, "Error: Short to GND detected\n");
    } else if (fault & FAULT_SHORT_TO_VCC) {
        fprintf(log_file, "Error: Short to VCC detected\n");
    }

    return temperature;
}

void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    unsigned int period = 1000000 / PWM_FREQ;
    unsigned int on_time = (period * duty_cycle) / 100;

    gpiod_line_set_value(pwm_line, 1);
    usleep(on_time);
    gpiod_line_set_value(pwm_line, 0);
    usleep(period - on_time);
}

double pid_compute(double setpoint, double measured_value) {
    double error = setpoint - measured_value;
    pid.integral += error;
    double derivative = error - pid.prev_error;
    pid.prev_error = error;

    return pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Cannot open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI configuration failed");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Cannot open GPIO chip");
        close(spi_fd);
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Cannot get PWM line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "heater_pwm", 0) < 0) {
        perror("Cannot request PWM line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Cannot open log file");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    time_t last_log_time = time(NULL);

    while (keep_running) {
        double temperature = read_temperature();
        if (temperature < 0 || temperature > 100) {
            fprintf(log_file, "Error: Temperature out of range: %.2f°C\n", temperature);
            set_pwm_duty_cycle(0);
            pid.integral = 0;
            pid.prev_error = 0;
        } else {
            double pid_output = pid_compute(TARGET_TEMP, temperature);
            int duty_cycle = (int)(pid_output + 50);  // Convert to 0-100 range

            set_pwm_duty_cycle(duty_cycle);

            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 1) {
                fprintf(log_file, "%.2f, %d, %.2f\n", temperature, duty_cycle, pid_output);
                fflush(log_file);
                last_log_time = current_time;
            }
        }

        usleep(10000);  // 10ms delay
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

