#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <sys/sysinfo.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0
#define MAX_DUTY 100
#define LOG_FILE "cooling_log.csv"
#define READ_INTERVAL 5

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

double get_cpu_temperature() {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    double temp;
    if (fscanf(fp, "%lf", &temp) != 1) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp / 1000.0;
}

int map_temperature_to_duty(double temp) {
    if (temp <= MIN_TEMP) return MIN_DUTY;
    if (temp >= MAX_TEMP) return MAX_DUTY;
    return (int)((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "pwm-fan", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Failed to set initial GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),Duty Cycle (%%)\n");

    while (1) {
        double temp = get_cpu_temperature();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature\n");
            sleep(READ_INTERVAL);
            continue;
        }

        int duty = map_temperature_to_duty(temp);
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.1f,%d\n", timestamp, temp, duty);
        fflush(log_file);

        ret = gpiod_line_set_value(line, duty > 0 ? 1 : 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line value\n");
        }

        sleep(READ_INTERVAL);
    }

    return EXIT_SUCCESS;
}

