#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x0D
#define SENSOR2_ADDR 0x0E
#define MAX_RETRIES 3

int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int addr, uint8_t *buffer) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, &addr, 1) != 1) {
            perror("Failed to write to sensor");
            retries++;
            continue;
        }

        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from sensor");
            retries++;
            continue;
        }

        if (calculate_crc8(buffer, 2) == buffer[2]) {
            return 0;
        } else {
            fprintf(stderr, "CRC check failed for sensor %02X\n", addr);
            retries++;
        }
    }
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR1_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR2_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buffer[3];
    time_t last_log_time = 0;

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;

            if (read_sensor(SENSOR1_ADDR, buffer) == 0 &&
                read_sensor(SENSOR2_ADDR, buffer + 3) == 0) {
