                        (buffer[0] << 8) | buffer[1],
                        (buffer[3] << 8) | buffer[4]);
                fflush(log_file);
            }
        }

        usleep(100000);  // Sleep for 100ms to reduce CPU usage
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}
