#define CHANNEL_A_PIN 17
#define CHANNEL_B_PIN 18
#define NUM_PULSES 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line_a, *line_b;
static FILE *log_file;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    line_a = gpiod_chip_get_line(chip, CHANNEL_A_PIN);
    line_b = gpiod_chip_get_line(chip, CHANNEL_B_PIN);

    if (!line_a || !line_b) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_request_input(line_a, "encoder_a", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    gpiod_line_request_input(line_b, "encoder_b", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);

    return 0;
}

void cleanup_gpio() {
    if (line_a) gpiod_line_release(line_a);
    if (line_b) gpiod_line_release(line_b);
    if (chip) gpiod_chip_close(chip);
}

int init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

void log_position(double position) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline
    fprintf(log_file, "[%s] Position: %.2f degrees\n", time_str, position);
    fflush(log_file);
}

void cleanup_log_file() {
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    if (init_gpio() < 0 || init_log_file() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int state = 0;
    int position = 0;
    double normalized_position = 0.0;

    while (keep_running) {
        int a = gpiod_line_get_value(line_a);
        int b = gpiod_line_get_value(line_b);

        state = (state << 2) | (a << 1) | b;

        switch (state) {
            case 0b0000:
            case 0b1111:
                break;
            case 0b0001:
            case 0b0111:
                position++;
                break;
            case 0b0011:
            case 0b0101:
                position--;
                break;
            case 0b0110:
            case 0b1000:
                position++;
                break;
            case 0b1001:
            case 0b1110:
                position--;
                break;
            default:
                fprintf(stderr, "Unexpected state: %04b\n", state);
        }

        state &= 0b11;  // Keep only the last 2 bits

        if (position >= NUM_PULSES) {
            position -= NUM_PULSES;
        } else if (position < 0) {
            position += NUM_PULSES;
        }

        normalized_position = (double)position / NUM_PULSES * 360.0;

        if (position != 0) {
            log_position(normalized_position);
            position = 0;
        }
    }

    cleanup_gpio();
    cleanup_log_file();
    return EXIT_SUCCESS;
}

