#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define ADPD144RI_ADDR 0x3C
#define SAMPLE_INTERVAL_MS 100
#define IR_THRESHOLD 2000
#define LED_GPIO_PIN 17

static int i2c_fd;
static FILE *log_file;
static struct gpiod_line *led_line;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int read_sensor(int16_t *red, int16_t *ir) {
    uint8_t buf[4];
    if (i2c_read(i2c_fd, 0x00, buf) != 1 ||
        i2c_read(i2c_fd, 0x01, buf + 1) != 1 ||
        i2c_read(i2c_fd, 0x02, buf + 2) != 1 ||
        i2c_read(i2c_fd, 0x03, buf + 3) != 1) {
        return -1;
    }
    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];
    return 0;
}

int main() {
    struct timespec ts;
    int16_t red, ir;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return 1;
    }

    // Open I2C bus
    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }
    fprintf(log_file, "timestamp,red,ir\n");

    // Set up GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "ADPD144RI_LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        if (read_sensor(&red, &ir) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
            fflush(log_file);

            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }

        ts.tv_sec = SAMPLE_INTERVAL_MS / 1000;
        ts.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

