#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <errno.h>
#include <unistd.h>

#define GPIO_PIN 18
#define PULSE_TIMEOUT_MS 1000
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void *pulse_counter(void *arg) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = PULSE_TIMEOUT_MS * 1000000;

    while (keep_running) {
        int result = gpiod_line_event_wait(line, &ts);
        if (result > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) == 0 && event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pthread_mutex_lock(&pulse_mutex);
                pulse_count++;
                pthread_mutex_unlock(&pulse_mutex);
            }
        }
    }
    return NULL;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "MLX90254_PULSE") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    pthread_t counter_thread;
    if (pthread_create(&counter_thread, NULL, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to create pulse counter thread\n");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (count > 0) ? (count * 60.0) : 0.0;

        time_t now;
        time(&now);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

        fprintf(log_file, "[%s] %.2f RPM\n", timestamp, rpm);
        fflush(log_file);
    }

    pthread_cancel(counter_thread);
    pthread_join(counter_thread, NULL);

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
