#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_OUT 17
#define GPIO_PIN_GAIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000 // 10 ms

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line_out;
static struct gpiod_line *line_gain;
static FILE *log_file;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(int level) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s LEVEL\n", timestamp);
    fflush(log_file);
}

int main() {
    int ret;
    int last_state = 0;
    int current_state;

    printf("Starting audio sampling program...\n");

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line_out = gpiod_chip_get_line(chip, GPIO_PIN_OUT);
    if (!line_out) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN_OUT);
        goto cleanup;
    }

    line_gain = gpiod_chip_get_line(chip, GPIO_PIN_GAIN);
    if (!line_gain) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN_GAIN);
        goto cleanup;
    }

    // Configure GPIO lines
    ret = gpiod_line_request_input(line_out, "audio_in");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d\n", GPIO_PIN_OUT);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_gain, "gain_select", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output on GPIO %d\n", GPIO_PIN_GAIN);
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        current_state = gpiod_line_get_value(line_out);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN_OUT);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            log_event(1);
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line_out) {
        gpiod_line_release(line_out);
    }
    if (line_gain) {
        gpiod_line_release(line_gain);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

