#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x39
#define MEASUREMENT_INTERVAL_MS 1000
#define LOG_FILE "flow_log.csv"

static int i2cHandle;
static FILE *logFile;

void signalHandler(int signo) {
    if (signo == SIGINT) {
        fprintf(stderr, "SIGINT received. Cleaning up...\n");
        if (i2cHandle >= 0) {
            i2cClose(i2cHandle);
        }
        if (logFile) {
            fflush(logFile);
            fclose(logFile);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

uint8_t calculateCRC8(const uint8_t *data, int len) {
    const uint8_t POLYNOMIAL = 0x31;
    uint8_t crc = 0;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int readFlowSensor(uint16_t *flow_rate) {
    uint8_t buffer[3];
    int bytesRead;

    bytesRead = i2cReadI2CBlock(i2cHandle, SENSOR_ADDR, buffer, 3);
    if (bytesRead != 3) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    uint8_t received_crc = buffer[2];
    uint8_t calculated_crc = calculateCRC8(buffer, 2);

    if (received_crc != calculated_crc) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *flow_rate = raw_value;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);

    time_t lastLogTime = 0;
    uint16_t flow_rate;

    while (1) {
        if (readFlowSensor(&flow_rate) == 0) {
            time_t now = time(NULL);
            if (now - lastLogTime >= 1) {
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(logFile, "%s,%u\n", timestamp, flow_rate);
                fflush(logFile);
                lastLogTime = now;
            }
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

