    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C read register error");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read value error");
        return -1;
    }
    return 0;
}

int read_sensor_data(uint16_t *tvoc, uint16_t *eco2) {
    uint8_t buf[8];
    if (i2c_read(i2c_fd, 0x20, buf) != 0) return -1;
    if (i2c_read(i2c_fd, 0x21, buf + 1) != 0) return -1;
    *tvoc = (buf[0] << 8) | buf[1];

    if (i2c_read(i2c_fd, 0x22, buf) != 0) return -1;
    if (i2c_read(i2c_fd, 0x23, buf + 1) != 0) return -1;
    *eco2 = (buf[0] << 8) | buf[1];

    return 0;
}

int compute_iaq_index(uint16_t tvoc, uint16_t eco2, uint16_t *iaq_index) {
    // Simplified IAQ index calculation
    *iaq_index = (tvoc / 100) + (eco2 / 100);
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MICS_VZ_89TE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,IAQ Index,TVOC (ppb),eCO2 (ppm)\n");

    while (1) {
        uint16_t tvoc, eco2, iaq_index;
        time_t now;
        struct tm *tm_info;
        char timestamp[20];

        if (read_sensor_data(&tvoc, &eco2) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            sleep(1);
            continue;
        }

        if (compute_iaq_index(tvoc, eco2, &iaq_index) != 0) {
            fprintf(stderr, "Failed to compute IAQ index\n");
            sleep(1);
            continue;
        }

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%u,%u,%u\n", timestamp, iaq_index, tvoc, eco2);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

