#define GPIO_PIN 17
#define ALERT_THRESHOLD 5 // seconds
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec last_high_time, current_time;
    int last_state = 0;
    int high_duration = 0;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    int ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        goto cleanup_line;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            goto cleanup_line;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (current_state == 1) {
            if (last_state == 0) {
                // Sensor just went high
                last_high_time = current_time;
            } else {
                // Calculate duration in seconds
                high_duration = current_time.tv_sec - last_high_time.tv_sec;
                if (high_duration >= ALERT_THRESHOLD) {
                    printf("Intrusion alert: TTP223B sensor held HIGH for %d seconds\n", high_duration);
                }
            }
        } else {
            // Sensor went low, reset the timer
            high_duration = 0;
        }

        last_state = current_state;

        // Sleep for poll interval
        struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
        nanosleep(&sleep_time, NULL);
    }

cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

