#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 17
#define RAW_FILE "audio_capture.pcm"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        terminate = 1;
    }
}

int main() {
    int fd, gpio_fd, ret;
    snd_pcm_t *capture_handle;
    snd_pcm_hw_params_t *params;
    unsigned int val;
    int dir;
    int16_t buffer[BUFFER_SIZE];
    FILE *file;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open ALSA device
    ret = snd_pcm_open(&capture_handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (ret < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(ret));
        return EXIT_FAILURE;
    }

    // Allocate and fill hardware parameters
    snd_pcm_hw_params_alloca(&params);
    ret = snd_pcm_hw_params_any(capture_handle, params);
    if (ret < 0) {
        fprintf(stderr, "Error setting PCM parameters: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    ret = snd_pcm_hw_params_set_access(capture_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (ret < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    ret = snd_pcm_hw_params_set_format(capture_handle, params, SND_PCM_FORMAT_S16_LE);
    if (ret < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    unsigned int rate = 44100;
    ret = snd_pcm_hw_params_set_rate_near(capture_handle, params, &rate, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    unsigned int channels = 2;
    ret = snd_pcm_hw_params_set_channels(capture_handle, params, channels);
    if (ret < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    ret = snd_pcm_hw_params(capture_handle, params);
    if (ret < 0) {
        fprintf(stderr, "Error setting PCM parameters: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    // Open GPIO chip
    gpio_fd = gpiod_chip_open(GPIO_CHIP);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        goto cleanup;
    }

    // Get line and request it
    struct gpiod_line *line = gpiod_chip_get_line(gpio_fd, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line, "audio_capture", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        goto cleanup;
    }

    // Open raw file for writing
    file = fopen(RAW_FILE, "wb");
    if (!file) {
        perror("Error opening raw file");
        gpiod_line_release(line);
        goto cleanup;
    }

    // Start capture
    ret = snd_pcm_prepare(capture_handle);
    if (ret < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(ret));
        goto cleanup;
    }

    printf("Capturing audio. Press Ctrl+C to stop.\n");

    while (!terminate) {
        ret = snd_pcm_readi(capture_handle, buffer, BUFFER_SIZE / 2);
        if (ret != BUFFER_SIZE / 2) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(ret));
            break;
        }

        // Write left channel samples to file
        size_t written = fwrite(buffer, sizeof(int16_t), BUFFER_SIZE / 2, file);
        if (written != BUFFER_SIZE / 2) {
            perror("Error writing to raw file");
            break;
        }

        // Toggle GPIO to select right channel
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        usleep(1000); // Small delay

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (capture_handle) {
        snd_pcm_drain(capture_handle);
        snd_pcm_close(capture_handle);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }

    return EXIT_SUCCESS;
}

