#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spidev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_PERIOD_MS 100
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"
#define MAGIC_NUMBER 4144

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
} ConfigStruct;

static int spi_fd;
static int gpio_chip;
static struct gpiod_line *frame_trigger_line;
static struct gpiod_line *data_ready_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    frame_trigger_line = gpiod_chip_get_line(gpio_chip, FRAME_TRIGGER_PIN);
    data_ready_line = gpiod_chip_get_line(gpio_chip, DATA_READY_PIN);

    if (!frame_trigger_line || !data_ready_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(frame_trigger_line, "frame_trigger", 0) < 0 ||
        gpiod_line_request_input(data_ready_line, "data_ready") < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int setup_logging() {
    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    ConfigStruct config = {770000000, 790000000, 64, 256};
    if (fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, log_file) != 1 ||
        fwrite(&config, sizeof(ConfigStruct), 1, log_file) != 1) {
        perror("Failed to write log header");
        fclose(log_file);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (data_ready_line) gpiod_line_release(data_ready_line);
    if (frame_trigger_line) gpiod_line_release(frame_trigger_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_spi() < 0 || setup_gpio() < 0 || setup_logging() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint64_t frame_number = 0;
    struct timespec start_time, end_time;
    uint8_t buffer[FRAME_SIZE];

    while (!terminate) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        gpiod_line_set_value(frame_trigger_line, 1);
        usleep(10);  // Short pulse
        gpiod_line_set_value(frame_trigger_line, 0);

        while (gpiod_line_get_value(data_ready_line) == 0) {
            usleep(100);
        }

        struct spi_ioc_transfer xfer = {
            .tx_buf = (unsigned long)buffer,
            .rx_buf = (unsigned long)buffer,
            .len = FRAME_SIZE,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("SPI transfer failed");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        uint64_t timestamp = (end_time.tv_sec * 1000000000 + end_time.tv_nsec) -
                             (start_time.tv_sec * 1000000000 + start_time.tv_nsec);

        if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1 ||
            fwrite(&frame_number, sizeof(uint64_t), 1, log_file) != 1 ||
            fwrite(buffer, FRAME_SIZE, 1, log_file) != 1) {
            perror("Failed to write frame data");
            break;
        }

        frame_number++;

        struct timespec sleep_time;
        sleep_time.tv_sec = FRAME_PERIOD_MS / 1000;
        sleep_time.tv_nsec = (FRAME_PERIOD_MS % 1000) * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

