#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00
#define I2C_RETRIES 3
#define RETRY_DELAY_MS 100

static int i2c_fd;
static FILE *file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (file) {
        fclose(file);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return write(fd, buf, 3);
}

int read_i2c(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t config = 0xC610; // Continuous conversion, auto full-scale range
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write_i2c(i2c_fd, OPT3001_CONFIG_REG, config) == 3) {
            break;
        }
        if (i == I2C_RETRIES - 1) {
            fprintf(stderr, "Failed to configure OPT3001\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }

    file = fopen("light_data.txt", "a");
    if (!file) {
        perror("Failed to open output file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t result;
        for (int i = 0; i < I2C_RETRIES; i++) {
            if (read_i2c(i2c_fd, OPT3001_RESULT_REG, &result) == 0) {
                break;
            }
            if (i == I2C_RETRIES - 1) {
                fprintf(stderr, "Failed to read from OPT3001\n");
                sleep(1);
                continue;
            }
            usleep(RETRY_DELAY_MS * 1000);
        }

        float lux = (float)result * 0.01;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(file, "%s %.2f\n", timestamp, lux);
        fflush(file);

        usleep(100000); // 100ms
    }

    return EXIT_SUCCESS;
}

