#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *center_line, *right_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !center_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    ret = gpiod_line_request_input(left_line, "KY-033 Left");
    if (ret < 0) {
        fprintf(stderr, "Failed to request left line as input\n");
        goto cleanup;
    }

    ret = gpiod_line_request_input(center_line, "KY-033 Center");
    if (ret < 0) {
        fprintf(stderr, "Failed to request center line as input\n");
        goto cleanup;
    }

    ret = gpiod_line_request_input(right_line, "KY-033 Right");
    if (ret < 0) {
        fprintf(stderr, "Failed to request right line as input\n");
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read GPIO values\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        usleep(50000);
    }

cleanup:
    if (right_line) gpiod_line_release(right_line);
    if (center_line) gpiod_line_release(center_line);
    if (left_line) gpiod_line_release(left_line);
    if (chip) gpiod_chip_close(chip);

    return (keep_running) ? EXIT_SUCCESS : EXIT_FAILURE;
}

