#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_CHANNELS];
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

void cleanup() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int offsets[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", offsets[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Channel");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as input\n", offsets[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Timestamp\tChannel 1\tChannel 2\tChannel 3\tChannel 4\tChannel 5\tChannel 6\tChannel 7\tChannel 8\n");

    while (keep_running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        printf("%ld.%09ld\t", start.tv_sec, start.tv_nsec);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from channel %d\n", i + 1);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("%d\t\t", value);
        }
        printf("\n");

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns < POLL_INTERVAL_MS * 1000000) {
            nanosleep(&poll_interval, NULL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

