    struct timespec sleep_time = {0, CHECK_INTERVAL_MS * 1000000};
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
