int main() {
    int bcm_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};

    signal(SIGINT, signal_handler);

    gpio_chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

