            cleanup();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Channel");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for BCM pin %d\n", bcm_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
