        clock_gettime(CLOCK_MONOTONIC, &start);

        int values[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Failed to read value from channel %d\n", i);
                cleanup();
                return EXIT_FAILURE;
            }
