#define GPIO_PIN 4
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int last_state = -1;
    int current_state;

    printf("Omron D7E-1 Tilt Sensor Monitoring\n");
    printf("--------------------------------\n");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "D7E-1-Tilt-Sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            cleanup(SIGINT);
        }

        if (current_state != last_state) {
            fflush(stdout);
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

