#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define LOG_FILE "uv_als_log.csv"

// Si1145 Register addresses
#define SI1145_COMMAND 0x00
#define SI1145_PARAMWR 0x01
#define SI1145_PARAMRD 0x02
#define SI1145_NOP 0xFF
#define SI1145_RESET 0x01
#define SI1145_MEASURE 0x05
#define SI1145_UVINDEX0 0x2A
#define SI1145_ALS_VISIBLE0 0x22

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int si1145_init() {
    if (i2c_write(i2c_fd, SI1145_COMMAND, SI1145_RESET) != 1) return -1;
    usleep(10000); // Wait for reset

    uint8_t param = 0x00;
    if (i2c_write(i2c_fd, SI1145_PARAMWR, 0x11) != 1 ||
        i2c_read(i2c_fd, SI1145_PARAMRD, &param) != 1 ||
        param != 0x00) return -1;

    if (i2c_write(i2c_fd, SI1145_COMMAND, SI1145_MEASURE) != 1) return -1;
    return 0;
}

int si1145_read(uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read(i2c_fd, reg, buf) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_write = 0;
    while (1) {
        time_t now = time(NULL);
        if (now - last_write >= 1) {
            uint16_t uv_index, als_visible;
            if (si1145_read(SI1145_UVINDEX0, &uv_index) < 0 ||
                si1145_read(SI1145_ALS_VISIBLE0, &als_visible) < 0) {
                fprintf(stderr, "Failed to read sensor data\n");
            } else {
                printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);
                fprintf(log_file, "%ld,%d,%d\n", (long)now, uv_index, als_visible);
                fflush(log_file);
            }
            last_write = now;
        }
        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    return EXIT_SUCCESS;
}

