    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_write = 0;
    while (1) {
        time_t now = time(NULL);
        if (now - last_write >= 1) {
            uint16_t uv_index, als_visible;
            if (si1145_read(SI1145_UVINDEX0, &uv_index) < 0 ||
                si1145_read(SI1145_ALS_VISIBLE0, &als_visible) < 0) {
                fprintf(stderr, "Failed to read sensor data\n");
            } else {
                printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);
                fprintf(log_file, "%ld,%d,%d\n", (long)now, uv_index, als_visible);
                fflush(log_file);
            }
            last_write = now;
        }
        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    return EXIT_SUCCESS;
}
