#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS_1 0x39
#define SENSOR_ADDRESS_2 0x3A
#define ALARM_PIN 17
#define LOG_FILE "flow_log.txt"
#define MEASUREMENT_INTERVAL 1
#define START_DELAY_MS 100
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float read_sensor(int fd, uint8_t address) {
    uint8_t write_buf[3] = {0x03, 0x00, 0x00};
    uint8_t read_buf[9];
    float flow_rate = -1.0;

    if (write(fd, write_buf, 3) != 3) {
        perror("Failed to write to sensor");
        return flow_rate;
    }

    usleep(START_DELAY_MS * 1000);

    if (read(fd, read_buf, 9) != 9) {
        perror("Failed to read from sensor");
        return flow_rate;
    }

    if (calculate_crc(read_buf, 8) != read_buf[8]) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", address);
        return flow_rate;
    }

    uint32_t flow_raw = (read_buf[3] << 16) | (read_buf[4] << 8) | read_buf[5];
    flow_rate = flow_raw * 0.001; // Convert to ml/min

    return flow_rate;
}

int main() {
    int i2c_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    ret = gpiod_line_request_output(line, "flow_alarm", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDRESS_1) < 0) {
        perror("Failed to set I2C address for sensor 1");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDRESS_2) < 0) {
        perror("Failed to set I2C address for sensor 2");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    time_t last_log_time = 0;

    while (keep_running) {
        float flow_rate_1 = read_sensor(i2c_fd, SENSOR_ADDRESS_1);
        float flow_rate_2 = read_sensor(i2c_fd, SENSOR_ADDRESS_2);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            float avg_flow_rate = -1.0;
            int valid_readings = 0;

            if (flow_rate_1 >= 0) {
                avg_flow_rate += flow_rate_1;
                valid_readings++;
            }
            if (flow_rate_2 >= 0) {
                avg_flow_rate += flow_rate_2;
                valid_readings++;
            }

            if (valid_readings > 0) {
                avg_flow_rate /= valid_readings;
                char log_entry[100];
                snprintf(log_entry, sizeof(log_entry), "%.3f,%.3f,%.3f\n", 
                         difftime(current_time, last_log_time), flow_rate_1, flow_rate_2);
                if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
                    perror("Failed to write to log file");
                }
            }

            if (avg_flow_rate < 0.5) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }

            last_log_time = current_time;
        }

        usleep(MEASUREMENT_INTERVAL * 1000000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(log_fd);

    return 0;
}

