#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50
#define GPIO_PIN 4

typedef struct {
    struct timespec timestamp;
    int detection;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    int last_detection = -1;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "KY-033 Sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        int detection = gpiod_line_get_value(line);
        if (detection < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        if (detection != last_detection) {
            printf("Obstacle detected: %s\n", detection ? "No obstacle" : "Obstacle present");
            last_detection = detection;

            buffer[buffer_index].timestamp = ts;
            buffer[buffer_index].detection = detection;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_index == 0) {
                buffer_full = 1;
            }
        }

        struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
        nanosleep(&sleep_time, NULL);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

