#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D // Example address, replace with actual
#define SENSOR_ACTIVE_TIMEOUT 1000000 // 1 second in microseconds
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds
#define CSV_FILENAME "fan_health.csv"

static int i2c_fd;
static FILE *csv_file;
static int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    int ret;
    do {
        ret = write(fd, buf, len);
    } while (ret == -1 && errno == EINTR);
    return ret;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    int ret;
    do {
        ret = read(fd, buf, len);
    } while (ret == -1 && errno == EINTR);
    return ret;
}

int setup_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line 2\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "SDA", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line 2 as output\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line 3\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "SCL", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line 3 as output\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

int check_sensor_active() {
    uint8_t buf[1];
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    do {
        if (i2c_read(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "Failed to read from sensor\n");
            return 0;
        }
        clock_gettime(CLOCK_MONOTONIC, &current);
    } while ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 < SENSOR_ACTIVE_TIMEOUT);

    return 1;
}

void write_csv_header() {
    fprintf(csv_file, "Timestamp,X,Y,Z\n");
    fflush(csv_file);
}

void poll_sensor() {
    uint8_t buf[6];
    struct timespec ts;
    char timestamp[64];

    while (running) {
        if (i2c_read(i2c_fd, buf, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, buf[0], buf[1], buf[2]);
        fflush(csv_file);

        usleep(SAMPLE_INTERVAL);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILENAME, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ftell(csv_file) == 0) {
        write_csv_header();
    }

    if (!check_sensor_active()) {
        fprintf(stderr, "Sensor did not become active within the timeout period\n");
        fclose(csv_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    poll_sensor();

    fclose(csv_file);
    close(i2c_fd);
    return 0;
}

