#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMAG5170_ADDR 0x30
#define TMAG5170_XOUT 0x01
#define TMAG5170_YOUT 0x03
#define TMAG5170_ZOUT 0x05
#define TMAG5170_CONFIG 0x10
#define TMAG5170_RANGE 0x11
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, len);
}

int main() {
    struct timespec ts;
    uint8_t buf[6];
    int16_t x, y, z;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, TMAG5170_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, TMAG5170_CONFIG, 0x00) < 0 ||
        i2c_write(i2c_fd, TMAG5170_RANGE, 0x03) < 0) {
        fprintf(stderr, "Failed to configure TMAG5170\n");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X (mT),Y (mT),Z (mT)\n");
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(0);
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    if (gpiod_line_request_output(line, "TMAG5170", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup(0);
    }

    while (1) {
        if (i2c_read(i2c_fd, TMAG5170_XOUT, buf, 6) != 6) {
            fprintf(stderr, "Failed to read from TMAG5170\n");
            continue;
        }

        x = (int16_t)((buf[0] << 8) | buf[1]);
        y = (int16_t)((buf[2] << 8) | buf[3]);
        z = (int16_t)((buf[4] << 8) | buf[5]);

        now = time(NULL);
        tm_info = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(log_file);

        ts.tv_sec = SAMPLE_INTERVAL_MS / 1000;
        ts.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

