#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <stdatomic.h>
#include <gpiod.h>

#define PIN 4
#define LOG_FILE "rpm_log.txt"
#define PULSE_COUNT_WINDOW 1000000000 // 1 second in nanoseconds

static atomic_int pulse_count = ATOMIC_VAR_INIT(0);
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int running = 1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    running = 0;
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void pulse_callback(void) {
    atomic_fetch_add(&pulse_count, 1);
}

int main() {
    struct timespec start_time, current_time;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        goto cleanup_chip;
    }

    // Configure GPIO line as input with pull-up
    ret = gpiod_line_request_input(line, "MLX90217_HALL", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        goto cleanup_line;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_line;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (running) {
        atomic_store(&pulse_count, 0);
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for 1 second
        while (running) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if ((current_time.tv_sec - start_time.tv_sec) >= 1) break;
            usleep(10000); // Sleep for 10ms to reduce CPU usage
        }

        if (!running) break;

        // Calculate RPM
        long long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000LL +
                               (current_time.tv_nsec - start_time.tv_nsec);
        int count = atomic_load(&pulse_count);
        double rpm = (count * 60.0) / (elapsed_ns / 1000000000.0);

        // Log RPM
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        char log_entry[50];
        snprintf(log_entry, sizeof(log_entry), "%s %.0f\n", timestamp, rpm);

        printf("%s", log_entry);
        fflush(stdout);

        if (fputs(log_entry, log_file) == EOF) {
            perror("Failed to write to log file");
        }
        fflush(log_file);
    }

cleanup_line:
    if (line) gpiod_line_release(line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

