#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE_NAME "rotation_log.txt"

static volatile int running = 1;
static int quadrature_state = 0;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_a_line = NULL;
static struct gpiod_line *sensor_b_line = NULL;

void signal_handler(int signum) {
    running = 0;
    pthread_cond_signal(&state_cond);
}

void log_rotation(const char *direction) {
    struct timespec ts;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, direction);
    fflush(log_file);
}

void update_quadrature_state(int a_state, int b_state) {
    int new_state = (a_state << 1) | b_state;
    int direction;

    pthread_mutex_lock(&state_mutex);
    direction = (new_state - quadrature_state + 4) % 4;
    quadrature_state = new_state;
    pthread_mutex_unlock(&state_mutex);

    if (direction == 1) {
        log_rotation("Clockwise");
    } else if (direction == 3) {
        log_rotation("Counter-Clockwise");
    }
}

int event_handler(struct gpiod_line *line, int event_type, void *data) {
    int a_state, b_state;

    a_state = gpiod_line_get_value(sensor_a_line);
    b_state = gpiod_line_get_value(sensor_b_line);

    update_quadrature_state(a_state, b_state);

    return 0;
}

int main() {
    struct sigaction sa;
    int ret;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    sensor_a_line = gpiod_chip_get_line(chip, SENSOR_A_PIN);
    if (!sensor_a_line) {
        perror("Failed to get Sensor A line");
        goto cleanup;
    }

    sensor_b_line = gpiod_chip_get_line(chip, SENSOR_B_PIN);
    if (!sensor_b_line) {
        perror("Failed to get Sensor B line");
        goto cleanup;
    }

    ret = gpiod_line_request_input(sensor_a_line, "MLX90217_Sensor_A");
    if (ret < 0) {
        perror("Failed to request Sensor A line as input");
        goto cleanup;
    }

    ret = gpiod_line_request_input(sensor_b_line, "MLX90217_Sensor_B");
    if (ret < 0) {
        perror("Failed to request Sensor B line as input");
        goto cleanup;
    }

    ret = gpiod_line_event_loop(sensor_a_line, event_handler, NULL);
    if (ret < 0) {
        perror("Failed to start event loop for Sensor A");
        goto cleanup;
    }

    ret = gpiod_line_event_loop(sensor_b_line, event_handler, NULL);
    if (ret < 0) {
        perror("Failed to start event loop for Sensor B");
        goto cleanup;
    }

    while (running) {
        pthread_mutex_lock(&state_mutex);
        pthread_cond_wait(&state_cond, &state_mutex);
        pthread_mutex_unlock(&state_mutex);
    }

cleanup:
    if (sensor_a_line) {
        gpiod_line_release(sensor_a_line);
    }
    if (sensor_b_line) {
        gpiod_line_release(sensor_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

