#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main() {
    int ret;

    openlog("ttp223b_led", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting TTP223B LED program");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        syslog(LOG_ERR, "Failed to get sensor line");
        goto cleanup_chip;
    }

    ret = gpiod_line_request_input(sensor_line, "TTP223B_Sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request sensor line as input");
        goto cleanup_sensor;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line");
        goto cleanup_sensor;
    }

    ret = gpiod_line_request_output(led_line, "TTP223B_LED", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output");
        goto cleanup_led;
    }

    while (keep_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            syslog(LOG_ERR, "Failed to read sensor value");
        } else {
            gpiod_line_set_value(led_line, sensor_value);
            if (sensor_value) {
                syslog(LOG_INFO, "Sensor touched");
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down TTP223B LED program");

cleanup_led:
    gpiod_line_release(led_line);
cleanup_sensor:
    gpiod_line_release(sensor_line);
cleanup_chip:
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

