#include <gpiod.h>
#include <unistd.h>

#define BUFFER_SIZE 100
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22
#define DEBOUNCE_DELAY_MS 50

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;
int running = 1;

struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *led1_line, *led2_line;

void log_event(int sensor_pin, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;
    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_index == 0) overflow_count++;
}

void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor: %d, Time: %ld, State: %d\n",
               log_buffer[i].sensor_pin,
               log_buffer[i].timestamp,
               log_buffer[i].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

void cleanup() {
    if (led1_line) gpiod_line_release(led1_line);
    if (led2_line) gpiod_line_release(led2_line);
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (chip) gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led1_line = gpiod_chip_get_line(chip, LED1_PIN);
    led2_line = gpiod_chip_get_line(chip, LED2_PIN);

    if (!sensor1_line || !sensor2_line || !led1_line || !led2_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") < 0 ||
        gpiod_line_request_output(led1_line, "led1", 0) < 0 ||
        gpiod_line_request_output(led2_line, "led2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return 1;
    }

    int sensor1_state = 0, sensor2_state = 0;

    while (running) {
        int new_sensor1_state = gpiod_line_get_value(sensor1_line);
        int new_sensor2_state = gpiod_line_get_value(sensor2_line);

        if (new_sensor1_state != sensor1_state) {
            log_event(SENSOR1_PIN, new_sensor1_state);
            gpiod_line_set_value(led1_line, new_sensor1_state);
            sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != sensor2_state) {
            log_event(SENSOR2_PIN, new_sensor2_state);
            gpiod_line_set_value(led2_line, new_sensor2_state);
            sensor2_state = new_sensor2_state;
        }

        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    print_log_buffer();
    cleanup();
    return 0;
}

