#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define PIN 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_MS 500

static int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "raindrop_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input\n", PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 1; // Assume no rain initially

    while (keep_running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", PIN);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

