#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define I2C_BUS 1
#define I2C_ADDR 0x51
#define LOG_FILE "biometric_log.txt"

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nCtrl-C pressed. Exiting...\n");
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int si1182_init() {
    uint8_t init_cmd = 0x11; // Example command to initialize Si1182
    if (i2c_write(i2c_fd, &init_cmd, 1) < 0) {
        return -1;
    }
    return 0;
}

int si1182_read_heart_rate_spo2(uint16_t *heart_rate, uint8_t *spo2) {
    uint8_t cmd = 0xAA; // Example command to read heart rate and SpO2
    uint8_t data[3];

    if (i2c_write(i2c_fd, &cmd, 1) < 0) {
        return -1;
    }

    if (i2c_read(i2c_fd, data, sizeof(data)) < 0) {
        return -1;
    }

    *heart_rate = (data[0] << 8) | data[1];
    *spo2 = data[2];
    return 0;
}

int main() {
    char filename[256];
    struct timespec ts;
    struct tm *tm_info;
    char time_str[64];
    uint16_t heart_rate;
    uint8_t spo2;

    openlog("biometric_logger", LOG_PID, LOG_USER);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        closelog();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (si1182_init() < 0) {
        fprintf(stderr, "Failed to initialize Si1182\n");
        close(i2c_fd);
        closelog();
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        closelog();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);

    while (1) {
        if (si1182_read_heart_rate_spo2(&heart_rate, &spo2) < 0) {
            fprintf(stderr, "Failed to read heart rate and SpO2\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", time_str, heart_rate, spo2);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();
    return 0;
}

