#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27
#define ALARM_DURATION 2000 // 2 seconds in milliseconds
#define POLL_INTERVAL 100 // 100 ms in milliseconds
#define LOG_FILE "bridge_integrity.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1, *sensor2, *alarm;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file);
}

void activate_alarm() {
    gpiod_line_set_value(alarm, 1);
    log_event("Alarm activated");
}

void deactivate_alarm() {
    gpiod_line_set_value(alarm, 0);
    log_event("Alarm deactivated");
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    alarm = gpiod_chip_get_line(chip, ALARM_PIN);

    if (!sensor1 || !sensor2 || !alarm) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2, "sensor2") < 0 ||
        gpiod_line_request_output(alarm, "alarm", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int sensor1_state = 0, sensor2_state = 0;
    int sensor1_high_time = 0, sensor2_high_time = 0;
    time_t last_check_time = time(NULL);

    while (keep_running) {
        int current_sensor1_state = gpiod_line_get_value(sensor1);
        int current_sensor2_state = gpiod_line_get_value(sensor2);

        if (current_sensor1_state != sensor1_state) {
            sensor1_state = current_sensor1_state;
            if (sensor1_state) {
                log_event("Sensor 1 tilt-start");
                sensor1_high_time = 0;
            } else {
                log_event("Sensor 1 tilt-end");
            }
        }

        if (current_sensor2_state != sensor2_state) {
            sensor2_state = current_sensor2_state;
            if (sensor2_state) {
                log_event("Sensor 2 tilt-start");
                sensor2_high_time = 0;
            } else {
                log_event("Sensor 2 tilt-end");
            }
        }

        time_t current_time = time(NULL);
        int elapsed_time = difftime(current_time, last_check_time) * 1000;
        last_check_time = current_time;

        if (sensor1_state) sensor1_high_time += elapsed_time;
        if (sensor2_state) sensor2_high_time += elapsed_time;

        if (sensor1_high_time >= ALARM_DURATION || sensor2_high_time >= ALARM_DURATION) {
            activate_alarm();
        } else if (!sensor1_state && !sensor2_state) {
            deactivate_alarm();
            sensor1_high_time = 0;
            sensor2_high_time = 0;
        }

        usleep(POLL_INTERVAL * 1000);
    }

    deactivate_alarm();
    fclose(log_file);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

