#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>
#include <syslog.h>

#define SENSOR_ADDR 0x1D
#define SENSOR_I2C_BUS 1
#define SENSOR_SDA_PIN 2
#define SENSOR_SCL_PIN 3
#define ALERT_LED_PIN 17
#define VIBRATION_THRESHOLD 500
#define RETRY_COUNT 3
#define POLL_INTERVAL_MS 100

static int i2c_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *alert_led;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    syslog(LOG_INFO, "Program terminated.");
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        i2c_handle = i2cOpen(SENSOR_I2C_BUS, SENSOR_ADDR, 0);
        if (i2c_handle >= 0) {
            return i2c_handle;
        }
        retries++;
        syslog(LOG_WARNING, "I2C initialization failed, retrying... (%d/%d)", retries, RETRY_COUNT);
        usleep(500000); // 500ms
    }
    syslog(LOG_ERR, "Failed to initialize I2c after %d attempts.", RETRY_COUNT);
    return -1;
}

int init_sensor() {
    unsigned char ctrl1;
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (i2cReadByteData(i2c_handle, 0x10, &ctrl1) == 0) {
            ctrl1 &= ~0x20; // Clear power-down bit
            if (i2cWriteByteData(i2c_handle, 0x10, ctrl1) == 0) {
                syslog(LOG_INFO, "Sensor initialized successfully.");
                return 0;
            }
        }
        retries++;
        syslog(LOG_WARNING, "Sensor initialization failed, retrying... (%d/%d)", retries, RETRY_COUNT);
        usleep(500000); // 500ms
    }
    syslog(LOG_ERR, "Failed to initialize sensor after %d attempts.", RETRY_COUNT);
    return -1;
}

int read_vibration_magnitude() {
    unsigned char data[6];
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (i2cReadI2CBlockData(i2c_handle, 0x00, data, 6) == 6) {
            return (data[0] << 8) | data[1];
        }
        retries++;
        syslog(LOG_WARNING, "Failed to read vibration magnitude, retrying... (%d/%d)", retries, RETRY_COUNT);
        usleep(500000); // 500ms
    }
    syslog(LOG_ERR, "Failed to read vibration magnitude after %d attempts.", RETRY_COUNT);
    return -1;
}

void log_event(int magnitude) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s, %d\n", timestamp, magnitude);
    fflush(log_file);
