#define SENSOR_I2C_BUS 1
#define SENSOR_SDA_PIN 2
#define SENSOR_SCL_PIN 3
#define ALERT_LED_PIN 17
#define VIBRATION_THRESHOLD 500
#define RETRY_COUNT 3
#define POLL_INTERVAL_MS 100

static int i2c_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *alert_led;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    syslog(LOG_INFO, "Program terminated.");
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        i2c_handle = i2cOpen(SENSOR_I2C_BUS, SENSOR_ADDR, 0);
        if (i2c_handle >= 0) {
            return i2c_handle;
        }
        retries++;
        syslog(LOG_WARNING, "I2C initialization failed, retrying... (%d/%d)", retries, RETRY_COUNT);
        usleep(500000); // 500ms
    }
    syslog(LOG_ERR, "Failed to initialize I2c after %d attempts.", RETRY_COUNT);
    return -1;
}

int init_sensor() {
    unsigned char ctrl1;
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (i2cReadByteData(i2c_handle, 0x10, &ctrl1) == 0) {
            ctrl1 &= ~0x20; // Clear power-down bit
            if (i2cWriteByteData(i2c_handle, 0x10, ctrl1) == 0) {
                syslog(LOG_INFO, "Sensor initialized successfully.");
                return 0;
            }
        }
        retries++;
        syslog(LOG_WARNING, "Sensor initialization failed, retrying... (%d/%d)", retries, RETRY_COUNT);
        usleep(500000); // 500ms
    }
    syslog(LOG_ERR, "Failed to initialize sensor after %d attempts.", RETRY_COUNT);
    return -1;
}

