static struct gpiod_chip *chip;
static struct gpiod_line *sensors[NUM_SENSORS];
static struct gpiod_line *led;

void cleanup(int signum) {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i]) {
            gpiod_line_release(sensors[i]);
        }
    }
    if (led) {
        gpiod_line_release(led);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int i, ret;
    int sensor_values[NUM_SENSORS];
    int any_sensor_active = 0;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        sensors[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!sensors[i]) {
            fprintf(stderr, "Failed to get line for sensor %d\n", i);
            cleanup(0);
        }
        ret = gpiod_line_request_input(sensors[i], "sensor_input");
        if (ret < 0) {
            fprintf(stderr, "Failed to request input for sensor %d\n", i);
            cleanup(0);
        }
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get line for LED\n");
        cleanup(0);
    }
    ret = gpiod_line_request_output(led, "led_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for LED\n");
        cleanup(0);
    }

    while (1) {
        any_sensor_active = 0;
        for (i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = gpiod_line_get_value(sensors[i]);
            if (sensor_values[i] == 0) {
                any_sensor_active = 1;
                break;
            }
        }
        gpiod_line_set_value(led, any_sensor_active);
        usleep(POLL_INTERVAL_US);
    }

    return EXIT_SUCCESS;
}

