#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME_MS 50
#define POLL_INTERVAL_MS 1000

const int gpio_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
struct gpiod_line *lines[NUM_SENSORS];
volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_message(const char *message) {
    syslog(LOG_USER | LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_USER | LOG_ERR, "%s: %s", message, strerror(errno));
}

int main() {
    struct gpiod_chip *chip;
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec debounce_interval = {0, DEBOUNCE_TIME_MS * 1000000};
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    openlog("flame_monitor", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);
    log_message("Flame monitor started");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            log_error("Failed to get line for GPIO pin");
            goto cleanup;
        }

        int ret = gpiod_line_request_input(lines[i], "flame_sensor");
        if (ret < 0) {
            log_error("Failed to request line as input");
            goto cleanup;
        }
    }

    log_file = fopen("/var/log/flame_events.log", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                log_error("Failed to read GPIO line");
                continue;
            }

            if (value == 0) {
                nanosleep(&debounce_interval, NULL);
                int debounced_value = gpiod_line_get_value(lines[i]);
                if (debounced_value < 0) {
                    log_error("Failed to read GPIO line during debounce");
                    continue;
                }

                if (debounced_value == 0) {
                    now = time(NULL);
                    tm_info = gmtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

                    if (flock(fileno(log_file), LOCK_EX) < 0) {
                        log_error("Failed to lock log file");
                        continue;
                    }

                    fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n",
                            timestamp, i + 1, gpio_pins[i]);
                    fflush(log_file);

                    if (flock(fileno(log_file), LOCK_UN) < 0) {
                        log_error("Failed to unlock log file");
                    }
                }
            }
        }

        nanosleep(&poll_interval, NULL);
    }

    fclose(log_file);

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    log_message("Flame monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}

