#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <stdbool.h>

#define NUM_TOUCH_SENSORS 8
#define POLL_INTERVAL_MS 50

const int touch_pins[NUM_TOUCH_SENSORS] = {5, 6, 13, 19, 26, 12, 16, 20};
struct gpiod_line *lines[NUM_TOUCH_SENSORS];
bool last_states[NUM_TOUCH_SENSORS] = {false};

void cleanup(int gpio_fd) {
    for (int i = 0; i < NUM_TOUCH_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
}

void signal_handler(int signum) {
    printf("\nReceived signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

void log_touch(int index, int pin, bool state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s Sensor %d (BCM GPIO %d) %s\n", timestamp, index, pin, state ? "Touched" : "Released");
}

int main() {
    struct gpiod_chip *chip;
    int gpio_fd;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_chip_get_fd(chip);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error getting GPIO chip file descriptor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_TOUCH_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", touch_pins[i], strerror(errno));
            cleanup(gpio_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Touch");
        if (ret < 0) {
            fprintf(stderr, "Error requesting input for GPIO %d: %s\n", touch_pins[i], strerror(errno));
            cleanup(gpio_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < NUM_TOUCH_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO %d: %s\n", touch_pins[i], strerror(errno));
                cleanup(gpio_fd);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }

            bool current_state = value == 1;
            if (current_state != last_states[i]) {
                log_touch(i, touch_pins[i], current_state);
                last_states[i] = current_state;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup(gpio_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

