    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read lux data");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int map_lux_to_duty_cycle(int lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

