    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(PWM_PIN, PWM_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

