    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(log_file, "%s, Error reading sensor, %d\n", __DATE__, lux);
            fflush(log_file);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int duty_cycle = map_lux_to_duty_cycle(lux);
        if (gpioSetPWMdutycycle(PWM_PIN, duty_cycle * 255 / 100) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s, %d, %d, 0\n", timestamp, lux, duty_cycle);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

