#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define DEBOUNCE_TIME_MS 50
#define LED_PIN 17
#define CHANNEL_PINS[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9}

volatile sig_atomic_t keep_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_CHANNELS + 1];
struct gpiod_line *led_line;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_touch(int channel) {
    FILE *file = fopen("touch_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline

    fprintf(file, "%s – Channel %d Touched\n", time_str, channel);
    fclose(file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, CHANNEL_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for channel %d\n", i + 1);
            goto cleanup;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Channel");
        if (ret < 0) {
            fprintf(stderr, "Failed to request input for channel %d\n", i + 1);
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for LED\n");
        goto cleanup;
    }

    int ret = gpiod_line_request_output(led_line, "TTP226_LED", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for LED\n");
        goto cleanup;
    }

    int last_states[NUM_CHANNELS] = {0};
    int led_on = 0;

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = gpiod_line_get_value(lines[i]);
            if (current_state != last_states[i]) {
                usleep(DEBOUNCE_TIME_MS * 1000);
                current_state = gpiod_line_get_value(lines[i]);
                if (current_state != last_states[i]) {
                    if (current_state == 1) {
                        log_touch(i + 1);
                        if (!led_on) {
                            gpiod_line_set_value(led_line, 1);
                            led_on = 1;
                        }
                    }
                    last_states[i] = current_state;
                }
            }
        }

        if (led_on) {
            int all_released = 1;
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (gpiod_line_get_value(lines[i]) == 1) {
                    all_released = 0;
                    break;
                }
            }
            if (all_released) {
                gpiod_line_set_value(led_line, 0);
                led_on = 0;
            }
        }

        usleep(50000);  // 50ms delay
    }

cleanup:
    gpiod_line_release(led_line);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

