#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <endian.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00
#define I2C_SLAVE_FORCE 0x0706

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return write(fd, buf, sizeof(buf));
}

int read_i2c(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != sizeof(buf)) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t config = htole16(0xC610); // Continuous conversion, 100ms integration time
    if (write_i2c(i2c_fd, OPT3001_CONFIG_REG, config) != 3) {
        perror("Failed to write configuration");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(100000); // Wait 100ms

    log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t result;
        if (read_i2c(i2c_fd, OPT3001_RESULT_REG, &result) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            sleep(1);
            continue;
        }

        float lux = (float)le16toh(result) * 0.01;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        char log_entry[50];
        snprintf(log_entry, sizeof(log_entry), "%s, %.2f\n", timestamp, lux);

        if (fputs(log_entry, log_file) == EOF) {
            fprintf(stderr, "Failed to write to log file\n");
        } else {
            fflush(log_file);
            printf("%s", log_entry);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

