#define GPIO_PIN 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_INTERVAL_MS 50

static struct gpiod_line *line;
static FILE *log_file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void log_touch(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    int last_state = -1;
    int current_state;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "TTP223", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                log_touch("Touch Detected");
            } else {
                log_touch("Touch Released");
            }
            last_state = current_state;
        }

        usleep(DEBOUNCE_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

