#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x0D
#define SENSOR_COMMAND 0x06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(int fd, uint8_t *data, size_t length) {
    if (write(fd, data, length) != length) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, size_t length) {
    if (read(fd, data, length) != length) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int initialize_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("I2C slave address set error");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_sensor_data(float *flow_rate, uint8_t *flags) {
    uint8_t command = SENSOR_COMMAND;
    uint8_t data[3];

    if (i2c_write(i2c_fd, &command, 1) < 0) {
        return -1;
    }

    usleep(2000);  // Wait 2ms

    if (i2c_read(i2c_fd, data, 3) < 0) {
        return -1;
    }

    uint16_t raw_flow = (data[0] << 8) | data[1];
    uint8_t crc = data[2];

    if (calculate_crc8(data, 2) != crc) {
        return -1;
    }

    *flow_rate = (float)raw_flow / 100.0;
    *flags = data[1] & 0x03;  // Assuming flags are in the lower 2 bits of the second byte

    return 0;
}

void log_data(float flow_rate, uint8_t flags) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    char status[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        strcpy(status, "INVALID");
    } else {
        strcpy(status, "OK");
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Log file open error");
            return;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Raw Flags,Status\n");
    }

    fprintf(log_file, "%s,%.2f,%02X,%s\n", timestamp, flow_rate, flags, status);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    while (1) {
        float flow_rate;
        uint8_t flags;

        if (read_sensor_data(&flow_rate, &flags) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            close(i2c_fd);
            if (initialize_i2c() < 0) {
                fprintf(stderr, "Failed to reinitialize I2C\n");
                return EXIT_FAILURE;
            }
            log_data(0, 0);  // Log error
            continue;
        }

        log_data(flow_rate, flags);
        sleep(1);
    }

    return EXIT_SUCCESS;
}

