#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE_NAME "path_log.csv"
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *middle_line, *right_line;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (right_line) gpiod_line_release(right_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (left_line) gpiod_line_release(left_line);
    if (chip) gpiod_chip_close(chip);
}

void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

int main(void) {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct tm *tm_info;
    char timestamp[64];
    int left_value, middle_value, right_value;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_line, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,left,middle,right\n");

    while (true) {
        left_value = gpiod_line_get_value(left_line);
        middle_value = gpiod_line_get_value(middle_line);
        right_value = gpiod_line_get_value(right_line);

        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        nanosleep(&poll_interval, NULL);
    }

    return EXIT_SUCCESS;
}

