#define GPIO_PIN 4
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "flame_events.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    printf("[%s] %s\n", time_str, message);

    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "[%s] %s\n", time_str, message);
        fclose(file);
    }
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_falling_edge(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Flame sensor monitoring started");

    while (keep_running) {
        struct gpiod_line_event event;
        int event_count = gpiod_line_event_wait(line, NULL);

        if (event_count < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        if (event_count > 0) {
            ret = gpiod_line_event_read(line, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading event: %s\n", strerror(errno));
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                log_event("Flame detected!");
            }
        }
    }

    log_event("Flame sensor monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

