#define GPIO_CHIP_PATH "/dev/gpiochip4"
#define TOUCH_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
        touch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct timespec timeout = { .tv_sec = 0, .tv_nsec = POLL_TIMEOUT_MS * 1000000 };
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP_PATH);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        goto cleanup_touch;
    }

    ret = gpiod_line_request_input(touch_line, "touch_input");
    if (ret < 0) {
        fprintf(stderr, "Failed to request touch line as input: %s\n", strerror(errno));
        goto cleanup_led;
    }

    ret = gpiod_line_request_output(led_line, "led_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup_touch;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup_led;
    }

    while (1) {
        enum gpiod_line_event event;
        int value;

        ret = gpiod_line_event_wait(touch_line, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for touch event: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        event = gpiod_line_event_read(touch_line);
        if (event != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        value = gpiod_line_get_value(led_line);
        value = !value;
        ret = gpiod_line_set_value(led_line, value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            break;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s: LED state changed to %s\n", timestamp, value ? "ON" : "OFF");
        fflush(log_file);
    }

    fclose(log_file);
    log_file = NULL;

cleanup_led:
    gpiod_line_release(led_line);
    led_line = NULL;

cleanup_touch:
    gpiod_line_release(touch_line);
    touch_line = NULL;

cleanup_chip:
    gpiod_chip_close(chip);
    chip = NULL;

    return EXIT_FAILURE;
}

