#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define SLICE_DURATION_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t shutdown_requested = 0;

void signal_handler(int signum) {
    shutdown_requested = 1;
}

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    log_message("System started");

    int last_flame_state = 1; // Assume no flame initially
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec slice_duration = {0, SLICE_DURATION_MS * 1000000};

    while (!shutdown_requested) {
        int current_flame_state = gpiod_line_get_value(flame_sensor_line);
        if (current_flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            break;
        }

        if (current_flame_state == 0 && last_flame_state == 1) {
            log_message("FLAME DETECTED");

            for (int i = 0; i < BUZZER_DURATION_MS / SLICE_DURATION_MS; i++) {
                if (shutdown_requested) break;
                gpiod_line_set_value(buzzer_line, 1);
                nanosleep(&slice_duration, NULL);
                gpiod_line_set_value(buzzer_line, 0);
                nanosleep(&slice_duration, NULL);
            }
        }

        last_flame_state = current_flame_state;
        nanosleep(&poll_interval, NULL);
    }

cleanup:
    gpiod_line_release(buzzer_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);
    if (log_file) {
        log_message("System stopped");
        fclose(log_file);
    }

    return shutdown_requested ? EXIT_SUCCESS : EXIT_FAILURE;
}

