}

int main() {
    struct timespec last_touch_time = {0, 0};
    int last_value = 1;  // Assume sensor is not touched initially

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
