        goto cleanup_chip;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line\n");
        goto cleanup_sensor;
    }

    // Configure lines
    if (gpiod_line_request_input(sensor_line, "TTP223B") < 0) {
        fprintf(stderr, "Error requesting sensor line as input\n");
        goto cleanup_led;
    }

