        fprintf(stderr, "Error requesting LED line as output\n");
        goto cleanup_led;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        goto cleanup_led;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        int current_value = gpiod_line_get_value(sensor_line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            continue;
        }

        if (current_value == 0 && last_value == 1) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);

            if ((current_time.tv_sec - last_touch_time.tv_sec) * 1000000 +
                (current_time.tv_nsec - last_touch_time.tv_nsec) >= DEBOUNCE_TIME_US) {

                // Toggle LED
                int led_value = gpiod_line_get_value(led_line);
                if (led_value < 0) {
                    fprintf(stderr, "Error reading LED value\n");
                    continue;
                }

                if (gpiod_line_set_value(led_line, !led_value) < 0) {
                    fprintf(stderr, "Error setting LED value\n");
                    continue;
                }

                // Log timestamp
                char timestamp[64];
                struct tm *tm_info;
                time_t now = time(NULL);
                tm_info = gmtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

                if (fprintf(log_file, "%s\n", timestamp) < 0) {
                    fprintf(stderr, "Warning: Failed to write to log file\n");
                }

                last_touch_time = current_time;
            }
        }

        last_value = current_value;
        usleep(POLL_INTERVAL_US);
    }

cleanup_led:
    gpiod_line_release(led_line);
cleanup_sensor:
    gpiod_line_release(sensor_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

