#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define NUM_SENSORS 3
#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL_MS 100

// GPIO pin numbers for sensors
const int sensor_pins[NUM_SENSORS] = {4, 17, 27};

// File descriptor for the log file
FILE *log_file = NULL;

// GPIOD chip and line structures
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_SENSORS] = {NULL};

// Previous states of the sensors
int previous_states[NUM_SENSORS] = {-1};

// Function prototypes
void setup_gpio(void);
void cleanup_gpio(void);
void log_state_change(int sensor_id, int state);
void signal_handler(int signum);
void poll_sensors(void);

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO
    setup_gpio();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        poll_sensors();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // This point should never be reached
    return 0;
}

void setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for sensor %d\n", i + 1);
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }

        // Request the line as input with pull-up
        ret = gpiod_line_request_input(lines[i], "TMAG5110A1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for sensor %d\n", i + 1);
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio(void) {
    // Release all lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

void log_state_change(int sensor_id, int state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet removed" : "Magnet present");
    fflush(log_file);
}

void signal_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

void poll_sensors(void) {
    int value;

    for (int i = 0; i < NUM_SENSORS; i++) {
        value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor %d\n", i + 1);
            continue;
        }

        // Invert the value because the sensor pulls the line low when a magnet is present
        value = !value;

        // Check for state change
        if (previous_states[i] == -1) {
            // First read, record the initial state
            previous_states[i] = value;
        } else if (previous_states[i] != value) {
            // State changed, log it
            log_state_change(i + 1, value);
            previous_states[i] = value;
        }
    }
}

