#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    int last_value = 1;  // Assume high initially (active-low)
    struct timespec last_event_time = {0, 0};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        cleanup();
        return 1;
    }

    int ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value\n");
            break;
        }

        if (value == 0 && last_value == 1) {
            // Falling edge detected
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);

            // Check if enough time has passed since the last event
            if ((current_time.tv_sec - last_event_time.tv_sec) > 0 ||
                (current_time.tv_nsec - last_event_time.tv_nsec) >= 100000000) {

                printf("FLAME DETECTED\n");
                fprintf(log_file, "FLAME DETECTED at %ld.%09ld\n", 
                        current_time.tv_sec, current_time.tv_nsec);
                fflush(log_file);
                last_event_time = current_time;
            }
        }

        last_value = value;
        nanosleep(&poll_interval, NULL);
    }

    cleanup();
    return 0;
}

