#define STABILIZATION_DELAY_MS 200
#define POLL_INTERVAL_MS 10

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *counter_lines[NUM_CHANNELS];
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (sensor_lines[i]) {
                gpiod_line_release(sensor_lines[i]);
            }
            if (counter_lines[i]) {
                gpiod_line_release(counter_lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, 5 + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_input(sensor_lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Failed to request input for sensor line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        counter_lines[i] = gpiod_chip_get_line(chip, COUNTER_START_PIN + i);
        if (!counter_lines[i]) {
            fprintf(stderr, "Failed to get counter line %d: %s\n", COUNTER_START_PIN + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(counter_lines[i], "counter_output", 0) < 0) {
            fprintf(stderr, "Failed to request output for counter line %d: %s\n", COUNTER_START_PIN + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Failed to open log file: %s\n", strerror(errno));
    }

    usleep(STABILIZATION_DELAY_MS * 1000);

    unsigned char counter = 0;
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value;
            if (gpiod_line_get_value(sensor_lines[i]) < 0) {
                fprintf(stderr, "Error reading sensor line %d: %s\n", 5 + i, strerror(errno));
                continue;
            }
            value = gpiod_line_get_value(sensor_lines[i]);
            if (value == 1) {
                counter = (counter + 1) % 256;
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    int bit_value = (counter >> j) & 1;
                    if (gpiod_line_set_value(counter_lines[j], bit_value) < 0) {
                        fprintf(stderr, "Error setting counter line %d: %s\n", COUNTER_START_PIN + j, strerror(errno));
                    }
                }

                time_t now = time(NULL);
                struct tm tm_info;
                gmtime_r(&now, &tm_info);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

                if (log_file) {
                    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counter);
                    fflush(log_file);
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
        nanosleep(&poll_interval, NULL);
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_set_value(counter_lines[i], 0);
    }

    cleanup();
    return EXIT_SUCCESS;
}

