#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define GPIO_PINS[NUM_SENSORS] = {17, 18, 27, 22}
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_SENSORS];
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PINS[i]);
            return -1;
        }

        int ret = gpiod_line_request_input(lines[i], "KY-033 Sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting input for GPIO line %d\n", GPIO_PINS[i]);
            return -1;
        }
    }

    return 0;
}

void cleanup_gpio() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    return 0;
}

void cleanup_log_file() {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

void write_log(int sensor_values[NUM_SENSORS]) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, "%d", sensor_values[i]);
        if (i < NUM_SENSORS - 1) {
            fprintf(log_file, ",");
        }
    }
    fprintf(log_file, "\n");
    fflush(log_file);
}

int main() {
    if (init_gpio() < 0 || init_log_file() < 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_values[NUM_SENSORS];

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO line %d\n", GPIO_PINS[i]);
                sensor_values[i] = -1;
            } else {
                sensor_values[i] = value;
            }
        }

        write_log(sensor_values);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_log_file();
    cleanup_gpio();
    return 0;
}

