#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_TIME_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (sensor1_line) gpiod_line_release(sensor1_line);
    if (sensor2_line) gpiod_line_release(sensor2_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

void log_tilt_event(int sensor_number) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    int ret;

    // Set up signal handlers
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);

    if (!sensor1_line || !sensor2_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(0);
    }

    // Configure lines as inputs with active-low pull-up
    ret = gpiod_line_request_input(sensor1_line, "tilt_sensor1");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for sensor1\n");
        cleanup(0);
    }

    ret = gpiod_line_request_input(sensor2_line, "tilt_sensor2");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for sensor2\n");
        cleanup(0);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    int last_state1 = 1, last_state2 = 1;
    time_t last_change1 = 0, last_change2 = 0;

    while (1) {
        int state1 = gpiod_line_get_value(sensor1_line);
        int state2 = gpiod_line_get_value(sensor2_line);

        time_t now = time(NULL);

        if (state1 != last_state1 && (now - last_change1) > (DEBOUNCE_TIME_MS / 1000.0)) {
            if (state1 == 0) {
                log_tilt_event(1);
            }
            last_state1 = state1;
            last_change1 = now;
        }

        if (state2 != last_state2 && (now - last_change2) > (DEBOUNCE_TIME_MS / 1000.0)) {
            if (state2 == 0) {
                log_tilt_event(2);
            }
            last_state2 = state2;
            last_change2 = now;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

