        sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            perror("Failed to read sensor values");
            cleanup();
            return 1;
        }

        led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        time_t now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
        fflush(log_file);

        gpiod_line_set_value(led_line, led_state);

        nanosleep(&poll_interval, NULL);
    }

    return 0;
}

