#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_DURATION_MS 100

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        stop_flag = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *mic_line, *led_line;
    int ret;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request lines
    mic_line = gpiod_chip_get_line(chip, MIC_PIN);
    if (!mic_line) {
        fprintf(stderr, "Error getting MIC_PIN line\n");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED_PIN line\n");
        goto cleanup;
    }

    // Configure lines
    ret = gpiod_line_request_input(mic_line, "mic_input");
    if (ret < 0) {
        fprintf(stderr, "Error requesting MIC_PIN as input\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(led_line, "led_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED_PIN as output\n");
        goto cleanup;
    }

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (!stop_flag) {
        int value = gpiod_line_get_value(mic_line);
        if (value < 0) {
            fprintf(stderr, "Error reading MIC_PIN value\n");
            break;
        }

        if (value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            long long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000LL +
                                   (current.tv_nsec - start.tv_nsec) / 1000000LL;
            printf("%lld\n", elapsed_ms);

            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error setting LED_PIN high\n");
                break;
            }

            usleep(LED_DURATION_MS * 1000);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Error setting LED_PIN low\n");
                break;
            }
        }

        usleep(SAMPLE_PERIOD_US * 1000 - 100); // Account for function call overhead
    }

cleanup:
    gpiod_line_release(mic_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

