#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define ALS_COMMAND 0x51
#define ALS_LSB_COMMAND 0x52
#define ALS_MSB_COMMAND 0x53
#define I2C_BUS 1
#define I2C_ADDR 0x60
#define ALS_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_init(int bus, int address) {
    char filename[20];
    int file;

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        close(file);
        return -1;
    }

    return file;
}

int read_i2c_register(int file, uint8_t reg) {
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        return -1;
    }

    uint8_t value;
    if (read(file, &value, 1) != 1) {
        perror("Failed to read from I2C register");
        return -1;
    }

    return value;
}

int main() {
    int i2c_file;
    int als_raw;
    uint8_t als_lsb, als_msb;

    signal(SIGINT, signal_handler);

    i2c_file = i2c_init(I2C_BUS, I2C_ADDR);
    if (i2c_file < 0) {
        fprintf(stderr, "Error initializing I2C\n");
        return EXIT_FAILURE;
    }

    while (keep_running) {
        als_lsb = read_i2c_register(i2c_file, ALS_LSB_COMMAND);
        if (als_lsb == -1) {
            fprintf(stderr, "Error reading ALS LSB\n");
            break;
        }

        als_msb = read_i2c_register(i2c_file, ALS_MSB_COMMAND);
        if (als_msb == -1) {
            fprintf(stderr, "Error reading ALS MSB\n");
            break;
        }

        als_raw = (als_msb << 8) | als_lsb;
        printf("ALS Raw Value: %d\n", als_raw);

        usleep(ALS_INTERVAL_MS * 1000);
    }

    close(i2c_file);
    return EXIT_SUCCESS;
}

