#include <unistd.h>
#include <gpiod.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define DEVICE_PATH "/dev/gpiochip0"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (right_line) gpiod_line_release(right_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (left_line) gpiod_line_release(left_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_line, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Failed to read GPIO lines\n");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

