#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

const int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_CHANNELS];
volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char time_str[20];
    int values[NUM_CHANNELS];
    int i, ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "TTP226");
        if (ret < 0) {
            fprintf(stderr, "Error requesting input for GPIO %d: %s\n", gpio_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (keep_running) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%H:%M:%S", tm_info);
        printf("[%.3lfs] ", (double)ts.tv_sec + (double)ts.tv_nsec / 1e9);

        // Read sensor values
        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error reading value for GPIO %d: %s\n", gpio_pins[i], strerror(-values[i]));
                goto cleanup;
            }
            printf("CH%d=%d ", i + 1, values[i]);
        }
        printf("\n");

        // Wait for next poll interval
        nanosleep(&(struct timespec){0, POLL_INTERVAL_MS * 1000000}, NULL);
    }

cleanup:
    // Release resources
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (i < NUM_CHANNELS || !chip) ? EXIT_FAILURE : EXIT_SUCCESS;
}

