#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define PWM_FREQ 1000
#define STEPS 50
#define DURATION 5
#define RANGE 255

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

void set_pwm(int pin, int value) {
    int ret;
    ret = gpiod_line_set_value(lines[pin], value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set PWM value on GPIO%d", pin);
    }
}

void fade_to_hue(int start_hue, int end_hue) {
    int r, g, b;
    for (int step = 0; step < STEPS; step++) {
        float t = (float)step / STEPS;
        int current_hue = start_hue + (int)((end_hue - start_hue) * t);

        // Convert hue to RGB
        float c = 1.0f;
        float x = c * (1.0f - fabsf(fmodf(current_hue / 60.0f, 2.0f) - 1.0f));
        float m = 0.0f;

        if (current_hue < 60) {
            r = c; g = x; b = 0;
        } else if (current_hue < 120) {
            r = x; g = c; b = 0;
        } else if (current_hue < 180) {
            r = 0; g = c; b = x;
        } else if (current_hue < 240) {
            r = 0; g = x; b = c;
        } else if (current_hue < 300) {
            r = x; g = 0; b = c;
        } else {
            r = c; g = 0; b = x;
        }

        set_pwm(0, (int)((r + m) * RANGE));
        set_pwm(1, (int)((g + m) * RANGE));
        set_pwm(2, (int)((b + m) * RANGE));

        usleep(DURATION * 1000000 / STEPS);
    }
}

int main() {
    int ret;
    struct timespec ts;

    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 17);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %d", i + 17);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "RGB_Fade", 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request GPIO line %d as output", i + 17);
            goto cleanup;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    srand(time(NULL));
    int prev_hue = rand() % 360;

    while (keep_running) {
        int next_hue = rand() % 360;
        fade_to_hue(prev_hue, next_hue);
        prev_hue = next_hue;
    }

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return 0;
}

