#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define PON 0x01
#define AEN 0x02
#define IT_154MS 0xEB

#define GPIO_CHIP "/dev/gpiochip0"
#define LED_PIN 17
#define RED_THRESHOLD 200

static int i2c_fd;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");

    // Power down the sensor
    unsigned char enable = 0x00;
    if (write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to write to sensor");
    }

    // Close I2C file descriptor
    if (close(i2c_fd) != 0) {
        perror("Failed to close I2C file descriptor");
    }

    // Release GPIO line
    if (led_line) {
        gpiod_line_release(led_line);
    }

    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Power on the sensor and enable RGBC
    unsigned char enable = PON | AEN;
    if (write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to enable sensor");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set integration time to 154ms
    unsigned char atime = IT_154MS;
    if (write(i2c_fd, &atime, 1) != 1) {
        perror("Failed to set integration time");
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Get LED GPIO line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Request LED GPIO line
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        unsigned char data[8];
        if (read(i2c_fd, data, 8) != 8) {
            perror("Failed to read from sensor");
            cleanup(0);
            return EXIT_FAILURE;
        }

        unsigned int clear = (data[1] << 8) | data[0];
        unsigned int red = (data[3] << 8) | data[2];
        unsigned int green = (data[5] << 8) | data[4];
        unsigned int blue = (data[7] << 8) | data[6];

        printf("C: %u R: %u G: %u B: %u\n", clear, red, green, blue);

        // Control LED based on red value
        int led_state = (red > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            perror("Failed to set LED state");
        }

        usleep(200000); // 200ms delay
    }

    return EXIT_SUCCESS;
}

