            }
        } else {
            fprintf(stderr, "Failed to read from sensor\n");
        }

        sleep(1);  // Wait before next reading
    }

    // Cleanup
    set_pwm_duty_cycle(pwm_fd, 0);
    close(pwm_fd);
    close(i2c_fd);

    return 0;
}

