#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23 // BH1750 I2C address
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 30 // Example number of LEDs
#define CONVERSION_DELAY_MS 120
#define START_FRAME 0x00000000
#define END_FRAME 0xFFFFFFFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }
    return fd;
}

int spi_init(int bus, int chip_select, int speed) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, speed) < 0) {
        perror("Failed to set SPI parameters");
        close(fd);
        return -1;
    }

    return fd;
}

int read_light_level(int i2c_fd) {
    unsigned char cmd = 0x20; // Continuous high resolution mode
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to send command to BH1750");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void set_led_brightness(int spi_fd, int brightness) {
    uint8_t tx[4 * (NUM_LEDS + 2)];
    uint32_t *frame = (uint32_t *)tx;

    *frame++ = START_FRAME;

    for (int i = 0; i < NUM_LEDS; i++) {
        *frame++ = (brightness << 16) | 0x000000; // Blue, Green, Red set to 0
    }

    *frame = END_FRAME;

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to send SPI message");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT, SPI_SPEED);
    if (spi_fd < 0) {
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int light_level = read_light_level(i2c_fd);
        if (light_level < 0) {
            fprintf(stderr, "Error reading light level\n");
            break;
        }

        int brightness = (int)((float)light_level / 65535.0 * 255.0);
        set_led_brightness(spi_fd, brightness);

        usleep(100000); // 100ms delay between readings
    }

    set_led_brightness(spi_fd, 0); // Turn off all LEDs

    close(spi_fd);
    close(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

