#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define SENSOR_ADDRESSES {0x23, 0x5C}
#define NUM_SENSORS 2
#define SENSOR_READ_DELAY_MS 180
#define APA102_MOSI_PIN 10
#define APA102_SCLK_PIN 11
#define APA102_SPI_SPEED 8000000
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100

static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");

    // Turn off LED strip
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close I2C handles
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            close(i2c_handles[i]);
        }
    }

    // Close SPI handle
    if (spi_handle >= 0) {
        close(spi_handle);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(EXIT_SUCCESS);
}

float read_sensor(int handle) {
    unsigned char tx[2] = {0x20, 0x10}; // Power on, one time high resolution mode
    unsigned char rx[2];

    if (write(handle, tx, 2) != 2) {
        perror("Failed to write to sensor");
        return -1;
    }

    usleep(SENSOR_READ_DELAY_MS * 1000);

    if (read(handle, rx, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }

    return (rx[0] << 8 | rx[1]) / 1.2f; // Convert to lux
}

void fade_led_strip(float target_brightness) {
    unsigned char tx[4];
    unsigned char rx[4];
    struct spi_ioc_transfer spi_xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = APA102_SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    float current_brightness = 0;
    int steps = FADE_DURATION_MS / LOOP_DELAY_MS;

    for (int i = 0; i <= steps; i++) {
        float step_brightness = current_brightness + (target_brightness - current_brightness) * (i / (float)steps);

        tx[0] = 0xE0 | (int)(step_brightness * 31); // Global brightness
        tx[1] = 0x00;
        tx[2] = 0x00;
        tx[3] = 0x00;

        if (ioctl(spi_handle, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            perror("SPI transfer failed");
        }

        current_brightness = step_brightness;
        usleep(LOOP_DELAY_MS * 1000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    // Open I2C bus
    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    int i2c_bus = open(i2c_dev, O_RDWR);
    if (i2c_bus < 0) {
        perror("Failed to open I2C bus");
        cleanup(0);
    }

    // Initialize I2C handles for sensors
    const uint8_t sensor_addresses[] = SENSOR_ADDRESSES;
