#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define WS2812B_PIN 18
#define I2C_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_DELAY_MS 200
#define GAMMA_CORRECTION 2.2
#define MAX_BRIGHTNESS 255

static int i2c_fd;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        int result = write(fd, buf, len);
        if (result == len) return 0;
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }
    fprintf(stderr, "I2C write failed after %d retries\n", I2C_RETRIES);
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        int result = read(fd, buf, len);
        if (result == len) return 0;
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRIES);
    return -1;
}

float read_veml7700_lux() {
    uint8_t buf[2];
    if (i2c_read(i2c_fd, buf, 2) != 0) return -1;
    uint16_t raw = (buf[0] << 8) | buf[1];
    return (float)raw * 0.4;  // VEML7700 sensitivity
}

void set_ws2812b_brightness(uint8_t brightness) {
    gpioWrite(WS2812B_PIN, 0);
    usleep(50);  // Start bit

    for (int i = 0; i < 24; i++) {
        if (brightness & (1 << i)) {
            gpioPWM(WS2812B_PIN, 800);  // 1-bit: 0.8us high, 0.4us low
            usleep(400);
        } else {
            gpioPWM(WS2812B_PIN, 400);  // 0-bit: 0.4us high, 0.8us low
            usleep(800);
        }
    }

    gpioPWM(WS2812B_PIN, 0);  // End bit
    usleep(50);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(WS2812B_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_PIN, 800000);  // 800 kHz

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        float lux = read_veml7700_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux\n");
        } else {
            float gamma_corrected = powf(lux / 100000.0f, GAMMA_CORRECTION);
            uint8_t brightness = (uint8_t)(gamma_corrected * MAX_BRIGHTNESS);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
            set_ws2812b_brightness(brightness);
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    close(i2c_fd);
    gpioTerminate();
    return 0;
}

