#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define LED_PIN 18
#define BUZZER_PIN 17
#define FLAME_SENSOR_PIN 4
#define NUM_STARTUP_READS 5
#define STARTUP_READ_INTERVAL_MS 100
#define MAIN_POLL_INTERVAL_MS 50
#define ERROR_BLINK_INTERVAL_MS 100
#define BUZZER_PATTERN_MS {200, 200, 600, 200}
#define NUM_BUZZER_PATTERNS 3

static struct gpiod_chip *chip;
static struct gpiod_line *led_line, *buzzer_line, *flame_sensor_line;

void cleanup_and_exit(int status) {
    if (led_line) gpiod_line_release(led_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
    if (chip) gpiod_chip_close(chip);
    exit(status);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting.\n", signum);
    cleanup_and_exit(0);
}

void log_event(const char *event) {
    time_t now;
    time(&now);
    printf("%s: %s\n", ctime(&now), event);
}

int read_gpio(struct gpiod_line *line) {
    int value;
    int ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-ret));
        cleanup_and_exit(1);
    }
    return value;
}

void set_gpio(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line: %s\n", strerror(-ret));
        cleanup_and_exit(1);
    }
}

void delay_ms(int ms) {
    usleep(ms * 1000);
}

void blink_led(int on_ms, int off_ms, int count) {
    for (int i = 0; i < count; i++) {
        set_gpio(led_line, 0);
        delay_ms(on_ms);
        set_gpio(led_line, 1);
        delay_ms(off_ms);
    }
}

void sound_buzzer() {
    const int pattern[] = BUZZER_PATTERN_MS;
    for (int i = 0; i < NUM_BUZZER_PATTERNS; i++) {
        set_gpio(buzzer_line, 1);
        delay_ms(pattern[0]);
        set_gpio(buzzer_line, 0);
        delay_ms(pattern[1]);
        set_gpio(buzzer_line, 1);
        delay_ms(pattern[2]);
        set_gpio(buzzer_line, 0);
        delay_ms(pattern[3]);
    }
}

int self_test() {
    int flame_detected = 0;
    blink_led(500, 500, 2);

    for (int i = 0; i < NUM_STARTUP_READS; i++) {
        if (read_gpio(flame_sensor_line) == 0) {
            flame_detected++;
        }
        delay_ms(STARTUP_READ_INTERVAL_MS);
    }

    if (flame_detected == NUM_STARTUP_READS) {
        log_event("Flame detected during self-test");
        blink_led(ERROR_BLINK_INTERVAL_MS, ERROR_BLINK_INTERVAL_MS, 5);
        sound_buzzer();
        return 1;
    }

    log_event("Self-test passed");
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);

    if (!led_line || !buzzer_line || !flame_sensor_line) {
        fprintf(stderr, "Error getting GPIO lines\n");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0 ||
        gpiod_line_request_output(led_line, "led", 1) < 0 ||
        gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        cleanup_and_exit(1);
    }

    if (self_test()) {
        cleanup_and_exit(1);
    }

    int flame_active = 0;
    while (1) {
        if (read_gpio(flame_sensor_line) == 0) {
            if (!flame_active) {
                log_event("Flame detected");
                set_gpio(led_line, 0);
                set_gpio(buzzer_line, 0);
                flame_active = 1;
            }
        } else {
            if (flame_active) {
                log_event("Flame cleared");
                set_gpio(led_line, 1);
                set_gpio(buzzer_line, 1);
                flame_active = 0;
            }
        }
        delay_ms(MAIN_POLL_INTERVAL_MS);
    }

    return 0;
}

