#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SENSOR_READ_INTERVAL 1
#define BUFFER_SIZE 60
#define LED_GPIO 17
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0
#define MIN_LUX 0
#define MAX_LUX 1000

static int i2c_fd;
static int gpio_fd;
static int circular_buffer[BUFFER_SIZE] = {0};
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

void cleanup(int signum) {
    terminate = 1;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    return write(fd, buf, len);
}

int i2c_read(int fd, uint8_t *buf, int len) {
    return read(fd, buf, len);
}

int bh1750_read_lux() {
    uint8_t cmd = 0x20; // Power on, continuous mode
    uint8_t data[2];

    if (i2c_write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send command to BH1750\n");
        return -1;
    }

    usleep(180000); // Wait for measurement

    if (i2c_read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void set_led_frequency(float freq) {
    char path[64];
    int period_ns = (int)(1e9 / freq);
    int duty_ns = period_ns / 2;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/period", LED_GPIO);
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO period file");
        return;
    }
    dprintf(fd, "%d\n", period_ns);
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/duty_cycle", LED_GPIO);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO duty cycle file");
        return;
    }
    dprintf(fd, "%d\n", duty_ns);
    close(fd);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO export");
        close(i2c_fd);
        return 1;
    }

    char buf[4];
    snprintf(buf, sizeof(buf), "%d", LED_GPIO);
    if (write(gpio_fd, buf, strlen(buf)) < 0) {
        perror("Failed to export GPIO");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }
    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO direction");
        close(i2c_fd);
        return 1;
    }

    if (write(gpio_fd, "out", 3) < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }
    close(gpio_fd);

    while (!terminate) {
        int lux = bh1750_read_lux();
        if (lux >= 0) {
            circular_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            long sum = 0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                sum += circular_buffer[i];
            }
            float avg_lux = (float)sum / BUFFER_SIZE;

            float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (avg_lux / MAX_LUX);
            freq = (freq > MAX_FREQ) ? MAX_FREQ : ((freq < MIN_FREQ) ? MIN_FREQ : freq);
            set_led_frequency(freq);
        }

        sleep(SENSOR_READ_INTERVAL);
    }

    gpio_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO unexport");
    } else {
        char buf[4];
        snprintf(buf, sizeof(buf), "%d", LED_GPIO);
        if (write(gpio_fd, buf, strlen(buf)) < 0) {
            perror("Failed to unexport GPIO");
        }
        close(gpio_fd);
    }

    close(i2c_fd);
    return 0;
}

