#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define NUM_SEGMENTS 7
#define BLINK_DELAY_MS 500

// Segment patterns for digits 0-9
const unsigned char digit_patterns[10] = {
    0b0111111, // 0
    0b0000110, // 1
    0b1011011, // 2
    0b1001111, // 3
    0b1100110, // 4
    0b1101101, // 5
    0b1111101, // 6
    0b0000111, // 7
    0b1111111, // 8
    0b1101111  // 9
};

void shift_out(struct gpiod_chip *chip, int data_fd, int clock_fd, int latch_fd, unsigned char value) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_fd, (value >> i) & 0x01);
        usleep(1); // Small delay for stability
        gpiod_line_set_value(clock_fd, 1);
        usleep(1);
        gpiod_line_set_value(clock_fd, 0);
    }
    gpiod_line_set_value(latch_fd, 1);
    usleep(1);
    gpiod_line_set_value(latch_fd, 0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    int data_fd, clock_fd, latch_fd;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    data_fd = gpiod_line_request_output(data_line, "74HC595_DATA", 0);
    clock_fd = gpiod_line_request_output(clock_line, "74HC595_CLOCK", 0);
    latch_fd = gpiod_line_request_output(latch_line, "74HC595_LATCH", 0);

    if (data_fd < 0 || clock_fd < 0 || latch_fd < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        shift_out(chip, data_fd, clock_fd, latch_fd, digit_patterns[5]);
        usleep(BLINK_DELAY_MS * 1000);
        shift_out(chip, data_fd, clock_fd, latch_fd, 0);
        usleep(BLINK_DELAY_MS * 1000);
    }

    // Cleanup (this part will never be reached in this infinite loop)
    gpiod_line_release(data_fd);
    gpiod_line_release(clock_fd);
    gpiod_line_release(latch_fd);
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

