#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define TIMEOUT_MS 1000

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        goto cleanup_chip;
    }

    ret = gpiod_line_request_output(led_line, "blink_led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(-ret));
        goto cleanup_led;
    }

    // Request button line as input with pull-up and falling edge detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        goto cleanup_led;
    }

    ret = gpiod_line_request_input(button_line, "button_input");
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", strerror(-ret));
        goto cleanup_button;
    }

    ret = gpiod_line_set_flags(button_line, GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-up on button line: %s\n", strerror(-ret));
        goto cleanup_button;
    }

    ret = gpiod_line_request_rising_edge_events(button_line, "button_edge");
    if (ret < 0) {
        fprintf(stderr, "Failed to request rising edge events on button line: %s\n", strerror(-ret));
        goto cleanup_button;
    }

    while (keep_running) {
        // Blink LED
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED on: %s\n", strerror(-ret));
            break;
        }
        sleep(1);

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED off: %s\n", strerror(-ret));
            break;
        }
        sleep(1);

        // Check for button press
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(button_line, TIMEOUT_MS);
        if (ret > 0) {
            ret = gpiod_line_event_read(button_line, &event);
            if (ret == 0 && event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed. Stopping blink.\n");
                break;
            }
        } else if (ret < 0) {
            fprintf(stderr, "Failed to wait for button event: %s\n", strerror(-ret));
            break;
        }
    }

    // Turn off LED
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set LED off: %s\n", strerror(-ret));
    }

cleanup_button:
    gpiod_line_release(button_line);

cleanup_led:
    gpiod_line_release(led_line);

cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

