        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED on: %s\n", strerror(-ret));
            break;
        }
        sleep(1);

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED off: %s\n", strerror(-ret));
            break;
        }
        sleep(1);

        // Check for button press
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(button_line, TIMEOUT_MS);
        if (ret > 0) {
            ret = gpiod_line_event_read(button_line, &event);
            if (ret == 0 && event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed. Stopping blink.\n");
                break;
            }
        } else if (ret < 0) {
            fprintf(stderr, "Failed to wait for button event: %s\n", strerror(-ret));
            break;
        }
    }

    // Turn off LED
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set LED off: %s\n", strerror(-ret));
    }

cleanup_button:
    gpiod_line_release(button_line);

cleanup_led:
    gpiod_line_release(led_line);

cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
