#include <time.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_FREQUENCY 100 // 100 Hz
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)
#define INTENSITY_LEVELS 101

static struct gpiod_line *red_line, *green_line, *blue_line;
static struct gpiod_chip *chip;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(0);
    }

    if (gpiod_line_request_output(red_line, "RGB_LED_RED", 0) < 0 ||
        gpiod_line_request_output(green_line, "RGB_LED_GREEN", 0) < 0 ||
        gpiod_line_request_output(blue_line, "RGB_LED_BLUE", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output\n");
        cleanup(0);
    }

    struct timespec sleep_time = {0, PWM_PERIOD_NS / 2};
    struct timespec remaining;

    while (1) {
        int red_intensity = rand() % INTENSITY_LEVELS;
        int green_intensity = rand() % INTENSITY_LEVELS;
        int blue_intensity = rand() % INTENSITY_LEVELS;

        for (int i = 0; i < INTENSITY_LEVELS; i++) {
            if (i < red_intensity)
                gpiod_line_set_value(red_line, 1);
            else
                gpiod_line_set_value(red_line, 0);

            if (i < green_intensity)
                gpiod_line_set_value(green_line, 1);
            else
                gpiod_line_set_value(green_line, 0);

            if (i < blue_intensity)
                gpiod_line_set_value(blue_line, 1);
            else
                gpiod_line_set_value(blue_line, 0);

            if (clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, &remaining) == EINTR) {
                sleep_time = remaining;
            }
        }
    }

    return EXIT_SUCCESS;
}

