    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return -1;
    }
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return -1;
    }
    if (gpiod_line_request_output(line, "impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return -1;
    }
    return 0;
}

int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_i2c(i2c_fd, 0x28 | 0x80, buf) != 0 ||
        read_i2c(i2c_fd, 0x2A | 0x80, buf + 2) != 0) {
        return -1;
    }
    *x = (buf[0] | (buf[1] << 8));
    *y = (buf[2] | (buf[3] << 8));
    *z = (buf[4] | (buf[5] << 8));
    return 0;
}

void trigger_impact() {
    gpiod_line_set_value(line, 1);
    time_sleep(PULSE_DURATION_MS / 1000.0);
    gpiod_line_set_value(line, 0);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() != 0 || init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(0);
    }

    struct timespec ts;
    int16_t x, y, z;
    double g_force;

    while (1) {
        if (read_accel(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        g_force = sqrt(x*x + y*y + z*z) / 16384.0; // LSM303DLHC sensitivity

        if (g_force > threshold) {
            trigger_impact();
            time_now(&ts);
            fprintf(log_file, "%lld.%09ld, %d, %d, %d, %.3f\n",
                    (long long)ts.tv_sec, ts.tv_nsec, x, y, z, g_force);
            fflush(log_file);
        }

        nanosleep(&(struct timespec){0, 100000000 / SAMPLE_RATE_HZ}, NULL);
    }

    fclose(log_file);
    cleanup(0);
}
