#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x88
#define ALS_MSB_REG 0x89
#define RED_LSB_REG 0x8A
#define RED_MSB_REG 0x8B
#define GREEN_LSB_REG 0x8C
#define GREEN_MSB_REG 0x8D
#define BLUE_LSB_REG 0x8E
#define BLUE_MSB_REG 0x8F
#define LED_PIN 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

static int i2c_fd;
static FILE *csv_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int init_i2c() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD188BI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioHardwarePWM(LED_PIN, 0, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpioTerminate();
        return 1;
    }

    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup();
        return 1;
    }

    fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
    fflush(csv_file);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioHardwarePWM(LED_PIN, 1000, 0);  // 1 kHz frequency, 0% duty cycle

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec last_sample_time = {0, 0};
    struct timespec current_time;

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - last_sample_time.tv_sec) * 1000 +
                          (current_time.tv_nsec - last_sample_time.tv_nsec) / 1000000;

        if (elapsed_ms >= SAMPLE_INTERVAL_MS) {
            int als, red, green, blue;
            int retry_count = 0;

            while (retry_count < 3) {
                als = i2c_read_word(i2c_fd, ALS_LSB_REG);
                red = i2c_read_word(i2c_fd, RED_LSB_REG);
                green = i2c_read_word(i2c_fd, GREEN_LSB_REG);
                blue = i2c_read_word(i2c_fd, BLUE_LSB_REG);

                if (als >= 0 && red >= 0 && green >= 0 && blue >= 0) {
                    break;
                }

                fprintf(stderr, "I2C read error, retrying...\n");
                usleep(100000);  // 100 ms delay
                retry_count++;
            }

            if (retry_count == 3) {
                fprintf(stderr, "Failed to read sensor data after 3 attempts\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, als, red, green, blue);
            fflush(csv_file);

            // Adjust LED brightness based on ALS value
            int brightness = (als * PWM_RANGE) / 65535;  // Assuming ALS is 16-bit
            gpioPWM(LED_PIN, brightness);

            last_sample_time = current_time;
        }

        usleep(1000);  // Sleep for 1 ms to reduce CPU usage
    }

    cleanup();
    return 0;
}

