#define I2C_BUS 1
#define FXOS8700CQ_SLAVE_ADDR 0x1F
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_MCTRL_REG 0x5B
#define FXOS8700CQ_MAG_DATA 0x01
#define FXOS8700CQ_STATUS_REG 0x00

#define WHO_AM_I_EXPECTED 0xC7
#define IMPACT_THRESHOLD 1.5 // Adjust as needed

static int i2cHandle;

void signalHandler(int signo) {
    if (signo == SIGINT) {
        printf("Exiting...\n");
        if (i2cHandle >= 0) {
            i2cClose(i2cHandle);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    FILE *logFile;
    int16_t accel[3], mag[3];
    float magnitude;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, FXOS8700CQ_SLAVE_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I
    char whoAmI;
    if (i2cReadByteData(i2cHandle, FXOS8700CQ_WHO_AM_I, &whoAmI) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (whoAmI != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", whoAmI);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Place in standby
    if (i2cWriteByteData(i2cHandle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to place FXOS8700CQ in standby\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2cHandle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure FXOS8700CQ range\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Activate for 200Hz output data rate
    if (i2cWriteByteData(i2cHandle, FXOS8700CQ_CTRL_REG1, 0x15) < 0) {
        fprintf(stderr, "Failed to activate FXOS8700CQ\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen("impact_log.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);

    while (1) {
        // Wait for data ready
        char status;
        if (i2cReadByteData(i2cHandle, FXOS8700CQ_STATUS_REG, &status) < 0) {
            fprintf(stderr, "Failed to read status register\n");
            continue;
        }

        if (!(status & 0x08)) {
            usleep(1000); // Wait 1ms before retrying
            continue;
        }

        // Read acceleration data
        if (i2cReadI2CBlockData(i2cHandle, FXOS8700CQ_MAG_DATA, 6, (char *)accel) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        // Compute magnitude
        magnitude = sqrtf(accel[0] * accel[0] + accel[1] * accel[1] + accel[2] * accel[2]) / 4096.0;

        if (magnitude > IMPACT_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            tm_info = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(logFile, "%s,%d,%d,%d,%.3f\n", timestamp, accel[0], accel[1], accel[2], magnitude);
            fflush(logFile);
        }

        nanosleep(&(struct timespec){0, 50000000}, NULL); // 50ms
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

