static int check_i2c_call(int result, const char *func) {
    if (result < 0) {
        fprintf(stderr, "Error in %s: %s\n", func, strerror(errno));
        cleanup();
    }
    return result;
}

static void calibrate_gyro(void) {
    int16_t raw_x[SAMPLE_COUNT], raw_y[SAMPLE_COUNT], raw_z[SAMPLE_COUNT];
    float sum_x = 0, sum_y = 0, sum_z = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        check_i2c_call(i2cReadWordData(i2c_fd, OUT_X_L), "i2cReadWordData");
