#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define DEVICE_ID_REG 0x00
#define DEVICE_ID 0xE5
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define DATAY0_REG 0x34
#define DATAZ0_REG 0x36
#define LED_PIN 17
#define SAMPLE_INTERVAL_MS 100
#define SAMPLE_INTERVAL_S (SAMPLE_INTERVAL_MS / 1000.0)
#define GRAVITY 9.80665

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(i2c_fd, buf, sizeof(buf));
}

int i2c_read(int reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_fd, buf, len);
}

int main() {
    struct timespec ts;
    uint8_t buf[6];
    int16_t x, y, z;
    float x_g, y_g, z_g;
    float max_accel = 2.0;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_read(DEVICE_ID_REG, buf, 1) != 1 || buf[0] != DEVICE_ID) {
        fprintf(stderr, "ADXL345 device ID check failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(DATA_FORMAT_REG, 0x0B) != 1) {
        fprintf(stderr, "Failed to set ADXL345 data format\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(POWER_CTL_REG, 0x08) != 1) {
        fprintf(stderr, "Failed to set ADXL345 power control\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("accel_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "ADXL345_LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c_read(DATAX0_REG, buf, 6) != 6) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        x = (int16_t)((buf[1] << 8) | buf[0]);
        y = (int16_t)((buf[3] << 8) | buf[2]);
        z = (int16_t)((buf[5] << 8) | buf[4]);

        x_g = x * GRAVITY / 1024.0;
        y_g = y * GRAVITY / 1024.0;
        z_g = z * GRAVITY / 1024.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n",
                ts.tv_sec, ts.tv_nsec, x_g, y_g, z_g);
        fflush(log_file);

        if (fabs(x_g) > max_accel || fabs(y_g) > max_accel || fabs(z_g) > max_accel) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

    return EXIT_SUCCESS;
}

