#define SAMPLE_INTERVAL_MS 100

typedef struct {
    float ax, ay, az;
    float mx, my, mz;
} SensorData;

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        gpioI2CClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, LSM303DLHC_ACCEL_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for accelerometer\n");
        gpioTerminate();
        return -1;
    }

    if (gpioI2CWriteByte(i2c_handle, 0x20 | 0x60) < 0) { // CTRL_REG1_A
        fprintf(stderr, "Failed to set accelerometer control register\n");
        cleanup(0);
        return -1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, LSM303DLHC_MAG_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for magnetometer\n");
        gpioTerminate();
        return -1;
    }

    if (gpioI2CWriteByte(i2c_handle, 0x00 | 0x20) < 0) { // CRA_REG_M
        fprintf(stderr, "Failed to set magnetometer control register\n");
        cleanup(0);
        return -1;
    }

    return 0;
}

int read_accel(SensorData *data) {
    char buf[6];
    if (gpioI2CReadI2CBlock(i2c_handle, 0x28 | 0x80, buf, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    data->ax = (float)(buf[0] | (buf[1] << 8)) / 16384.0f;
    data->ay = (float)(buf[2] | (buf[3] << 8)) / 16384.0f;
    data->az = (float)(buf[4] | (buf[5] << 8)) / 16384.0f;

    return 0;
}

int read_mag(SensorData *data) {
    char buf[6];
    if (gpioI2CReadI2CBlock(i2c_handle, 0x00 | 0x80, buf, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    data->mx = (float)(buf[0] | (buf[1] << 8));
    data->my = (float)(buf[2] | (buf[3] << 8));
    data->mz = (float)(buf[4] | (buf[5] << 8));

    return 0;
}

float calculate_heading(SensorData *data) {
    float heading;
    float mag_x = data->mx;
    float mag_y = data->my;

    heading = atan2(mag_y, mag_x);
    heading = heading * 180.0f / M_PI;

    if (heading < 0) {
        heading += 360.0f;
    }

    return heading;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("compass_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading,AccelX,AccelY,AccelZ,MagX,MagY,MagZ\n");
    }

    SensorData data;
    struct timespec ts;
    char timestamp[20];

    while (1) {
        if (read_accel(&data) < 0 || read_mag(&data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        float heading = calculate_heading(&data);

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, heading, data.ax, data.ay, data.az, data.mx, data.my, data.mz);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}
