int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int vl6180x_init() {
    uint8_t value;

    // System init
    if (i2c_read(i2c_fd, 0x0016, &value) || value != 0x01) {
        return -1;
    }

    // Perform the sensor's mandatory initialization sequence
    i2c_write(i2c_fd, 0x0207, 0x01);
    i2c_write(i2c_fd, 0x0208, 0x01);
    i2c_write(i2c_fd, 0x0096, 0x00);
    i2c_write(i2c_fd, 0x0097, 0xfd);
    i2c_write(i2c_fd, 0x00e3, 0x00);
