    i2c_write(i2c_fd, 0x00e5, 0x02);
    i2c_write(i2c_fd, 0x00e6, 0x01);
    i2c_write(i2c_fd, 0x00e7, 0x03);
    i2c_write(i2c_fd, 0x00f5, 0x02);
    i2c_write(i2c_fd, 0x00d9, 0x05);
    i2c_write(i2c_fd, 0x00db, 0xce);
    i2c_write(i2c_fd, 0x00dc, 0x03);
    i2c_write(i2c_fd, 0x00dd, 0xf8);
    i2c_write(i2c_fd, 0x009f, 0x00);
    i2c_write(i2c_fd, 0x00a3, 0x3c);
    i2c_write(i2c_fd, 0x00b7, 0x00);
    i2c_write(i2c_fd, 0x00bb, 0x3c);
    i2c_write(i2c_fd, 0x00b2, 0x09);
    i2c_write(i2c_fd, 0x00ca, 0x09);
    i2c_write(i2c_fd, 0x0198, 0x01);
    i2c_write(i2c_fd, 0x01b0, 0x17);
    i2c_write(i2c_fd, 0x01ad, 0x00);
    i2c_write(i2c_fd, 0x00ff, 0x05);
    i2c_write(i2c_fd, 0x0100, 0x05);
    i2c_write(i2c_fd, 0x0199, 0x05);
    i2c_write(i2c_fd, 0x01a6, 0x1b);
    i2c_write(i2c_fd, 0x01ac, 0x3e);
    i2c_write(i2c_fd, 0x01a7, 0x1f);
    i2c_write(i2c_fd, 0x0030, 0x00);

    // Poll for device ready
    do {
        i2c_read(i2c_fd, 0x0011, &value);
    } while (value != 0x01);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

