        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (vl6180x_init() < 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t range;
        if (i2c_read(i2c_fd, 0x0410, &range) < 0) {
            fprintf(stderr, "Failed to read range\n");
            if (vl6180x_init() < 0) {
                fprintf(stderr, "Re-initialization failed\n");
            }
            continue;
        }

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        fprintf(log_fp, "[%s] Distance: %d mm\n", timestamp, range);
        if (range < 100) {
            fprintf(log_fp, "[%s] DOOR_OPEN\n", timestamp);
        } else {
            fprintf(log_fp, "[%s] DOOR_CLOSED\n", timestamp);
        }
        fflush(log_fp);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

