#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x34
#define SENSOR2_ADDR 0x35
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.dat"

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int i2c_write(int addr, uint8_t *buf, int len) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];

    messages[0].addr = addr;
    messages[0].flags = 0;
    messages[0].len = len;
    messages[0].buf = buf;

    packets.msgs = messages;
    packets.nmsgs = 1;

    return ioctl(i2c_fd, I2C_RDWR, &packets);
}

int i2c_read(int addr, uint8_t *buf, int len) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];

    messages[0].addr = addr;
    messages[0].flags = I2C_M_RD;
    messages[0].len = len;
    messages[0].buf = buf;

    packets.msgs = messages;
    packets.nmsgs = 1;

    return ioctl(i2c_fd, I2C_RDWR, &packets);
}

int read_sensor(int addr, int16_t *sample) {
    uint8_t buf[2];
    if (i2c_read(addr, buf, 2) < 0) {
        return -1;
    }
    *sample = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main() {
    struct timespec sample_time, prev_time;
    int16_t sample1, sample2;
    int64_t tdoa;

    signal(SIGINT, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_input(line, "IMP23ABSU") < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    clock_gettime(CLOCK_REALTIME, &prev_time);

    while (1) {
        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);

        clock_gettime(CLOCK_REALTIME, &sample_time);

        if (read_sensor(SENSOR1_ADDR, &sample1) == 0 && read_sensor(SENSOR2_ADDR, &sample2) == 0) {
            tdoa = (sample_time.tv_sec - prev_time.tv_sec) * 1000000000LL +
                   (sample_time.tv_nsec - prev_time.tv_nsec);

            fprintf(log_file, "%lld,%lld,%d,%d,%lld\n",
                    sample_time.tv_sec, sample_time.tv_nsec,
                    sample1, sample2, tdoa);
            fflush(log_file);

            prev_time = sample_time;
        }
    }

    return 0;
}

