#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_US 40

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

#define REG_GYRO_X_OUT_L 0x0A
#define REG_GYRO_Y_OUT_L 0x0C
#define REG_GYRO_Z_OUT_L 0x0E
#define REG_ACCEL_X_OUT_L 0x14
#define REG_ACCEL_Y_OUT_L 0x16
#define REG_ACCEL_Z_OUT_L 0x18

static volatile sig_atomic_t keep_running = 1;
static int spi_fd;
static FILE *csv_file;

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(uint16_t tx, uint16_t *rx) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)&tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = SPI_DELAY_US,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_SPEED,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
    }
    return ret;
}

int read_register(uint8_t reg_addr, int16_t *value) {
    uint16_t tx = (0x00 << 15) | (reg_addr << 8);
    uint16_t rx[2];

    if (spi_transfer(tx, rx) < 0) {
        return -1;
    }

    *value = (int16_t)rx[1];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    atexit(cleanup);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return 1;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    struct timespec ts;
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long timestamp = ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

        if (read_register(REG_GYRO_X_OUT_L, &gyro_x) < 0 ||
            read_register(REG_GYRO_Y_OUT_L, &gyro_y) < 0 ||
            read_register(REG_GYRO_Z_OUT_L, &gyro_z) < 0 ||
            read_register(REG_ACCEL_X_OUT_L, &accel_x) < 0 ||
            read_register(REG_ACCEL_Y_OUT_L, &accel_y) < 0 ||
            read_register(REG_ACCEL_Z_OUT_L, &accel_z) < 0) {
            fprintf(stderr, "Failed to read all registers\n");
            continue;
        }

        float gyro_x_val = gyro_x * GYRO_SENSITIVITY;
        float gyro_y_val = gyro_y * GYRO_SENSITIVITY;
        float gyro_z_val = gyro_z * GYRO_SENSITIVITY;
        float accel_x_val = accel_x * ACCEL_SENSITIVITY;
        float accel_y_val = accel_y * ACCEL_SENSITIVITY;
        float accel_z_val = accel_z * ACCEL_SENSITIVITY;

        fprintf(csv_file, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, gyro_x_val, gyro_y_val, gyro_z_val,
                accel_x_val, accel_y_val, accel_z_val);
        fflush(csv_file);

        // Non-blocking delay
        struct timespec delay = {0, 100000000}; // 100ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

