#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define REG_GYRO_X 0x18
#define REG_GYRO_Y 0x1A
#define REG_GYRO_Z 0x1C
#define REG_ACCEL_X 0x1E
#define REG_ACCEL_Y 0x20
#define REG_ACCEL_Z 0x22
#define SCALE_GYRO 0.02
#define SCALE_ACCEL 0.00025
#define LOG_INTERVAL_MS 100

static int spi_fd;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret;
    uint8_t mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_register(uint8_t reg, int16_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0};
    uint8_t rx[2] = {0};

    if (spi_transfer(tx, rx, 2) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_register(REG_GYRO_X, &gyro_x) < 0 ||
            read_register(REG_GYRO_Y, &gyro_y) < 0 ||
            read_register(REG_GYRO_Z, &gyro_z) < 0 ||
            read_register(REG_ACCEL_X, &accel_x) < 0 ||
            read_register(REG_ACCEL_Y, &accel_y) < 0 ||
            read_register(REG_ACCEL_Z, &accel_z) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        printf("Gyro X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n",
