        printf("Accel X: %.4f g, Y: %.4f g, Z: %.4f g\n",
               accel_x * SCALE_ACCEL, accel_y * SCALE_ACCEL, accel_z * SCALE_ACCEL);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

