#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define READ_INTERVAL_MS 100
#define STALL_TIME_US 40
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

static int spi_fd;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int spi_transfer(uint16_t tx, uint16_t *rx) {
    uint8_t tx_buf[2] = {tx >> 8, tx & 0xFF};
    uint8_t rx_buf[2];

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .delay_usecs = STALL_TIME_US,
        .bits_per_word = 8,
        .speed_hz = SPI_SPEED,
        .cs_change = 0,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    *rx = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t data[6];
    const uint16_t read_commands[6] = {0x02, 0x04, 0x06, 0x08, 0x0A, 0x0C};

    for (int i = 0; i < 6; i++) {
        if (spi_transfer(read_commands[i] | 0x8000, &data[i]) != 0) {
            return -1;
        }
    }

    *gyro_x = (float)(int16_t)data[0] * GYRO_SCALE;
    *gyro_y = (float)(int16_t)data[1] * GYRO_SCALE;
    *gyro_z = (float)(int16_t)data[2] * GYRO_SCALE;
    *accel_x = (float)(int16_t)data[3] * ACCEL_SCALE;
    *accel_y = (float)(int16_t)data[4] * ACCEL_SCALE;
    *accel_z = (float)(int16_t)data[5] * ACCEL_SCALE;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spi_init() != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Failed to read IMU data\n");
            break;
        }

        printf("Gyro X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_x, gyro_y, gyro_z);
        printf("Accel X: %.4f g, Y: %.4f g, Z: %.4f g\n", accel_x, accel_y, accel_z);

        usleep(READ_INTERVAL_MS * 1000);
    }

    close(spi_fd);
    gpioTerminate();
    return 0;
}

