#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68
#define MPU6886_ACCEL_OUT 0x3B
#define MPU6886_GYRO_OUT 0x43
#define RETRY_LIMIT 3
#define SAMPLE_INTERVAL_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_write(fd, reg, 0) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int read_sensor_data(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (i2c_read(fd, reg, buf, 2) == 2) {
            *value = (int16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        retries++;
        usleep(10000); // 10ms delay before retry
    }
    return -1;
}

int main() {
    int fd;
    int16_t accel[3], gyro[3];

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Unable to set up signal handler");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Initialize MPU6886
    if (i2c_write(fd, 0x6B, 0x00) != 1) {
        perror("Failed to wake up MPU6886");
        close(fd);
        return 1;
    }

    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (keep_running) {
        if (read_sensor_data(fd, MPU6886_ACCEL_OUT, accel) == 0 &&
            read_sensor_data(fd, MPU6886_ACCEL_OUT + 2, accel + 1) == 0 &&
            read_sensor_data(fd, MPU6886_GYRO_OUT, gyro) == 0 &&
            read_sensor_data(fd, MPU6886_GYRO_OUT + 2, gyro + 1) == 0) {

            printf("Accel: X=%d Y=%d Z=%d | Gyro: X=%d Y=%d Z=%d\n",
                   accel[0], accel[1], accel[2], gyro[0], gyro[1], gyro[2]);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - last_time.tv_sec) * 1000 +
                          (current_time.tv_nsec - last_time.tv_nsec) / 1000000;

        if (elapsed_ms < SAMPLE_INTERVAL_MS) {
            usleep((SAMPLE_INTERVAL_MS - elapsed_ms) * 1000);
        }

        clock_gettime(CLOCK_MONOTONIC, &last_time);
    }

    close(fd);
    return 0;
}

