#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define ADXL345_DEVID 0xE5
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define LED_PIN 17
#define SAMPLE_INTERVAL_MS 10
#define ACCEL_THRESHOLD 2.5
#define SCALE_FACTOR 256.0

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(0);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        cleanup(0);
    }

    uint8_t dev_id;
    if (i2c_read(i2c_fd, ADXL345_DATAX0, &dev_id) != 1 || dev_id != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 device ID verification failed\n");
        cleanup(0);
    }

    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x08) != 1 ||
        i2c_write(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) != 1) {
        fprintf(stderr, "Failed to configure ADXL345\n");
        cleanup(0);
    }

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    uint8_t data[6];
    int16_t x, y, z;
    float magnitude;
    struct timespec ts;

    while (1) {
        if (i2c_read(i2c_fd, ADXL345_DATAX0, data) != 1 ||
            i2c_read(i2c_fd, ADXL345_DATAX0 + 1, data + 1) != 1 ||
            i2c_read(i2c_fd, ADXL345_DATAX0 + 2, data + 2) != 1 ||
            i2c_read(i2c_fd, ADXL345_DATAX0 + 3, data + 3) != 1 ||
            i2c_read(i2c_fd, ADXL345_DATAX0 + 4, data + 4) != 1 ||
            i2c_read(i2c_fd, ADXL345_DATAX0 + 5, data + 5) != 1) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            cleanup(0);
        }

        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        magnitude = sqrtf((x * x + y * y + z * z) / (SCALE_FACTOR * SCALE_FACTOR));

        if (magnitude > ACCEL_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld, %.2f g, X: %d, Y: %d, Z: %d\n",
                    ts.tv_sec, ts.tv_nsec, magnitude, x, y, z);
            fflush(log_file);
            usleep(500000);
            gpioWrite(LED_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

