#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define SAMPLE_RATE_MS 100
#define ACCEL_REG 0x3B
#define GYRO_REG 0x43
#define NUM_SAMPLES 1000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_handle;
    FILE *log_file;
    char buffer[14];
    struct timespec ts;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, 2)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(line, "I2C_SDA", 1) < 0) {
        fprintf(stderr, "Failed to request I2C_SDA line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("imu_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        ret = i2cReadI2CBlockData(i2c_handle, ACCEL_REG, buffer, 14);
        if (ret != 14) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        }

        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];
        int16_t gyro_x = (buffer[8] << 8) | buffer[9];
        int16_t gyro_y = (buffer[10] << 8) | buffer[11];
        int16_t gyro_z = (buffer[12] << 8) | buffer[13];

        fprintf(log_file, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec,
                accel_x, accel_y, accel_z,
                gyro_x, gyro_y, gyro_z);

        fflush(log_file);
        time_sleep(SAMPLE_RATE_MS / 1000.0);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

