    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        ret = i2cReadI2CBlockData(i2c_handle, ACCEL_REG, buffer, 14);
        if (ret != 14) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        }

        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];
        int16_t gyro_x = (buffer[8] << 8) | buffer[9];
        int16_t gyro_y = (buffer[10] << 8) | buffer[11];
        int16_t gyro_z = (buffer[12] << 8) | buffer[13];

        fprintf(log_file, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec,
                accel_x, accel_y, accel_z,
                gyro_x, gyro_y, gyro_z);

        fflush(log_file);
        time_sleep(SAMPLE_RATE_MS / 1000.0);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}
