    signal(SIGTERM, cleanup);

    while (1) {
        int16_t x = readRegister(OUT_X_MSB_REG);
        int16_t y = readRegister(OUT_Y_MSB_REG);
        int16_t z = readRegister(OUT_Z_MSB_REG);

        if (x < 0) x += 4096;
        if (y < 0) y += 4096;
        if (z < 0) z += 4096;

        float magnitude = sqrt(x*x + y*y + z*z);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(logFile, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", 
                timestamp, x, y, z, magnitude);
        fflush(logFile);

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(ledLine, 1);
            usleep(500000);
            gpiod_line_set_value(ledLine, 0);
        }

        usleep(SAMPLE_RATE_MS * 1000);
    }

    return EXIT_SUCCESS;
}

