#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_ID 0xE5
#define ADXL345_INT1_PIN 17
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x21
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

static int i2c_fd;
static int gpio_fd;
static struct gpiod_line *gpio_line;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (i2c_read(fd, reg, buf) != 2) return -1;
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    char timestamp[30];
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s.%03ld,%d,%d,%d\n", timestamp, ts.tv_nsec / 1000000, x, y, z);
    fflush(log_file);
}

void gpio_callback(struct gpiod_line *line, int event, void *user_data) {
    int16_t x, y, z;
    while (running && gpiod_line_event_wait(line, 0) > 0) {
        if (i2c_read_word(i2c_fd, ADXL345_DATAX0, &x) == 0 &&
            i2c_read_word(i2c_fd, ADXL345_DATAY0, &y) == 0 &&
            i2c_read_word(i2c_fd, ADXL345_DATAZ0, &z) == 0) {
            log_acceleration(x, y, z);
        }
    }
}

int main() {
    struct i2c_msg msgs[1];
    uint8_t buf[6];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t device_id;
    if (i2c_read(i2c_fd, 0x00, &device_id) != 1 || device_id != ADXL345_ID) {
        fprintf(stderr, "ADXL345 not found or incorrect ID\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x00) != 1) {
        perror("Failed to set ADXL345 to standby mode");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ADXL345_INT_ENABLE, 0x01) != 1) {
        perror("Failed to enable ADXL345 interrupts");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ADXL345_INT_MAP, 0x01) != 1) {
        perror("Failed to map ADXL345 interrupt to INT1");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x08) != 1) {
        perror("Failed to set ADXL345 to measurement mode");
        close(i2c_fd);
        return 1;
    }

    gpio_fd = gpiod_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_get_line(gpio_fd, ADXL345_INT1_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_input(gpio_line, "ADXL345_INT1") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(gpio_line);
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("freefall_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(gpio_line, 100) > 0) {
            if (gpiod_line_event_read(gpio_line, &event) == 0) {
                gpio_callback(gpio_line, event.event_type, NULL);
            }
        }
    }

    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_close(gpio_fd);
    i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x00);
    close(i2c_fd);

    return 0;
}

