#define IMPACT_THRESHOLD 2.5
#define DETECTION_WINDOW 1.0
#define WHO_AM_I 0x0F
#define CTRL_REG6_G 0x15
#define CTRL_REG1_XL 0x10
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} FallState;

static int i2c_fd;
static FILE *log_file;
static FallState state = IDLE;
static time_t last_fall_time = 0;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

static void signal_handler(int signo) {
    (void)signo;
    cleanup();
}

static int i2c_write(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(i2c_fd, buf, sizeof(buf));
}

static int i2c_read(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_fd, value, 1);
}

static int read_sensor_data(int16_t *accel, int16_t *gyro) {
    uint8_t buf[6];
    if (i2c_read(OUTX_L_XL, buf) != 1 ||
        i2c_read(OUTX_L_XL + 1, buf + 1) != 1 ||
        i2c_read(OUTX_L_G, buf + 2) != 1 ||
        i2c_read(OUTX_L_G + 1, buf + 3) != 1 ||
        i2c_read(OUTX_L_G + 2, buf + 4) != 1 ||
        i2c_read(OUTX_L_G + 3, buf + 5) != 1) {
        return -1;
    }
    accel[0] = (int16_t)(buf[1] | (buf[0] << 8));
    accel[1] = (int16_t)(buf[3] | (buf[2] << 8));
    accel[2] = (int16_t)(buf[5] | (buf[4] << 8));
    gyro[0] = (int16_t)(buf[7] | (buf[6] << 8));
    return 0;
}

static float calculate_accel_magnitude(int16_t *accel) {
    return sqrtf(accel[0] * accel[0] + accel[1] * accel[1] + accel[2] * accel[2]) / 16384.0;
}

static void log_data(time_t timestamp, int16_t *accel, int16_t *gyro, float accel_mag) {
    fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d,%.3f\n",
            timestamp, accel[0], accel[1], accel[2], gyro[0], gyro[1], gyro[2], accel_mag);
    fflush(log_file);
}

