    struct timespec ts;
    int16_t accel[3], gyro[3];
    float accel_mag;
    time_t current_time, fall_start_time;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_FILE, O_RDWR);
