        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read(WHO_AM_I, &who_am_i) != 1 || who_am_i != 0x69) {
        fprintf(stderr, "Sensor not detected or incorrect WHO_AM_I value\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(CTRL_REG1_XL, 0x67) != 1 ||  // ODR = 104 Hz, FS = ±2g
        i2c_write(CTRL_REG6_G, 0x60) != 1) {  // ODR = 104 Hz, FS = ±250 dps
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(log_file, "Timestamp,AccelX,AccelY,AccelZ,GyroX,GyroY,GyroZ,AccelMag\n");

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("Failed to get current time");
            break;
        }

        if (read_sensor_data(accel, gyro) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        accel_mag = calculate_accel_magnitude(accel);
        log_data(ts.tv_sec, accel, gyro, accel_mag);

        current_time = ts.tv_sec;

        switch (state) {
            case IDLE:
                if (accel_mag < ACCEL_THRESHOLD) {
                    state = FREEFALL;
                    fall_start_time = current_time;
                }
                break;
            case FREEFALL:
                if (current_time - fall_start_time > DETECTION_WINDOW) {
                    state = IDLE;
                } else if (accel_mag > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    printf("Impact detected at %ld\n", current_time);
                }
                break;
            case IMPACT:
                state = IDLE;
                break;
        }

        nanosleep(&(struct timespec){0, 9500000}, NULL);  // Sleep for ~9.5ms to maintain 104Hz
    }

    cleanup();
    return EXIT_SUCCESS;
