#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define WHO_AM_I 0x00
#define WHO_AM_I_EXPECTED 0x3D
#define GYRO_XOUT 0x08
#define SCALE_FACTOR 0.0305
#define SAMPLE_INTERVAL_MS 10

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

uint16_t read_register(uint8_t reg_addr) {
    uint8_t tx[2] = {reg_addr | 0x80, 0x00};
    uint8_t rx[2] = {0};
    int ret;

    ret = spi_transfer(tx, rx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    return (rx[0] << 8) | rx[1];
}

void write_register(uint8_t reg_addr, uint16_t value) {
    uint8_t tx[2] = {reg_addr & 0x7F, (value >> 8) & 0xFF};
    uint8_t rx[2] = {0};
    int ret;

    tx[1] = value & 0xFF;
    ret = spi_transfer(tx, rx, sizeof(tx));
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, cleanup);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    // Verify WHO_AM_I register
    uint16_t who_am_i = read_register(WHO_AM_I);
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I verification failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_EXPECTED, who_am_i);
        goto cleanup_spi;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    fprintf(log_file, "Timestamp,X_Rate,Y_Rate,Z_Rate\n");

    // Main sampling loop
    while (1) {
        struct timespec ts;
        char timestamp[64];

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int16_t x_rate = (int16_t)read_register(GYRO_XOUT);
        int16_t y_rate = (int16_t)read_register(GYRO_XOUT + 2);
        int16_t z_rate = (int16_t)read_register(GYRO_XOUT + 4);

        float x_rate_deg = x_rate * SCALE_FACTOR;
        float y_rate_deg = y_rate * SCALE_FACTOR;
        float z_rate_deg = z_rate * SCALE_FACTOR;

        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate_deg, y_rate_deg, z_rate_deg);
        fflush(log_file);

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

cleanup_spi:
    close(spi_fd);
cleanup:
    if (log_file) {
        fclose(log_file);
    }
    return EXIT_FAILURE;
}

