    int ret;

    signal(SIGINT, cleanup);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    // Verify WHO_AM_I register
    uint16_t who_am_i = read_register(WHO_AM_I);
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I verification failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_EXPECTED, who_am_i);
        goto cleanup_spi;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    fprintf(log_file, "Timestamp,X_Rate,Y_Rate,Z_Rate\n");

    // Main sampling loop
    while (1) {
        struct timespec ts;
        char timestamp[64];

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int16_t x_rate = (int16_t)read_register(GYRO_XOUT);
        int16_t y_rate = (int16_t)read_register(GYRO_XOUT + 2);
        int16_t z_rate = (int16_t)read_register(GYRO_XOUT + 4);

        float x_rate_deg = x_rate * SCALE_FACTOR;
        float y_rate_deg = y_rate * SCALE_FACTOR;
        float z_rate_deg = z_rate * SCALE_FACTOR;

        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate_deg, y_rate_deg, z_rate_deg);
        fflush(log_file);

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

cleanup_spi:
    close(spi_fd);
cleanup:
    if (log_file) {
        fclose(log_file);
    }
    return EXIT_FAILURE;
}
