#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 100 // 100 Hz
#define SAMPLE_INTERVAL 10000 // 10 ms

static int i2c_handle;
static FILE *csv_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int main() {
    struct timespec ts;
    char filename[] = "gyro_log.csv";
    int retry_count;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, cleanup) == SIG_ERR) {
        fprintf(stderr, "Cannot set up signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to select I2C slave device");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (retry_count = 0; retry_count < 3; retry_count++) {
        uint8_t who_am_i;
        if (i2c_read(i2c_handle, WHO_AM_I, &who_am_i) == 1 && who_am_i == WHO_AM_I_EXPECTED) {
            break;
        }
        fprintf(stderr, "WHO_AM_I check failed, retrying...\n");
        usleep(100000); // 100ms delay
    }

    if (retry_count == 3) {
        fprintf(stderr, "WHO_AM_I check failed after 3 attempts\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_handle, CTRL_REG1, 0x0F) != 2 || // Normal mode, 100 Hz
        i2c_write(i2c_handle, CTRL_REG4, 0x20) != 2) { // 2000 dps full scale
        fprintf(stderr, "Failed to configure gyroscope\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen(filename, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(csv_file, 0, SEEK_END) == 0) {
        if (ftell(csv_file) == 0) {
            fprintf(csv_file, "Timestamp,X,Y,Z\n");
        }
    }

    while (1) {
        int16_t raw_x, raw_y, raw_z;
        float x, y, z;

        if (i2c_read(i2c_handle, OUT_X_L | 0x80, (uint8_t *)&raw_x) != 2 ||
            i2c_read(i2c_handle, OUT_X_L + 1 | 0x80, (uint8_t *)&raw_y) != 2 ||
            i2c_read(i2c_handle, OUT_X_L + 2 | 0x80, (uint8_t *)&raw_z) != 2) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        x = (float)raw_x / 114.285f;
        y = (float)raw_y / 114.285f;
        z = (float)raw_z / 114.285f;

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        fprintf(csv_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        fflush(csv_file);

        usleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

