#include <string.h>
#include <gpiod.h>

#define LOG_FILE "flame_events.log"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s – %s\n", time_str, message);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Enable internal pull-up resistor
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up resistor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!exit_flag) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            log_event("Error reading sensor");
        } else if (value == 0) {
            log_event("Flame detected: YES");
            printf("FLAME DETECTED!\n");
        } else {
            log_event("Flame detected: NO");
        }

        struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

