#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x1D // Example address, adjust as needed
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "vibration_log.csv"

static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_sensor_data(short *x, short *y, short *z) {
    unsigned char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    // Check for sensor absent condition (example: all values are 0)
    if (*x == 0 && *y == 0 && *z == 0) {
        fprintf(stderr, "Sensor absent or not responding\n");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_END) == 0) {
        if (ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,X,Y,Z\n");
        }
    } else {
        perror("Failed to seek in log file");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        short x, y, z;
        if (read_sensor_data(&x, &y, &z) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = gmtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

            fprintf(log_file, "%s,%hd,%hd,%hd\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

