#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get line for sensor 1: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get line for sensor 2: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Failed to request lines as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_MONOTONIC, &current);
        long long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000LL +
                               (current.tv_nsec - start.tv_nsec) / 1000000LL;

        fprintf(log_file, "%lld ms: Sensor1=%d, Sensor2=%d\n", elapsed_ms, sensor1_value, sensor2_value);
        fflush(log_file);

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("HALT: Both sensors are active\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

