#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG_REG 0x0E
#define OUT_X_MSB_REG 0x01

#define EXPECTED_WHO_AM_I 0x2A
#define DATA_RATE_100HZ 0x07
#define ACTIVE_MODE 0x01

#define TILT_THRESHOLD 45.0

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    ssize_t bytes_written = write(fd, buf, sizeof(buf));
    if (bytes_written != sizeof(buf)) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register for read: %s\n", strerror(errno));
        return -1;
    }
    ssize_t bytes_read = read(fd, value, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, CTRL_REG1, 0x00) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, XYZ_DATA_CFG_REG, 0x00) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, CTRL_REG1, DATA_RATE_100HZ | ACTIVE_MODE) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    int16_t x, y, z;
    float tilt;
    struct timespec ts;

    while (1) {
        if (i2c_read(i2c_fd, OUT_X_MSB_REG, data, 6) != 0) {
            continue;
        }

        x = (int16_t)((data[0] << 8) | data[1]);
        y = (int16_t)((data[2] << 8) | data[3]);
        z = (int16_t)((data[4] << 8) | data[5]);

        x >>= 4;
        y >>= 4;
        z >>= 4;

        tilt = atan2(sqrt(y * y + z * z), x) * 180.0 / M_PI;

        if (tilt > TILT_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fflush(log_file);
        }

        nanosleep(&(struct timespec){0, 10000000}, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

