#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3MDL_ADDR 0x1E
#define SAMPLE_RATE 10
#define SENSITIVITY 0.146
#define ALERT_THRESHOLD 800.0
#define CALIBRATION_OFFSET_X 0.0
#define CALIBRATION_OFFSET_Y 0.0
#define CALIBRATION_OFFSET_Z 0.0
#define CALIBRATION_SCALE_X 1.0
#define CALIBRATION_SCALE_Y 1.0
#define CALIBRATION_SCALE_Z 1.0
#define LOG_FILE "magnetic_log.txt"

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int lis3mdl_init() {
    uint8_t ctrl_reg1 = 0x00;
    uint8_t ctrl_reg2 = 0x00;
    uint8_t ctrl_reg3 = 0x00;
    uint8_t ctrl_reg4 = 0x00;
    uint8_t ctrl_reg5 = 0x00;

    // Set ODR to 10 Hz, full scale to ±4 gauss, and enable temperature sensor
    ctrl_reg1 = 0x60;
    ctrl_reg2 = 0x00;
    ctrl_reg3 = 0x00;
    ctrl_reg4 = 0x20;
    ctrl_reg5 = 0x00;

    if (i2c_write(i2c_fd, 0x20, ctrl_reg1) != 2 ||
        i2c_write(i2c_fd, 0x21, ctrl_reg2) != 2 ||
        i2c_write(i2c_fd, 0x22, ctrl_reg3) != 2 ||
        i2c_write(i2c_fd, 0x23, ctrl_reg4) != 2 ||
        i2c_write(i2c_fd, 0x24, ctrl_reg5) != 2) {
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (retries < 3 && lis3mdl_init() != 0) {
        fprintf(stderr, "Sensor initialization failed, retrying...\n");
        retries++;
        sleep(1);
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to initialize sensor after 3 attempts\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float x, y, z, magnitude;

    while (1) {
        if (i2c_read(i2c_fd, 0x28, data, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        x = (int16_t)((data[0] << 8) | data[1]) * SENSITIVITY * CALIBRATION_SCALE_X + CALIBRATION_OFFSET_X;
        y = (int16_t)((data[2] << 8) | data[3]) * SENSITIVITY * CALIBRATION_SCALE_Y + CALIBRATION_OFFSET_Y;
        z = (int16_t)((data[4] << 8) | data[5]) * SENSITIVITY * CALIBRATION_SCALE_Z + CALIBRATION_OFFSET_Z;

        magnitude = sqrt(x*x + y*y + z*z);

        fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
        fflush(log_file);

        if (magnitude > ALERT_THRESHOLD) {
            fprintf(stderr, "Metal detector alert! Total field magnitude: %.2f mG\n", magnitude);
        }

        usleep(1000000 / SAMPLE_RATE);
    }

    return EXIT_SUCCESS;
}

