        i2c_write(i2c_fd, 0x23, ctrl_reg4) != 2 ||
        i2c_write(i2c_fd, 0x24, ctrl_reg5) != 2) {
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (retries < 3 && lis3mdl_init() != 0) {
        fprintf(stderr, "Sensor initialization failed, retrying...\n");
        retries++;
        sleep(1);
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to initialize sensor after 3 attempts\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float x, y, z, magnitude;

    while (1) {
        if (i2c_read(i2c_fd, 0x28, data, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        x = (int16_t)((data[0] << 8) | data[1]) * SENSITIVITY * CALIBRATION_SCALE_X + CALIBRATION_OFFSET_X;
        y = (int16_t)((data[2] << 8) | data[3]) * SENSITIVITY * CALIBRATION_SCALE_Y + CALIBRATION_OFFSET_Y;
        z = (int16_t)((data[4] << 8) | data[5]) * SENSITIVITY * CALIBRATION_SCALE_Z + CALIBRATION_OFFSET_Z;

        magnitude = sqrt(x*x + y*y + z*z);

        fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
        fflush(log_file);

        if (magnitude > ALERT_THRESHOLD) {
            fprintf(stderr, "Metal detector alert! Total field magnitude: %.2f mG\n", magnitude);
        }

        usleep(1000000 / SAMPLE_RATE);
    }

    return EXIT_SUCCESS;
}
