#define STATUS_REG 0x2B
#define DATA_FORMAT_REG 0x31
#define XDATA3_REG 0x08
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0};
    uint8_t rx[2] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_transfer(tx, rx, 2) == 0) {
            *value = rx[1];
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_transfer(tx, NULL, 2) == 0) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(CE_PIN, PI_OUTPUT);
    gpioWrite(CE_PIN, PI_LOW);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Reset sequence
    if (write_register(RESET_REG, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        cleanup(0);
    }
    usleep(1000);

    if (write_register(POWER_CTL_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to clear RUN bit\n");
        cleanup(0);
    }

    uint8_t status;
    while (1) {
        if (read_register(STATUS_REG, &status) != 0) {
            fprintf(stderr, "Failed to read status register\n");
            cleanup(0);
        }
        if (status & 0x08) break;
        usleep(1000);
    }

    if (write_register(POWER_CTL_REG, 0x28) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        cleanup(0);
    }

    // Verify sensor presence
    uint8_t partid;
    if (read_register(0x00, &partid) != 0 || partid != ADXL354B_PARTID) {
        fprintf(stderr, "ADXL354B not detected\n");
        cleanup(0);
    }

    // Configure data format
    if (write_register(DATA_FORMAT_REG, 0x0B) != 0) {
        fprintf(stderr, "Failed to configure data format\n");
        cleanup(0);
    }

    time_t last_log_time = 0;
    while (1) {
        int16_t x, y, z;
        uint8_t data[6];

        if (read_register(XDATA3_REG | 0x80, data) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            cleanup(0);
        }

        x = (int16_t)((data[0] << 8) | data[1]);
        y = (int16_t)((data[2] << 8) | data[3]);
        z = (int16_t)((data[4] << 8) | data[5]);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            fprintf(log_file, "%ld,%d,%d,%d\n", (long)current_time, x, y, z);
            fflush(log_file);
            last_log_time = current_time;
        }

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

