#include <gpiod.h>
#include <spi/spi.h>

#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_3
#define CE_PIN 8
#define LOG_FILE "imu_log.csv"
#define SAMPLE_DELAY_MS 10
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025

static int spi_fd = -1;
static FILE *log_file = NULL;
static struct spi_ioc_transfer xfer[2];

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    struct spi_ioc_transfer *x = &xfer[0];
    memset(x, 0, sizeof(*x));
    x->tx_buf = (unsigned long)NULL;
    x->rx_buf = (unsigned long)NULL;
    x->len = 0;
    x->delay_usecs = 0;
    x->speed_hz = SPI_SPEED;
    x->bits_per_word = 8;
    x->cs_change = 0;

    x = &xfer[1];
    memset(x, 0, sizeof(*x));
    x->rx_buf = (unsigned long)NULL;
    x->len = 0;
    x->delay_usecs = 0;
    x->speed_hz = SPI_SPEED;
    x->bits_per_word = 8;
    x->cs_change = 0;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_imu_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t tx[2], rx[2];
    int16_t raw_gyro[3], raw_accel[3];

    for (int i = 0; i < 3; i++) {
        tx[0] = 0x80 | (i * 2);
        tx[1] = 0x00;

        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = (unsigned long)rx;
        xfer[0].len = 2;

        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("SPI transfer failed");
            return -1;
        }

        raw_gyro[i] = (rx[0] << 8) | rx[1];
    }

    for (int i = 0; i < 3; i++) {
        tx[0] = 0xA0 | (i * 2);
        tx[1] = 0x00;

        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = (unsigned long)rx;
        xfer[0].len = 2;

        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 2;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("SPI transfer failed");
            return -1;
        }

        raw_accel[i] = (rx[0] << 8) | rx[1];
    }

    *gyro_x = raw_gyro[0];
    *gyro_y = raw_gyro[1];
    *gyro_z = raw_gyro[2];
    *accel_x = raw_accel[0];
    *accel_y = raw_accel[1];
    *accel_z = raw_accel[2];

    return 0;
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    if (signal(SIGINT, cleanup) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (1) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) < 0) {
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get timestamp");
            continue;
        }

        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s.%09ld,%.2f,%.2f,%.2f,%.4f,%.4f,%.4f\n",
                timestamp, ts.tv_nsec,
                gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE,
                accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);
        fflush(log_file);

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

