#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec wait_interval = {0, 1000000}; // 1ms
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting line for sensor 1\n");
        goto cleanup_chip;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting line for sensor 2\n");
        goto cleanup_sensor1;
    }

    ret = gpiod_line_request_input(sensor1_line, "sensor1");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for sensor 1\n");
        goto cleanup_sensor2;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input for sensor 2\n");
        goto cleanup_sensor1;
    }

    struct gpiod_line_bulk bulk;
    gpiod_line_bulk_init(&bulk);
    gpiod_line_bulk_add(&bulk, sensor1_line);
    gpiod_line_bulk_add(&bulk, sensor2_line);

    while (keep_running) {
        struct timespec start, current;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int values[2];
        ret = gpiod_line_bulk_read_values(&bulk, values);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        printf("%sSensor 1: %s, Sensor 2: %s\n", ctime(&now),
               values[0] == 0 ? "Obstacle detected" : "Path clear",
               values[1] == 0 ? "Obstacle detected" : "Path clear");

        clock_gettime(CLOCK_MONOTONIC, &current);
        long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 +
                          (current.tv_nsec - start.tv_nsec) / 1000000;

        if (elapsed_ms < POLL_INTERVAL_MS) {
            nanosleep(&wait_interval, NULL);
        }
    }

cleanup_sensor2:
    gpiod_line_release(sensor2_line);
cleanup_sensor1:
    gpiod_line_release(sensor1_line);
cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

