#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_3
#define BUFFER_SIZE 3
#define SCALE_FACTOR 0.02
#define READ_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_open() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[BUFFER_SIZE] = {0x3E | 0x80, 0x00, 0x00};
    uint8_t rx[BUFFER_SIZE] = {0};

    if (spi_transfer(fd, tx, rx, BUFFER_SIZE) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *x = (int16_t)((rx[1] << 8) | rx[2]);
    *y = (int16_t)((rx[3] << 8) | rx[4]);
    *z = (int16_t)((rx[5] << 8) | rx[6]);

    return 0;
}

int main() {
    int fd = spi_open();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        int16_t x, y, z;
        if (read_gyro(fd, &x, &y, &z) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
                   x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);
        }
        usleep(READ_INTERVAL_MS * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

