#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM6DSR_I2C_ADDR 0x6B
#define WHO_AM_I_REG 0x0F
#define OUTX_L_A 0x28
#define OUTY_L_A 0x2A
#define OUTZ_L_A 0x2C
#define OUTX_L_G 0x18
#define OUTY_L_G 0x1A
#define OUTZ_L_G 0x1C

int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM6DSR_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) != 1 || who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec ts = {0, 100000000}; // 100ms

    while (1) {
        int16_t acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z;
        uint8_t buf[6];

        if (i2c_read(i2c_fd, OUTX_L_A, buf, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        acc_x = (int16_t)(buf[1] << 8 | buf[0]);
        acc_y = (int16_t)(buf[3] << 8 | buf[2]);
        acc_z = (int16_t)(buf[5] << 8 | buf[4]);

        if (i2c_read(i2c_fd, OUTX_L_G, buf, 6) != 6) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        gyro_x = (int16_t)(buf[1] << 8 | buf[0]);
        gyro_y = (int16_t)(buf[3] << 8 | buf[2]);
        gyro_z = (int16_t)(buf[5] << 8 | buf[4]);

        printf("%d %d %d %d %d %d\n", acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z);

        if (nanosleep(&ts, NULL) != 0) {
            perror("nanosleep");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

