#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define TILT_THRESHOLD 30.0
#define SAMPLE_INTERVAL_MS 100

#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) return -1;
    *x = (buf[1] << 8) | buf[0];
    *y = (buf[3] << 8) | buf[2];
    *z = (buf[5] << 8) | buf[4];
    return 0;
}

double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = x / 256.0;
    double y_g = y / 256.0;
    double z_g = z / 256.0;
    return atan2(sqrt(x_g * x_g + y_g * y_g), z_g) * (180.0 / M_PI);
}

int main() {
    int i2c_fd;
    char filename[20];
    FILE *log_file;
    struct timespec ts;
    char timestamp[64];
    int16_t x, y, z;
    double tilt;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < I2C_RETRIES; i++) {
        if (i2c_write(i2c_fd, ADXL345_POWER_CTL, 0x08) == 1 &&
            i2c_write(i2c_fd, ADXL345_DATA_FORMAT, 0x08) == 1) {
            break;
        }
        if (i == I2C_RETRIES - 1) {
            fprintf(stderr, "Failed to initialize ADXL345\n");
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }

    log_file = fopen("/var/log/tilt_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        for (int i = 0; i < I2C_RETRIES; i++) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                tilt = calculate_tilt(x, y, z);
                if (tilt > TILT_THRESHOLD) {
                    clock_gettime(CLOCK_REALTIME, &ts);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    fprintf(log_file, "[%s.%09ld] Tilt: %.2f degrees\n", timestamp, ts.tv_nsec, tilt);
                    fflush(log_file);
                }
                break;
            }
            if (i == I2C_RETRIES - 1) {
                fprintf(stderr, "Failed to read acceleration data\n");
            }
            usleep(I2C_RETRY_DELAY_MS * 1000);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

