#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define PIN 17
#define WINDOW_DURATION_MS 5000
#define SAMPLE_INTERVAL_MS 1
#define STATUS_WAIT_MS 1000

static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold;
    char *endptr;
    errno = 0;
    threshold = strtol(argv[1], &endptr, 10);

    if (errno != 0 || endptr == argv[1] || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int high_count;
    struct timespec start, current;
    struct tm *tm_info;
    char timestamp[64];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "KY-038 Sound Sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line as input: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        high_count = 0;
        clock_gettime(CLOCK_REALTIME, &start);

        for (int i = 0; i < WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS; i++) {
            value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line: %s\n", strerror(-value));
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
            if (value == 1) {
                high_count++;
            }
            clock_nanosleep(CLOCK_REALTIME, 0, SAMPLE_INTERVAL_MS * 1000000, NULL);
        }

        clock_gettime(CLOCK_REALTIME, &current);
        tm_info = localtime(&current.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s Status: High readings = %d\n", timestamp, high_count);
        }

        clock_nanosleep(CLOCK_REALTIME, 0, STATUS_WAIT_MS * 1000000, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

