#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x23
#define CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define LOG_INTERVAL_SEC 5

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = write(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = read(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int bh1750_init(int fd) {
    uint8_t cmd = 0x01; // Power on
    if (i2c_write(fd, &cmd, 1) < 0) {
        return -1;
    }
    usleep(CONVERSION_TIME_MS * 1000);
    return 0;
}

int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    uint8_t cmd = 0x10; // Read data
    if (i2c_write(fd, &cmd, 1) < 0) {
        return -1;
    }
    usleep(CONVERSION_TIME_MS * 1000);
    if (i2c_read(fd, buf, 2) < 0) {
        return -1;
    }
    *lux = (buf[0] << 8 | buf[1]) / 1.2;
    return 0;
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t last_log_time = time(NULL);

    while (1) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux from sensor\n");
        } else {
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= LOG_INTERVAL_SEC) {
                fprintf(log_file, "Timestamp: %ld, Lux: %.2f\n", (long)current_time, lux);
                fflush(log_file);
                last_log_time = current_time;
            }
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

