#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define TCP_PORT 12345
#define PWM_PIN 18
#define SAMPLE_INTERVAL_MS 20
#define TONE_DURATION_MS 5000
#define SHARED_SECRET "MySecretKey"

static int i2c_fd;
static int tcp_socket;
static int pwm_handle;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (pwm_handle >= 0) gpioPWM(pwm_handle, 0);
    if (pwm_handle >= 0) gpioSetMode(PWM_PIN, PI_INPUT);
    if (tcp_socket >= 0) close(tcp_socket);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int mpr121_init() {
    unsigned char data[2];
    // Soft reset
    data[0] = 0x60;
    data[1] = 0x63;
    if (write(i2c_fd, data, 2) != 2) return -1;
    usleep(10000); // Wait for reset

    // Configure electrodes
    data[0] = 0x5E;
    data[1] = 0x00;
    if (write(i2c_fd, data, 2) != 2) return -1;
    return 0;
}

int mpr121_read_touch() {
    unsigned char data[2];
    data[0] = 0x00;
    if (write(i2c_fd, data, 1) != 1) return -1;
    if (read(i2c_fd, data, 2) != 2) return -1;
    return (data[0] << 8) | data[1];
}

void play_tone(int freq) {
    gpioSetPWMfrequency(PWM_PIN, freq);
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
    usleep(TONE_DURATION_MS * 1000);
    gpioPWM(PWM_PIN, 0);
}

int main() {
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[1024];
    int val;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open failed");
        cleanup(0);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("I2C set address failed");
        cleanup(0);
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup(0);
    }

    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        perror("Socket creation failed");
        cleanup(0);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        cleanup(0);
    }

    if (listen(tcp_socket, 1) < 0) {
        perror("Listen failed");
        cleanup(0);
    }

    printf("Waiting for connection...\n");
    int client_socket = accept(tcp_socket, (struct sockaddr*)&client_addr, &client_len);
    if (client_socket < 0) {
        perror("Accept failed");
        cleanup(0);
    }

    printf("Client connected\n");

    while (1) {
        memset(buffer, 0, sizeof(buffer));
        val = read(client_socket, buffer, sizeof(buffer) - 1);
        if (val < 0) {
            perror("Read failed");
            break;
        }
        if (val == 0) {
            printf("Client disconnected\n");
            break;
        }

        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0 &&
            strstr(buffer, SHARED_SECRET) != NULL) {
            printf("Valid command received\n");

            FILE *log_file = fopen("frequency_log.txt", "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }

            for (int i = 0; i < TONE_DURATION_MS / SAMPLE_INTERVAL_MS; i++) {
                int touch_value = mpr121_read_touch();
                int freq = 200 + (touch_value & 0x3FF); // Map touch value to 200-1220 Hz
                play_tone(freq);
                fprintf(log_file, "%d\n", freq);
                fflush(log_file);
                usleep(SAMPLE_INTERVAL_MS * 1000);
            }

            fclose(log_file);
        }
    }

    close(client_socket);
    cleanup(0);
    return 0;
}

