    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup(0);
    }

    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        perror("Socket creation failed");
        cleanup(0);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        cleanup(0);
    }

    if (listen(tcp_socket, 1) < 0) {
        perror("Listen failed");
        cleanup(0);
    }

    printf("Waiting for connection...\n");
    int client_socket = accept(tcp_socket, (struct sockaddr*)&client_addr, &client_len);
    if (client_socket < 0) {
        perror("Accept failed");
        cleanup(0);
    }

    printf("Client connected\n");

    while (1) {
        memset(buffer, 0, sizeof(buffer));
        val = read(client_socket, buffer, sizeof(buffer) - 1);
        if (val < 0) {
            perror("Read failed");
            break;
        }
        if (val == 0) {
            printf("Client disconnected\n");
            break;
        }

        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0 &&
            strstr(buffer, SHARED_SECRET) != NULL) {
            printf("Valid command received\n");

            FILE *log_file = fopen("frequency_log.txt", "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }

            for (int i = 0; i < TONE_DURATION_MS / SAMPLE_INTERVAL_MS; i++) {
                int touch_value = mpr121_read_touch();
                int freq = 200 + (touch_value & 0x3FF); // Map touch value to 200-1220 Hz
                play_tone(freq);
                fprintf(log_file, "%d\n", freq);
                fflush(log_file);
                usleep(SAMPLE_INTERVAL_MS * 1000);
            }

            fclose(log_file);
        }
    }

    close(client_socket);
    cleanup(0);
    return 0;
}
