int main() {
    struct i2c_msg messages[1];
    char buffer[6];
    int16_t z_axis;
    float z_axis_magnitude;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pwm_handle = gpioHardwarePWM(PWM_PIN, 1000);
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        messages[0].addr = I2C_ADDR;
        messages[0].flags = 0;
        messages[0].len = 6;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "I2C read error\n");
        } else {
            z_axis = (buffer[1] << 8) | buffer[0];
            z_axis_magnitude = (float)z_axis / 16.0f;

            if (z_axis_magnitude < 0) z_axis_magnitude = 0;
            if (z_axis_magnitude > 1023) z_axis_magnitude = 1023;

            gpioPWM(pwm_handle, (uint16_t)z_axis_magnitude);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

