#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SAMPLES 100
#define INTERVAL_MS 500

typedef struct {
    int16_t x[SAMPLES];
    int16_t y[SAMPLES];
    int16_t z[SAMPLES];
    int index;
} MagBuffer;

MagBuffer magBuffer = {0};
int running = 1;

void cleanup(int signum) {
    running = 0;
}

int16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (i2cReadI2CBlockData(fd, reg, buf, 2) < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return 0;
    }
    return (buf[0] << 8) | buf[1];
}

void write_i2c_word(int fd, uint8_t reg, int16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = value >> 8;
    buf[2] = value & 0xFF;
    if (i2cWriteI2CBlockData(fd, reg, buf, 3) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
    }
}

void update_buffer(int16_t x, int16_t y, int16_t z) {
    magBuffer.x[magBuffer.index] = x;
    magBuffer.y[magBuffer.index] = y;
    magBuffer.z[magBuffer.index] = z;
    magBuffer.index = (magBuffer.index + 1) % SAMPLES;
}

void compute_offsets(int16_t *offset_x, int16_t *offset_y, int16_t *offset_z) {
    int32_t sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < SAMPLES; i++) {
        sum_x += magBuffer.x[i];
        sum_y += magBuffer.y[i];
        sum_z += magBuffer.z[i];
    }
    *offset_x = sum_x / SAMPLES;
    *offset_y = sum_y / SAMPLES;
    *offset_z = sum_z / SAMPLES;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Configure HMC5883L
    write_i2c_word(fd, 0x00, 0x70); // Configuration register A
    write_i2c_word(fd, 0x01, 0xA0); // Configuration register B
    write_i2c_word(fd, 0x02, 0x00); // Mode register

    int16_t offset_x = 0, offset_y = 0, offset_z = 0;

    while (running) {
        int16_t x = read_i2c_word(fd, 0x03);
        int16_t y = read_i2c_word(fd, 0x05);
        int16_t z = read_i2c_word(fd, 0x07);

        update_buffer(x, y, z);

        if (magBuffer.index == 0) { // Buffer is full
            compute_offsets(&offset_x, &offset_y, &offset_z);
            printf("Offset-corrected: X=%d Y=%d Z=%d\n",
                   x - offset_x, y - offset_y, z - offset_z);
        }

        usleep(INTERVAL_MS * 1000);
    }

    i2cClose(fd);
    gpioTerminate();
    return 0;
}

