#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303D_ADDR 0x19
#define BUFFER_SIZE 64
#define SAMPLE_INTERVAL_MS 10
#define INT1_PIN 23
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_OUT_X_L 0x28
#define LSM303D_INT1_CFG 0x37
#define LSM303D_INT1_THS 0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_WHO_AM_I_VALUE 0x33
#define LSM303D_POWER_DOWN 0x00
#define LSM303D_NORMAL_MODE 0x27
#define LSM303D_SENSITIVITY 0.061f

typedef struct {
    int16_t x, y, z;
} Sample;

Sample buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    return write(fd, data, sizeof(data));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t data[2];
    if (i2c_read(fd, reg, data) != 2) return -1;
    *value = (int16_t)((data[1] << 8) | data[0]);
    return 0;
}

int main() {
    uint8_t who_am_i;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_read(i2c_fd, LSM303D_WHO_AM_I, &who_am_i) != 1 || who_am_i != LSM303D_WHO_AM_I_VALUE) {
        fprintf(stderr, "LSM303D device not found or incorrect ID\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, LSM303D_CTRL_REG1, LSM303D_NORMAL_MODE) != 1) {
        perror("Failed to set accelerometer mode");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, LSM303D_INT1_THS, 32) != 1) {
        perror("Failed to set interrupt threshold");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, LSM303D_INT1_DURATION, 0) != 1) {
        perror("Failed to set interrupt duration");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, INT1_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "LSM303D_INT1") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_wait(line, 1000000) > 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            tm_info = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("%s.%09ld\n", timestamp, ts.tv_nsec);

            for (int i = 0; i < 10; i++) {
                int idx = (buffer_index - i - 1 + BUFFER_SIZE) % BUFFER_SIZE;
                printf("Sample %d: X=%d Y=%d Z=%d\n", i + 1, buffer[idx].x, buffer[idx].y, buffer[idx].z);
            }
        }

        int16_t x, y, z;
        if (i2c_read_word(i2c_fd, LSM303D_OUT_X_L | 0x80, &x) == 0 &&
            i2c_read_word(i2c_fd, LSM303D_OUT_X_L + 2 | 0x80, &y) == 0 &&
            i2c_read_word(i2c_fd, LSM303D_OUT_X_L + 4 | 0x80, &z) == 0) {
            buffer[buffer_index].x = x;
            buffer[buffer_index].y = y;
            buffer[buffer_index].z = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

