#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/select.h>

#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"
#define BAUD_RATE B9600
#define TIMEOUT_SECONDS 5
#define EXPECTED_CODE "123456"
#define RELAY_GPIO1 17
#define RELAY_GPIO2 27

static int uart_fd[2];
static struct gpiod_chip *chip;
static struct gpiod_line *relay1, *relay2;
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    keep_running = 0;
}

static int set_interface_attribs(int fd, int speed, int parity) {
    struct termios tty;

    if (tcgetattr(fd, &tty) < 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        return -1;
    }

    cfsetospeed(&tty, speed);
    cfsetispeed(&tty, speed);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo,
                                                    // no canonical processing
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;                            // read doesn't block
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls,
                                                    // enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag |= parity;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void set_blocking(int fd, int should_block) {
    struct termios tty;
    memset(&tty, 0, sizeof tty);
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tggetattr: %s\n", strerror(errno));
        return;
    }

    tty.c_cc[VMIN] = should_block ? 1 : 0;
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting blocking: %s\n", strerror(errno));
    }
}

static int read_code(int fd, char *code, size_t size) {
    fd_set read_fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);

    tv.tv_sec = TIMEOUT_SECONDS;
    tv.tv_usec = 0;

    ret = select(fd + 1, &read_fds, NULL, NULL, &tv);
    if (ret == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Read timeout on fd %d\n", fd);
        return -1;
    }

    ssize_t n = read(fd, code, size);
    if (n < 0) {
        fprintf(stderr, "Error reading from fd %d: %s\n", fd, strerror(errno));
        return -1;
    }

    code[n] = '\0';
    return 0;
}

static int constant_time_compare(const char *a, const char *b) {
    size_t i;
    int ret = 0;

    for (i = 0; i < strlen(EXPECTED_CODE); i++) {
        ret |= a[i] ^ b[i];
    }

    return ret == 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handlers\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    relay1 = gpiod_chip_get_line(chip, RELAY_GPIO1);
    relay2 = gpiod_chip_get_line(chip, RELAY_GPIO2);

    if (!relay1 || !relay2) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay1, "relay1", 0) < 0 ||
        gpiod_line_request_output(relay2, "relay2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output\n");
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uart_fd[0] = open(PRIMARY_UART, O_RDWR | O_NOCTTY | O_SYNC);
    uart_fd[1] = open(SECONDARY_UART, O_RDWR | O_NOCTTY | O_SYNC);

    if (uart_fd[0] < 0 || uart_fd[1] < 0) {
        fprintf(stderr, "Error opening UART devices\n");
        gpiod_line_set_value(relay1, 0);
        gpiod_line_set_value(relay2, 0);
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    set_interface_attribs(uart_fd[0], BAUD_RATE, 0);
    set_interface_attribs(uart_fd[1], BAUD_RATE, 0);
    set_blocking(uart_fd[0], 0);
    set_blocking(uart_fd[1], 0);

    char code1[7] = {0}, code2[7] = {0};

    while (keep_running) {
        int ret1 = read_code(uart_fd[0], code1, sizeof(code1));
        int ret2 = read_code(uart_fd[1], code2, sizeof(code2));

        if (ret1 == 0 && ret2 == 0) {
            if (constant_time_compare(code1, code2) && constant_time_compare(code1, EXPECTED_CODE)) {
                gpiod_line_set_value(relay1, 1);
                gpiod_line_set_value(relay2, 1);
                sleep(2);
                gpiod_line_set_value(relay1, 0);
                gpiod_line_set_value(relay2, 0);
            }
        }

        memset(code1, 0, sizeof(code1));
        memset(code2, 0, sizeof(code2));
    }

    gpiod_line_set_value(relay1, 0);
    gpiod_line_set_value(relay2, 0);
    gpiod_line_release(relay1);
    gpiod_line_release(relay2);
    gpiod_chip_close(chip);
    close(uart_fd[0]);
    close(uart_fd[1]);

    return EXIT_SUCCESS;
}

