#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define RELAY_PINS[4] = {4, 17, 27, 22}
#define CYCLE_TIME 300
#define PAUSE_TIME 60
#define CYCLE_COUNT 4

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void set_relay(struct gpiod_chip *chip, int pin, int state) {
    int ret;
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for GPIO %d", pin);
        return;
    }

    ret = gpiod_line_request_output(line, "irrigation_system", state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d to %d", pin, state);
    }

    gpiod_line_release(line);
}

int main() {
    struct gpiod_chip *chip;
    int i, j;
    time_t start_time, current_time;
    struct sigaction sa;

    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    for (i = 0; i < 4; i++) {
        set_relay(chip, RELAY_PINS[i], 1);
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    while (keep_running) {
        start_time = time(NULL);

        for (i = 0; i < CYCLE_COUNT && keep_running; i++) {
            set_relay(chip, RELAY_PINS[i], 0);
            syslog(LOG_INFO, "Relay %d activated", i + 1);

            while (difftime(time(NULL), start_time) < CYCLE_TIME && keep_running) {
                sleep(1);
            }

            set_relay(chip, RELAY_PINS[i], 1);
            syslog(LOG_INFO, "Relay %d deactivated", i + 1);

            start_time = time(NULL);
            while (difftime(time(NULL), start_time) < PAUSE_TIME && keep_running) {
                sleep(1);
            }
        }
    }

    for (i = 0; i < 4; i++) {
        set_relay(chip, RELAY_PINS[i], 1);
    }

    gpiod_chip_close(chip);
    closelog();
    return 0;
}

