#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 1000
#define SAMPLE_RATE 100 // Hz

typedef struct {
    float x, y, z;
} AccelSample;

AccelSample buffer[BUFFER_SIZE];
int bufferIndex = 0;
int i2cFd;
int timerFd;
int driverFd;
char *driverPath = "/sys/kernel/mpu6050_accel/latest";

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (i2cFd >= 0) close(i2cFd);
    if (timerFd >= 0) close(timerFd);
    if (driverFd >= 0) close(driverFd);
    munmap(buffer, sizeof(buffer));
    exit(0);
}

void signalHandler(int signum) {
    cleanup(signum);
}

int initI2C() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int readAccelData(int fd, float *x, float *y, float *z) {
    unsigned char data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    *x = (float)(data[0] << 8 | data[1]) / 16384.0;
    *y = (float)(data[2] << 8 | data[3]) / 16384.0;
    *z = (float)(data[4] << 8 | data[5]) / 16384.0;

    return 0;
}

void timerCallback(union sigval sv) {
    float x, y, z;
    if (readAccelData(i2cFd, &x, &y, &z) == 0) {
        buffer[bufferIndex].x = x;
        buffer[bufferIndex].y = y;
        buffer[bufferIndex].z = z;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

        // Update driver interface
        char bufferStr[100];
        snprintf(bufferStr, sizeof(bufferStr), "%.2f,%.2f,%.2f", x, y, z);
        lseek(driverFd, 0, SEEK_SET);
        write(driverFd, bufferStr, strlen(bufferStr));
    }
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    i2cFd = initI2C();
    if (i2cFd < 0) {
        fprintf(stderr, "MPU6050 not found or I2C bus error\n");
        return 1;
    }

    buffer = mmap(NULL, sizeof(buffer), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to allocate memory for buffer");
        cleanup(0);
    }

    driverFd = open(driverPath, O_RDWR);
    if (driverFd < 0) {
        perror("Failed to open driver interface");
        cleanup(0);
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(struct sigevent));
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = timerCallback;

    timerFd = timer_create(CLOCK_REALTIME, &sev, NULL);
    if (timerFd < 0) {
        perror("Failed to create timer");
        cleanup(0);
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 1000000000 / SAMPLE_RATE;
    its.it_interval = its.it_value;

    if (timer_settime(timerFd, 0, &its, NULL) < 0) {
        perror("Failed to start timer");
        cleanup(0);
    }

    printf("Sampling started. Press Ctrl+C to exit.\n");
    while (1) {
        pause();
    }

    return 0;
}

