#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define RELAY_COUNT 4
const int relay_pins[RELAY_COUNT] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

struct gpiod_chip *chip;
struct gpiod_line *lines[RELAY_COUNT];
int running = 1;

void cleanup() {
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec start, current;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for relay %d\n", i + 1);
            cleanup();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(lines[i], "relay", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for relay %d\n", i + 1);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current);

        for (int i = 0; i < RELAY_COUNT; i++) {
            long elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;
            if (elapsed % (i + 2) == 0) {
                int value = gpiod_line_get_value(lines[i]);
                if (value < 0) {
                    fprintf(stderr, "Failed to get value for relay %d\n", i + 1);
                    running = 0;
                    break;
                }
                ret = gpiod_line_set_value(lines[i], !value);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set value for relay %d\n", i + 1);
                    running = 0;
                    break;
                }
            }
        }

        // Sleep for a short time to reduce CPU usage
        struct timespec sleep_time = {0, 100000000}; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

