    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current);

        for (int i = 0; i < RELAY_COUNT; i++) {
            long elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;
            if (elapsed % (i + 2) == 0) {
                int value = gpiod_line_get_value(lines[i]);
                if (value < 0) {
                    fprintf(stderr, "Failed to get value for relay %d\n", i + 1);
                    running = 0;
                    break;
                }
                ret = gpiod_line_set_value(lines[i], !value);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set value for relay %d\n", i + 1);
                    running = 0;
                    break;
                }
            }
        }

        // Sleep for a short time to reduce CPU usage
        struct timespec sleep_time = {0, 100000000}; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}
