#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

typedef struct {
    float x, y, z;
} Vector3;

typedef struct {
    Vector3 data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_fd;
static CircularBuffer buffer = {.head = 0, .count = 0};
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

bool init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return false;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to select MPU6050");
        close(i2c_fd);
        return false;
    }

    return true;
}

bool write_i2c(uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to MPU6050");
        return false;
    }
    return true;
}

bool read_i2c(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return false;
    }

    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read from MPU6050");
        return false;
    }
    return true;
}

bool init_mpu6050() {
    if (!write_i2c(0x6B, 0x00)) return false; // Wake up MPU6050
    if (!write_i2c(0x1B, 0x08)) return false; // Set gyro full scale to ±500°/s
    return true;
}

bool read_gyro(Vector3 *gyro) {
    uint8_t buf[6];
    if (!read_i2c(0x43, buf, 6)) return false;

    gyro->x = (int16_t)(buf[0] << 8 | buf[1]) / 131.0;
    gyro->y = (int16_t)(buf[2] << 8 | buf[3]) / 131.0;
    gyro->z = (int16_t)(buf[4] << 8 | buf[5]) / 131.0;

    return true;
}

void add_to_buffer(Vector3 *gyro) {
    buffer.data[buffer.head] = *gyro;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }
}

float calculate_magnitude(Vector3 *gyro) {
    return sqrt(gyro->x * gyro->x + gyro->y * gyro->y + gyro->z * gyro->z);
}

void user_callback(Vector3 *gyro) {
    printf("High angular velocity detected: %.2f°/s\n", calculate_magnitude(gyro));
}

int main() {
    if (!init_i2c()) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    if (!init_mpu6050()) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        Vector3 gyro;
        if (read_gyro(&gyro)) {
            add_to_buffer(&gyro);
            if (calculate_magnitude(&gyro) > THRESHOLD) {
                user_callback(&gyro);
            }
        }
        usleep(10000); // 10ms delay
    }

    close(i2c_fd);
    return 0;
}

