#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE B9600
#define BUFFER_SIZE 9
#define RETRY_DELAY_MS 100
#define TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_SEC 5

static int uart_fd = -1;
static FILE *co2_log = NULL;
static FILE *co2_error = NULL;

void cleanup(int signum) {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (co2_log != NULL) {
        fclose(co2_log);
    }
    if (co2_error != NULL) {
        fclose(co2_error);
    }
    exit(EXIT_SUCCESS);
}

int set_interface_attribs(int fd, int speed) {
    struct termios tty;
    if (tcgetattr(fd, &tty) < 0) {
        perror("Error from tcgetattr");
        return -1;
    }

    cfsetospeed(&tty, speed);
    cfsetispeed(&tty, speed);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN] = 0;                             // read doesn't block
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) < 0) {
        perror("Error from tcsetattr");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    uart_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    if (set_interface_attribs(uart_fd, BAUD_RATE) < 0) {
        return EXIT_FAILURE;
    }

    co2_log = fopen("co2_log.json", "a");
    if (co2_log == NULL) {
        perror("Error opening co2_log.json");
        cleanup(0);
    }

    co2_error = fopen("co2_error.log", "a");
    if (co2_error == NULL) {
        perror("Error opening co2_error.log");
        fclose(co2_log);
        cleanup(0);
    }

    unsigned char read_buffer[BUFFER_SIZE];
    unsigned char command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

    while (1) {
        struct timespec start, current;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int bytes_written = write(uart_fd, command, sizeof(command));
        if (bytes_written != sizeof(command)) {
            fprintf(co2_error, "[%ld] Error writing to UART: %s\n", (long)time(NULL), strerror(errno));
            continue;
        }

        int bytes_read = 0;
        while (bytes_read < BUFFER_SIZE) {
            fd_set read_fds;
            FD_ZERO(&read_fds);
            FD_SET(uart_fd, &read_fds);

            struct timeval tv;
            tv.tv_sec = 0;
            tv.tv_usec = RETRY_DELAY_MS * 1000;

            int ret = select(uart_fd + 1, &read_fds, NULL, NULL, &tv);
            if (ret < 0) {
                fprintf(co2_error, "[%ld] Error in select: %s\n", (long)time(NULL), strerror(errno));
                break;
            } else if (ret == 0) {
                clock_gettime(CLOCK_MONOTONIC, &current);
                long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000;
                if (elapsed_ms >= TIMEOUT_MS) {
                    fprintf(co2_error, "[%ld] Timeout waiting for response\n", (long)time(NULL));
                    break;
                }
                continue;
            }

            int n = read(uart_fd, read_buffer + bytes_read, BUFFER_SIZE - bytes_read);
            if (n < 0) {
                fprintf(co2_error, "[%ld] Error reading from UART: %s\n", (long)time(NULL), strerror(errno));
                break;
            }
            bytes_read += n;
        }

        if (bytes_read == BUFFER_SIZE) {
            unsigned char checksum = 0xFF - (command[1] + command[2] + command[3] + command[4] + command[5] + command[6] + command[7]) + 1;
            if (read_buffer[8] == checksum) {
                unsigned int ppm = (read_buffer[2] << 8) | read_buffer[3];
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[64];
                struct tm *tm_info = localtime(&ts.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                char json_line[256];
                snprintf(json_line, sizeof(json_line),
                         "{\"timestamp\":\"%s.%06ld\",\"ppm\":%u,\"error\":false}\n",
                         timestamp, ts.tv_nsec / 1000, ppm);
                fputs(json_line, co2_log);
                fflush(co2_log);
                printf("%s", json_line);
            } else {
                fprintf(co2_error, "[%ld] Checksum mismatch\n", (long)time(NULL));
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup(0);
}

