#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

typedef struct {
    float headings[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

static int i2c_fd;
static CircularBuffer buffer = { .index = 0, .count = 0 };
static int gpio_fd;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

float read_heading() {
    unsigned char data[6];
    if (read(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[4] << 8) | data[5];
    float heading = atan2((float)y, (float)x) * 180.0 / M_PI;
    if (heading < 0) heading += 360;
    return heading;
}

void update_gpio(float heading) {
    if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
        gpiod_line_set_value(gpio_fd, 1);
    } else {
        gpiod_line_set_value(gpio_fd, 0);
    }
}

void add_to_buffer(float heading) {
    buffer.headings[buffer.index] = heading;
    buffer.index = (buffer.index + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpio_set_mode(17, PI_OUTPUT);

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpio_fd = gpiod_chip_get_line(chip, 17);
    if (!gpio_fd) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(gpio_fd, "heading_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (keep_running) {
        float heading = read_heading();
        if (heading >= 0) {
            heading -= HARD_IRON_X;
            if (heading < 0) heading += 360;
            add_to_buffer(heading);
            update_gpio(heading);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(gpio_fd);
    gpiod_chip_close(chip);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

