#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LOG_FILE "lighting_log.txt"
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22

#define BH1750_POWER_ON 0x01
#define BH1750_POWER_DOWN 0x00
#define BH1750_CONT_HIGH_RES_MODE 0x10

#define CONVERSION_DELAY_MS 120

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    cleanup();
    exit(EXIT_FAILURE);
}

int i2c_write(unsigned char *buf, int len) {
    if (write(i2c_fd, buf, len) != len) {
        handle_error("Failed to write to I2C device");
    }
    return 0;
}

int i2c_read(unsigned char *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        handle_error("Failed to read from I2C device");
    }
    return 0;
}

float read_light_level() {
    unsigned char buf[2];
    i2c_write(&BH1750_CONT_HIGH_RES_MODE, 1);
    usleep(CONVERSION_DELAY_MS * 1000);
    i2c_read(buf, 2);
    return (buf[0] << 8 | buf[1]) / 1.2f;
}

void set_relay_state(float lux) {
    gpiod_line_set_value(red_line, lux < 50);
    gpiod_line_set_value(green_line, lux >= 50 && lux < 150);
    gpiod_line_set_value(blue_line, lux >= 150 && lux < 300);
}

int main() {
    struct timespec ts;
    char timestamp[64];
    float lux;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        handle_error("Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        handle_error("Failed to set I2C slave address");
    }

    i2c_write(&BH1750_POWER_ON, 1);
    usleep(10000);  // Wait 10ms for the sensor to power up

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        handle_error("Failed to get GPIO lines");
    }

    gpiod_line_request_output(red_line, "red_relay", 0);
    gpiod_line_request_output(green_line, "green_relay", 0);
    gpiod_line_request_output(blue_line, "blue_relay", 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        handle_error("Failed to open log file");
    }

    atexit(cleanup);

    while (1) {
        lux = read_light_level();
        set_relay_state(lux);

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux,
                gpiod_line_get_value(red_line),
                gpiod_line_get_value(green_line),
                gpiod_line_get_value(blue_line));
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

