#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <unistd.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define CONTROL_LOOP_INTERVAL_MS 100

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int set_gpio_mode(int gpio, int mode) {
    int result = gpiod_ctxless_gpio_set_value(gpio, mode);
    if (result < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pin %d\n", gpio);
        return -1;
    }
    return 0;
}

int set_pwm_duty(int gpio, int duty) {
    if (gpioSetPWMfrequency(gpio, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for pin %d\n", gpio);
        return -1;
    }
    if (gpioSetPWMrange(gpio, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range for pin %d\n", gpio);
        return -1;
    }
    if (gpioSetPWMdutycycle(gpio, duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for pin %d\n", gpio);
        return -1;
    }
    return 0;
}

void stop_motors() {
    set_gpio_mode(MOTOR_A_IN1, 0);
    set_gpio_mode(MOTOR_A_IN2, 0);
    set_gpio_mode(MOTOR_B_IN3, 0);
    set_gpio_mode(MOTOR_B_IN4, 0);
    set_pwm_duty(MOTOR_A_IN2, 0);
    set_pwm_duty(MOTOR_B_IN4, 0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < 10 || distance_motor_a > 100 || distance_motor_b < 10 || distance_motor_b > 100) {
        fprintf(stderr, "Distance values must be between 10 and 100 cm\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (set_gpio_mode(MOTOR_A_IN1, 0) < 0 || set_gpio_mode(MOTOR_A_IN2, 0) < 0 ||
        set_gpio_mode(MOTOR_B_IN3, 0) < 0 || set_gpio_mode(MOTOR_B_IN4, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int duty_a = (distance_motor_a < 50) ? 255 - (distance_motor_a * 510 / 50) : 0;
        int duty_b = (distance_motor_b < 50) ? 255 - (distance_motor_b * 510 / 50) : 0;

        if (distance_motor_a < 50) {
            set_gpio_mode(MOTOR_A_IN1, 1);
            set_gpio_mode(MOTOR_A_IN2, 0);
        } else {
            set_gpio_mode(MOTOR_A_IN1, 0);
            set_gpio_mode(MOTOR_A_IN2, 1);
        }

        if (distance_motor_b < 50) {
            set_gpio_mode(MOTOR_B_IN3, 1);
            set_gpio_mode(MOTOR_B_IN4, 0);
        } else {
            set_gpio_mode(MOTOR_B_IN3, 0);
            set_gpio_mode(MOTOR_B_IN4, 1);
        }

        set_pwm_duty(MOTOR_A_IN2, duty_a);
        set_pwm_duty(MOTOR_B_IN4, duty_b);

        usleep(CONTROL_LOOP_INTERVAL_MS * 1000);
    }

    stop_motors();
    gpioTerminate();
    return EXIT_SUCCESS;
}

