    lines[2] = gpiod_chip_get_line(chip, IN3_PIN);
    lines[3] = gpiod_chip_get_line(chip, IN4_PIN);

    for (int i = 0; i < 4; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for IN%d\n", i + 1);
