        fprintf(stderr, "Error getting button lines\n");
        cleanup(0);
    }

    ret = gpiod_line_request_input_flags(lock_button, "lock_button", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting lock button line\n");
        cleanup(0);
    }

    ret = gpiod_line_request_input_flags(unlock_button, "unlock_button", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting unlock button line\n");
        cleanup(0);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Ready. Press LOCK button to lock, UNLOCK button to unlock, or Ctrl+C to exit.\n");

    int last_lock_state = 1;
    int last_unlock_state = 1;

    while (1) {
        int lock_state = gpiod_line_get_value(lock_button);
        int unlock_state = gpiod_line_get_value(unlock_button);

        if (lock_state == 0 && last_lock_state == 1) {
            printf("Locking...\n");
            step_motor(1);
            printf("Locked.\n");
        }

        if (unlock_state == 0 && last_unlock_state == 1) {
            printf("Unlocking...\n");
            step_motor(-1);
            printf("Unlocked.\n");
        }

        last_lock_state = lock_state;
        last_unlock_state = unlock_state;

        delay_ms(50);
    }

    return 0;
}

