#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define PWM_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define LOG_FILE "solar_tracker.log"

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, data, len);
}

int init_i2c() {
    int retries = 5;
    int fd;
    while (retries--) {
        fd = open(I2C_BUS, O_RDWR);
        if (fd < 0) {
            if (errno == EBUSY) {
                sleep(1);
                continue;
            }
            return -1;
        }
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            close(fd);
            sleep(1);
            continue;
        }
        return fd;
    }
    return -1;
}

int init_mpu6050() {
    if (i2c_write(i2c_fd, 0x6B, 0x00) < 0) return -1; // Wake up MPU6050
    if (i2c_write(i2c_fd, 0x1A, 0x07) < 0) return -1; // Set DLPF to 98 Hz
    return 0;
}

int read_mpu6050(int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read(i2c_fd, 0x3B, buf, 14) != 14) return -1;

    *ax = (buf[0] << 8) | buf[1];
    *ay = (buf[2] << 8) | buf[3];
    *az = (buf[4] << 8) | buf[5];
    *gx = (buf[8] << 8) | buf[9];
    *gy = (buf[10] << 8) | buf[11];
    *gz = (buf[12] << 8) | buf[13];

    return 0;
}

float compute_pitch(int16_t ax, int16_t ay, int16_t az) {
    return atan2((float)ay, sqrt((float)(ax*ax + az*az))) * 180 / M_PI;
}

float compute_roll(int16_t ax, int16_t ay, int16_t az) {
    return atan2((float)ax, sqrt((float)(ay*ay + az*az))) * 180 / M_PI;
}

int set_servo_angle(int angle) {
    char path[64];
    FILE *f;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    f = fopen(path, "w");
    if (!f) return -1;
    fprintf(f, "%d", angle * 10000); // Assuming 20ms period, 50Hz frequency
    fclose(f);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    f = fopen(path, "w");
    if (!f) return -1;
    fprintf(f, "1");
    fclose(f);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        cleanup(0);
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    int16_t ax, ay, az, gx, gy, gz;
    float pitch, roll;
    int position = 0;

    while (1) {
        if (read_mpu6050(&ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Failed to read MPU6050 data\n");
            sleep(1);
            continue;
        }

        pitch = compute_pitch(ax, ay, az);
        roll = compute_roll(ax, ay, az);

        // Simple control logic (adjust as needed)
        if (pitch > 10) position += 5;
        else if (pitch < -10) position -= 5;
        if (position < 0) position = 0;
        if (position > 180) position = 180;

        if (set_servo_angle(position) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f,%f,%d\n", (long)now, pitch, roll, position);
        fflush(log_file);

        sleep(1); // Adjust sampling rate as needed
    }

    cleanup(0);
    return 0;
}

