#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2  // cm
#define MAX_DISTANCE 400 // cm
#define MIN_FREQUENCY 20 // Hz
#define MAX_FREQUENCY 20000 // Hz
#define MEASUREMENT_INTERVAL 60000 // 60 ms
#define SAMPLE_RATE 50 // Hz

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int measure_distance() {
    gpiod_line_event event;
    struct timespec start, end;
    long long elapsed_ns;

    gpiod_line_set_value(TRIG_PIN, 1);
    usleep(10);
    gpiod_line_set_value(TRIG_PIN, 0);

    if (gpiod_line_event_wait(ECHO_PIN, GPIOD_LINE_EVENT_RISING_EDGE, NULL) < 0) {
        fprintf(stderr, "Error waiting for rising edge\n");
        return -1;
    }
    if (gpiod_line_event_read(ECHO_PIN, &event) < 0) {
        fprintf(stderr, "Error reading rising edge event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (gpiod_line_event_wait(ECHO_PIN, GPIOD_LINE_EVENT_FALLING_EDGE, NULL) < 0) {
        fprintf(stderr, "Error waiting for falling edge\n");
        return -1;
    }
    if (gpiod_line_event_read(ECHO_PIN, &event) < 0) {
        fprintf(stderr, "Error reading falling edge event\n");
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return (int)(elapsed_ns / 5800); // Speed of sound ~343 m/s = 5800 cm/s
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *buzzer_line;
    int distance, frequency;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);

    if (!trig_line || !echo_line || !buzzer_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "theremin_trig", 0) < 0 ||
        gpiod_line_request_input(echo_line, "theremin_echo") < 0 ||
        gpiod_line_request_output(buzzer_line, "theremin_buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance\n");
            continue;
        }

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %d cm\n", distance);
            continue;
        }

        frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        gpioSetPWMfrequency(BUZZER_PIN, frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle

        usleep(MEASUREMENT_INTERVAL);
    }

    gpioSetPWMfrequency(BUZZER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

