#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static int running = 1;

void cleanup(int signum) {
    running = 0;
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {0, 10000000}; // 10ms
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(SIGINT);
    }

    ret = gpiod_line_request_output(red_line, "rgb_led_red", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request red line\n");
        cleanup(SIGINT);
    }

    ret = gpiod_line_request_output(green_line, "rgb_led_green", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request green line\n");
        cleanup(SIGINT);
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led_blue", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request blue line\n");
        cleanup(SIGINT);
    }

    time_t start_time = time(NULL);

    while (running) {
        double time_elapsed = difftime(time(NULL), start_time);
        double proximity = (sin(time_elapsed) + 1) / 2; // Range 0.0 to 1.0

        int red_value = (int)(proximity * PWM_RANGE);
        int green_value = (int)((1 - proximity) * PWM_RANGE);
        int blue_value = (int)((1 - proximity) * PWM_RANGE);

        ret = gpiod_line_set_value(red_line, red_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set red value\n");
            cleanup(SIGINT);
        }

        ret = gpiod_line_set_value(green_line, green_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set green value\n");
            cleanup(SIGINT);
        }

        ret = gpiod_line_set_value(blue_line, blue_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set blue value\n");
            cleanup(SIGINT);
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}

