#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "gyro_log.txt"

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct i2c_msg messages[1];
    char buffer[14];
    struct timeval tv;
    struct timezone tz;
    int16_t x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        buffer[0] = 0x43; // Start reading from gyro data register
        messages[0].addr = MPU6050_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        x = (buffer[0] << 8) | buffer[1];
        y = (buffer[2] << 8) | buffer[3];
        z = (buffer[4] << 8) | buffer[5];

        gettimeofday(&tv, &tz);
