    is_playing = true;
    stop_playback = false;

    for (int i = 0; i < MELODY_NOTES && !stop_playback; i++) {
        gpioSetPWMfrequency(BUZZER_PIN, melody[i]);
        gpioSetPWMdutycycle(BUZZER_PIN, 128);  // 50% duty cycle
        gpioSetPWMrange(BUZZER_PIN, 255);
        usleep(note_durations[i] * 100000);  // Convert to microseconds

        if (button_pressed) {
            button_pressed = false;
            stop_playback = true;
            break;
        }
    }

    gpioSetPWMdutycycle(BUZZER_PIN, 0);
    gpioSetPWMrange(BUZZER_PIN, 0);
    is_playing = false;
}

