        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    gpioSetAlertFunc(BUTTON_PIN, button_callback);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        cleanup();
    }

    if (gpiod_line_request_input(button_line, "button-monitor") < 0) {
        fprintf(stderr, "Failed to request button line as input\n");
        cleanup();
    }

