#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000
#define LOG_FILE "vibration_events.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_event(FILE *log_file, int value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %d\n", timestamp, value);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int timeout_ms = DEFAULT_TIMEOUT;
    FILE *log_file;
    int event_window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int high_count = 0;

    if (argc > 2) {
        fprintf(stderr, "Usage: %s [timeout_ms]\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (argc == 2) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value\n");
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_rising_edge(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request rising edge: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_falling_edge(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request falling edge: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_both_edges(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request both edges: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        struct gpiod_line_event event;
        int event_value;

        ret = gpiod_line_event_wait(line, timeout_ms);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(-ret));
            continue;
        }

        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(-ret));
            continue;
        }

        event_value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;
        log_event(log_file, event_value);

        event_window[window_index] = event_value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (event_window[i] == 1) {
                high_count++;
            }
        }

        if (high_count >= 3) {
            time_t now;
            struct tm *tm_info;
            char timestamp[64];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            printf("EARTHQUAKE ALERT at %s\n", timestamp);
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

