#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20
#define SAMPLE_INTERVAL 1

static int i2c_fd;
static FILE *csv_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C read register write failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read data failed");
        return -1;
    }
    return 0;
}

int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read(i2c_fd, 0x08, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }
    *x = (buf[0] << 8) | buf[1];
    *y = (buf[2] << 8) | buf[3];
    *z = (buf[4] << 8) | buf[5];
    return 0;
}

const char *get_compass_direction(float heading) {
    static const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    int index = (int)((heading + 22.5) % 360) / 45;
    return directions[index];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, 0x20, 0x60) < 0) { // CRA_REG_M: 75 Hz
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write(i2c_fd, 0x21, 0x20) < 0) { // CRB_REG_M: +/- 8 gauss
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write(i2c_fd, 0x22, 0x00) < 0) { // MR_REG_M: Continuous conversion mode
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen("mag_log.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }

    while (1) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            float calibrated_x = x - X_OFFSET;
            float calibrated_y = y - Y_OFFSET;
            float calibrated_z = z - Z_OFFSET;

            float heading = atan2(calibrated_y, calibrated_x) * 180 / M_PI;
            if (heading < 0) {
                heading += 360;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s, %d, %d, %d, %.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
            fflush(csv_file);

            printf("Direction: %s, Heading: %.2f\n", get_compass_direction(heading), heading);
        }

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

