#define DEBOUNCE_TIME_MS 200

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *relay_line;
static int relay_state = 0;
static struct timespec last_touch_time;

void log_state_change(int state) {
    FILE *log_file = fopen("relay_log.json", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", 
            timestamp, state ? "ON" : "OFF");
    fclose(log_file);
}

void toggle_relay() {
    relay_state = !relay_state;
    int ret = gpiod_line_set_value(relay_line, relay_state);
    if (ret < 0) {
        perror("Failed to set relay state");
        exit(EXIT_FAILURE);
    }
    log_state_change(relay_state);
}

void touch_callback(struct gpiod_line *line, int event, void *user_data) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    long elapsed_ms = (current_time.tv_sec - last_touch_time.tv_sec) * 1000 +
                      (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000;

    if (elapsed_ms >= DEBOUNCE_TIME_MS) {
        last_touch_time = current_time;
        toggle_relay();
    }
}

void cleanup(int signum) {
    gpiod_line_release(relay_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);
    log_state_change(0);
    exit(EXIT_SUCCESS);
}

int main() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(touch_line, "touch_input");
    if (ret < 0) {
        perror("Failed to request touch line as input");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(relay_line, "relay_output", 0);
    if (ret < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    while (1) {
        ret = gpiod_line_event_wait(touch_line, 1000);
        if (ret < 0) {
            perror("Failed to wait for touch event");
            cleanup(SIGINT);
        } else if (ret > 0) {
            int event_type = gpiod_line_event_read(touch_line);
            if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                touch_callback(touch_line, event_type, NULL);
            }
        }
    }

    return 0;
}

