#define MOISTURE_THRESHOLD 30
#define CHECK_INTERVAL 10
#define RELAY_DURATION 5

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_file;

void cleanup(int signum) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated by signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PINS[i]);
            cleanup(0);
        }

        int ret = gpiod_line_request_output(lines[i], "relay", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PINS[i]);
            cleanup(0);
        }
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        int moisture = rand() % 101;
        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 0);
                fprintf(log_file, "%s,Relay%d,%d\n", timestamp, i + 1, moisture);
                fflush(log_file);
                sleep(RELAY_DURATION);
                gpiod_line_set_value(lines[i], 1);
                sleep(1);
            }
        }

        sleep(CHECK_INTERVAL);
    }

    return EXIT_SUCCESS;
}

