#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define MOISTURE_SEQUENCE_SIZE 5
#define MOISTURE_SEQUENCE {20, 40, 60, 80, 100}
#define MOISTURE_THRESHOLD 50
#define SERVO_PULSE_WIDTH_0 500
#define SERVO_PULSE_WIDTH_90 1500
#define SERVO_PULSE_WIDTH_180 2500
#define NOZZLE_ANGLES {500, 1000, 1500, 2000, 2500}
#define STEP_DURATION 2
#define HOLD_DURATION 5
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int set_servo_pulse(int gpio, int pulse_width_us) {
    struct gpiod_line *line;
    struct gpiod_line_request_config config = {
        .consumer = "Servo Control",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };

    line = gpiod_find_line(gpio);
    if (!line) {
        fprintf(stderr, "Failed to find GPIO line\n");
        return -1;
    }

    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (gpiod_line_request(line, &config, 0) == 0) {
            gpiod_line_set_value(line, 1);
            usleep(pulse_width_us);
            gpiod_line_set_value(line, 0);
            gpiod_line_release(line);
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }

    fprintf(stderr, "Failed to set servo pulse after %d retries\n", RETRY_LIMIT);
    gpiod_line_release(line);
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    int moisture_sequence[] = MOISTURE_SEQUENCE;
    int nozzle_angles[] = NOZZLE_ANGLES;

    int gpiod_ctx = gpiod_ctxless_open("/dev/gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open gpiod context");
        return EXIT_FAILURE;
    }

    int seq_index = 0;
    while (!terminate) {
        int moisture = moisture_sequence[seq_index];
        seq_index = (seq_index + 1) % MOISTURE_SEQUENCE_SIZE;

        if (moisture < MOISTURE_THRESHOLD) {
            if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_90) != 0) {
                fprintf(stderr, "Critical: Failed to open valve\n");
                break;
            }

            for (int i = 0; i < MOISTURE_SEQUENCE_SIZE; i++) {
                if (set_servo_pulse(NOZZLE_PIN, nozzle_angles[i]) != 0) {
                    fprintf(stderr, "Warning: Failed to set nozzle position\n");
                    continue;
                }
                sleep(STEP_DURATION);
            }

            sleep(HOLD_DURATION);

            if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
                fprintf(stderr, "Warning: Failed to close valve\n");
            }

            sleep(HOLD_DURATION);
        } else {
            sleep(1);
        }
    }

    if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
        fprintf(stderr, "Warning: Failed to close valve during shutdown\n");
    }

    if (set_servo_pulse(NOZZLE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
        fprintf(stderr, "Warning: Failed to reset nozzle during shutdown\n");
    }

    gpiod_ctxless_close(gpiod_ctx);
    return EXIT_SUCCESS;
}

