    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    int moisture_sequence[] = MOISTURE_SEQUENCE;
    int nozzle_angles[] = NOZZLE_ANGLES;

    int gpiod_ctx = gpiod_ctxless_open("/dev/gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open gpiod context");
        return EXIT_FAILURE;
    }

    int seq_index = 0;
    while (!terminate) {
        int moisture = moisture_sequence[seq_index];
        seq_index = (seq_index + 1) % MOISTURE_SEQUENCE_SIZE;

        if (moisture < MOISTURE_THRESHOLD) {
            if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_90) != 0) {
                fprintf(stderr, "Critical: Failed to open valve\n");
                break;
            }

            for (int i = 0; i < MOISTURE_SEQUENCE_SIZE; i++) {
                if (set_servo_pulse(NOZZLE_PIN, nozzle_angles[i]) != 0) {
                    fprintf(stderr, "Warning: Failed to set nozzle position\n");
                    continue;
                }
                sleep(STEP_DURATION);
            }

            sleep(HOLD_DURATION);

            if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
                fprintf(stderr, "Warning: Failed to close valve\n");
            }

            sleep(HOLD_DURATION);
        } else {
            sleep(1);
        }
    }

    if (set_servo_pulse(VALVE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
        fprintf(stderr, "Warning: Failed to close valve during shutdown\n");
    }

    if (set_servo_pulse(NOZZLE_PIN, SERVO_PULSE_WIDTH_0) != 0) {
        fprintf(stderr, "Warning: Failed to reset nozzle during shutdown\n");
    }

    gpiod_ctxless_close(gpiod_ctx);
    return EXIT_SUCCESS;
}
