#define MPU6050_ADDR 0x68
#define I2C_BUS 1
#define SAMPLE_RATE 10
#define LOG_FILE "gyro_log.txt"

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, data, len);
}

int init_mpu6050() {
    if (i2c_write(i2c_fd, 0x6B, 0x00) != 1) return -1; // Wake up MPU6050
    if (i2c_write(i2c_fd, 0x1B, 0x08) != 1) return -1; // Set gyro full scale to ±500°/s
    return 0;
}

int read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read(i2c_fd, 0x43, buf, 6) != 6) return -1;
    *x = (buf[0] << 8) | buf[1];
    *y = (buf[2] << 8) | buf[3];
    *z = (buf[4] << 8) | buf[5];
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    struct timeval start, current;
    gettimeofday(&start, NULL);

    while (1) {
        int16_t x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            continue;
        }

        gettimeofday(&current, NULL);
        double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_usec - start.tv_usec) / 1000000.0;

        fprintf(log_file, "%.3f,%d,%d,%d\n", elapsed, x, y, z);
        fflush(log_file);

        usleep((1000000 / SAMPLE_RATE) - 1000); // Account for function call time
    }

    return EXIT_SUCCESS;
}

