#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define MEASUREMENT_INTERVAL_MS 60000

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void cleanup(int signum) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec start, end;
    long echo_duration_us;
    double distance_cm;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        goto error;
    }

    if (gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        goto error;
    }

    if (gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        goto error;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto error;
    }

    while (1) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for rising edge
        if (gpiod_line_event_wait_us(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, ECHO_TIMEOUT_US) < 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            goto wait;
        }

        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for falling edge
        if (gpiod_line_event_wait_us(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, ECHO_TIMEOUT_US) < 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            goto wait;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);

        echo_duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance_cm = (echo_duration_us / 2) / 29.1; // Speed of sound ~343 m/s, so 29.1 cm/us

        fprintf(log_file, "%.2f\n", distance_cm);
        fflush(log_file);

    wait:
        usleep(MEASUREMENT_INTERVAL_MS * 1000 - TRIGGER_PULSE_US * 2);
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

