    if (gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        goto error;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto error;
    }

    while (1) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for rising edge
        if (gpiod_line_event_wait_us(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, ECHO_TIMEOUT_US) < 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            goto wait;
        }

        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for falling edge
        if (gpiod_line_event_wait_us(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, ECHO_TIMEOUT_US) < 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            goto wait;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);

        echo_duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance_cm = (echo_duration_us / 2) / 29.1; // Speed of sound ~343 m/s, so 29.1 cm/us

        fprintf(log_file, "%.2f\n", distance_cm);
        fflush(log_file);

    wait:
        usleep(MEASUREMENT_INTERVAL_MS * 1000 - TRIGGER_PULSE_US * 2);
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}
