        i2cClose(i2c_handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        uint16_t distance;
        status = VL53L1X_GetDistance(&dev, &distance);
