            if (distance <= 500) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        } else {
            fprintf(stderr, "VL53L1X get distance failed: %d\n", status);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

