#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_FORCE 0x0706

static int i2c_fd;

void signal_handler(int signo) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    ssize_t bytes_written = write(fd, buf, sizeof(buf));
    if (bytes_written != sizeof(buf)) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register for read: %s\n", strerror(errno));
        return -1;
    }
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Power management register 0x6B, set to 0 to start the sensor
    if (i2c_write(i2c_fd, 0x6B, 0) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    while (1) {
        if (i2c_read(i2c_fd, 0x43, buf, 6) < 0) {
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[2] << 8) | buf[3];
        int16_t z = (buf[4] << 8) | buf[5];

        printf("Gyroscope - X: %d, Y: %d, Z: %d\n", x, y, z);

        usleep(100000); // 100ms delay
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

