    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for pin %d: %s\n", relay_pins[i], strerror(errno));
            cleanup(0);
        }

        int ret = gpiod_line_request_output(lines[i], "watering_relay", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", relay_pins[i], strerror(errno));
            cleanup(0);
        }
    }

    while (1) {
        log_start_time();

        for (int cycle = 0; cycle < CYCLE_DURATION / 60; cycle++) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 0); // Activate relay (active-low)
                sleep(RELAY_DURATION);
                gpiod_line_set_value(lines[i], 1); // Deactivate relay
            }
            sleep(60 - (NUM_RELAYS * RELAY_DURATION));
        }
    }

    return EXIT_SUCCESS;
