#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define STEP_INTERVAL 1
#define TOTAL_DURATION 1800 // 30 minutes in seconds
#define LOG_FILE "smart_lighting.log"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_file;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup(int signum) {
    log_event("Cleaning up resources...");

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    log_event("Resources cleaned up. Exiting.");
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    log_event("Program started");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    const int gpio_pins[NUM_RELAYS] = {17, 18, 27, 22};
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            log_event("Failed to get GPIO line");
            cleanup(0);
        }

        int ret = gpiod_line_request_output(lines[i], "smart_lighting", 0);
        if (ret < 0) {
            log_event("Failed to request GPIO line as output");
            cleanup(0);
        }

        log_event("GPIO pin configured successfully");
    }

    for (int step = 0; step <= 255; step += STEP_INTERVAL) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            int ret = gpiod_line_set_value(lines[i], step);
            if (ret < 0) {
                char buffer[100];
                snprintf(buffer, sizeof(buffer), "Failed to set GPIO value for pin %d", gpio_pins[i]);
                log_event(buffer);
                cleanup(0);
            }
        }

        char buffer[100];
        snprintf(buffer, sizeof(buffer), "PWM duty cycle set to %d", step);
        log_event(buffer);

        sleep(STEP_INTERVAL);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

