#define LED_PIN 17
#define THRESHOLD 250.0

typedef struct {
    double x, y, z;
    struct timespec timestamp;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
int bufferIndex = 0;
int i2cHandle;
struct gpiod_chip *chip;
struct gpiod_line *ledLine;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpiod_line_set_value(ledLine, 0);
    gpiod_line_release(ledLine);
    gpiod_chip_close(chip);
    close(i2cHandle);
    exit(0);
}

int initI2C() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
