        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int readGyro(int fd, GyroReading *reading) {
    unsigned char data[6];
    if (read(fd, data, 6) != 6) {
        return -1;
    }

    reading->x = (int16_t)(data[0] << 8 | data[1]) / 131.0;
    reading->y = (int16_t)(data[2] << 8 | data[3]) / 131.0;
    reading->z = (int16_t)(data[4] << 8 | data[5]) / 131.0;

    clock_gettime(CLOCK_MONOTONIC, &reading->timestamp);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    ledLine = gpiod_chip_get_line(chip, LED_PIN);
    if (!ledLine) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(ledLine, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_release(ledLine);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int initAttempts = 0;
    while (initAttempts < 3) {
        i2cHandle = initI2C();
        if (i2cHandle >= 0) break;
        initAttempts++;
        fprintf(stderr, "I2C initialization failed. Attempt %d of 3.\n", initAttempts);
        sleep(1);
    }

    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to initialize I2C after 3 attempts\n");
        cleanup(0);
    }

    struct timespec sleepTime = {0, 50000000}; // 50ms

    while (1) {
        GyroReading reading;
        if (readGyro(i2cHandle, &reading) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            close(i2cHandle);
            i2cHandle = initI2C();
            if (i2cHandle < 0) {
                fprintf(stderr, "Failed to reinitialize I2C\n");
                cleanup(0);
            }
            continue;
        }

        buffer[bufferIndex] = reading;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

        double maxAbsValue = fmax(fabs(reading.x), fmax(fabs(reading.y), fabs(reading.z)));
        int ledState = (maxAbsValue > THRESHOLD) ? 1 : 0;
        gpiod_line_set_value(ledLine, ledState);

        nanosleep(&sleepTime, NULL);
    }

    return 0;
}

