#define SPI_DEVICE "/dev/spidev0.0"
#define GYRO_LOG_FILE "gyro_log.txt"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 3
#define GYRO_READ_INTERVAL_MS 10
#define GYRO_REGISTER 0x43 // Example register for gyro data
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 8

static int spi_fd;
static FILE *log_file;
static struct gpiod_line *cs_line;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    unsigned char tx[6] = {GYRO_REGISTER, 0, 0, 0, 0, 0};
    unsigned char rx[6];
    int retries = 0;

    while (retries < SPI_MAX_RETRIES) {
        if (spi_transfer(tx, rx, sizeof(rx)) == 0) {
            *x_rate = (short)(rx[1] << 8 | rx[2]) / 131.0; // Example conversion
            *y_rate = (short)(rx[3] << 8 | rx[4]) / 131.0;
            *z_rate = (short)(rx[5] << 8 | rx[6]) / 131.0;
            return 0;
        }
        retries++;
    }
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        cleanup(0);
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(0);
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    if (gpiod_line_request_output(cs_line, "gyro_cs", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    log_file = fopen(GYRO_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    struct timespec ts;
    char timestamp[64];

    while (1) {
        gpiod_line_set_value(cs_line, 0);
        float x_rate, y_rate, z_rate;
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm *tm_info = gmtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
            fprintf(log_file, "%s.%09ld,%f,%f,%f\n", timestamp, ts.tv_nsec, x_rate, y_rate, z_rate);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpiod_line_set_value(cs_line, 1);
        usleep(GYRO_READ_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

