#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE SPI_MODE_0
#define BUFFER_SIZE 64
#define GYRO_THRESHOLD 200.0
#define WARNING_LED_PIN 17

typedef struct {
    double x, y, z;
    struct timespec timestamp;
} GyroSample;

GyroSample circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int running = 1;
int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *led_line;

void cleanup(int signum) {
    running = 0;
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char time_str[64];
        struct tm *tm_info;
        tm_info = localtime(&circular_buffer[i].timestamp.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s.%09ld,%f,%f,%f\n", time_str, circular_buffer[i].timestamp.tv_nsec,
               circular_buffer[i].x, circular_buffer[i].y, circular_buffer[i].z);
    }
    exit(0);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI open");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("SPI mode");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_gyro(int fd, double *x, double *y, double *z) {
    uint8_t tx[14] = {0x6B, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                      0x6C, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[14];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer");
        return -1;
    }

    *x = (int16_t)(rx[1] << 8 | rx[0]) / 131.0;
    *y = (int16_t)(rx[3] << 8 | rx[2]) / 131.0;
    *z = (int16_t)(rx[5] << 8 | rx[4]) / 131.0;

    return 0;
}

