#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <math.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 100
#define LED_PIN 21
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int mpu6050_init(int i2c_bus, int addr) {
    int fd = i2cOpen(i2c_bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    i2cWriteByteData(fd, MPU6050_PWR_MGMT_1, 0x00);
    usleep(10000);  // Wait for sensor to stabilize

    return fd;
}

int16_t read_word(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (i2cReadI2CBlockData(fd, reg, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from MPU6050: %s\n", strerror(errno));
        return 0;
    }
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

void compute_orientation(int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz, float *roll, float *pitch) {
    // Simplified orientation calculation (not accurate for all orientations)
    *roll = atan2(ay, az) * 180.0 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180.0 / M_PI;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    signal(SIGINT, signal_handler);

    int fd = mpu6050_init(I2C_BUS, MPU6050_ADDR);
    if (fd < 0) {
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("tilt_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        int16_t ax = read_word(fd, MPU6050_ACCEL_XOUT_H);
        int16_t ay = read_word(fd, MPU6050_ACCEL_XOUT_H + 2);
        int16_t az = read_word(fd, MPU6050_ACCEL_XOUT_H + 4);
        int16_t gx = read_word(fd, MPU6050_GYRO_XOUT_H);
        int16_t gy = read_word(fd, MPU6050_GYRO_XOUT_H + 2);
        int16_t gz = read_word(fd, MPU6050_GYRO_XOUT_H + 4);

        float roll, pitch;
        compute_orientation(ax, ay, az, gx, gy, gz, &roll, &pitch);

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, roll, pitch);
        fflush(log_file);

        if (fabs(roll) > ROLL_THRESHOLD || fabs(pitch) > PITCH_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(fd);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

