#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define READ_INTERVAL_MS 100
#define PROXIMITY_THRESHOLD 100
#define LED_PIN 17

int i2c_fd;
int log_fd;
struct gpiod_chip *chip;
struct gpiod_line *led_line;

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);

    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (log_fd >= 0) {
        close(log_fd);
    }

    exit(EXIT_SUCCESS);
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int read_i2c(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int main() {
    struct timespec read_interval = {0, READ_INTERVAL_MS * 1000000};
    struct timespec retry_delay = {0, RETRY_DELAY_MS * 1000000};
    uint8_t ambient_light, proximity;
    char log_entry[64];
    time_t now;
    struct tm *tm_info;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int retries = 0;
        while (retries < RETRY_COUNT) {
            if (read_i2c(i2c_fd, 0x1A, &ambient_light) == 1 &&
                read_i2c(i2c_fd, 0x1B, &proximity) == 1) {
                break;
            }
            retries++;
            nanosleep(&retry_delay, NULL);
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d attempts\n", RETRY_COUNT);
            continue;
        }

        now = time(NULL);
        tm_info = localtime(&now);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S,AmbientLight:%04d,Proximity:%04d\n",
                 tm_info, ambient_light, proximity);

        if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
            perror("Failed to write to log file");
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        nanosleep(&read_interval, NULL);
    }

    return EXIT_SUCCESS;
}

