#include <gpiod.h>
#include <unistd.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17
#define ALERT_DURATION 2
#define ALERT_THRESHOLD_MS 500

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line, *alert_line;
static FILE *log_file;
static int alert_active = 0;
static time_t alert_start_time;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

void log_event(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

int check_sensors() {
    int sensor1_value, sensor2_value;
    sensor1_value = gpiod_line_get_value(sensor1_line);
    sensor2_value = gpiod_line_get_value(sensor2_line);
    return (sensor1_value && sensor2_value);
}

void alert_callback() {
    time_t current_time;
    time(&current_time);

    if (check_sensors()) {
        if (!alert_active) {
            alert_active = 1;
            alert_start_time = current_time;
            gpiod_line_set_value(alert_line, 1);
            log_event("Seismic event detected!");
        } else if (difftime(current_time, alert_start_time) >= ALERT_DURATION) {
            gpiod_line_set_value(alert_line, 0);
            alert_active = 0;
        }
    } else {
        alert_active = 0;
        gpiod_line_set_value(alert_line, 0);
    }
}

void sensor_callback(struct gpiod_line *line) {
    static time_t last_change_time = 0;
    time_t current_time = time(NULL);

    if (difftime(current_time, last_change_time) >= ALERT_THRESHOLD_MS / 1000.0) {
        alert_callback();
    }
    last_change_time = current_time;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!sensor1_line || !sensor2_line || !alert_line) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") < 0 ||
        gpiod_line_request_output(alert_line, "alert", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup(0);
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    gpiod_line_event_request(sensor1_line, GPIOD_LINE_EDGE_BOTH, "sensor1_callback");
    gpiod_line_event_request(sensor2_line, GPIOD_LINE_EDGE_BOTH, "sensor2_callback");

    while (1) {
        struct gpiod_line_event event;
        int ret;

        ret = gpiod_line_event_wait(sensor1_line, NULL);
        if (ret > 0) {
            gpiod_line_event_read(sensor1_line, &event);
            sensor_callback(sensor1_line);
        }

        ret = gpiod_line_event_wait(sensor2_line, NULL);
        if (ret > 0) {
            gpiod_line_event_read(sensor2_line, &event);
            sensor_callback(sensor2_line);
        }

        usleep(1000);  // Small delay to prevent busy-waiting
    }

    return EXIT_SUCCESS;
}

