#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <spi/spi.h>

#define BUFFER_SIZE 100
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_CHIP_SELECT 0
#define ADXRS290_REGISTER_ANGULAR_RATE 0x02
#define ADXRS290_READ_FLAG 0x80
#define THRESHOLD 20.0

typedef struct {
    double rate;
    struct timespec timestamp;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

CircularBuffer buffer = { .head = 0, .tail = 0, .count = 0 };
struct spi_ioc_transfer spi_xfer[1];
int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *led_line;

void buffer_add(SensorData *data) {
    if (buffer.count == BUFFER_SIZE) {
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
    } else {
        buffer.count++;
    }
    buffer.data[buffer.head] = *data;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
}

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "ADXRS290_LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char tx[2] = { ADXRS290_REGISTER_ANGULAR_RATE | ADXRS290_READ_FLAG, 0 };
    unsigned char rx[2] = { 0 };

    while (1) {
        memset(spi_xfer, 0, sizeof(spi_xfer));
        spi_xfer[0].tx_buf = (unsigned long)tx;
        spi_xfer[0].rx_buf = (unsigned long)rx;
        spi_xfer[0].len = 2;
        spi_xfer[0].delay_usecs = 0;
        spi_xfer[0].cs_change = 0;
        spi_xfer[0].bits_per_word = 8;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_xfer) < 0) {
            perror("Failed to transfer SPI data");
            continue;
        }

        int16_t raw_rate = (rx[0] << 8) | rx[1];
        double rate = (double)raw_rate * 0.005; // Convert raw value to deg/s

        SensorData data = { .rate = rate };
        if (clock_gettime(CLOCK_MONOTONIC, &data.timestamp) < 0) {
            perror("Failed to get timestamp");
            continue;
        }

        buffer_add(&data);

        if (rate > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
    }

    return EXIT_SUCCESS;
}

