    if (gpiod_line_request_output(led_line, "ADXRS290_LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char tx[2] = { ADXRS290_REGISTER_ANGULAR_RATE | ADXRS290_READ_FLAG, 0 };
    unsigned char rx[2] = { 0 };

    while (1) {
        memset(spi_xfer, 0, sizeof(spi_xfer));
        spi_xfer[0].tx_buf = (unsigned long)tx;
        spi_xfer[0].rx_buf = (unsigned long)rx;
        spi_xfer[0].len = 2;
        spi_xfer[0].delay_usecs = 0;
        spi_xfer[0].cs_change = 0;
        spi_xfer[0].bits_per_word = 8;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_xfer) < 0) {
            perror("Failed to transfer SPI data");
            continue;
        }

        int16_t raw_rate = (rx[0] << 8) | rx[1];
        double rate = (double)raw_rate * 0.005; // Convert raw value to deg/s

        SensorData data = { .rate = rate };
        if (clock_gettime(CLOCK_MONOTONIC, &data.timestamp) < 0) {
            perror("Failed to get timestamp");
            continue;
        }

        buffer_add(&data);

        if (rate > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
    }

    return EXIT_SUCCESS;
}
