#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define TOUCH_PIN 17
#define DEBOUNCE_DELAY_MS 100
#define READ_INTERVAL_MS 10

#define LOG_FILE "touch_relay.log"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        log_message("Failed to initialize GPIO");
        cleanup(0);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        cleanup(0);
    }

    line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!line) {
        log_message("Failed to get GPIO line");
        cleanup(0);
    }

    if (gpiod_line_request_output(line, "touch_relay", 0) < 0) {
        log_message("Failed to request GPIO line as output");
        cleanup(0);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        cleanup(0);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_message("Failed to set I2C slave address");
        cleanup(0);
    }

    uint8_t config[2] = {0x5E, 0x00}; // Soft reset
    if (write(i2c_fd, config, 2) != 2) {
        log_message("Failed to write to MPR121");
        cleanup(0);
    }
    usleep(10000); // Wait for reset

    config[0] = 0x5D;
    config[1] = 0x03; // Enable electrode 0
    if (write(i2c_fd, config, 2) != 2) {
        log_message("Failed to configure MPR121");
        cleanup(0);
    }

    uint8_t touch_status[2];
    int last_touch = 0;
    time_t last_toggle_time = 0;

    while (1) {
        touch_status[0] = 0x59; // Touch status register
        if (write(i2c_fd, touch_status, 1) != 1 || read(i2c_fd, touch_status, 2) != 2) {
            log_message("Failed to read touch status from MPR121");
            cleanup(0);
        }

        int current_touch = touch_status[0] & 0x01;

        if (current_touch && !last_touch) {
            time_t now = time(NULL);
            if (difftime(now, last_toggle_time) >= DEBOUNCE_DELAY_MS / 1000.0) {
                int relay_state = gpiod_line_get_value(line);
                gpiod_line_set_value(line, !relay_state);
                last_toggle_time = now;
                char msg[50];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "HIGH" : "LOW");
                log_message(msg);
            }
        }

        last_touch = current_touch;
        usleep(READ_INTERVAL_MS * 1000);
    }

    return 0;
}

