#define HALF_INTERVAL_MS (DISPENSE_INTERVAL_MS / 2)

static struct gpiod_chip *chip;
static struct gpiod_line *solenoid1;
static struct gpiod_line *solenoid2;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
