    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    printf("Ctrl+C received, cleaning up...\n");
    gpiod_line_set_value(solenoid1, 0);
    gpiod_line_set_value(solenoid2, 0);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct timespec ts;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

