    solenoid1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!solenoid1) {
        fprintf(stderr, "Failed to get GPIO line for solenoid1\n");
        goto cleanup_chip;
    }

    solenoid2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid2) {
        fprintf(stderr, "Failed to get GPIO line for solenoid2\n");
        goto cleanup_solenoid1;
    }

    // Configure GPIO lines as output
    ret = gpiod_line_request_output(solenoid1, "solenoid1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for solenoid1\n");
        goto cleanup_solenoid2;
    }

    ret = gpiod_line_request_output(solenoid2, "solenoid2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for solenoid2\n");
        goto cleanup_solenoid1;
    }

    // Open log file
    log_file = fopen("dispense_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup_solenoid2;
    }

