        time_t now = time(NULL);
        fprintf(log_file, "%s solenoid1:%d solenoid2:%d duration:%dms\n",
                ctime(&now), SOLENOID1_PIN, SOLENOID2_PIN, DISPENSE_INTERVAL_MS);
        fflush(log_file);

        // Wait for the next dispense interval
        ts.tv_sec = DISPENSE_INTERVAL_MS / 1000;
        ts.tv_nsec = (DISPENSE_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }

cleanup_solenoid2:
    gpiod_line_release(solenoid2);
cleanup_solenoid1:
    gpiod_line_release(solenoid1);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

