#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>
#include <float.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENABLE_A 24
#define ENABLE_B 25
#define PID_INTERVAL_MS 50
#define LOG_FILE "balance_log.txt"
#define MIN_DISTANCE_CM 20.0
#define MAX_DISTANCE_CM 400.0
#define MIN_TILT_ERROR -10.0
#define MAX_TILT_ERROR 10.0
#define MAX_MOTOR_SPEED 255

static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *motor_a_forward, *motor_a_backward, *motor_b_forward, *motor_b_backward;
static struct gpiod_line *enable_a, *enable_b;

void cleanup(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (motor_a_forward) gpiod_line_release(motor_a_forward);
    if (motor_a_backward) gpiod_line_release(motor_a_backward);
    if (motor_b_forward) gpiod_line_release(motor_b_forward);
    if (motor_b_backward) gpiod_line_release(motor_b_backward);
    if (enable_a) gpiod_line_release(enable_a);
    if (enable_b) gpiod_line_release(enable_b);
    gpioTerminate();
    exit(0);
}

void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s %.2f %.2f %d %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

void set_motor_speed(int gpio_forward, int gpio_backward, int speed) {
    if (speed > 0) {
        gpiod_line_set_value(gpio_forward, 1);
        gpiod_line_set_value(gpio_backward, 0);
        gpioPWM(gpio_forward, speed);
    } else if (speed < 0) {
        gpiod_line_set_value(gpio_forward, 0);
        gpiod_line_set_value(gpio_backward, 1);
        gpioPWM(gpio_backward, -speed);
    } else {
        gpiod_line_set_value(gpio_forward, 0);
        gpiod_line_set_value(gpio_backward, 0);
        gpioPWM(gpio_forward, 0);
        gpioPWM(gpio_backward, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    motor_a_forward = gpiod_chip_get_line(chip, MOTOR_A_FORWARD);
    motor_a_backward = gpiod_chip_get_line(chip, MOTOR_A_BACKWARD);
    motor_b_forward = gpiod_chip_get_line(chip, MOTOR_B_FORWARD);
    motor_b_backward = gpiod_chip_get_line(chip, MOTOR_B_BACKWARD);
    enable_a = gpiod_chip_get_line(chip, ENABLE_A);
    enable_b = gpiod_chip_get_line(chip, ENABLE_B);

    if (!motor_a_forward || !motor_a_backward || !motor_b_forward || !motor_b_backward || !enable_a || !enable_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(0);
        return 1;
    }

    gpiod_line_request_output(motor_a_forward, "MOTOR_A_FORWARD", 0);
    gpiod_line_request_output(motor_a_backward, "MOTOR_A_BACKWARD", 0);
    gpiod_line_request_output(motor_b_forward, "MOTOR_B_FORWARD", 0);
    gpiod_line_request_output(motor_b_backward, "MOTOR_B_BACKWARD", 0);
    gpiod_line_request_output(enable_a, "ENABLE_A", 1);
    gpiod_line_request_output(enable_b, "ENABLE_B", 1);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }

    signal(SIGINT, cleanup);

    srand(time(NULL));

    double tilt_error, distance;
    int motor_a_speed = 0, motor_b_speed = 0;

    while (1) {
        tilt_error = ((double)rand() / RAND_MAX) * (MAX_TILT_ERROR - MIN_TILT_ERROR) + MIN_TILT_ERROR;
        distance = ((double)rand() / RAND_MAX) * (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_DISTANCE_CM;

        if (distance < MIN_DISTANCE_CM) {
            motor_a_speed = -MAX_MOTOR_SPEED / 2;
            motor_b_speed = -MAX_MOTOR_SPEED / 2;
        } else {
            // Simple PID control (P only for demonstration)
            double kp = 1.0;
            motor_a_speed = (int)(kp * tilt_error);
            motor_b_speed = (int)(kp * tilt_error);
        }

        motor_a_speed = (motor_a_speed > MAX_MOTOR_SPEED) ? MAX_MOTOR_SPEED : (motor_a_speed < -MAX_MOTOR_SPEED) ? -MAX_MOTOR_SPEED : motor_a_speed;
        motor_b_speed = (motor_b_speed > MAX_MOTOR_SPEED) ? MAX_MOTOR_SPEED : (motor_b_speed < -MAX_MOTOR_SPEED) ? -MAX_MOTOR_SPEED : motor_b_speed;

        set_motor_speed(motor_a_forward, motor_a_backward, motor_a_speed);
        set_motor_speed(motor_b_forward, motor_b_backward, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioSleep(PI_TIME_MILLISECONDS, PID_INTERVAL_MS);
    }

    return 0;
}

