    gpiod_line_request_output(motor_a_backward, "MOTOR_A_BACKWARD", 0);
    gpiod_line_request_output(motor_b_forward, "MOTOR_B_FORWARD", 0);
    gpiod_line_request_output(motor_b_backward, "MOTOR_B_BACKWARD", 0);
    gpiod_line_request_output(enable_a, "ENABLE_A", 1);
    gpiod_line_request_output(enable_b, "ENABLE_B", 1);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }

    signal(SIGINT, cleanup);

    srand(time(NULL));

    double tilt_error, distance;
    int motor_a_speed = 0, motor_b_speed = 0;

    while (1) {
        tilt_error = ((double)rand() / RAND_MAX) * (MAX_TILT_ERROR - MIN_TILT_ERROR) + MIN_TILT_ERROR;
        distance = ((double)rand() / RAND_MAX) * (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_DISTANCE_CM;

        if (distance < MIN_DISTANCE_CM) {
            motor_a_speed = -MAX_MOTOR_SPEED / 2;
            motor_b_speed = -MAX_MOTOR_SPEED / 2;
        } else {
            // Simple PID control (P only for demonstration)
            double kp = 1.0;
            motor_a_speed = (int)(kp * tilt_error);
            motor_b_speed = (int)(kp * tilt_error);
        }

        motor_a_speed = (motor_a_speed > MAX_MOTOR_SPEED) ? MAX_MOTOR_SPEED : (motor_a_speed < -MAX_MOTOR_SPEED) ? -MAX_MOTOR_SPEED : motor_a_speed;
        motor_b_speed = (motor_b_speed > MAX_MOTOR_SPEED) ? MAX_MOTOR_SPEED : (motor_b_speed < -MAX_MOTOR_SPEED) ? -MAX_MOTOR_SPEED : motor_b_speed;

        set_motor_speed(motor_a_forward, motor_a_backward, motor_a_speed);
        set_motor_speed(motor_b_forward, motor_b_backward, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioSleep(PI_TIME_MILLISECONDS, PID_INTERVAL_MS);
    }

    return 0;
}
