#include <gpiod.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_input(sensor_line, "TTP223_Sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line as input\n");
        goto cleanup;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay_line, "Relay_Control", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay line as output\n");
        goto cleanup;
    }

    printf("Monitoring TTP223 sensor on GPIO%d and controlling relay on GPIO%d\n", SENSOR_PIN, RELAY_PIN);

    while (keep_running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            break;
        }

        if (value == 1) {
            // Toggle relay
            int current_state = gpiod_line_get_value(relay_line);
            if (current_state < 0) {
                fprintf(stderr, "Error reading relay state\n");
                break;
            }
            gpiod_line_set_value(relay_line, !current_state);
            printf("Relay toggled to %s\n", !current_state ? "ON" : "OFF");

            // Debounce
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        // Small delay to prevent busy-waiting
        usleep(1000);
    }

cleanup:
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

