#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <unistd.h>
#include <time.h>
#include <alsa/asoundlib.h>

#ifdef ALSA_AVAILABLE
#include <gpiod.h>
#else
#include <pigpio.h>
#endif

#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define BUFFER_TIME_MS 10
#define NUM_CHANNELS 1
#define SENSITIVITY_DEFAULT 1.0

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27

static volatile sig_atomic_t keep_running = 1;
static snd_pcm_t *capture_handle = NULL;
static snd_pcm_hw_params_t *params = NULL;
static unsigned char *buffer = NULL;

#ifdef ALSA_AVAILABLE
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[3] = {NULL, NULL, NULL};
#else
static int gpio_initialized = 0;
#endif

static void cleanup(void) {
    if (keep_running) {
        keep_running = 0;
    }

    if (buffer) {
        free(buffer);
        buffer = NULL;
    }

    if (params) {
        snd_pcm_hw_params_free(params);
        params = NULL;
    }

    if (capture_handle) {
        snd_pcm_close(capture_handle);
        capture_handle = NULL;
    }

#ifdef ALSA_AVAILABLE
    if (chip) {
        for (int i = 0; i < 3; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
                lines[i] = NULL;
            }
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
#else
    if (gpio_initialized) {
        gpioTerminate();
        gpio_initialized = 0;
    }
#endif
}

static void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int init_alsa(void) {
    int err;

    if ((err = snd_pcm_open(&capture_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_malloc(&params)) < 0) {
        fprintf(stderr, "Error allocating hardware parameter structure: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(capture_handle, params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(capture_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(capture_handle, params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_rate_near(capture_handle, params, &SAMPLE_RATE, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size_near(capture_handle, params, &PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(capture_handle, params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params(capture_handle, params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_free(params);
    params = NULL;

    if ((err = snd_pcm_prepare(capture_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

#ifdef ALSA_AVAILABLE
static int init_gpio(void) {
    int err;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_RED);
    lines[1] = gpiod_chip_get_line(chip, GPIO_GREEN);
    lines[2] = gpiod_chip_get_line(chip, GPIO_BLUE);

    for (int i = 0; i < 3; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", i);
            return -1;
        }

        err = gpiod_line_request_output(lines[i], "mood_light", 0);
        if (err < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", i, strerror(-err));
            return -1;
        }
    }

    return 0;
}
#else
static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return -1;
    }

    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    gpio_initialized = 1;
    return 0;
}
#endif

static void set_rgb(int r, int g, int b) {
#ifdef ALSA_AVAILABLE
    gpiod_line_set_value(lines[0], r);
    gpiod_line_set_value(lines[1], g);
    gpiod_line_set_value(lines[2], b);
#else
    gpioPWM(GPIO_RED, r);
    gpioPWM(GPIO_GREEN, g);
    gpioPWM(GPIO_BLUE, b);
#endif
}

static void process_audio_buffer(snd_pcm_t *handle, float sensitivity) {
    int err;
    int count = snd_pcm_avail_update(handle);

    if (count < 0) {
        if (count == -EPIPE) {
            fprintf(stderr, "Buffer underrun occurred. Preparing PCM device...\n");
            snd_pcm_prepare(handle);
        } else if (count == -ESTRPIPE) {
            fprintf(stderr, "Resuming PCM device...\n");
            while ((err = snd_pcm_resume(handle)) == -EAGAIN) {
                usleep(1000);
            }
            if (err < 0) {
                fprintf(stderr, "Error resuming PCM device: %s\n", snd_strerror(err));
            }
        } else {
            fprintf(stderr, "Error from snd_pcm_avail_update: %s\n", snd_strerror(count));
        }
        return;
    }

    if (count > 0) {
        int frames = snd_pcm_readi(handle, buffer, count);
        if (frames < 0) {
            if (frames == -EPIPE) {
                fprintf(stderr, "Buffer underrun occurred. Preparing PCM device...\n");
                snd_pcm_prepare(handle);
            } else {
                fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(frames));
            }
            return;
        }

        double sum_squares = 0.0;
        for (int i = 0; i < frames * NUM_CHANNELS; i++) {
            short sample = buffer[i * 2 + 1] << 8 | buffer[i * 2];
            sum_squares += sample * sample;
        }

        double rms = sqrt(sum_squares / (frames * NUM_CHANNELS));
        double normalized_rms = rms / 32768.0;
        double scaled_rms = normalized_rms * sensitivity;

        int red = (int)(255 * scaled_rms);
        int green = (int)(255 * (1.0 - scaled_rms));
        int blue = 0;

        set_rgb(red, green, blue);
    }
}

int main(int argc, char *argv[]) {
    float sensitivity = SENSITIVITY_DEFAULT;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default.\n");
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_alsa() < 0) {
        fprintf(stderr, "Failed to initialize ALSA\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer = (unsigned char *)malloc(PERIOD_SIZE * NUM_CHANNELS * 2);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting audio capture and mood light control\n");

    struct timespec sleep_time = {0, BUFFER_TIME_MS * 1000000};

    while (keep_running) {
        process_audio_buffer(capture_handle, sensitivity);
        nanosleep(&sleep_time, NULL);
    }

    printf("Stopping audio capture and mood light control\n");
    cleanup();
    return EXIT_SUCCESS;
}

