        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer = (unsigned char *)malloc(PERIOD_SIZE * NUM_CHANNELS * 2);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting audio capture and mood light control\n");

    struct timespec sleep_time = {0, BUFFER_TIME_MS * 1000000};

    while (keep_running) {
        process_audio_buffer(capture_handle, sensitivity);
        nanosleep(&sleep_time, NULL);
    }

