#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define INTEGRATION_TIME 154 // in ms
#define SAMPLE_INTERVAL 500 // in ms

static int i2c_fd;
static FILE *csv_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    if (gpioInitialise() == PI_INIT_FAILED) {
        fprintf(stderr, "Failed to initialize GPIO\n");
    }
    exit(signum);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C read register error\n");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read data error\n");
        return -1;
    }
    return 0;
}

int configure_sensor() {
    if (i2c_write(i2c_fd, 0x00 | 0x80, 0x03) < 0) return -1; // Power on
    usleep(3000); // Wait for power on
    if (i2c_write(i2c_fd, 0x01 | 0x80, 0x00) < 0) return -1; // Disable interrupts
    if (i2c_write(i2c_fd, 0x0F | 0x80, INTEGRATION_TIME) < 0) return -1; // Set integration time
    if (i2c_write(i2c_fd, 0x00 | 0x80, 0x01) < 0) return -1; // Enable device
    return 0;
}

int read_sensor(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t data[8];
    if (i2c_read(i2c_fd, 0x14 | 0x80, data, 8) < 0) return -1;
    *c = (data[1] << 8) | data[0];
    *r = (data[3] << 8) | data[2];
    *g = (data[5] << 8) | data[4];
    *b = (data[7] << 8) | data[6];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() != PI_INIT_FAILED) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor() < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen("color_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "Timestamp,C,R,G,B\n");
    fflush(csv_file);

    while (1) {
        time_t now = time(NULL);
        uint16_t c, r, g, b;

        if (read_sensor(&c, &r, &g, &b) < 0) {
            c = r = g = b = 0;
        }

        fprintf(csv_file, "%ld,%u,%u,%u,%u\n", now, c, r, g, b);
        fflush(csv_file);

        time_t next_sample = now + SAMPLE_INTERVAL / 1000;
        while (time(NULL) < next_sample) {
            usleep(10000);
        }
    }

    return 0;
}

