#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define CYCLE_DURATION 32400 // Total cycle duration in seconds (1 + 6 + 1 + 14.4) * 3600
#define Sunrise_DURATION 3600
#define Daytime_DURATION 21600
#define Sunset_DURATION 3600
#define Nighttime_DURATION 51840

#define MAX_DUTY_CYCLE 100
#define DUTY_CYCLE_STEP 1

struct gpiod_chip *chip;
struct gpiod_line *relay1, *relay2, *relay3, *relay4;

void cleanup(int signum) {
    printf("Received signal %d. Cleaning up...\n", signum);

    if (relay1) gpiod_line_release(relay1);
    if (relay2) gpiod_line_release(relay2);
    if (relay3) gpiod_line_release(relay3);
    if (relay4) gpiod_line_release(relay4);
    if (chip) gpiod_chip_close(chip);

    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    int duty_cycle = 0;
    int direction = 1; // 1 for increasing, -1 for decreasing

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay1 = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2 = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3 = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4 = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1 || !relay2 || !relay3 || !relay4) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(0);
    }

    ret = gpiod_line_request_output(relay1, "Relay1", 0);
    ret |= gpiod_line_request_output(relay2, "Relay2", 0);
    ret |= gpiod_line_request_output(relay3, "Relay3", 0);
    ret |= gpiod_line_request_output(relay4, "Relay4", 0);

    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup(0);
    }

    while (1) {
        for (int i = 0; i < CYCLE_DURATION; i++) {
            if (i < Sunrise_DURATION) {
                duty_cycle += direction;
                if (duty_cycle >= MAX_DUTY_CYCLE) {
                    duty_cycle = MAX_DUTY_CYCLE;
                    direction = -1;
                }
            } else if (i >= (Sunrise_DURATION + Daytime_DURATION + Sunset_DURATION)) {
                duty_cycle += direction;
                if (duty_cycle <= 0) {
                    duty_cycle = 0;
                    direction = 1;
                }
            }

            int relay_state = (i % 100) < duty_cycle ? 0 : 1; // Active-low relay

            gpiod_line_set_value(relay1, relay_state);
            gpiod_line_set_value(relay2, relay_state);
            gpiod_line_set_value(relay3, relay_state);
            gpiod_line_set_value(relay4, relay_state);

            usleep(10000); // 10ms delay
        }
    }

    return EXIT_SUCCESS;
}

