#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/wait.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 200
#define CAPTURE_DURATION 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_DIR "/home/pi/logs/"
#define LOG_FILE "motion_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void sigint_handler(int signum) {
    printf("Interrupt received, cleaning up...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

char* get_timestamp() {
    time_t now;
    struct tm *tm_info;
    char *timestamp;

    time(&now);
    tm_info = localtime(&now);
    timestamp = malloc(20 * sizeof(char));
    if (!timestamp) {
        perror("Failed to allocate memory for timestamp");
        exit(EXIT_FAILURE);
    }
    strftime(timestamp, 20, "%Y%m%d_%H%M%S", tm_info);
    return timestamp;
}

char* get_iso8601_timestamp() {
    time_t now;
    struct tm *tm_info;
    char *timestamp;

    time(&now);
    tm_info = gmtime(&now);
    timestamp = malloc(30 * sizeof(char));
    if (!timestamp) {
        perror("Failed to allocate memory for ISO 8601 timestamp");
        exit(EXIT_FAILURE);
    }
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp;
}

void log_motion_event() {
    char *iso_timestamp = get_iso8601_timestamp();
    fprintf(log_file, "%s\n", iso_timestamp);
    fflush(log_file);
    free(iso_timestamp);
}

void capture_video() {
    char *timestamp = get_timestamp();
    char command[256];
    snprintf(command, sizeof(command), "raspivid -t %d000 -o %s%s.h264", CAPTURE_DURATION * 1000, VIDEO_DIR, timestamp);

    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Video capture failed with error code: %d\n", result);
    }

    free(timestamp);
}

int main() {
    struct timespec wait_time = {0, DEBOUNCE_TIME_MS * 1000000};
    int last_state = 1;  // Active-low, so initially high (1)
    time_t last_trigger_time = 0;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(line, "KY-033_IR_Sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(strcat(LOG_DIR, LOG_FILE), "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    printf("Monitoring IR sensor on GPIO %d...\n", GPIO_PIN);

    while (1) {
        int current_state = gpiod_line_get_value(line);
        if (current_state == 0 && last_state == 1) {  // Motion detected (active-low)
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) >= DEBOUNCE_TIME_MS / 1000.0) {
                printf("Motion detected!\n");
                log_motion_event();
                capture_video();
                last_trigger_time = current_time;
            }
        }
        last_state = current_state;
        nanosleep(&wait_time, NULL);
    }

    return 0;
}

