            if (difftime(current_time, last_trigger_time) >= DEBOUNCE_TIME_MS / 1000.0) {
                printf("Motion detected!\n");
                log_motion_event();
                capture_video();
                last_trigger_time = current_time;
            }
        }
        last_state = current_state;
        nanosleep(&wait_time, NULL);
    }

    return 0;
}
