#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define GYRO_SCALE 131.0
#define SAMPLE_RATE 100
#define MAX_RETRIES 3

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000000; // 10ms

    int16_t x, y, z;
    struct timespec start, end;
    int retries;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_gyro(&x, &y, &z) == 0) {
                break;
            }
            retries++;
            usleep(10000); // 10ms
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read gyro data after %d attempts\n", MAX_RETRIES);
            continue;
        }

        double x_degps = x / GYRO_SCALE;
        double y_degps = y / GYRO_SCALE;
        double z_degps = z / GYRO_SCALE;

        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        double timestamp = now.tv_sec + now.tv_nsec / 1e9;

        fprintf(log_file, "%.3f,%.3f,%.3f,%.3f\n", timestamp, x_degps, y_degps, z_degps);
        fflush(log_file);

        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns < 10000000) {
            ts.tv_nsec = 10000000 - elapsed_ns;
        } else {
            ts.tv_sec = elapsed_ns / 1000000000;
            ts.tv_nsec = elapsed_ns % 1000000000;
        }
    }

    return EXIT_SUCCESS;
}

