#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define NUM_RELAYS 4
#define RELAY_PINS[NUM_RELAYS] = {4, 17, 27, 22}
#define LOG_FILE "irrigation_log.txt"
#define MOISTURE_THRESHOLD 30
#define LOOP_INTERVAL 5

int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];
FILE *log_file;

void signal_handler(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", relay_pins[i]);
            signal_handler(SIGINT);
        }

        int ret = gpiod_line_request_output(lines[i], "relay", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", relay_pins[i]);
            signal_handler(SIGINT);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        signal_handler(SIGINT);
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "Timestamp: %s\n", timestamp);

        for (int i = 0; i < NUM_RELAYS; i++) {
            int moisture = rand() % 100;
            int relay_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

            int ret = gpiod_line_set_value(lines[i], !relay_state);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO %d\n", relay_pins[i]);
                signal_handler(SIGINT);
            }

            fprintf(log_file, "Relay %d: Moisture %d%%, State %s\n",
                    i + 1, moisture, relay_state ? "ON" : "OFF");
        }

        fprintf(log_file, "\n");
        fflush(log_file);
        sleep(LOOP_INTERVAL);
    }

    return EXIT_SUCCESS;
}

