#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_MEASURE 0x08
#define GRAVITY 9.81
#define SAMPLE_RATE 100
#define FREE_FALL_THRESHOLD 0.2
#define FREE_FALL_DURATION 500
#define ALARM_PIN 27
#define LOG_FILE "freefall.log"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *alarm_line;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        fprintf(stdout, "Caught SIGINT, cleaning up...\n");
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    ssize_t bytes_written = write(fd, buf, sizeof(buf));
    if (bytes_written != sizeof(buf)) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C register: %s\n", strerror(errno));
        return -1;
    }
    ssize_t bytes_read = read(fd, value, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read(i2c_fd, ADXL345_DATAX0, buf, sizeof(buf)) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_line, "ADXL345 Free-Fall Alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, ADXL345_MEASURE) != 0) {
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    int free_fall_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_acceleration(&x, &y, &z) != 0) {
            continue;
        }

        float x_g = (float)x / 256.0 * GRAVITY;
        float y_g = (float)y / 256.0 * GRAVITY;
        float z_g = (float)z / 256.0 * GRAVITY;

        if (fabs(x_g) < FREE_FALL_THRESHOLD &&
            fabs(y_g) < FREE_FALL_THRESHOLD &&
            fabs(z_g) < FREE_FALL_THRESHOLD) {
            free_fall_count++;
        } else {
            free_fall_count = 0;
        }

        if (free_fall_count >= 2) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

            if (elapsed_ms >= FREE_FALL_DURATION) {
                gpiod_line_set_value(alarm_line, 1);
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                        tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                        tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                        x_g, y_g, z_g);
                fflush(log_file);

                usleep(5000000);  // 5 seconds
                gpiod_line_set_value(alarm_line, 0);
                free_fall_count = 0;
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        }

        usleep(SAMPLE_RATE * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return EXIT_SUCCESS;
}

