        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, ADXL345_POWER_CTL, ADXL345_MEASURE) != 0) {
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    int free_fall_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_acceleration(&x, &y, &z) != 0) {
            continue;
        }

        float x_g = (float)x / 256.0 * GRAVITY;
        float y_g = (float)y / 256.0 * GRAVITY;
        float z_g = (float)z / 256.0 * GRAVITY;

        if (fabs(x_g) < FREE_FALL_THRESHOLD &&
            fabs(y_g) < FREE_FALL_THRESHOLD &&
            fabs(z_g) < FREE_FALL_THRESHOLD) {
            free_fall_count++;
        } else {
            free_fall_count = 0;
        }

        if (free_fall_count >= 2) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

            if (elapsed_ms >= FREE_FALL_DURATION) {
                gpiod_line_set_value(alarm_line, 1);
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                        tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                        tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                        x_g, y_g, z_g);
                fflush(log_file);

                usleep(5000000);  // 5 seconds
                gpiod_line_set_value(alarm_line, 0);
                free_fall_count = 0;
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        }

        usleep(SAMPLE_RATE * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    return EXIT_SUCCESS;
}
