#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <errno.h>
#include <unistd.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define TRIGGER_DELAY_MS 200
#define MAX_PULSE_WIDTH_US 23200
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static FILE *log_file;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int keep_running = 1;
static uint32_t tick_counter = 0;

static uint32_t get_tick_counter(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint32_t)(ts.tv_sec * 1000000000 + ts.tv_nsec);
}

static void trigger_pulse(void) {
    gpiod_line_set_value(trig_line, 1);
    usleep(TRIGGER_PULSE_US);
    gpiod_line_set_value(trig_line, 0);
}

static void handle_echo_rising_edge(void) {
    static uint32_t start_time = 0;
    pthread_mutex_lock(&mutex);
    if (start_time == 0) {
        start_time = get_tick_counter();
    }
    pthread_mutex_unlock(&mutex);
}

static void handle_echo_falling_edge(void) {
    uint32_t end_time, pulse_width;
    pthread_mutex_lock(&mutex);
    end_time = get_tick_counter();
    if (end_time >= start_time) {
        pulse_width = end_time - start_time;
    } else {
        pulse_width = UINT32_MAX - start_time + end_time;
    }
    start_time = 0;
    pthread_mutex_unlock(&mutex);

    if (pulse_width <= MAX_PULSE_WIDTH_US * 1000) {
        uint32_t timestamp = get_tick_counter();
        float distance_cm = pulse_width / 58.0f; // Speed of sound ~343 m/s -> 58 µs/cm
        fprintf(log_file, "%u,%f\n", timestamp, distance_cm);
        fflush(log_file);
    }
}

static void *echo_monitor(void *arg) {
    while (keep_running) {
        int echo_state = gpiod_line_get_value(echo_line);
        if (echo_state) {
            handle_echo_rising_edge();
        } else {
            handle_echo_falling_edge();
        }
        usleep(1000); // Check every 1 ms
    }
    return NULL;
}

static void sigint_handler(int signum) {
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig_line, "hc-sr04-trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    pthread_t echo_thread;
    if (pthread_create(&echo_thread, NULL, echo_monitor, NULL) != 0) {
        perror("pthread_create");
        goto cleanup;
    }

    while (keep_running) {
        trigger_pulse();
        usleep(TRIGGER_DELAY_MS * 1000);
    }

    pthread_join(echo_thread, NULL);

cleanup:
    if (log_file) fclose(log_file);
    if (echo_line) gpiod_line_release(echo_line);
    if (trig_line) gpiod_line_release(trig_line);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

