#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define DEFAULT_FREE_FALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define BUZZER_PIN 17
#define MAX_RETRIES 3

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int init_i2c() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_sensor() {
    uint8_t ctrl_reg1 = 0x20; // Normal mode, 50Hz data rate
    uint8_t ctrl_reg4 = 0x08; // Full scale = 2g
    return (i2c_write(i2c_fd, 0x20, ctrl_reg1) == 1 &&
            i2c_write(i2c_fd, 0x23, ctrl_reg4) == 1);
}

int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read(i2c_fd, 0x28 | 0x80, buf) == 1) {
            *x = (buf[0] | (buf[1] << 8));
            *y = (buf[2] | (buf[3] << 8));
            *z = (buf[4] | (buf[5] << 8));
            return 0;
        }
        usleep(10000); // 10ms delay between retries
    }
    return -1;
}

float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf(x*x + y*y + z*z) / 16384.0; // LSB/g = 16384
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return -1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line for buzzer\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return -1;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for buzzer\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return -1;
    }
    return 0;
}

void activate_buzzer() {
    gpiod_line_set_value(buzzer_line, 1);
    usleep(1000000); // 1 second
    gpiod_line_set_value(buzzer_line, 0);
}

int main(int argc, char *argv[]) {
    float free_fall_threshold = DEFAULT_FREE_FALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        free_fall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    signal(SIGINT, cleanup);

    if (init_i2c() < 0 || init_sensor() < 0 || init_gpio() < 0) {
        fprintf(stderr, "Initialization failed\n");
        return 1;
    }

    int16_t x, y, z;
    float magnitude, prev_magnitude = 0;
    int in_free_fall = 0;

    while (keep_running) {
        if (read_accel(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        magnitude = calculate_magnitude(x, y, z);

        if (magnitude < free_fall_threshold) {
            in_free_fall = 1;
        } else if (in_free_fall && magnitude > impact_threshold) {
            activate_buzzer();
            in_free_fall = 0;
        }

        prev_magnitude = magnitude;
        usleep(100000); // 100ms delay between readings
    }

    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

