#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define DEFAULT_I2C_ADDR 0x19
#define DEFAULT_THRESHOLD 2.0
#define I2C_BUS 1
#define LOG_FILE "/var/log/high_acceleration.log"

static int i2c_addr = DEFAULT_I2C_ADDR;
static float threshold = DEFAULT_THRESHOLD;
static int i2c_handle;

void cleanup_and_exit(int code) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(code);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    cleanup_and_exit(0);
}

void log_high_acceleration(float x, float y, float z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] High acceleration detected: X=%.2f g, Y=%.2f g, Z=%.2f g\n", timestamp, x, y, z);
    fclose(log_file);

    printf("High acceleration detected! Shutting down...\n");
    system("sudo shutdown -h now");
}

int read_acceleration(int handle, float *x, float *y, float *z) {
    unsigned char buffer[6];
    if (i2cReadI2CBlock(handle, i2c_addr, 0x80 | 0x28, 6, buffer) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        *x = *y = *z = 0.0f;
        return -1;
    }

    int16_t raw_x = (buffer[0] | (buffer[1] << 8));
    int16_t raw_y = (buffer[2] | (buffer[3] << 8));
    int16_t raw_z = (buffer[4] | (buffer[5] << 8));

    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

int configure_sensor(int handle) {
    // CTRL_REG1: Normal mode, 100Hz data rate
    if (i2cWriteByte(handle, i2c_addr, 0x20, 0x67) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: High resolution mode, ±2g range
    if (i2cWriteByte(handle, i2c_addr, 0x23, 0x88) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = strtol(optarg, NULL, 16);
                if (i2c_addr < 0x03 || i2c_addr > 0x77) {
                    fprintf(stderr, "Invalid I2C address\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a I2C_ADDRESS] [-t THRESHOLD]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup_and_exit(0);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            continue;
        }

        if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
            log_high_acceleration(x, y, z);
        }

        usleep(100000); // 100ms
    }

    return 0;
}

