    if (gpioInitialise() < 0) {
        log_message("Failed to initialize GPIO library");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        gpioTerminate();
        return 1;
