#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <gpiod.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, client_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (client_fd >= 0) {
        close(client_fd);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    log_event("Shutting down...");
    cleanup();
    exit(0);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("Setsockopt failed");
        cleanup();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    log_event("Server started, waiting for connections...");

    while (1) {
        // Accept connection
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            continue;
        }

        log_event("New connection accepted");

        // Read command
        ssize_t valread = read(client_fd, buffer, 1024);
        if (valread > 0) {
            buffer[valread] = '\0';
            char *command = strtok(buffer, " \t\n\r");
            if (command) {
                for (char *p = command; *p; ++p) *p = toupper(*p); // Convert to uppercase

                if (strcmp(command, "ON") == 0) {
                    gpiod_line_set_value(line, 1);
                    log_event("Relay turned ON");
                } else if (strcmp(command, "OFF") == 0) {
                    gpiod_line_set_value(line, 0);
                    log_event("Relay turned OFF");
                } else {
                    log_event("Invalid command received");
                }
            }
        }

        close(client_fd);
    }

    return 0;
}

