#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define SENSOR1_ADDR 0x61
#define SENSOR2_ADDR 0x62
#define I2C_BUS 1
#define RELAY_PIN 18
#define POLL_INTERVAL_MS 100
#define FLOW_THRESHOLD 5.0

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd1, i2c_fd2;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static float parse_flow_rate(const uint8_t *data) {
    return (float)((data[0] << 8) | data[1]) / 100.0;
}

static int read_sensor(int fd, uint8_t *buffer) {
    if (read(fd, buffer, 3) != 3) {
        return -1;
    }
    return crc8(buffer, 2) == buffer[2] ? 0 : -1;
}

static void cleanup(int signum) {
    fprintf(stderr, "Shutting down...\n");
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd1 >= 0) {
        close(i2c_fd1);
    }
    if (i2c_fd2 >= 0) {
        close(i2c_fd2);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay-control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_fd1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    i2c_fd2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        close(i2c_fd1);
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address for sensor 1\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address for sensor 2\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    uint8_t start_measurement[] = {0x00, 0x10};
    if (write(i2c_fd1, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        fprintf(stderr, "Failed to start measurement for sensor 1\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd2, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        fprintf(stderr, "Failed to start measurement for sensor 2\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer1[3], buffer2[3];
        struct timespec ts;
        char timestamp[64];

        if (read_sensor(i2c_fd1, buffer1) != 0 || read_sensor(i2c_fd2, buffer2) != 0) {
            fprintf(stderr, "Warning: Sensor read failed or CRC check failed\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float flow_rate1 = parse_flow_rate(buffer1);
        float flow_rate2 = parse_flow_rate(buffer2);

        fprintf(log_file, "%s.%03ld,%.2f,%.2f\n", timestamp, ts.tv_nsec / 1000000, flow_rate1, flow_rate2);
        fflush(log_file);

        int relay_state = (flow_rate1 >= FLOW_THRESHOLD && flow_rate2 >= FLOW_THRESHOLD) ? 0 : 1;
        gpiod_line_set_value(line, relay_state);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    cleanup(0);
    return EXIT_SUCCESS;
}

