    uint8_t start_measurement[] = {0x00, 0x10};
    if (write(i2c_fd1, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        fprintf(stderr, "Failed to start measurement for sensor 1\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd2, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        fprintf(stderr, "Failed to start measurement for sensor 2\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer1[3], buffer2[3];
        struct timespec ts;
        char timestamp[64];

        if (read_sensor(i2c_fd1, buffer1) != 0 || read_sensor(i2c_fd2, buffer2) != 0) {
            fprintf(stderr, "Warning: Sensor read failed or CRC check failed\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float flow_rate1 = parse_flow_rate(buffer1);
        float flow_rate2 = parse_flow_rate(buffer2);

        fprintf(log_file, "%s.%03ld,%.2f,%.2f\n", timestamp, ts.tv_nsec / 1000000, flow_rate1, flow_rate2);
        fflush(log_file);

        int relay_state = (flow_rate1 >= FLOW_THRESHOLD && flow_rate2 >= FLOW_THRESHOLD) ? 0 : 1;
        gpiod_line_set_value(line, relay_state);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    cleanup(0);
    return EXIT_SUCCESS;
}
