                if (set_gpio_value(ena, 1) == 0 &&
                    set_gpio_value(in1, 1) == 0 &&
                    set_gpio_value(in2, 0) == 0) {
                    usleep(MOTOR_RUN_TIME_US);
                    set_gpio_value(ena, 0);
                    set_gpio_value(in1, 0);
                    set_gpio_value(in2, 0);
                    syslog(LOG_INFO, "Close-window sequence completed");
                }
                rain_detected = 0;
                dry_poll_count = 0;
            }
        } else {  // Wet
            dry_poll_count = 0;
            if (!rain_detected) {
                syslog(LOG_INFO, "Rain detected");
                rain_detected = 1;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

