#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY_MS 50
#define LOCK_PULSE_WIDTH_US 2000
#define UNLOCK_PULSE_WIDTH_US 1000
#define SHUTDOWN_PULSE_WIDTH_US 0

static struct gpiod_chip *chip;
static struct gpiod_line *servo_line;
static struct gpiod_line *lock_button_line;
static struct gpiod_line *unlock_button_line;
static volatile int running = 1;

void cleanup_and_exit(int status) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (lock_button_line) {
        gpiod_line_release(lock_button_line);
    }
    if (unlock_button_line) {
        gpiod_line_release(unlock_button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(status);
}

void signal_handler(int signum) {
    printf("Shutting down...\n");
    running = 0;
}

int set_servo_pulse_width(int pin, int width_us) {
    int ret = gpiod_line_set_value(servo_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set servo high\n");
        return -1;
    }
    usleep(width_us);
    ret = gpiod_line_set_value(servo_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set servo low\n");
        return -1;
    }
    usleep(20000 - width_us); // Ensure 20ms period
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        fprintf(stderr, "Failed to get servo line\n");
        cleanup_and_exit(1);
    }

    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON_PIN);
    if (!lock_button_line) {
        fprintf(stderr, "Failed to get lock button line\n");
        cleanup_and_exit(1);
    }

    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    if (!unlock_button_line) {
        fprintf(stderr, "Failed to get unlock button line\n");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_input(lock_button_line, "lock_button") < 0 ||
        gpiod_line_request_input(unlock_button_line, "unlock_button") < 0) {
        fprintf(stderr, "Failed to request button lines as input\n");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        fprintf(stderr, "Failed to request servo line as output\n");
        cleanup_and_exit(1);
    }

    while (running) {
        if (gpiod_line_get_value(lock_button_line) == 0) {
            printf("Lock button pressed\n");
            if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH_US) < 0) {
                fprintf(stderr, "Failed to set lock pulse width\n");
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
            while (gpiod_line_get_value(lock_button_line) == 0) {
                usleep(1000);
            }
        } else if (gpiod_line_get_value(unlock_button_line) == 0) {
            printf("Unlock button pressed\n");
            if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH_US) < 0) {
                fprintf(stderr, "Failed to set unlock pulse width\n");
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
            while (gpiod_line_get_value(unlock_button_line) == 0) {
                usleep(1000);
            }
        }
        usleep(1000); // Small delay to keep CPU usage low
    }

    printf("Sending shutdown signal to servo\n");
    if (set_servo_pulse_width(SERVO_PIN, SHUTDOWN_PULSE_WIDTH_US) < 0) {
        fprintf(stderr, "Failed to set shutdown pulse width\n");
    }

    cleanup_and_exit(0);
}

