#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_MS 100
#define LED_DURATION_S 60

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *led_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void log_event(const char *event, time_t timestamp, double duration) {
    struct tm tm_info;
    char time_str[64];

    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "Error formatting time string\n");
        return;
    }

    if (fprintf(log_file, "%s %s", time_str, event) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return;
    }

    if (duration > 0) {
        if (fprintf(log_file, " %.2f seconds", duration) < 0) {
            fprintf(stderr, "Error writing duration to log file\n");
            return;
        }
    }

    if (fprintf(log_file, "\n") < 0) {
        fprintf(stderr, "Error writing newline to log file\n");
        return;
    }
}

int main() {
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
    int ret;

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Request PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error getting PIR sensor line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_input(pir_line, "PIR Sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting PIR sensor line as input\n");
        goto cleanup;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(led_line, "LED Floodlight", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output\n");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        goto cleanup;
    }

    time_t activation_time;
    int pir_state = 0;

    while (!terminate) {
        int new_state = gpiod_line_get_value(pir_line);
        if (new_state < 0) {
            fprintf(stderr, "Error reading PIR sensor state\n");
            break;
        }

        if (new_state && !pir_state) {
            // Rising edge detected
            activation_time = time(NULL);
            gpiod_line_set_value(led_line, 1);
            log_event("Activated", activation_time, 0);
        } else if (!new_state && pir_state) {
            // Falling edge detected
            time_t deactivation_time = time(NULL);
            double duration = difftime(deactivation_time, activation_time);
            gpiod_line_set_value(led_line, 0);
            log_event("Deactivated", deactivation_time, duration);
        }

        pir_state = new_state;
        nanosleep(&sleep_time, NULL);
    }

    // Ensure LED is off on exit
    gpiod_line_set_value(led_line, 0);

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

