#define MPR121_DEBOUNCE 0x5B
#define MPR121_FFI 0x29
#define MPR121_SFI 0x2A
#define MPR121_CDT 0x2F
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_AUTOCONFIG2 0x7D
#define MPR121_UPPER_THRESH_TOUCH 0x41
#define MPR121_LOWER_THRESH_TOUCH 0x42
#define MPR121_ELECTRODE_CONFIG 0x5E

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (line) {
