        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(i2c_fd, buf, 2);
}

int i2c_read(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    return read(i2c_fd, value, 1);
}

int mpr121_init() {
    // Soft reset
    if (i2c_write(MPR121_SOFT_RESET, 0x63) != 2) return -1;
    usleep(10000); // Wait 10ms

    // Configure baseline filtering
    if (i2c_write(MPR121_MHD_R, 0x01) != 2 ||
        i2c_write(MPR121_NHD_R, 0x01) != 2 ||
        i2c_write(MPR121_NCL_R, 0x00) != 2 ||
        i2c_write(MPR121_FDL_R, 0x00) != 2) return -1;

    // Set debounce
    if (i2c_write(MPR121_DEBOUNCE, 0x00) != 2) return -1;

    // Configure FFI, SFI, CDT
    if (i2c_write(MPR121_FFI, 0x04) != 2 ||
        i2c_write(MPR121_SFI, 0x04) != 2 ||
        i2c_write(MPR121_CDT, 0x04) != 2) return -1;

    // Enable auto-config
    if (i2c_write(MPR121_AUTOCONFIG0, 0x0B) != 2 ||
        i2c_write(MPR121_AUTOCONFIG1, 0x0A) != 2 ||
        i2c_write(MPR121_AUTOCONFIG2, 0x00) != 2) return -1;

    // Set electrode configuration
    for (int i = 0; i < 12; i++) {
        if (i2c_write(MPR121_ELECTRODE_CONFIG + i, 0x00) != 2) return -1;
    }

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2c_write(MPR121_UPPER_THRESH_TOUCH + i, 0x10) != 2 ||
            i2c_write(MPR121_LOWER_THRESH_TOUCH + i, 0x0A) != 2) return -1;
    }

    // Enable interrupts
    if (i2c_write(MPR121_ELECTRODE_CONFIG, 0x0C) != 2) return -1;

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set relay to OFF
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_OFF);

    // Open I2C bus
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(0);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup(0);
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup(0);
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(0);
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup(0);
    }

    if (gpiod_line_request_output(line, "relay-control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        cleanup(0);
    }

    uint8_t last_touch_status = 0;
    uint32_t last_touch_time = 0;

    while (1) {
        uint8_t touch_status;
        if (i2c_read(MPR121_TOUCH_STATUS, &touch_status) != 1) {
            fprintf(stderr, "Failed to read touch status\n");
            cleanup(0);
        }

        uint32_t current_time = time(NULL) * 1000;
        if ((touch_status & 0x01) && !(last_touch_status & 0x01) &&
            (current_time - last_touch_time > DEBOUNCE_TIME_MS)) {
            gpiod_line_set_value(line, 1);
            printf("Relay ON\n");
        } else if (!(touch_status & 0x01) && (last_touch_status & 0x01)) {
            gpiod_line_set_value(line, 0);
            printf("Relay OFF\n");
        }

        last_touch_status = touch_status;
        last_touch_time = current_time;

        usleep(10000); // Sleep for 10ms
    }

    return 0;
}

