#define PIR_PIN 4
#define TCP_PORT 5000
#define PWM_FREQ 50
#define PWM_DURATION 20000 // 20ms
#define LOG_FILE "security.log"

static int gpiochip_fd = -1;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static int server_fd = -1;
static FILE *log_file = NULL;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);

    va_end(args);

    va_start(args, format);
    syslog(LOG_USER | LOG_INFO, format, args);
    va_end(args);
}

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] ERROR: ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);

    va_end(args);

    va_start(args, format);
    syslog(LOG_USER | LOG_ERR, format, args);
    va_end(args);
}

void cleanup(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpiochip_fd >= 0) {
        close(gpiochip_fd);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    closelog();
}

void signal_handler(int signum) {
    log_message("Received signal %d, shutting down...", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    openlog("servo_pir_control", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    gpiochip_fd = gpiod_open("/dev/gpiochip0");
    if (gpiochip_fd < 0) {
        log_error("Failed to open GPIO chip: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    servo_line = gpiod_get_line(gpiochip_fd, SERVO_PIN);
    if (!servo_line) {
        log_error("Failed to get servo line: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pir_line = gpiod_get_line(gpiochip_fd, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_error("Failed to request servo line as output: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_error("Failed to request PIR line as input: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("Failed to create socket: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_error("Failed to set socket options: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Failed to bind socket: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        log_error("Failed to listen on socket: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Server listening on port %d", TCP_PORT);

    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);

        if (client_fd < 0) {
            log_error("Failed to accept client connection: %s", strerror(errno));
            continue;
        }

        char buffer[1024] = {0};
        ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            log_message("Received command: %s", buffer);

            if (strncmp(buffer, "set_servo ", 10) == 0) {
                int angle = atoi(buffer + 10);
                if (angle >= 0 && angle <= 180) {
                    int duty_cycle = (angle * PWM_DURATION) / 180;
                    for (int i = 0; i < PWM_FREQ; i++) {
                        gpiod_line_set_value(servo_line, 1);
                        usleep(duty_cycle);
                        gpiod_line_set_value(servo_line, 0);
                        usleep(PWM_DURATION - duty_cycle);
                    }
                    char response[50];
                    snprintf(response, sizeof(response), "Servo set to %d degrees", angle);
                    log_message("%s", response);
                    write(client_fd, response, strlen(response));
                } else {
                    const char *error_msg = "Invalid angle. Must be between 0 and 180.";
                    log_message("%s", error_msg);
                    write(client_fd, error_msg, strlen(error_msg));
                }
            } else if (strcmp(buffer, "PIR") == 0) {
                int pir_value = gpiod_line_get_value(pir_line);
                char response[10];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                log_message("%s", response);
                write(client_fd, response, strlen(response));
            } else {
                const char *error_msg = "Unknown command";
                log_message("%s", error_msg);
                write(client_fd, error_msg, strlen(error_msg));
            }
        } else if (bytes_read == 0) {
            log_message("Client disconnected");
        } else {
            log_error("Failed to read from client: %s", strerror(errno));
        }

        close(client_fd);
    }

    return EXIT_SUCCESS;
}
