#define SENSOR_ADDR 0x23
#define LOG_FILE "grow_log.txt"
#define RELAY_PIN 23
#define SAMPLE_INTERVAL 2
#define LUX_THRESHOLD 150
#define I2C_BUS 1

static int i2c_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "grow-light-relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        unsigned char cmd = 0x20; // Power on and start measurement
        if (i2cWriteByteData(i2c_handle, cmd, 0) < 0) {
            fprintf(stderr, "Failed to send command to sensor\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        usleep(120000); // Wait 120ms

        unsigned char data[2];
        if (i2cReadI2CBlockData(i2c_handle, 0, data, 2) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float lux = (data[0] << 8) | data[1];
        lux /= 1.2; // Convert to lux

        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);

        if (lux < LUX_THRESHOLD) {
            gpiod_line_set_value(line, 1); // Activate relay
        } else {
            gpiod_line_set_value(line, 0); // Deactivate relay
        }

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

