#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define NUM_TARE_READINGS 10
#define NUM_AVG_READINGS 5
#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 25
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int gpio_set_mode(struct gpiod_chip *chip, int line_offset, int direction) {
    int ret = gpiod_line_request_config(chip, line_offset, direction, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for pin %d", line_offset);
    }
    return ret;
}

int gpio_write(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to write to GPIO line");
    }
    return ret;
}

int gpio_read(struct gpiod_line *line) {
    int value, ret;
    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read from GPIO line");
        return -1;
    }
    value = ret;
    return value;
}

int hx711_read(struct gpiod_chip *chip, struct gpiod_line *dout, struct gpiod_line *sck) {
    int value = 0;
    int retries = 0;
    struct timespec start, current;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (retries < MAX_RETRIES) {
        if (gpio_read(dout) == 0) {
            for (int i = 0; i < 24; i++) {
                gpio_write(sck, 1);
                gpio_write(sck, 0);
                value = (value << 1) | gpio_read(dout);
            }
            gpio_write(sck, 1);
            gpio_write(sck, 0);
            return value;
        }

        clock_gettime(CLOCK_MONOTONIC, &current);
        if ((current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000 > 1000) {
            syslog(LOG_ERR, "Timeout waiting for DOUT to go LOW");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    syslog(LOG_ERR, "Failed to read HX711 after %d retries", MAX_RETRIES);
    return -1;
}

void tare_scale(struct gpiod_chip *chip, struct gpiod_line *dout, struct gpiod_line *sck) {
    long sum = 0;
    for (int i = 0; i < NUM_TARE_READINGS; i++) {
        int reading = hx711_read(chip, dout, sck);
        if (reading < 0) {
            syslog(LOG_ERR, "Failed to read during tare");
            exit(EXIT_FAILURE);
        }
        sum += reading;
        usleep(10000);  // Small delay between readings
    }
    syslog(LOG_INFO, "Tare completed. Offset: %ld", sum / NUM_TARE_READINGS);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor");

    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck, *solenoid;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(chip, HX711_DOUT_PIN, GPIOD_LINE_DIRECTION_INPUT) < 0 ||
        gpio_set_mode(chip, HX711_SCK_PIN, GPIOD_LINE_DIRECTION_OUTPUT) < 0 ||
        gpio_set_mode(chip, SOLENOID_PIN, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    tare_scale(chip, dout, sck);

    while (keep_running) {
        long sum = 0;
        for (int i = 0; i < NUM_AVG_READINGS; i++) {
            int reading = hx711_read(chip, dout, sck);
            if (reading < 0) {
                syslog(LOG_ERR, "Failed to read during measurement");
                continue;
            }
            sum += reading;
            usleep(10000);  // Small delay between readings
        }
        double weight = (sum / (double)NUM_AVG_READINGS - threshold) * scale;
        syslog(LOG_INFO, "Current weight: %.2f g", weight);

        if (weight > 0) {
            gpio_write(solenoid, 1);
            usleep(duration * 1000);
            gpio_write(solenoid, 0);
        }

        usleep(500000);  // 500ms delay between measurements
    }

    gpio_write(solenoid, 0);  // Ensure solenoid is LOW on exit

    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);

    closelog();
    syslog(LOG_INFO, "Weight monitor stopped");

    return 0;
}

