                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor");

    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck, *solenoid;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(chip, HX711_DOUT_PIN, GPIOD_LINE_DIRECTION_INPUT) < 0 ||
        gpio_set_mode(chip, HX711_SCK_PIN, GPIOD_LINE_DIRECTION_OUTPUT) < 0 ||
        gpio_set_mode(chip, SOLENOID_PIN, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    tare_scale(chip, dout, sck);

    while (keep_running) {
        long sum = 0;
        for (int i = 0; i < NUM_AVG_READINGS; i++) {
            int reading = hx711_read(chip, dout, sck);
            if (reading < 0) {
                syslog(LOG_ERR, "Failed to read during measurement");
                continue;
            }
            sum += reading;
            usleep(10000);  // Small delay between readings
        }
        double weight = (sum / (double)NUM_AVG_READINGS - threshold) * scale;
        syslog(LOG_INFO, "Current weight: %.2f g", weight);

        if (weight > 0) {
            gpio_write(solenoid, 1);
            usleep(duration * 1000);
            gpio_write(solenoid, 0);
        }

        usleep(500000);  // 500ms delay between measurements
    }

    gpio_write(solenoid, 0);  // Ensure solenoid is LOW on exit

    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);

    closelog();
    syslog(LOG_INFO, "Weight monitor stopped");

    return 0;
}
