#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"

static struct mosquitto *mosq = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t run = 1;

void cleanup(void) {
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

void signal_handler(int sig) {
    run = 0;
}

void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    char *message;
    if (result == 0) {
        message = "Connected to MQTT broker";
        syslog(LOG_USER | LOG_INFO, "%s", message);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        message = "Failed to connect to MQTT broker";
        syslog(LOG_USER | LOG_ERR, "%s", message);
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int result) {
    char *message = "Disconnected from MQTT broker";
    syslog(LOG_USER | LOG_INFO, "%s", message);
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->payloadlen == 2 && strncmp((char *)msg->payload, "ON", 2) == 0) {
        gpiod_line_set_value(line, 1);
        syslog(LOG_USER | LOG_INFO, "Relay turned ON");
    } else if (msg->payloadlen == 3 && strncmp((char *)msg->payload, "OFF", 3) == 0) {
        gpiod_line_set_value(line, 0);
        syslog(LOG_USER | LOG_INFO, "Relay turned OFF");
    } else {
        syslog(LOG_USER | LOG_ERR, "Invalid message received: %.*s", msg->payloadlen, (char *)msg->payload);
    }
}

int main(void) {
    int ret;

    openlog("mqtt_relay", LOG_CONS | LOG_PID | LOG_PERROR, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_USER | LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        syslog(LOG_USER | LOG_ERR, "Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "relay_controller", 0);
    if (ret < 0) {
        syslog(LOG_USER | LOG_ERR, "Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_USER | LOG_ERR, "Failed to create MQTT client");
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    while (run) {
        ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_USER | LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
            sleep(5);
            continue;
        }

        while (run) {
            ret = mosquitto_loop(mosq, -1, 1);
            if (ret != MOSQ_ERR_SUCCESS) {
                syslog(LOG_USER | LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(ret));
                sleep(5);
                break;
            }
        }

        mosquitto_disconnect(mosq);
    }

    mosquitto_lib_cleanup();
    return EXIT_SUCCESS;
}

