#define NUM_SERVOS 5
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define SERVO_PINS[NUM_SERVOS] = {7, 8, 9, 10, 11}
#define SERVO_POSITIONS[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500}
#define MIN_PULSE_WIDTH_US 500
#define MAX_PULSE_WIDTH_US 2500
#define PULSE_DURATION_US 3000000

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_SERVOS];

void cleanup(int signum) {
    for (int i = 0; i < NUM_SERVOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, SERVO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", SERVO_PINS[i]);
            cleanup(0);
        }

        ret = gpiod_line_request_output(lines[i], "servo_pwm", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", SERVO_PINS[i]);
            cleanup(0);
        }
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        int pulse_width = SERVO_POSITIONS[i];
        if (pulse_width < MIN_PULSE_WIDTH_US) pulse_width = MIN_PULSE_WIDTH_US;
        if (pulse_width > MAX_PULSE_WIDTH_US) pulse_width = MAX_PULSE_WIDTH_US;

        int on_time = pulse_width;
        int off_time = PWM_PERIOD_US - on_time;

        for (int j = 0; j < PULSE_DURATION_US; j += PWM_PERIOD_US) {
            gpiod_line_set_value(lines[i], 1);
            usleep(on_time);
            gpiod_line_set_value(lines[i], 0);
            usleep(off_time);
        }
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

