    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (level == PI_HIGH) {
        encoder_ticks_b++;
        last_tick_time_b = current_time;
    }

    if (encoder_ticks_b == 0) {
        encoder_stall_b = true;
    } else {
        encoder_stall_b = false;
    }
}

static void cleanup_and_exit(int sig) {
    gpioSetPWMfrequency(MOTOR_A_PWM, 0);
    gpioSetPWMfrequency(MOTOR_B_PWM, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_OFF) < 0 ||
        gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_OFF) < 0 ||
        gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_OFF) < 0 ||
        gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(ENCODER_A_PHASE_A, PI_FALLING_EDGE, 0, encoder_isr_a) < 0 ||
        gpioSetISRFunc(ENCODER_A_PHASE_B, PI_FALLING_EDGE, 0, encoder_isr_b) < 0) {
        fprintf(stderr, "Failed to set ISR for encoder\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        long long elapsed_time_a = (current_time.tv_sec - last_tick_time_a.tv_sec) * 1000LL +
                                   (current_time.tv_nsec - last_tick_time_a.tv_nsec) / 1000000LL;
        long long elapsed_time_b = (current_time.tv_sec - last_tick_time_b.tv_sec) * 1000LL +
                                   (current_time.tv_nsec - last_tick_time_b.tv_nsec) / 1000000LL;

        if (elapsed_time_a > STALL_THRESHOLD_MS) {
            fprintf(stderr, "Warning: Encoder A stall detected\n");
        }
        if (elapsed_time_b > STALL_THRESHOLD_MS) {
            fprintf(stderr, "Warning: Encoder B stall detected\n");
        }

        double current_speed_a = (double)encoder_ticks_a / (TICKS_PER_REV * CONTROL_LOOP_INTERVAL_MS / 1000.0);
        double current_speed_b = (double)encoder_ticks_b / (TICKS_PER_REV * CONTROL_LOOP_INTERVAL_MS / 1000.0);

        double error_a = RPM_TO_RAD_PER_SEC - current_speed_a;
        double error_b = RPM_TO_RAD_PER_SEC - current_speed_b;

        double pwm_a = error_a * 1000.0;
        double pwm_b = error_b * 1000.0;

        if (pwm_a > 255) pwm_a = 255;
        if (pwm_a < -255) pwm_a = -255;
        if (pwm_b > 255) pwm_b = 255;
        if (pwm_b < -255) pwm_b = -255;

        gpioPWM(MOTOR_A_PWM, abs((int)pwm_a));
        gpioWrite(MOTOR_A_DIR, pwm_a >= 0 ? PI_HIGH : PI_LOW);
        gpioPWM(MOTOR_B_PWM, abs((int)pwm_b));
        gpioWrite(MOTOR_B_DIR, pwm_b >= 0 ? PI_HIGH : PI_LOW);

        printf("Motor A: RPM = %.2f, PWM = %d\n", current_speed_a * 60 / (2 * M_PI), (int)pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", current_speed_b * 60 / (2 * M_PI), (int)pwm_b);

        encoder_ticks_a = 0;
        encoder_ticks_b = 0;

        usleep(CONTROL_LOOP_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}
