#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDRESS 0x23
#define RELAY_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define SENSOR_POLL_INTERVAL 5
#define RELAY_DELAY_MS 180
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200

static int i2c_handle;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", time_str, message);
    fflush(log_file);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void signal_handler(int signo) {
    log_message("Received shutdown signal");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    int relay_state = 0;
    int previous_lux = -1;

    while (1) {
        // Set sensor to continuous high resolution mode
        if (i2cWriteByte(i2c_handle, 0x10) < 0) {
            log_message("Failed to set sensor mode");
            relay_state = 0;
        } else {
            usleep(RELAY_DELAY_MS * 1000);

            // Read lux value
            char data[2];
            if (i2cReadDevice(i2c_handle, data, 2) < 0) {
                log_message("Failed to read from sensor");
                relay_state = 0;
            } else {
                int lux = (data[0] << 8) | data[1];
                char lux_str[8];
                snprintf(lux_str, sizeof(lux_str), "%d", lux);
                char log_buf[128];
                snprintf(log_buf, sizeof(log_buf), "Lux = %s, Relay = %s", lux_str, relay_state ? "ON" : "OFF");
                log_message(log_buf);

                if (lux < LUX_THRESHOLD_LOW && !relay_state) {
                    gpiod_line_set_value(line, 1);
                    relay_state = 1;
                } else if (lux > LUX_THRESHOLD_HIGH && relay_state) {
                    gpiod_line_set_value(line, 0);
                    relay_state = 0;
                }

                previous_lux = lux;
            }
        }

        sleep(SENSOR_POLL_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

