#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME_MS 50
#define MAIN_LOOP_SLEEP_MS 10

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t running = 1;

void log_relay_state(int state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    int last_state = 0;
    int current_state;
    struct timespec sleep_time = {0, MAIN_LOOP_SLEEP_MS * 1000000};

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, "touch_input") < 0) {
        perror("Failed to request touch line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "relay_output", 0) < 0) {
        perror("Failed to request relay line as output");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        current_state = gpiod_line_get_value(touch_line);
        if (current_state < 0) {
            perror("Failed to read touch sensor");
            break;
        }

        if (current_state == 1 && last_state == 1) {
            usleep(DEBOUNCE_TIME_MS * 1000);
            current_state = gpiod_line_get_value(touch_line);
            if (current_state < 0) {
                perror("Failed to read touch sensor after debounce");
                break;
            }

            if (current_state == 1) {
                int new_state = !gpiod_line_get_value(relay_line);
                if (gpiod_line_set_value(relay_line, new_state) < 0) {
                    perror("Failed to set relay state");
                } else {
                    log_relay_state(new_state);
                }

                while (gpiod_line_get_value(touch_line) == 1) {
                    nanosleep(&sleep_time, NULL);
                }
            }
        }

        last_state = current_state;
        nanosleep(&sleep_time, NULL);
    }

    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Failed to turn off relay on exit");
    }

cleanup:
    if (relay_line) gpiod_line_release(relay_line);
    if (touch_line) gpiod_line_release(touch_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program exiting\n");
    return EXIT_SUCCESS;
}

