#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <pthread.h>
#include <unistd.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define DEBOUNCE_TIME_MS 1000
#define FLOW_THRESHOLD_OPEN 5.0
#define FLOW_THRESHOLD_CLOSE 4.5
#define LOG_FILE "water_flow.log"

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct gpiod_chip *chip;
static struct gpiod_line *flow_sensor_line;
static struct gpiod_line *solenoid_line;
static FILE *log_file;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void *flow_sensor_isr(void *arg) {
    struct timespec ts;
    ts.tv_sec = DEBOUNCE_TIME_MS / 1000;
    ts.tv_nsec = (DEBOUNCE_TIME_MS % 1000) * 1000000;

    while (1) {
        int value = gpiod_line_get_value(flow_sensor_line);
        if (value == 1) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
        nanosleep(&ts, NULL);
    }
    return NULL;
}

void handle_signal(int signum) {
    const char *signal_name;
    switch (signum) {
        case SIGINT:
            signal_name = "SIGINT";
            break;
        case SIGTERM:
            signal_name = "SIGTERM";
            break;
        default:
            return;
    }

    char message[100];
    snprintf(message, sizeof(message), "Received %s signal", signal_name);
    log_message(message);

    gpiod_line_set_value(solenoid_line, 1); // Open solenoid
    pthread_mutex_destroy(&pulse_mutex);
    gpiod_line_release(flow_sensor_line);
    gpiod_line_release(solenoid_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    flow_sensor_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!flow_sensor_line) {
        fprintf(stderr, "Failed to get flow sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(flow_sensor_line, "flow_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request flow sensor line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        fprintf(stderr, "Failed to get solenoid line\n");
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(solenoid_line, "solenoid", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request solenoid line as output\n");
        gpiod_line_release(flow_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(flow_sensor_line);
        gpiod_line_release(solenoid_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    pthread_t isr_thread;
    ret = pthread_create(&isr_thread, NULL, flow_sensor_isr, NULL);
    if (ret != 0) {
        fprintf(stderr, "Failed to create ISR thread\n");
        fclose(log_file);
        gpiod_line_release(flow_sensor_line);
        gpiod_line_release(solenoid_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        double flow_rate = (pulse_count * 60.0) / 7.5; // Assuming 7.5 pulses per L/min
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        char message[100];
        snprintf(message, sizeof(message), "Flow rate: %.2f LPM", flow_rate);
        log_message(message);

        if (flow_rate > FLOW_THRESHOLD_OPEN) {
            gpiod_line_set_value(solenoid_line, 0); // Close solenoid
            snprintf(message, sizeof(message), "Solenoid closed");
            log_message(message);
