#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define TCP_PORT 12345
#define MAX_BUFFER_SIZE 1024
#define TIMEOUT_ATTEMPTS 1000
#define DEFAULT_CALIBRATION_FACTOR 1.0

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int hx711_read() {
    unsigned long value = 0;
    int data, attempts = 0;

    gpiod_line_set_value(HX711_SCK_PIN, 0);
    usleep(1);

    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(HX711_SCK_PIN, 1);
        usleep(1);
        gpiod_line_set_value(HX711_SCK_PIN, 0);
        usleep(1);

        data = gpiod_line_get_value(HX711_DATA_PIN);
        value = (value << 1) | data;
    }

    gpiod_line_set_value(HX711_SCK_PIN, 1);
    usleep(1);
    gpiod_line_set_value(HX711_SCK_PIN, 0);
    usleep(1);

    value ^= 0x800000;
    return (int)value;
}

double get_calibration_factor() {
    FILE *file = fopen("config.ini", "r");
    if (!file) return DEFAULT_CALIBRATION_FACTOR;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "calibration_factor=%lf", &calibration_factor) == 1) {
            fclose(file);
            return calibration_factor;
        }
    }

    fclose(file);
    return DEFAULT_CALIBRATION_FACTOR;
}

void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    struct json_object *root = json_object_new_object();
    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    json_object_object_add(root, "date", json_object_new_string(asctime(t)));
    json_object_object_add(root, "target_weight", json_object_new_double(target_weight));
    json_object_object_add(root, "actual_weight", json_object_new_double(actual_weight));
    json_object_object_add(root, "error", json_object_new_string(error_message));

    FILE *file = fopen("dispensing_log.json", "a");
    if (file) {
        fprintf(file, "%s\n", json_object_to_json_string(root));
        fclose(file);
    }

    json_object_put(root);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *sck_line;
    int sockfd, client_sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
