    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, HX711_DATA_PIN);
    sck_line = gpiod_chip_get_line(chip, HX711_SCK_PIN);

    if (!data_line || !sck_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    gpiod_line_request_input(data_line, "HX711_DATA");
    gpiod_line_request_output(sck_line, "HX711_SCK", 0);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        gpiod_line_release(data_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        gpiod_line_release(data_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (listen(sockfd, 5) < 0) {
        perror("Listen failed");
        close(sockfd);
        gpiod_line_release(data_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on 127.0.0.1:%d\n", TCP_PORT);

    while (keep_running) {
        client_sockfd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_sockfd < 0) {
            perror("Accept failed");
            continue;
        }

        if (recv(client_sockfd, buffer, sizeof(buffer), 0) > 0) {
            target_weight = atof(buffer);
            calibration_factor = get_calibration_factor();

            // Dispense logic (placeholder)
            gpioServoWrite(SERVO_PIN, 1500);  // Move servo to dispense position
            usleep(1000000);  // Wait for 1 second

            actual_weight = hx711_read() * calibration_factor;

            char response[MAX_BUFFER_SIZE];
            snprintf(response, sizeof(response), "%.2f", actual_weight);
            send(client_sockfd, response, strlen(response), 0);

            log_dispensing_event(target_weight, actual_weight, "Success");
        }

        close(client_sockfd);
    }

    close(sockfd);
    gpiod_line_release(data_line);
    gpiod_line_release(sck_line);
    gpiod_chip_close(chip);
    gpioTerminate();

    return 0;
}

