#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define DEFAULT_DEBOUNCE_MS 50
#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *touch_sensor_line;
static volatile sig_atomic_t keep_running = 1;

void log_relay_state(int state) {
    time_t now;
    struct tm *tm_info;
    char time_str[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("%s Relay: %s\n", time_str, state ? "ON" : "OFF");
}

void toggle_relay() {
    int current_state = gpiod_line_get_value(relay_line);
    int new_state = !current_state;

    if (gpiod_line_set_value(relay_line, new_state) < 0) {
        perror("Failed to set relay state");
        exit(EXIT_FAILURE);
    }

    log_relay_state(new_state);
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Invalid debounce interval\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        goto cleanup;
    }

    touch_sensor_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_sensor_line) {
        perror("Failed to get touch sensor line");
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_sensor_line, "touch_sensor") < 0) {
        perror("Failed to request touch sensor line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay line as output");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 1;  // Assume sensor is not pressed initially
    while (keep_running) {
        int current_state = gpiod_line_get_value(touch_sensor_line);
        if (current_state == 0 && last_state == 1) {
            // Debounce
            usleep(debounce_ms * 1000);
            current_state = gpiod_line_get_value(touch_sensor_line);
            if (current_state == 0) {
                toggle_relay();
            }
        }
        last_state = current_state;
        usleep(1000);  // Small delay to prevent busy-waiting
    }

cleanup:
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (touch_sensor_line) {
        gpiod_line_release(touch_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

