    signal(SIGTERM, signal_handler);

    int last_state = 1;  // Assume sensor is not pressed initially
    while (keep_running) {
        int current_state = gpiod_line_get_value(touch_sensor_line);
        if (current_state == 0 && last_state == 1) {
            // Debounce
            usleep(debounce_ms * 1000);
            current_state = gpiod_line_get_value(touch_sensor_line);
            if (current_state == 0) {
                toggle_relay();
            }
        }
        last_state = current_state;
        usleep(1000);  // Small delay to prevent busy-waiting
    }

cleanup:
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (touch_sensor_line) {
        gpiod_line_release(touch_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
