#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 2
#define INTERVAL_SECONDS 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static unsigned long long pulse_count = 0;
static struct timespec last_time = {0, 0};

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    struct timespec current_time, interval_time;
    double rpm;
    char timestamp[64];

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "RPM_Sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &last_time) != 0) {
        fprintf(stderr, "Failed to get initial time: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int event_type = gpiod_line_event_wait(line, DEBOUNCE_TIME_MS * 1000000);
        if (event_type < 0) {
            fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
            break;
        } else if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            break;
        }

        interval_time.tv_sec = current_time.tv_sec - last_time.tv_sec;
        interval_time.tv_nsec = current_time.tv_nsec - last_time.tv_nsec;

        if (interval_time.tv_nsec < 0) {
            interval_time.tv_sec--;
            interval_time.tv_nsec += 1000000000L;
        }

        if (interval_time.tv_sec >= INTERVAL_SECONDS) {
            rpm = (pulse_count * 60.0) / (INTERVAL_SECONDS * 2.0);
            printf("RPM: %.2f\n", rpm);

            struct tm tm_info;
            char *iso_timestamp = ctime_r(&current_time.tv_sec, timestamp);
            if (iso_timestamp) {
                timestamp[strcspn(timestamp, "\n")] = 0;  // Remove newline
                fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
                fflush(log_file);
            } else {
                fprintf(stderr, "Failed to format timestamp\n");
            }

            last_time = current_time;
            pulse_count = 0;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

