#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define RELEASE_THRESHOLD_MS 10000

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    int sensor_value = 0;
    int relay_state = 0;
    struct timespec last_toggle_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_toggle_time);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!sensor_line || !relay_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure lines
    gpiod_line_request_input(sensor_line, "TTP223 Sensor");
    gpiod_line_request_output(relay_line, "Relay Control", 0);

    while (!exit_flag) {
        int new_sensor_value = gpiod_line_get_value(sensor_line);

        if (new_sensor_value == 1 && sensor_value == 0) {
            // Rising edge detected
            relay_state = !relay_state;
            gpiod_line_set_value(relay_line, relay_state);
            clock_gettime(CLOCK_MONOTONIC, &last_toggle_time);
        }

        sensor_value = new_sensor_value;

        if (sensor_value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_ms = (current_time.tv_sec - last_toggle_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - last_toggle_time.tv_nsec) / 1000000;

            if (elapsed_ms > RELEASE_THRESHOLD_MS) {
                // Force relay OFF
                gpiod_line_set_value(relay_line, 0);
                relay_state = 0;
            }
        }

        // Sleep for poll interval
        struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

