#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *pwm_line, *enable_line, *flow_sensor_line;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void flow_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

double calculate_flow_rate() {
    double flow_rate = (pulse_count * 60.0) / SAMPLE_INTERVAL_MS;
    pulse_count = 0;
    return flow_rate;
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    char *endptr;

    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    target_flow_rate = strtod(argv[2], &endptr);
    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    enable_line = gpiod_chip_get_line(chip, ENABLE_PIN);
    flow_sensor_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);

    if (!pwm_line || !enable_line || !flow_sensor_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(enable_line, "enable", 1) < 0) {
        fprintf(stderr, "Failed to request enable line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flow_sensor_line, "flow_sensor") < 0) {
        fprintf(stderr, "Failed to request flow sensor line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor mode\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to set flow sensor pull-up/down\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_PIN, flow_isr) != 0) {
        fprintf(stderr, "Failed to set flow sensor interrupt\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioHardwarePWM(PWM_PIN, 1000, 0);  // 1 kHz frequency, 0% duty cycle

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
