#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22
#define TAG_SIZE 10
#define DEBOUNCE_TIME_MS 50
#define LOCK_DURATION_SEC 5

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *lock1, *lock2, *button;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void cleanup_and_exit(int signum) {
    log_message("Exiting...");

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (lock1) {
        gpiod_line_release(lock1);
    }
    if (lock2) {
        gpiod_line_release(lock2);
    }
    if (button) {
        gpiod_line_release(button);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioTerminate();
    closelog();

    exit(EXIT_SUCCESS);
}

int read_rfid_tag(uint8_t *tag) {
    int retries = 4;
    int result;

    do {
        result = gpioSPIXfer(RFID_SPI_CHANNEL, tag, TAG_SIZE, NULL, TAG_SIZE);
        if (result >= 0) {
            return result;
        }
        usleep(1000); // 1ms delay between retries
    } while (--retries > 0);

    return -1;
}

int main() {
    uint8_t tag[TAG_SIZE];
    int button_state = 1;
    time_t last_button_press = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (openlog("door_access", LOG_PID | LOG_CONS, LOG_USER) < 0) {
        fprintf(stderr, "Failed to open syslog\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        fclose(log_file);
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lock1 = gpiod_chip_get_line(chip, LOCK1_PIN);
    lock2 = gpiod_chip_get_line(chip, LOCK2_PIN);
    button = gpiod_chip_get_line(chip, BUTTON_PIN);

    if (!lock1 || !lock2 || !button) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(lock1, "lock1") < 0 ||
        gpiod_line_request_input(lock2, "lock2") < 0 ||
        gpiod_line_request_input(button, "button") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines as input");
        gpiod_line_release(lock1);
        gpiod_line_release(lock2);
        gpiod_line_release(button);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    spi_fd = gpioSPIOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, 0);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI interface");
        cleanup_and_exit(0);
    }

    log_message("Door access control system started");

    while (1) {
        int bytes_read = read_rfid_tag(tag);

        if (bytes_read == TAG_SIZE) {
            if (memcmp(tag, "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", TAG_SIZE) == 0) {
                log_message("No tag present");
            } else {
                log_message("Valid tag read");

                button_state = gpioRead(BUTTON_PIN);
                if (button_state == 0) {
                    time_t current_time = time(NULL);
                    if (difftime(current_time, last_button_press) >= DEBOUNCE_TIME_MS / 1000.0) {
                        last_button_press = current_time;
                        log_message("Button pressed");

                        gpiod_line_set_value(lock1, 0);
                        gpiod_line_set_value(lock2, 0);
                        sleep(LOCK_DURATION_SEC);
                        gpiod_line_set_value(lock1, 1);
                        gpiod_line_set_value(lock2, 1);

                        log_message("Locks disengaged and re-engaged");
                    }
                } else {
                    log_message("Button press without valid tag");
                }
            }
        } else if (bytes_read < 0) {
            log_message("RFID read failure");
        }

        usleep(10000); // 10ms polling interval
    }

    return EXIT_SUCCESS;
}

