#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

#define TARGET_RPM 60
#define PID_SAMPLE_TIME_MS 100
#define PWM_FREQUENCY 100
#define LOG_FILE "motor_log.csv"

// GPIO pin definitions
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID constants
#define Kp 0.1
#define Ki 0.01
#define Kd 0.05

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *motor1_ena, *motor1_in1, *motor1_in2, *motor2_enb, *motor2_in3, *motor2_in4;
static struct gpiod_line *encoder1_a, *encoder1_b, *encoder2_a, *encoder2_b;
static int encoder1_count = 0, encoder2_count = 0;
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file;
static volatile int running = 1;

// Function prototypes
void setup_gpio(void);
void cleanup_gpio(void);
void *encoder_thread(void *arg);
void pid_control(void);
void log_data(double speed_rpm, double p, double i, double d, double output);
void signal_handler(int signum);

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    pthread_t encoder_thread1, encoder_thread2;
    if (pthread_create(&encoder_thread1, NULL, encoder_thread, (void *)&encoder1_a) != 0 ||
        pthread_create(&encoder_thread2, NULL, encoder_thread, (void *)&encoder2_a) != 0) {
        fprintf(stderr, "Failed to create encoder threads\n");
        cleanup_gpio();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_gpio();
        return 1;
    }
    fprintf(log_file, "Time,Speed_RPM,P,I,D,Output\n");
    fflush(log_file);

    while (running) {
        pid_control();
        usleep(PID_SAMPLE_TIME_MS * 1000);
    }

    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

void setup_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    motor1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);
    encoder1_a = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena || !motor1_in1 || !motor1_in2 || !motor2_enb || !motor2_in3 || !motor2_in4 ||
        !encoder1_a || !encoder1_b || !encoder2_a || !encoder2_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_gpio();
        exit(1);
    }

    if (gpiod_line_request_output(motor1_ena, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor1_in1, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor1_in2, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor2_enb, "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(motor2_in3, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor2_in4, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Failed to request motor control lines\n");
        cleanup_gpio();
        exit(1);
    }

    if (gpiod_line_request_input(encoder1_a, "encoder1_a") < 0 ||
        gpiod_line_request_input(encoder1_b, "encoder1_b") < 0 ||
        gpiod_line_request_input(encoder2_a, "encoder2_a") < 0 ||
        gpiod_line_request_input(encoder2_b, "encoder2_b") < 0) {
        fprintf(stderr, "Failed to request encoder lines\n");
        cleanup_gpio();
        exit(1);
    }

    if (gpiod_line_request_both_edges(encoder1_a, "encoder1_a") < 0 ||
        gpiod_line_request_both_edges(encoder2_a, "encoder2_a") < 0) {
        fprintf(stderr, "Failed to request edge detection on encoder A pins\n");
        cleanup_gpio();
        exit(1);
    }
}

void cleanup_gpio(void) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void *encoder_thread(void *arg) {
    struct gpiod_line *encoder_a = *(struct gpiod_line **)arg;
    struct gpiod_line_event event;
    int last_value = 0;

    while (running) {
        int ret = gpiod_line_event_wait(encoder_a, 100);
        if (ret > 0) {
            if (gpiod_line_event_read(encoder_a, &event) == 0) {
                int current_value = gpiod_line_get_value(encoder_a);
                struct gpiod_line *encoder_b = (encoder_a == encoder1_a) ? encoder1_b : encoder2_b;
                int b_value = gpiod_line_get_value(encoder_b);

                pthread_mutex_lock(&encoder_mutex);
                if (current_value != last_value) {
                    if (current_value == b_value) {
                        (encoder_a == encoder1_a) ? encoder1_count++ : encoder2_count++;
                    } else {
                        (encoder_a == encoder1_a) ? encoder1_count-- : encoder2_count--;
                    }
                }
                last_value = current_value;
                pthread_mutex_unlock(&encoder_mutex);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(errno));
        }
    }
    return NULL;
}

void pid_control(void) {
    static double integral1 = 0, integral2 = 0;
    static double last_error1 = 0, last_error2 = 0;
    double error1, error2, derivative1, derivative2;
    double output1, output2;

