#define MPR121_I2C_ADDR 0x5A
#define I2C_BUS 1
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50

#define MPR121_TOUCH_STATUS 0x00
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG 0x5C
#define MPR121_CHARGING_CURRENT 0x5F
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_UPPER_THRESHOLD 0x7D
#define MPR121_LOWER_THRESHOLD 0x7E
#define MPR121_TARGET_LEVEL 0x7F

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int mpr121_init(int fd) {
    // Soft reset
    i2c_write(fd, MPR121_CONFIG, 0x60);
    usleep(10000);

    // Wait for reset to complete
    uint8_t config;
    do {
        if (i2c_read(fd, MPR121_CONFIG, &config) != 1) return -1;
    } while (!(config & 0x60));

    // Configure electrode filtering
    i2c_write(fd, MPR121_MHDR, 0x01);
    i2c_write(fd, MPR121_NHDR, 0x01);
    i2c_write(fd, MPR121_NCLR, 0x0E);
    i2c_write(fd, MPR121_FDLR, 0x00);
    i2c_write(fd, MPR121_MHDF, 0x01);
    i2c_write(fd, MPR121_NHDF, 0x05);
    i2c_write(fd, MPR121_NCLF, 0x01);
    i2c_write(fd, MPR121_FDLF, 0x00);
    i2c_write(fd, MPR121_NHDT, 0x00);
    i2c_write(fd, MPR121_NCLT, 0x00);
    i2c_write(fd, MPR121_FDLT, 0x00);

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        i2c_write(fd, MPR121_TOUCH_THRESHOLD + i * 2, 0x10);
        i2c_write(fd, MPR121_RELEASE_THRESHOLD + i * 2, 0x0A);
    }

    // Configure electrode charge/discharge time
    i2c_write(fd, MPR121_DEBOUNCE, 0x00);
    i2c_write(fd, MPR121_CONFIG, 0x1E);

    // Enable auto-config
    i2c_write(fd, MPR121_AUTOCONFIG0, 0xBF);
    i2c_write(fd, MPR121_AUTOCONFIG1, 0xAF);
    i2c_write(fd, MPR121_UPPER_THRESHOLD, 0x00);
    i2c_write(fd, MPR121_LOWER_THRESHOLD, 0x00);
    i2c_write(fd, MPR121_TARGET_LEVEL, 0x00);

    // Wait for auto-config to complete
    usleep(200000);

    return 0;
}

void log_relay_state(int state) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline
    fprintf(log_file, "[%s] Relay state: %s\n", timestamp, state ? "HIGH" : "LOW");
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        close(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t touch_status;
    int last_state = -1;

    while (running) {
        if (i2c_read(i2c_fd, MPR121_TOUCH_STATUS, &touch_status) != 1) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        int current_state = (touch_status & 0x0F) ? 1 : 0;
        if (current_state != last_state) {
            gpioWrite(RELAY_PIN, current_state);
            log_relay_state(current_state);
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

