        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        close(i2c_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t touch_status;
    int last_state = -1;

    while (running) {
        if (i2c_read(i2c_fd, MPR121_TOUCH_STATUS, &touch_status) != 1) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        int current_state = (touch_status & 0x0F) ? 1 : 0;
        if (current_state != last_state) {
            gpioWrite(RELAY_PIN, current_state);
            log_relay_state(current_state);
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}
