#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define POLL_INTERVAL_MS 50
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_MS 2000

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static FILE *log_file;
static int running = 1;
static uint64_t last_motion_time = 0;
static uint64_t last_unlock_time = 0;

static void signal_handler(int signum) {
    running = 0;
}

static uint64_t get_current_time_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

static void log_event(const char *event) {
    uint64_t current_time = get_current_time_ms();
    fprintf(log_file, "%llu: %s\n", (unsigned long long)current_time, event);
    fflush(log_file);
}

static void set_relay(int state) {
    int err = gpiod_line_set_value(relay_line, state);
    if (err < 0) {
        fprintf(stderr, "Failed to set relay state: %s\n", strerror(-err));
        exit(1);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR line\n");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        goto cleanup;
    }

    int err = gpiod_line_request_input(pir_line, "PIR-Sensor");
    if (err < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(-err));
        goto cleanup;
    }

    err = gpiod_line_request_output(relay_line, "Door-Relay", 0);
    if (err < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(-err));
        goto cleanup;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    log_event("Program started");

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR value: %s\n", strerror(-pir_value));
            break;
        }

        uint64_t current_time = get_current_time_ms();

        if (pir_value == 1 && current_time - last_motion_time >= POLL_INTERVAL_MS &&
            current_time - last_unlock_time >= RATE_LIMIT_DURATION_MS) {
            log_event("Motion detected");
            set_relay(1);
            last_unlock_time = current_time;
            usleep(UNLOCK_DURATION_MS * 1000);
            set_relay(0);
            log_event("Door unlocked");
            last_motion_time = current_time;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Program terminated");

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

