#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION 50
#define MAX_DURATION 200
#define PWM_RANGE 255

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        shutdown_flag = 1;
    }
}

void cleanup(struct gpiod_chip *chip, struct gpiod_line *motor1, struct gpiod_line *motor2) {
    if (motor1) gpiod_line_release(motor1);
    if (motor2) gpiod_line_release(motor2);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *motor1, *motor2;
    struct timespec delay;
    int i, j, steps, duration;
    unsigned int duty_cycle1, duty_cycle2;

    srand(time(NULL));
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    motor1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    motor2 = gpiod_chip_get_line(chip, MOTOR2_PIN);

    if (!motor1 || !motor2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(chip, motor1, motor2);
        return 1;
    }

    if (gpiod_line_request_output(motor1, "motor1", 0) < 0 ||
        gpiod_line_request_output(motor2, "motor2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output\n");
        cleanup(chip, motor1, motor2);
        return 1;
    }

    while (!shutdown_flag) {
        steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;

        for (i = 0; i < steps; i++) {
            duty_cycle1 = rand() % (PWM_RANGE + 1);
            duty_cycle2 = rand() % (PWM_RANGE + 1);
            duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;

            gpiod_line_set_value(motor1, duty_cycle1 > 0);
            gpiod_line_set_value(motor2, duty_cycle2 > 0);

            delay.tv_sec = duration / 1000;
            delay.tv_nsec = (duration % 1000) * 1000000;
            nanosleep(&delay, NULL);
        }
    }

    gpiod_line_set_value(motor1, 0);
    gpiod_line_set_value(motor2, 0);
    cleanup(chip, motor1, motor2);
    return 0;
}

