#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define HX711_DOUT_PIN 4
#define HX711_SCK_PIN 17
#define SOLENOID_PIN 27
#define READ_INTERVAL_MS 500
#define READ_TIMEOUT_MS 500
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0

static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *solenoid_line;
static FILE *calibration_file, *log_file;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;

void cleanup(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (solenoid_line) {
        gpiod_line_release(solenoid_line);
    }
    if (calibration_file) {
        fclose(calibration_file);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int hx711_read() {
    unsigned long value = 0;
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(dout_line);
    }

    gpiod_line_set_value(sck_line, 1);
    usleep(1);
    gpiod_line_set_value(sck_line, 0);
    usleep(1);

    value ^= 0x800000;
    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    clock_gettime(CLOCK_MONOTONIC, &current);
    long elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000;
    return (elapsed_ms > READ_TIMEOUT_MS) ? -1 : (int)value;
}

void load_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Invalid calibration data, using defaults\n");
            scale_factor = DEFAULT_SCALE;
            offset = DEFAULT_OFFSET;
        }
        fclose(calibration_file);
    } else {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        scale_factor = DEFAULT_SCALE;
        offset = DEFAULT_OFFSET;
    }
}

void save_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file) {
        fprintf(calibration_file, "%.6f %.6f\n", scale_factor, offset);
        fclose(calibration_file);
    } else {
        perror("Failed to open calibration file for writing");
    }
}

double compute_weight(int raw_value) {
