static struct gpiod_line *motor_in1;
static struct gpiod_line *motor_in2;
static struct gpiod_line *motor_pwm;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    rain_sensor = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_sensor) {
        syslog(LOG_ERR, "Failed to get rain sensor line: %s", strerror(errno));
        return -1;
    }

    motor_in1 = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1) {
        syslog(LOG_ERR, "Failed to get motor IN1 line: %s", strerror(errno));
        return -1;
    }

    motor_in2 = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2) {
        syslog(LOG_ERR, "Failed to get motor IN2 line: %s", strerror(errno));
        return -1;
    }

    motor_pwm = gpiod_chip_get_line(chip, MOTOR_PWM_PIN);
    if (!motor_pwm) {
        syslog(LOG_ERR, "Failed to get motor PWM line: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(rain_sensor, "rain_sensor") < 0 ||
        gpiod_line_request_output(motor_in1, "motor_in1", 0) < 0 ||
        gpiod_line_request_output(motor_in2, "motor_in2", 0) < 0 ||
        gpiod_line_request_output(motor_pwm, "motor_pwm", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %s", strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (motor_pwm) gpiod_line_release(motor_pwm);
    if (motor_in2) gpiod_line_release(motor_in2);
    if (motor_in1) gpiod_line_release(motor_in1);
    if (rain_sensor) gpiod_line_release(rain_sensor);
    if (chip) gpiod_chip_close(chip);
}

int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int value = gpiod_line_get_value(rain_sensor);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor: %s", strerror(errno));
            return -1;
        }
        if (value == 0) low_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return low_count >= RAIN_THRESHOLD;
}

void control_motor(int on) {
    int ret;
    if (on) {
        ret = gpiod_line_set_value(motor_in1, 1);
        ret |= gpiod_line_set_value(motor_in2, 0);
        ret |= gpiod_line_set_value(motor_pwm, PWM_DUTY_CYCLE);
    } else {
        ret = gpiod_line_set_value(motor_in1, 0);
        ret |= gpiod_line_set_value(motor_in2, 0);
        ret |= gpiod_line_set_value(motor_pwm, 0);
    }
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set motor control lines: %s", strerror(errno));
    }
}

int main() {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (setup_gpio() < 0) {
        syslog(LOG_ERR, "GPIO setup failed");
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_check = 0;
    time_t last_close = 0;

    while (!terminate) {
        time_t now = time(NULL);

        if (now - last_check >= CHECK_INTERVAL && now - last_close >= CHECK_INTERVAL) {
            if (read_rain_sensor()) {
                syslog(LOG_INFO, "Rain detected at %s", ctime(&now));
                control_motor(1);
                sleep(CLOSE_WINDOW_DURATION);
                control_motor(0);
                last_close = time(NULL);
                syslog(LOG_INFO, "Window closed at %s", ctime(&last_close));
            }
            last_check = now;
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

