#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *dt_line, *sck_line, *lock_line;
static FILE *log_file;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Program terminated by signal");
    }

    if (log_file) {
        fclose(log_file);
    }

    if (lock_line) {
        gpiod_line_release(lock_line);
    }

    if (dt_line) {
        gpiod_line_release(dt_line);
    }

    if (sck_line) {
        gpiod_line_release(sck_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(EXIT_SUCCESS);
}

int hx711_read() {
    unsigned long value = 0;
    int i;

    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(dt_line);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
    }

    gpiod_line_set_value(sck_line, 1);
    usleep(1);
    value ^= 0x800000;
    gpiod_line_set_value(sck_line, 0);
    usleep(1);

    return (int)value;
}

int main() {
    int weight;
    struct sigaction sa;

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    dt_line = gpiod_chip_get_line(chip, DT_PIN);
    if (!dt_line) {
        fprintf(stderr, "Failed to get line for DT_PIN %d\n", DT_PIN);
        cleanup(0);
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        fprintf(stderr, "Failed to get line for SCK_PIN %d\n", SCK_PIN);
        cleanup(0);
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        fprintf(stderr, "Failed to get line for LOCK_PIN %d\n", LOCK_PIN);
        cleanup(0);
    }

    if (gpiod_line_request_input(dt_line, "hx711_dt") < 0 ||
        gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(lock_line, "solenoid_lock", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup(0);
    }

    log_event("Program started");

    while (1) {
        weight = hx711_read();
        if (weight < 0) {
            log_event("Error reading HX711");
        } else {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Weight: %d g", weight);
            log_event(log_buffer);

            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating lock");
                if (gpiod_line_set_value(lock_line, 1) < 0) {
                    log_event("Error activating lock");
                } else {
                    sleep(LOCK_DURATION);
                    if (gpiod_line_set_value(lock_line, 0) < 0) {
                        log_event("Error deactivating lock");
                    }
                }
            }
        }

        sleep(1);
    }

    return 0;
}

