static struct gpiod_line *data_line, *clock_line, *solenoid_line;
static FILE *calibration_file, *log_file;
static float calibration_factor = 0.0;

void cleanup(void) {
    if (solenoid_line) gpiod_line_release(solenoid_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (data_line) gpiod_line_release(data_line);
    if (chip) gpiod_chip_close(chip);
    if (calibration_file) fclose(calibration_file);
    if (log_file) fclose(log_file);
}

void signal_handler(int signum) {
    printf("Received signal %d, unlocking solenoid and exiting...\n", signum);
    if (solenoid_line) gpiod_line_set_value(solenoid_line, 0);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_hx711(void) {
    unsigned long value = 0;
    int timeout = 0;

    gpiod_line_set_value(clock_line, 0);
    usleep(1);

    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(data_line);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }

    gpiod_line_set_value(clock_line, 1);
    usleep(1);
    gpiod_line_set_value(clock_line, 0);
    usleep(1);

    if (gpiod_line_get_value(data_line)) {
        timeout = 1;
    }

    return timeout ? -1 : (int)value;
}

float get_weight(int raw_value) {
    return (float)raw_value / calibration_factor;
}

int main(void) {
    int raw_value;
    float weight;
    struct timespec start, current;
    char log_entry[100];

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!data_line || !clock_line || !solenoid_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(data_line, "HX711 data") < 0 ||
        gpiod_line_request_output(clock_line, "HX711 clock", 0) < 0 ||
        gpiod_line_request_output(solenoid_line, "Solenoid", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor\n");
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            fclose(calibration_file);
        }
    }

    if (calibration_factor == 0.0) {
        printf("Place a known weight on the scale and press Enter to calibrate...\n");
        getchar();
        printf("Reading raw value...\n");
        raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Calibration failed: HX711 timeout\n");
            cleanup();
            return EXIT_FAILURE;
        }
        printf("Enter the weight in grams: ");
        float known_weight;
        scanf("%f", &known_weight);
        calibration_factor = (float)raw_value / known_weight;
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (!calibration_file) {
            perror("Failed to open calibration file for writing");
            cleanup();
            return EXIT_FAILURE;
        }
        fprintf(calibration_file, "%f\n", calibration_factor);
        fclose(calibration_file);
        printf("Calibration complete. Factor: %f\n", calibration_factor);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_REALTIME, &start);

    while (1) {
        raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "HX711 timeout\n");
            continue;
        }

        weight = get_weight(raw_value);

        if (weight > WEIGHT_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &current);
            double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;

            gpiod_line_set_value(solenoid_line, 1);
            sleep(5);
            gpiod_line_set_value(solenoid_line, 0);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(log_entry, sizeof(log_entry), "[%Y-%m-%d %H:%M:%S] Weight: %.2f kg, Elapsed: %.2f s\n", tm_info, weight, elapsed);
            fprintf(log_file, "%s", log_entry);
            fflush(log_file);

            start = current;
        }

        usleep(100000);  // 100ms delay between readings
    }

    cleanup();
    return EXIT_SUCCESS;
}

