#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void log_motion() {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file);
}

int main() {
    int pir_value;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR line\n");
        cleanup(0);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        cleanup(0);
    }

    if (gpiod_line_request_input(pir_line, "PIR Sensor") < 0) {
        fprintf(stderr, "Failed to request PIR line as input\n");
        cleanup(0);
    }

    if (gpiod_line_request_output(buzzer_line, "Buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output\n");
        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    printf("Monitoring PIR sensor...\n");

    while (1) {
        pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR sensor value\n");
            cleanup(0);
        }

        if (pir_value) {
            printf("Motion detected!\n");
            log_motion();

            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Failed to turn on buzzer\n");
                cleanup(0);
            }

            usleep(2000000);  // 2 seconds

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Failed to turn off buzzer\n");
                cleanup(0);
            }
        }

        usleep(100000);  // 100ms delay to prevent excessive CPU usage
    }

    return EXIT_SUCCESS;
}
