#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

volatile sig_atomic_t terminate = 0;

void sig_handler(int signum) {
    terminate = 1;
}

int read_configuration(const char *filename, int *duration) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), file)) {
        fprintf(stderr, "Error reading configuration file: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);

    if (sscanf(line, "duration=%d", duration) != 1 || *duration < MIN_DURATION || *duration > MAX_DURATION) {
        fprintf(stderr, "Invalid configuration: duration must be between %d and %d seconds\n", MIN_DURATION, MAX_DURATION);
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;

    if (read_configuration("watering.conf", &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Configured watering duration: %d seconds\n", duration);

    chip = gpiod_chip_open(CHIP_PATH);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "watering_system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!terminate) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error activating valve: %s\n", strerror(errno));
            break;
        }
        printf("Valve activated\n");

        for (int i = 0; i < duration && !terminate; i++) {
            sleep(1);
        }

        if (terminate) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error deactivating valve: %s\n", strerror(errno));
            break;
        }
        printf("Valve deactivated\n");
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error ensuring valve is off: %s\n", strerror(errno));
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

