#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PIN 22
#define RIGHT_MOTOR_PIN 23
#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 10

static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor, *middle_sensor, *right_sensor;
static struct gpiod_line *left_motor, *right_motor;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpiod_line_set_value(left_motor, 0);
    gpiod_line_set_value(right_motor, 0);
    gpiod_line_release(left_motor);
    gpiod_line_release(right_motor);
    gpiod_line_release(left_sensor);
    gpiod_line_release(middle_sensor);
    gpiod_line_release(right_sensor);
    gpiod_chip_close(chip);
    fclose(log_file);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_control_cycle(int left_sensor_state, int middle_sensor_state, int right_sensor_state, int left_speed, int right_speed) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor_state, middle_sensor_state, right_sensor_state, left_speed, right_speed);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    left_sensor = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_sensor = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_sensor = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    left_motor = gpiod_chip_get_line(chip, LEFT_MOTOR_PIN);
    right_motor = gpiod_chip_get_line(chip, RIGHT_MOTOR_PIN);

    if (!left_sensor || !middle_sensor || !right_sensor || !left_motor || !right_motor) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(SIGINT);
    }

    if (gpiod_line_request_input(left_sensor, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_sensor, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_sensor, "right_sensor") < 0 ||
        gpiod_line_request_output(left_motor, "left_motor", 0) < 0 ||
        gpiod_line_request_output(right_motor, "right_motor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup(SIGINT);
    }

    gpioSetPWMfrequency(LEFT_MOTOR_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PIN, PWM_FREQUENCY);

    log_file = fopen("trace_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(SIGINT);
    }

    while (1) {
        int left_sensor_state = !gpiod_line_get_value(left_sensor);
        int middle_sensor_state = !gpiod_line_get_value(middle_sensor);
        int right_sensor_state = !gpiod_line_get_value(right_sensor);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (!middle_sensor_state) {
            if (!left_sensor_state) {
                right_speed = BASE_SPEED / 2;
            } else if (!right_sensor_state) {
                left_speed = BASE_SPEED / 2;
            } else {
                left_speed = 0;
                right_speed = 0;
            }
        }

        gpioPWM(LEFT_MOTOR_PIN, left_speed);
        gpioPWM(RIGHT_MOTOR_PIN, right_speed);

        log_control_cycle(left_sensor_state, middle_sensor_state, right_sensor_state, left_speed, right_speed);

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000);
    }

    return EXIT_SUCCESS;
}

