#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x23
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180

static int i2c_fd;
static FILE *log_file;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int read_sensor() {
    unsigned char data[2];
    int lux;

    if (write(i2c_fd, "\x01", 1) != 1) {
        log_message("Error: Failed to send command to sensor");
        return -1;
    }

    usleep(24000);  // 24ms delay for measurement

    if (read(i2c_fd, data, 2) != 2) {
        log_message("Error: Failed to read from sensor");
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    return lux;
}

void handle_sigint(int signum) {
    log_message("Received SIGINT. Cleaning up...");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int lux;
    int relay_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    log_message("Grow light controller started");

    while (1) {
        lux = read_sensor();
        if (lux >= 0) {
            char log_buffer[128];
            snprintf(log_buffer, sizeof(log_buffer), "Lux: %d", lux);
            log_message(log_buffer);

            if (lux < LUX_THRESHOLD && !relay_state) {
                gpioWrite(RELAY_PIN, 1);
                relay_state = 1;
                log_message("Relay ON");
            } else if (lux >= LUX_THRESHOLD && relay_state) {
                gpioWrite(RELAY_PIN, 0);
                relay_state = 0;
                log_message("Relay OFF");
            }
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);
    }

    return 0;
}

