        fprintf(stderr, "Failed to get line for motor 1\n");
        goto error;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        fprintf(stderr, "Failed to get line for motor 2\n");
        goto error;
    }

    if (gpiod_line_request_output(motor1_line, "motor1", 0) < 0 ||
        gpiod_line_request_output(motor2_line, "motor2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        goto error;
