    while (1) {
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            fprintf(stderr, "Failed to set motor 1 high\n");
            goto error;
        }
        usleep(MOTOR1_DURATION_MS * 1000);

        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            fprintf(stderr, "Failed to set motor 1 low\n");
            goto error;
        }

        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            fprintf(stderr, "Failed to set motor 2 high\n");
            goto error;
        }
        usleep(MOTOR2_DURATION_MS * 1000);

        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            fprintf(stderr, "Failed to set motor 2 low\n");
            goto error;
        }
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

