#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE "alarm_node"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_S 1

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sound_sensor_line;
static struct gpiod_line *alarm_led_line;
static void *zmq_context;
static void *zmq_socket;

void signal_handler(int signum) {
    running = 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Failed to get sound sensor line");
        goto cleanup;
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
        perror("Failed to request sound sensor line as input");
        goto cleanup;
    }

    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Failed to get alarm LED line");
        goto cleanup;
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0) < 0) {
        perror("Failed to request alarm LED line as output");
        goto cleanup;
    }

    return 0;

cleanup:
    if (alarm_led_line) gpiod_line_release(alarm_led_line);
    if (sound_sensor_line) gpiod_line_release(sound_sensor_line);
    if (chip) gpiod_chip_close(chip);
    return -1;
}

void cleanup_gpio() {
    if (alarm_led_line) gpiod_line_release(alarm_led_line);
    if (sound_sensor_line) gpiod_line_release(sound_sensor_line);
    if (chip) gpiod_chip_close(chip);
}

int init_zmq(const char *mode) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Failed to create ZeroMQ context");
        return -1;
    }

    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_socket) {
            perror("Failed to create ZeroMQ publisher socket");
            goto cleanup;
        }

        if (zmq_bind(zmq_socket, "tcp://*:5555") < 0) {
            perror("Failed to bind ZeroMQ socket");
            goto cleanup;
        }
    } else {
        zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            perror("Failed to create ZeroMQ subscriber socket");
            goto cleanup;
        }

        if (zmq_connect(zmq_socket, "tcp://localhost:5555") < 0) {
            perror("Failed to connect ZeroMQ socket");
            goto cleanup;
        }

        if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS")) < 0) {
            perror("Failed to set ZeroMQ socket option");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    if (zmq_socket) zmq_close(zmq_socket);
    if (zmq_context) zmq_ctx_term(zmq_context);
    return -1;
}

void cleanup_zmq() {
    if (zmq_socket) zmq_close(zmq_socket);
    if (zmq_context) zmq_ctx_term(zmq_context);
}

void run_sound_sensor_mode() {
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};

    while (running) {
        int value = gpiod_line_get_value(sound_sensor_line);
        if (value == 0) {
            if (zmq_send(zmq_socket, "SOUND_ALERTS", strlen("SOUND_ALERTS"), 0) < 0) {
                perror("Failed to send alert message");
            }
        }
        nanosleep(&sleep_time, NULL);
    }
}

void run_alarm_node_mode() {
    char buffer[256];

    while (running) {
        int rc = zmq_recv(zmq_socket, buffer, sizeof(buffer), 0);
        if (rc < 0) {
            if (errno == EINTR) continue;
            perror("Failed to receive alert message");
            break;
        }

        if (strcmp(buffer, "SOUND_ALERTS") == 0) {
            if (gpiod_line_set_value(alarm_led_line, 1) < 0) {
                perror("Failed to turn on alarm LED");
            }
            sleep(ALARM_DURATION_S);
            if (gpiod_line_set_value(alarm_led_line, 0) < 0) {
                perror("Failed to turn off alarm LED");
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], SOUND_SENSOR_MODE) != 0 && strcmp(argv[1], ALARM_NODE_MODE) != 0) {
        fprintf(stderr, "Invalid mode. Use '%s' or '%s'.\n", SOUND_SENSOR_MODE, ALARM_NODE_MODE);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) return 1;
    if (init_zmq(argv[1]) < 0) {
        cleanup_gpio();
        return 1;
    }

    if (strcmp(argv[1], SOUND_SENSOR_MODE) == 0) {
        run_sound_sensor_mode();
    } else {
        run_alarm_node_mode();
    }

    cleanup_zmq();
    cleanup_gpio();

    return 0;
}

