#include <unistd.h>
#include <gpiod.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define GPIO_PIN 17
#define BUFFER_SIZE 1000
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_1 1690
#define NEC_BIT_SPACE_0 560
#define EXTENDED_NEC_FRAME 0

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int pulse_buffer[BUFFER_SIZE];
static int pulse_count = 0;
static mosquitto *mosq;

void cleanup(int signum) {
    syslog(LOG_INFO, "Cleaning up...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_destroy(mosq);
    closelog();
    exit(0);
}

void pulse_callback(struct gpiod_line *line, int event, uint64_t timestamp, void *user_data) {
    if (pulse_count < BUFFER_SIZE) {
        pulse_buffer[pulse_count++] = (int)timestamp;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow");
    }
}

int decode_nec_frame() {
    if (pulse_count < 100) return -1;  // Not enough pulses

    int offset = 0;
    if (pulse_buffer[offset] < NEC_HEADER_MARK || pulse_buffer[offset + 1] < NEC_HEADER_SPACE) {
        return -1;  // Invalid header
    }
    offset += 2;

    uint32_t address = 0, command = 0;
    for (int i = 0; i < 32; i++) {
        if (pulse_buffer[offset] < NEC_BIT_MARK) return -1;
        offset++;
        if (pulse_buffer[offset] < NEC_BIT_SPACE_0 || pulse_buffer[offset] > NEC_BIT_SPACE_1) return -1;
        offset++;

        if (pulse_buffer[offset] < NEC_BIT_MARK) return -1;
        offset++;

        address <<= 1;
        command <<= 1;
        if (pulse_buffer[offset - 1] > NEC_BIT_SPACE_0) {
            address |= 1;
        }
        if (pulse_buffer[offset] > NEC_BIT_SPACE_0) {
            command |= 1;
        }
        offset++;
    }

    if (!EXTENDED_NEC_FRAME) {
        uint32_t inverted_address = 0, inverted_command = 0;
        for (int i = 0; i < 16; i++) {
            inverted_address <<= 1;
            inverted_command <<= 1;
            if (pulse_buffer[offset] < NEC_BIT_MARK) return -1;
            offset++;
            if (pulse_buffer[offset] < NEC_BIT_SPACE_0 || pulse_buffer[offset] > NEC_BIT_SPACE_1) return -1;
            offset++;

            if (pulse_buffer[offset] < NEC_BIT_MARK) return -1;
            offset++;

            if (pulse_buffer[offset] > NEC_BIT_SPACE_0) {
                inverted_address |= 1;
            }
            if (pulse_buffer[offset] > NEC_BIT_SPACE_0) {
                inverted_command |= 1;
            }
            offset++;
        }

        if (address != (~inverted_address & 0xFFFF) || command != (~inverted_command & 0xFF)) {
            return -1;  // Invalid checksum
        }
    }

    return (address << 8) | command;
}

void mqtt_callback(struct mosquitto *mosq, void *userdata, int message_id) {
    // Not used in this example
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder");

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_rising_edge_events(line, "ir_decoder", pulse_callback, NULL);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_callback);
    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        mosquitto_loop(mosq, -1, 1);

        if (pulse_count >= 100) {
            int command = decode_nec_frame();
            if (command >= 0) {
                char json_str[100];
                snprintf(json_str, sizeof(json_str), "{\"command\": %d}", command);

                syslog(LOG_INFO, "Decoded command: %d", command);

                mosquitto_message msg = {
                    .mid = 0,
                    .topic = "ir/decoded",
                    .payload = json_str,
                    .payloadlen = strlen(json_str),
                    .qos = 0,
                    .retain = false
                };
                mosquitto_publish(mosq, NULL, &msg);

                memset(pulse_buffer, 0, sizeof(pulse_buffer));
                pulse_count = 0;
            }
        }

        usleep(10000);  // 10ms delay to prevent busy-waiting
    }

    return 0;
}

