#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_COUNT 4
#define SENSOR_ADDR 0x23 // Example address, adjust as needed
#define I2C_TIMEOUT 1000 // ms
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5005
#define CONVERSION_DELAY_MS 180
#define ACQUISITION_INTERVAL_MS 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int i2c_set_slave(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("I2C_SLAVE ioctl failed");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = write(fd, buf, len);
    if (ret < 0) {
        perror("I2C write failed");
        return -1;
    }
    return ret;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret = read(fd, buf, len);
    if (ret < 0) {
        perror("I2C read failed");
        return -1;
    }
    return ret;
}

double read_bh1750(int fd) {
    uint8_t cmd = 0x20; // Start conversion command
    if (i2c_write(fd, &cmd, 1) < 0) return NAN;

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t data[2];
    if (i2c_read(fd, data, 2) < 0) return NAN;

    return (data[0] << 8 | data[1]) / 1.2;
}

int setup_udp_socket() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("UDP socket creation failed");
        return -1;
    }

    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(sock, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("UDP setsockopt failed");
        close(sock);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    return sock;
}

int send_udp_packet(int sock, const char *packet) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    ssize_t sent = sendto(sock, packet, strlen(packet), 0, (struct sockaddr*)&addr, sizeof(addr));
    if (sent < 0) {
        perror("UDP sendto failed");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open failed");
        return 1;
    }

    int udp_sock = setup_udp_socket();
    if (udp_sock < 0) {
        close(i2c_fd);
        return 1;
    }

    while (!terminate) {
        char packet[100] = {0};
        char *ptr = packet;

        for (int i = 0; i < SENSOR_COUNT; i++) {
            if (i2c_set_slave(i2c_fd, SENSOR_ADDR + i) < 0) {
                snprintf(ptr, sizeof(packet) - (ptr - packet), "%d,NaN", i + 1);
            } else {
                double lux = read_bh1750(i2c_fd);
                if (isnan(lux)) {
                    snprintf(ptr, sizeof(packet) - (ptr - packet), "%d,NaN", i + 1);
                } else {
                    snprintf(ptr, sizeof(packet) - (ptr - packet), "%d,%.1f", i + 1, lux);
                }
            }

            ptr += strlen(ptr);
            if (i < SENSOR_COUNT - 1) {
                *ptr++ = ';';
            }
        }

        if (send_udp_packet(udp_sock, packet) < 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
        }

        usleep(ACQUISITION_INTERVAL_MS * 1000);
    }

    close(udp_sock);
    close(i2c_fd);
    return 0;
}

