#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define FLOW_SCALE_FACTOR 0.078 // SLPM per LSB

static int i2c_fd = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret;
    do {
        ret = write(fd, buf, len);
    } while (ret == -1 && errno == EINTR);
    return ret;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret;
    int attempts = 0;
    do {
        ret = read(fd, buf, len);
        if (ret == -1 && errno == EINTR) {
            continue;
        }
        if (ret == -1 && (errno == ENXIO || errno == EIO)) {
            fprintf(stderr, "I2C error: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            usleep(RETRY_DELAY_MS * 1000);
            attempts++;
        }
    } while (ret == 0 && attempts < RETRY_COUNT);
    return ret;
}

int main() {
    uint8_t buf[2];
    int16_t flow_raw;
    float flow_slpm;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        buf[0] = 0; // Zero-length write to generate start condition
        if (i2c_write(i2c_fd, buf, 1) != 1) {
            perror("Failed to generate start condition");
            break;
        }

        if (i2c_read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
