#define AS7341_ENABLE_REG 0x80
#define AS7341_ENABLE_PON 0x01
#define AS7341_CFG6_REG 0x9F
#define AS7341_SP_EN 0x20
#define AS7341_DATA_REG 0x94

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read(fd, reg, buf) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    int fd, log_fd;
    uint8_t id;
    uint16_t data[10];
    FILE *log_file;
    struct timespec ts;
    char timestamp[64];

    signal(SIGINT, signal_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    if (i2c_read(fd, AS7341_ID_REG, &id) != 1 || id != AS7341_ID_VAL) {
        fprintf(stderr, "AS7341 sensor not found or ID mismatch\n");
        close(fd);
        return 1;
    }

    if (i2c_write(fd, AS7341_ENABLE_REG, AS7341_ENABLE_PON) != 1) {
        perror("Failed to set PON bit");
        close(fd);
        return 1;
    }
    usleep(10000);  // Wait 10ms for power-on

    if (i2c_write(fd, AS7341_CFG6_REG, AS7341_SP_EN) != 1) {
        perror("Failed to enable spectral measurement");
        close(fd);
        return 1;
    }

    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR\n");

    while (keep_running) {
        for (int i = 0; i < 10; i++) {
            if (i2c_read_word(fd, AS7341_DATA_REG + i * 2, &data[i]) != 0) {
                fprintf(stderr, "Failed to read spectral channel %d\n", i);
                keep_running = 0;
                break;
            }
        }

        if (!keep_running) break;

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                timestamp, data[0], data[1], data[2], data[3], data[4],
                data[5], data[6], data[7], data[8], data[9]);
        fflush(log_file);

        // Simple lux approximation
        double lux = (data[0] + data[1] + data[2] + data[3] + data[4] +
                      data[5] + data[6] + data[7] + data[8] + data[9]) / 10.0;
        printf("Lux: %.2f\n", lux);

        sleep(5);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

