#include <time.h>

#define DEFAULT_I2C_ADDR 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_log = NULL;
static int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = write(fd, buf, len);
        if (result == len) return 0;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = read(fd, buf, len);
        if (result == len) return 0;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_acceleration(int i2c_addr, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read(i2c_fd, buf, 6) != 0) {
        fprintf(error_log, "[%s] I2C read error\n", __func__);
        return -1;
    }

    *x = (int16_t)(buf[0] | (buf[1] << 8)) / 16384.0;
    *y = (int16_t)(buf[2] | (buf[3] << 8)) / 16384.0;
    *z = (int16_t)(buf[4] | (buf[5] << 8)) / 16384.0;

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    int i2c_addr = DEFAULT_I2C_ADDR;
    int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
    const char *output_filename = DEFAULT_OUTPUT_FILENAME;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = strtol(optarg, NULL, 16);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a I2C_ADDR] [-i INTERVAL] [-f FILENAME]\n", argv[0]);
                return 1;
        }
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(output_filename, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    error_log = fopen("seismic_error.log", "w");
    if (error_log == NULL) {
        perror("Failed to open error log");
        fclose(csv_file);
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float x, y, z;
        if (read_acceleration(i2c_addr, &x, &y, &z) == 0) {
            fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
            fflush(csv_file);
        } else {
            fprintf(error_log, "[%s] Failed to read acceleration data\n", timestamp);
            fflush(error_log);
        }

        sleep(sampling_interval);
    }

    fclose(csv_file);
    fclose(error_log);
    close(i2c_fd);

    return 0;
}

