#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define RETRY_DELAY 1

int i2c_fd;
int sock_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (sock_fd >= 0) {
        close(sock_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

float bh1750_read_light() {
    uint8_t cmd = 0x20; // Power on, reset
    if (i2c_write(i2c_fd, &cmd, 1) < 0) return -1;
    usleep(20000); // Wait for reset

    cmd = 0x10; // Continuous mode, high resolution
    if (i2c_write(i2c_fd, &cmd, 1) < 0) return -1;
    usleep(180000); // Wait for measurement

    uint8_t data[2];
    if (i2c_read(i2c_fd, data, 2) < 0) return -1;

    uint16_t raw = (data[0] << 8) | data[1];
    return (float)raw / 1.2f; // Convert to lux
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("Failed to create socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ttl = 1;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set TTL");
        cleanup(0);
    }

    struct sockaddr_in multicast_addr;
    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    multicast_addr.sin_port = htons(MULTICAST_PORT);

    while (1) {
