#define TIMEOUT_SECONDS 2
#define SELECT_TIMEOUT_SECONDS 2
#define LINE_TIMEOUT_SECONDS 0.5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void set_interface_attribs(int fd, int speed, int parity) {
    struct termios tty;
    if (tcgetattr(fd, &tty) < 0) {
        perror("Error from tcgetattr");
        exit(EXIT_FAILURE);
    }

    cfsetospeed(&tty, speed);
    cfsetispeed(&tty, speed);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN] = 0;                             // read doesn't block
    tty.c_cc[VTIME] = (LINE_TIMEOUT_SECONDS * 10);  // 0.5 second read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag |= parity;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS

    if (tcsetattr(fd, TCSANOW, &tty) < 0) {
        perror("Error from tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int fd;
    char buffer[BUFFER_SIZE];
    char line_buffer[BUFFER_SIZE];
    int line_index = 0;
    struct sigaction sa_int, sa_term;

    sa_int.sa_handler = signal_handler;
    sigemptyset(&sa_int.sa_mask);
    sa_int.sa_flags = 0;

    sa_term.sa_handler = signal_handler;
    sigemptyset(&sa_term.sa_mask);
    sa_term.sa_flags = 0;

    if (sigaction(SIGINT, &sa_int, NULL) == -1) {
        perror("Error setting SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa_term, NULL) == -1) {
        perror("Error setting SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART device");
        exit(EXIT_FAILURE);
    }

    set_interface_attribs(fd, BAUD_RATE, 0);

    fd_set readfds;
    struct timeval tv;
    int ret;

    while (keep_running) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        tv.tv_sec = SELECT_TIMEOUT_SECONDS;
        tv.tv_usec = 0;

        ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                perror("Error from select");
                break;
            }
        } else if (ret == 0) {
            fprintf(stderr, "Select timeout\n");
            continue;
        }

        ssize_t n = read(fd, buffer, sizeof(buffer) - 1);
        if (n < 0) {
            perror("Error from read");
            break;
        } else if (n == 0) {
            fprintf(stderr, "End of file\n");
            break;
        }

        buffer[n] = '\0';

        for (int i = 0; i < n; i++) {
            char c = buffer[i];
            if (c == '\n') {
                line_buffer[line_index] = '\0';
                line_index = 0;

                char *timestamp_str, *range_str;
                timestamp_str = strtok(line_buffer, ",");
                range_str = strtok(NULL, "\n");

                if (timestamp_str && range_str) {
                    long timestamp = strtol(timestamp_str, NULL, 10);
                    double range = atof(range_str);

                    time_t rawtime = (time_t)timestamp;
                    struct tm *timeinfo = localtime(&rawtime);
                    char time_str[26];
                    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

                    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
                }
            } else {
                if (line_index < sizeof(line_buffer) - 1) {
                    line_buffer[line_index++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow\n");
                    line_index = 0;
                }
            }
        }
    }

    if (close(fd) < 0) {
        perror("Error closing UART device");
    }

    return 0;
}

